--
-- Name: a_document_arriving_is_a_signal(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.a_document_arriving_is_a_signal() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
begin
  /*
    Fixtures are not news.

    A suite importing forty documents must not start forty jobs, and the
    project's own flag is the thing that knows. CLAUDE.md records five separate
    occasions when harness traffic was about to be reported to Grant as the
    office doing something; this is the sixth place it would have happened.
  */
  if exists (select 1 from public.projects p
              where p.project_id = new.project_id and p.is_fixture) then
    return new;
  end if;

  perform app.record_signal(
    'office', 'document.added', new.document_id::text, new.project_id,
    left(coalesce(new.title, '(untitled)'), 300),
    jsonb_build_object(
      'document_id', new.document_id,
      'connector', coalesce(new.connector, ''),
      'origin', coalesce(new.origin, ''),
      'doc_type', coalesce(new.doc_type, ''),
      'mime_type', coalesce(new.mime_type, '')),
    new.produced_by_job,
    coalesce(new.created_at, app.now_utc()));
  return new;
end;
$$;


--
-- Name: action_in_words(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.action_in_words(p_action text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case p_action
    when 'finding.committed'     then jsonb_build_object('verb', 'recorded', 'what', 'a finding')
    when 'office.learned'        then jsonb_build_object('verb', 'learned', 'what', 'something')
    when 'office.skill_written'  then jsonb_build_object('verb', 'wrote down', 'what', 'a procedure')
    when 'office.noticed'        then jsonb_build_object('verb', 'noticed', 'what', 'something unasked')
    when 'tool.requested'        then jsonb_build_object('verb', 'asked for', 'what', 'a tool')
    when 'tool.granted'          then jsonb_build_object('verb', 'was given', 'what', 'a tool')
    when 'tool.declined'         then jsonb_build_object('verb', 'was refused', 'what', 'a tool')
    when 'tool.revoked'          then jsonb_build_object('verb', 'lost', 'what', 'a tool')
    when 'tool.wanted'           then jsonb_build_object('verb', 'was promised', 'what', 'a tool')
    when 'job.committed'         then jsonb_build_object('verb', 'finished', 'what', 'a piece of work')
    when 'notebook.source_added' then jsonb_build_object('verb', 'added', 'what', 'a source')
    else
      /*
        The general case, and it has to be readable rather than merely present.

        Dotted lowercase with underscores is guaranteed by the constraint on
        `events.action_type`, so `thing.was_done` splits cleanly into "was done"
        and "a thing". A new action type nobody has named here still reads as a
        sentence, which is the whole point of not using a lookup table.
      */
      jsonb_build_object(
        'verb', replace(split_part(p_action, '.', 2), '_', ' '),
        'what', case
          when split_part(p_action, '.', 1) in ('office', 'ledger', 'system')
            -- These are the office acting on itself; "a office" is not a thing.
            then replace(split_part(p_action, '.', 1), '_', ' ')
          else 'a ' || replace(split_part(p_action, '.', 1), '_', ' ')
        end)
  end
$$;


--
-- Name: FUNCTION action_in_words(p_action text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.action_in_words(p_action text) IS 'A ledger action as a verb and a thing, so the activity panel reads as a sentence rather than an identifier (#68). Unnamed types degrade to something readable rather than to a machine string.';


--
-- Name: add_project_alias(uuid, text, text, numeric); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.add_project_alias(p_project_id uuid, p_alias text, p_source text DEFAULT 'grant'::text, p_confidence numeric DEFAULT 1.0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_norm  text := app.normalise_name(p_alias);
  v_owner record;
  v_from  record;
begin
  if v_norm is null then
    return jsonb_build_object('error', 'that is not a name');
  end if;
  if not exists (select 1 from public.projects where project_id = p_project_id) then
    return jsonb_build_object('error', 'no such project');
  end if;

  /*
    Checked before inserting rather than caught after, so the answer can name
    the project that already holds the phrase. A unique violation tells the
    caller that something is wrong and not which thing.

    `status <> 'archived'` since 0293, matching `app.alias_is_free_among_active`
    exactly. Without it this refused on behalf of retired projects the trigger
    had already stopped protecting, and 0282's release of 561 phrases could
    never actually happen.
  */
  select p.project_id, p.name into v_owner
    from public.project_aliases al
    join public.projects p on p.project_id = al.project_id
   where al.normalised = v_norm
     and al.project_id <> p_project_id
     and p.status <> 'archived';

  if found then
    return jsonb_build_object(
      'error', format('%L already means %s', p_alias, v_owner.name),
      'conflicts_with', v_owner.project_id
    );
  end if;

  /*
    An ARCHIVED project may still hold this phrase, and taking it is allowed —
    that is the whole point of 0282. But it is worth saying so: a phrase
    quietly changing which project it routes to is the ambiguity #44 was about,
    and the caller should be able to see it rather than discover it later.
  */
  select p.name into v_from
    from public.project_aliases al
    join public.projects p on p.project_id = al.project_id
   where al.normalised = v_norm
     and al.project_id <> p_project_id
     and p.status = 'archived'
   limit 1;

  insert into public.project_aliases (project_id, alias, source, confidence)
  values (p_project_id, btrim(p_alias), p_source, p_confidence)
  on conflict (project_id, normalised)
    do update set source = excluded.source,
                  confidence = greatest(public.project_aliases.confidence, excluded.confidence);

  return jsonb_build_object('ok', true, 'alias', btrim(p_alias), 'project_id', p_project_id)
    || case when v_from.name is null then '{}'::jsonb
            else jsonb_build_object('taken_from_archived', v_from.name) end;
end;
$$;


--
-- Name: FUNCTION add_project_alias(p_project_id uuid, p_alias text, p_source text, p_confidence numeric); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.add_project_alias(p_project_id uuid, p_alias text, p_source text, p_confidence numeric) IS 'Give a project a routing phrase. Refuses one already held by a project Grant can be routed to, and NAMES it — a unique violation says something is wrong and not which thing. An archived holder does not refuse (0282, #45); the answer says which project the phrase was taken from (0293).';


--
-- Name: add_project_reference(text, text, text, text, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.add_project_reference(p_slug text, p_url text, p_title text DEFAULT NULL::text, p_kind text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_by text DEFAULT 'grant'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_project uuid;
  v_url     text := btrim(coalesce(p_url, ''));
  v_kind    text;
  v_title   text;
  v_id      uuid;
  v_existing uuid;
begin
  if v_url = '' then
    return jsonb_build_object('ok', false, 'error', 'a reference needs a link');
  end if;

  select project_id into v_project
    from public.projects where slug = p_slug and status <> 'archived';
  if v_project is null then
    return jsonb_build_object('ok', false, 'error', format('no active project called %s', p_slug));
  end if;

  /*
    A bare host is a link. Grant pastes "stripe.com/docs" as often as the full
    thing, and refusing it would be the interface being pedantic about a
    detail it can fix itself.
  */
  if v_url !~* '^[a-z][a-z0-9+.-]*:' then
    v_url := 'https://' || v_url;
  end if;

  v_kind  := coalesce(nullif(btrim(coalesce(p_kind, '')), ''), app.guess_reference_kind(v_url));
  v_title := coalesce(nullif(btrim(coalesce(p_title, '')), ''),
                      app.guess_reference_title(v_url), v_url);

  select reference_id into v_existing
    from public.project_references
   where project_id = v_project
     and app.normalise_reference_url(url) = app.normalise_reference_url(v_url);
  if v_existing is not null then
    return jsonb_build_object(
      'ok', false, 'already', true, 'reference', v_existing,
      'error', format('%s already points at that', p_slug));
  end if;

  insert into public.project_references (project_id, kind, url, title, note, added_by)
  values (v_project, v_kind, v_url, v_title, btrim(coalesce(p_note, '')), p_by)
  returning reference_id into v_id;

  return jsonb_build_object('ok', true, 'reference', v_id, 'kind', v_kind, 'title', v_title);
end;
$$;


--
-- Name: ago(timestamp with time zone); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.ago(p_at timestamp with time zone) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  select case
    when p_at is null then 'never'
    when app.now_utc() - p_at < interval '90 seconds' then 'just now'
    when app.now_utc() - p_at < interval '90 minutes' then
      format('%s minutes ago', round(extract(epoch from app.now_utc() - p_at) / 60))
    when app.now_utc() - p_at < interval '36 hours' then
      format('%s hours ago', round(extract(epoch from app.now_utc() - p_at) / 3600))
    else
      format('%s days ago', round(extract(epoch from app.now_utc() - p_at) / 86400))
  end
$$;


--
-- Name: FUNCTION ago(p_at timestamp with time zone); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.ago(p_at timestamp with time zone) IS 'How long ago, in plain English and deliberately coarse. One sentence for every page that needs it, rather than a case expression per row.';


--
-- Name: alias_is_free_among_active(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.alias_is_free_among_active() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare v_holder text;
begin
  select p.slug into v_holder
    from public.project_aliases a
    join public.projects p on p.project_id = a.project_id
   where a.normalised = new.normalised
     and a.project_id <> new.project_id
     and p.status <> 'archived'
   limit 1;

  if v_holder is not null then
    raise exception 'the phrase %L already routes to %', new.normalised, v_holder
      using errcode = 'unique_violation';
  end if;
  return new;
end;
$$;


--
-- Name: FUNCTION alias_is_free_among_active(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.alias_is_free_among_active() IS '#45. Uniqueness among projects Grant can actually be routed to. An archived project keeps its aliases as history and no longer blocks a live one — which releases 561 phrases without deleting a single row.';


--
-- Name: answer_generation_approval(uuid, boolean, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.answer_generation_approval(p_blocker uuid, p_approved boolean, p_by text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  b public.blockers;
  v_config jsonb;
  v_next text;
  v_new uuid;
begin
  select * into b from public.blockers where blocker_id = p_blocker;
  if not found then
    return jsonb_build_object('error', 'no such request');
  end if;
  if b.state <> 'open' then
    return jsonb_build_object('already', true, 'state', b.state, 'resolution', b.resolution);
  end if;

  update public.blockers
     set state = 'resolved',
         resolved_at = app.now_utc(),
         resolution = case when p_approved
                        then format('approved by %s', p_by)
                        else format('declined by %s', p_by) end
   where blocker_id = p_blocker;

  if not p_approved then
    return jsonb_build_object('approved', false);
  end if;

  select pinned_config into v_config from public.jobs where job_id = b.job_id;
  -- `notebook.generate` when the job did not say, which is every approval
  -- created before this migration. An in-flight request must not become
  -- unanswerable because the schema moved under it.
  v_next := coalesce(v_config ->> 'approval_next', 'notebook.generate');

  insert into public.jobs
    (parent_job_id, correlation_id, project_id, idempotency_key, kind,
     requested_by, priority, pinned_config)
  select b.job_id, j.correlation_id, j.project_id,
         format('approved-%s', p_blocker),
         v_next,
         j.requested_by,
         -- Ahead of the queue: he has just pressed a button and is watching.
         50,
         coalesce(v_config, '{}'::jsonb)
           || jsonb_build_object('approved_by', p_by, 'approval', p_blocker)
    from public.jobs j where j.job_id = b.job_id
  returning job_id into v_new;

  return jsonb_build_object('approved', true, 'job_id', v_new, 'kind', v_next);
end;
$$;


--
-- Name: FUNCTION answer_generation_approval(p_blocker uuid, p_approved boolean, p_by text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.answer_generation_approval(p_blocker uuid, p_approved boolean, p_by text) IS 'A button press, applied — for a generation or for a plan. The job says what its yes should start (`approval_next`); this reads it. One mechanism, because two would need keeping in step and the button vocabulary already taught that lesson twice.';


