    '')
$$;


--
-- Name: approval_binds(uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.approval_binds(p_job uuid, p_fingerprint text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_bound text;
  v_at timestamptz;
begin
  select p.binds_to, p.at into v_bound, v_at
    from public.job_pauses p
   where p.job_id = p_job and p.reason = 'awaiting_approval'
   order by p.at desc
   limit 1;

  if v_bound is null then
    return jsonb_build_object('matched', false, 'approved_anything', false,
      'why', 'nothing was ever approved for this job');
  end if;
  if v_bound = p_fingerprint then
    return jsonb_build_object('matched', true, 'approved_at', v_at);
  end if;
  return jsonb_build_object('matched', false, 'approved_anything', true, 'approved_at', v_at,
    'why', 'what this job is about to do is not what was approved — the action '
           'changed while it was waiting, so it needs looking at rather than sending');
end;
$$;


--
-- Name: approve_document(uuid, text, text[], uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.approve_document(p_document uuid, p_collection text DEFAULT NULL::text, p_tags text[] DEFAULT NULL::text[], p_related_task uuid DEFAULT NULL::uuid, p_related_source uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_project uuid;
  v_title   text;
  v_source  text;
begin
  select project_id, title into v_project, v_title
    from public.documents where document_id = p_document;
  if v_project is null then
    -- A jsonb answer rather than a raise: this is called from a button, and
    -- "no such document" is something the page can say out loud.
    return jsonb_build_object('ok', false, 'error', 'no such document');
  end if;

  update public.documents
     set state = 'approved',
         tags = case when p_tags is null then tags else p_tags end
   where document_id = p_document;

  if p_collection is not null and length(btrim(p_collection)) > 0 then
    perform app.put_in_collection(p_document, p_collection);
  end if;

  if p_related_task is not null then
    perform app.link(v_project, 'document', p_document, 'attached_to', 'task', p_related_task, 'grant');
  end if;

  /*
    The fourth field (#28), and it is checked before it is written.

    A source is an attachment or a reference (#35), and `relations` has no
    foreign key on `to_id` — it cannot, because the id may point at any of
    seven tables. So a bad id would store silently and surface later as a
    dangling edge, which `relations_of` reports honestly and nobody would
    connect back to here.
  */
  if p_related_source is not null then
    select coalesce(
             (select a.display_name from public.project_attachments a
               where a.attachment_id = p_related_source and a.project_id = v_project),
             (select r.title from public.project_references r
               where r.reference_id = p_related_source and r.project_id = v_project))
      into v_source;
    if v_source is null then
      return jsonb_build_object('ok', false,
        'error', 'that source does not belong to this project');
    end if;
    perform app.link(v_project, 'document', p_document, 'derived_from', 'source',
                     p_related_source, 'grant');
  end if;

  return jsonb_build_object(
    'ok', true, 'document', p_document, 'title', v_title,
    'collection', nullif(btrim(coalesce(p_collection, '')), ''),
    'tags', to_jsonb(coalesce(p_tags, '{}')),
    'source', v_source);
end;
$$;


--
-- Name: approve_tool(uuid, text, jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.approve_tool(p_request_id uuid, p_by text DEFAULT 'grant'::text, p_limits jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  req    public.tool_requests%rowtype;
  known  public.tool_permissions%rowtype;
begin
  if p_by is distinct from 'grant' then
    return jsonb_build_object('error',
      'only Grant approves reach. An agent may ask and may never answer (ADR-0018).');
  end if;

  select * into req from public.tool_requests where request_id = p_request_id;
  if not found then
    return jsonb_build_object('error', 'no such request: ' || p_request_id::text);
  end if;
  if req.state <> 'open' then
    return jsonb_build_object('error', 'that request was already ' || req.state);
  end if;

  update public.tool_requests
     set state = 'approved', settled_at = app.now_utc(),
         decided_by = p_by, limits = p_limits
   where request_id = p_request_id;

  select * into known from public.tool_permissions where tool = req.tool;

  /*
    No implementation behind the name, so there is nothing to grant.

    Inserting the row anyway would make the approval appear to work and leave a
    permission that may or may not do anything. What Grant has actually decided
    here is that he wants it built, and saying that is more useful than a grant
    that silently does nothing.
  */
  if not found then
    perform public.append_event(
      extensions.gen_random_uuid(), 'user', p_by, 'approval', 'tool.wanted',
      true, null, null,
      jsonb_build_object('tool', req.tool, 'request_id', req.request_id),
      'Approved, but no such tool exists yet — this is a decision to build it.',
      '[]'::jsonb, null, null, 'app.withdraw_tool_request(request_id)', null);
    return jsonb_build_object(
      'approved', true, 'granted', false, 'needs_building', true, 'tool', req.tool,
      'say', format('Approved — but %s does not exist yet, so there is nothing '
                    || 'to switch on. It needs building before anyone can hold it.',
                    req.tool));
  end if;

  insert into public.staff_tools (staff_slug, tool, granted_by, note)
  values (req.asked_by, req.tool, p_by,
          format('Approved from request %s.', req.request_id))
  on conflict (staff_slug, tool) do nothing;

  perform public.append_event(
    extensions.gen_random_uuid(), 'user', p_by, 'approval', 'tool.granted',
    true, null,
    jsonb_build_object('held', false),
    jsonb_build_object('tool', req.tool, 'to', req.asked_by,
                       'request_id', req.request_id, 'limits', p_limits),
    left(req.what_for, 1000), '[]'::jsonb, null, req.tool,
    'app.revoke_tool(staff_slug, tool)', null);

  /*
    The global switch stays the ceiling (0119).

    A grant against a policy-disabled tool is recorded and does nothing, and
    saying so is the difference between a permission screen that explains itself
    and one that lies. Flipping the global switch is a separate, deliberate act.
  */
  return jsonb_build_object(
    'approved', true, 'granted', true, 'tool', req.tool, 'to', req.asked_by,
    'in_force', known.enabled,
    'say', case when known.enabled
      then format('%s can now use %s.', req.asked_by, req.tool)
      else format('Granted to %s, but %s is switched off for everyone — %s. '
                  || 'It stays off until that changes.',
                  req.asked_by, req.tool, coalesce(known.disabled_reason, 'by policy'))
    end);
end;
$$;


--
-- Name: FUNCTION approve_tool(p_request_id uuid, p_by text, p_limits jsonb); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.approve_tool(p_request_id uuid, p_by text, p_limits jsonb) IS 'Grant answering yes. Grants ONE exact tool and never a family; records who decided and the limits; and when the tool does not exist, records a decision to build rather than granting a fiction (ADR-0018).';


--
-- Name: archive_project(text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.archive_project(p_slug text, p_by text DEFAULT 'grant'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare v_project uuid; v_name text; v_stopped int; v_undo uuid;
begin
  select project_id, name into v_project, v_name
    from public.projects where slug = p_slug;
  if v_project is null then
    return jsonb_build_object('ok', false, 'error', format('no project called %s', p_slug));
  end if;

  update public.projects set status = 'archived' where project_id = v_project;

  update public.responsibilities
     set enabled = false, updated_at = app.now_utc()
   where project_id = v_project and enabled;
  get diagnostics v_stopped = row_count;

  /*
    The way back, offered at the moment it still knows what it changed.

    Ten minutes rather than the default two: archiving a project is not a
    typo in a title, and the realisation that it was the wrong one tends to
    arrive after looking for it somewhere else. `undo_offer` returns null while
    a reversal is being performed, so an undo of an undo is not a feature and
    nothing here has to know that.

    It does NOT restore the automations this call stopped. `unarchive_project`
    is explicit that they stay off and says which ones, because a duty that
    starts running again without being asked is a worse surprise than one that
    does not.
  */
  v_undo := app.undo_offer(
    'project_archive',
    format('archived %s', v_name),
    jsonb_build_object('action', 'unarchive_project',
                       'args', jsonb_build_object('p_slug', p_slug)),
    10);

  return jsonb_build_object(
    'ok', true, 'archived', p_slug, 'name', v_name, 'automations_stopped', v_stopped,
    'reversible', true, 'undo', v_undo);
end;
$$;


--
-- Name: artifacts_in(uuid, text[], integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.artifacts_in(p_project uuid, p_kinds text[] DEFAULT NULL::text[], p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select coalesce(jsonb_agg(q.v order by q.at desc), '[]'::jsonb)
    from (
      select a.created_at as at,
             jsonb_build_object(
               'id', a.artifact_id,
               'kind', a.kind,
               'title', coalesce(nullif(btrim(coalesce(a.title, '')), ''), '(untitled)'),
               'url', a.url,
               'openable', a.url is not null,
               'state', a.state,
               'detail', a.detail,
               'mine', a.requested_by_job is not null,
               'notebook', a.notebook_ref,
               'at', a.created_at,
               'ready_at', a.ready_at) as v
        from public.artifacts a
       where a.project_id = p_project
         and (p_kinds is null or coalesce(array_length(p_kinds, 1), 0) = 0
              or a.kind = any (p_kinds))
       order by a.created_at desc
       limit greatest(1, least(coalesce(p_limit, 50), 200))
    ) q;
$$;


--
-- Name: asset_actions(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.asset_actions() RETURNS TABLE(action text, label text, needs_two boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$ select a.action, a.label, a.needs_two from public.asset_actions a order by a.position $$;


--
-- Name: attach_drive_folder(uuid, text, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.attach_drive_folder(p_project_id uuid, p_url text, p_name text DEFAULT NULL::text, p_by text DEFAULT 'grant'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  fid      text;
  existing public.project_attachments%rowtype;
  made     public.project_attachments%rowtype;
begin
  fid := app.folder_id_from(p_url);
  if fid is null then
    return jsonb_build_object(
      'error', 'that does not look like a Drive folder link',
      'hint', 'Open the folder in Drive and copy the address bar — it looks '
              || 'like https://drive.google.com/drive/folders/…');
  end if;

  if not exists (select 1 from public.projects where project_id = p_project_id) then
    return jsonb_build_object('error', 'no such project');
  end if;

  select * into existing from public.project_attachments
   where connector = 'drive' and external_ref = fid and enabled;
  if found and existing.project_id <> p_project_id then
    return jsonb_build_object(
      'error', 'that folder is already watched by another project',
      'project_id', existing.project_id);
  end if;

  insert into public.project_attachments
    (project_id, connector, external_ref, display_name, external_url, role, ref_kind, enabled)
  values
    (p_project_id, 'drive', fid,
     coalesce(nullif(btrim(coalesce(p_name, '')), ''), 'Drive folder'),
     'https://drive.google.com/drive/folders/' || fid,
     'source', 'folder', true)
  on conflict do nothing
  returning * into made;

  if made.attachment_id is null then
    select * into made from public.project_attachments
     where project_id = p_project_id and connector = 'drive' and external_ref = fid;
  end if;

  insert into public.drive_watch (attachment_id, folder_id)
  values (made.attachment_id, fid)
  on conflict (attachment_id) do nothing;

  -- `wanted`, the word this table already uses. See the header.
  insert into public.project_connector_choices
    (project_id, connector, choice, reason, decided_by)
  values (p_project_id, 'drive', 'wanted', 'Folder attached by ' || p_by, p_by)
  on conflict (project_id, connector) do update
     set choice = 'wanted', reason = excluded.reason, decided_by = excluded.decided_by,
         decided_at = app.now_utc();

  return jsonb_build_object(
    'attachment_id', made.attachment_id,
    'folder_id', fid,
    'url', made.external_url);
end;
$$;


--
-- Name: FUNCTION attach_drive_folder(p_project_id uuid, p_url text, p_name text, p_by text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.attach_drive_folder(p_project_id uuid, p_url text, p_name text, p_by text) IS 'Give a project its Drive folder. Takes the pasted link (#62).';


--
-- Name: attach_file_to_document(uuid, text, text, bigint); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.attach_file_to_document(p_document_id uuid, p_storage_path text, p_mime_type text, p_byte_size bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_title    text;
  v_existing text;
  v_project  uuid;
  v_owner    uuid;
begin
  select title, storage_path, project_id
    into v_title, v_existing, v_project
    from public.documents where document_id = p_document_id;
  if v_title is null then
    return jsonb_build_object('ok', false, 'error', 'no such document');
  end if;

  /*
    Idempotent on the path, the way `record_file_document` is.

    A re-read of the same Drive file lands on the same object — `x-upsert` sees
    to that on the storage side — so arriving here twice is the normal case,
    not an error. Answering `already_there` lets a caller retry freely.
  */
  if v_existing is not distinct from p_storage_path then
    return jsonb_build_object(
      'ok', true, 'already_there', true, 'document', p_document_id, 'title', v_title);
  end if;

  if coalesce(btrim(p_storage_path), '') = '' or coalesce(btrim(p_mime_type), '') = ''
     or coalesce(p_byte_size, 0) <= 0 then
    -- `documents_file_is_complete` would refuse this too. Said in words here
    -- because a caller reading "violates check constraint" learns nothing
    -- about which of the three it forgot.
    return jsonb_build_object(
      'ok', false,
      'error', 'a file needs all three of a path, a mime type and a size above zero');
  end if;

  /*
    One document per object.

    Two rows pointing at the same bytes would make deleting either one a
    question nobody wants to answer, and the path is derived from the
    connector's own file id, so a collision means two documents claim to be the
    same file. Worth refusing loudly.
  */
  select document_id into v_owner
    from public.documents
   where storage_path = p_storage_path and document_id <> p_document_id;
  if v_owner is not null then
    return jsonb_build_object(
      'ok', false, 'error', format('another document already holds that file (%s)', v_owner));
  end if;

  /*
    Only the three file columns.

    `content`, `origin`, `connector`, `doc_type`, `state` and every other
    column are left exactly as they were: this is a document that gained a
    file, not a file that gained a document. The extracted text stays the
    readable half, and the reader falls through to it whenever the browser
    cannot render the bytes.
  */
  update public.documents
     set storage_path = p_storage_path,
         mime_type    = p_mime_type,
         byte_size    = p_byte_size
   where document_id = p_document_id;

  return jsonb_build_object(
    'ok', true, 'document', p_document_id, 'title', v_title,
    'project_id', v_project, 'bytes', p_byte_size);
end;
$$;


--
-- Name: FUNCTION attach_file_to_document(p_document_id uuid, p_storage_path text, p_mime_type text, p_byte_size bigint); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.attach_file_to_document(p_document_id uuid, p_storage_path text, p_mime_type text, p_byte_size bigint) IS '#96. Give an existing document its original file. Unlike app.record_file_document (0208) this touches ONLY storage_path, mime_type and byte_size — the text, the origin and the connector are what the document already is, and a PDF from Drive is sourced rather than made. Idempotent on the path. 0331.';


--
-- Name: autonomy_choices(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.autonomy_choices() RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  /*
    Named for what each means to Grant, valued as the enum requires.

    `act_with_review` is precise and nobody says it out loud. The mapping lives
    here rather than in the page so a fifth level cannot appear in one and not
    the other — which is exactly how "wide" came to be offered for a level that
    has never existed.
  */
  select jsonb_build_array(
    jsonb_build_object('id', 'observe', 'name', 'Watch only',
      'note', 'The team reads and reports. It changes nothing anywhere.'),
    jsonb_build_object('id', 'suggest', 'name', 'Ask me first',
      'note', 'Every action outside our own records waits for you.'),
    jsonb_build_object('id', 'act_with_review', 'name', 'Act, then show me',
      'note', 'Routine work proceeds and lands in front of you afterwards.'),
    jsonb_build_object('id', 'act', 'name', 'Act',
      'note', 'Only purchases and destructive changes stop and ask.')
  )
$$;


--
-- Name: autonomy_for(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.autonomy_for(p_project_id uuid DEFAULT NULL::uuid) RETURNS public.autonomy_level
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(
    -- The project's own setting, if it has one.
    (select level from public.autonomy_settings
      where project_id is not distinct from p_project_id
      order by set_at desc, setting_id desc limit 1),
    -- Otherwise the global setting.
    (select level from public.autonomy_settings
      where project_id is null
      order by set_at desc, setting_id desc limit 1),
    -- Otherwise the conservative default. A missing configuration must not
    -- read as permission.
    'suggest'::public.autonomy_level
  );
$$;


--
-- Name: FUNCTION autonomy_for(p_project_id uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.autonomy_for(p_project_id uuid) IS 'Project setting, else global, else `suggest`. The fallback is deliberately the cautious end: a missing configuration must never read as permission.';


--
-- Name: awaiting_review(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.awaiting_review(p_project uuid) RETURNS TABLE(document_id uuid, title text, produced_by text, produced_by_job uuid, created_at timestamp with time zone, derived_from text[], state text, kind text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select d.document_id, d.title,
         -- 0284: `produced_by` is NOT NULL defaulting to the empty string, so
         -- coalesce on it is dead code. nullif is what actually fires.
         coalesce(nullif(d.produced_by, ''), 'The team') as produced_by,
         d.produced_by_job, d.created_at,
         coalesce(array_agg(src.title order by src.title)
                    filter (where src.title is not null), '{}') as derived_from,
         d.state,
         case
           when coalesce(d.mime_type, '') like 'audio/%' then 'audio'
           when coalesce(d.mime_type, '') = 'application/pdf'
             or d.title ilike '%.pdf' then 'pdf'
           else 'doc' end as kind
    from public.documents d
    left join public.relations r
           on r.from_kind = 'document' and r.from_id = d.document_id
          and r.verb = 'derived_from' and r.to_kind = 'document'
    left join public.documents src on src.document_id = r.to_id
   where d.project_id = p_project
     and d.origin = 'made'
     and d.state in ('draft', 'review')
   group by d.document_id, d.title, d.produced_by, d.produced_by_job,
            d.created_at, d.state, d.mime_type
   order by d.created_at desc
$$;


--
-- Name: FUNCTION awaiting_review(p_project uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.awaiting_review(p_project uuid) IS 'What the team has made and Grant has not decided about (#28). Draft AND review: nothing has ever written the review state, so the original predicate could not match a row and the queue was empty by construction.';


--
-- Name: blocker_closes_its_task(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.blocker_closes_its_task() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.state = 'open' or old.state <> 'open' then return new; end if;
  /*
    The other direction, and the half that is easy to leave out. Answering on
    the Governance page without this leaves "Authorize Google Drive" on his
    list for ever with nothing left to do -- a task that cannot be completed
    by doing anything, which teaches him to ignore the list.
  */
  update public.tasks
     set state = 'done', done_at = app.now_utc()
   where satisfies_blocker = new.blocker_id and state <> 'done';
  return new;
end;
$$;


--
-- Name: blocker_makes_a_task(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.blocker_makes_a_task() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_answer text;
begin
  /*
    Only a blocker that actually STOPS the job. A blocker raised while work
    continues is a question, and a question belongs on the Governance page
    rather than on a to-do list -- putting every one of them on his list is
    how a list stops being read.
  */
  if new.work_can_continue then return new; end if;
  if new.job_id is null then return new; end if;

  v_answer := new.approval_options[1];
  if v_answer is null then return new; end if;

  insert into public.tasks
    (project_id, title, detail, state, assigned_to_human, job_id,
     satisfies_blocker, satisfies_answer, added_by, priority)
  values
    (new.project_id,
     new.requested_action,
     /*
       The task says WHY, because a task called "Authorize Google Drive" with
       no context is one he will look at in a week and not know the cost of
       leaving. The blockers own words, not a summary of them.
     */
     new.why_needed ||
       case when coalesce(new.consequences_of_delay, '') = '' then ''
            else ' If it waits: ' || new.consequences_of_delay end,
     'todo', true, new.job_id,
     new.blocker_id, v_answer,
     coalesce(new.originating_agent, 'the office'),
     2)
  on conflict do nothing;
  return new;
end;
$$;


--
-- Name: branch_outputs(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.branch_outputs(p_group uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select coalesce(jsonb_agg(v order by ord), '[]'::jsonb)
    from (
      select jsonb_build_object(
               'agent', br.agent,
               'name', coalesce(s.name, br.agent),
               'purpose', br.purpose,
               'required', br.required,
               'job_id', br.job_id,
               'body', o.body,
               'confidence', o.confidence,
               'evidence', o.evidence,
               'sources', o.sources) as v,
             br.created_at as ord
        from public.job_branches br
        join public.jobs j on j.job_id = br.job_id
        left join public.staff s on s.slug = br.agent
        join lateral (
          select o.body, o.confidence::text as confidence, o.evidence::text as evidence,
                 o.sources
            from public.outputs o where o.job_id = br.job_id
           order by o.created_at desc limit 1
        ) o on true
       where br.group_id = p_group
    ) q;
$$;


--
-- Name: browser_budget(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.browser_budget() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with cap as (
    select coalesce(
      (select nullif(value #>> '{}', '')::numeric from public.system_config
        where key = 'browser.daily_minutes'), 10)::numeric as minutes
  ), spent as (
    select coalesce(sum(a.ms), 0)::numeric / 60000 as minutes,
           count(*)::int as actions,
           count(*) filter (
             where app.harness_browsing(a.job_id, a.project_id))::int as harness_actions
      from public.browser_actions a
     where a.at >= date_trunc('day', app.now_utc())
  )
  select jsonb_build_object(
    'cap_minutes', round(cap.minutes, 2),
    'used_minutes', round(spent.minutes, 2),
    'left_minutes', round(greatest(cap.minutes - spent.minutes, 0), 2),
    'actions_today', spent.actions,
    'harness_actions_today', spent.harness_actions,
    'exhausted', spent.minutes >= cap.minutes
  ) from cap, spent;
$$;


--
-- Name: browser_lately(uuid, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.browser_lately(p_project uuid, p_limit integer DEFAULT 30) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(x.v order by x.ord), '[]'::jsonb) from (
    select row_number() over (order by a.at desc) as ord,
           jsonb_build_object(
             'at', a.at, 'verb', a.verb, 'url', a.url, 'ok', a.ok,
             'detail', a.detail, 'shot_path', a.shot_path, 'ms', a.ms,
             'site', b.site
           ) as v
      from public.browser_actions a
      left join public.browser_sessions b on b.session_id = a.session_id
     where (p_project is null or a.project_id = p_project)
       and not app.harness_browsing(a.job_id, a.project_id)
     order by a.at desc
     limit greatest(coalesce(p_limit, 30), 1)
  ) x;
$$;


--
-- Name: browser_note(uuid, uuid, text, text, boolean, text, text, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.browser_note(p_session uuid, p_job uuid, p_verb text, p_url text, p_ok boolean, p_detail text, p_shot text, p_ms integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_project uuid;
  v_id uuid;
begin
  select project_id into v_project from public.browser_sessions where session_id = p_session;
  if v_project is null then
    select project_id into v_project from public.jobs where job_id = p_job;
  end if;

  insert into public.browser_actions
    (session_id, job_id, project_id, verb, url, ok, detail, shot_path, ms)
  values (p_session, p_job, v_project, p_verb, left(coalesce(p_url, ''), 2000), coalesce(p_ok, false),
          left(coalesce(p_detail, ''), 600), p_shot, greatest(coalesce(p_ms, 0), 0))
  returning action_id into v_id;

  if p_session is not null and coalesce(p_ok, false) then
    update public.browser_sessions
       set last_alive_at = app.now_utc(), updated_at = app.now_utc()
     where session_id = p_session;
  end if;

  return jsonb_build_object('ok', true, 'action_id', v_id);
end;
$$;


--
-- Name: browser_now(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.browser_now(p_project uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(x.v order by x.ord), '[]'::jsonb) from (
    select row_number() over (order by j.created_at) as ord,
           jsonb_build_object(
             'job_id', j.job_id,
             'url', j.pinned_config ->> 'url',
             'state', j.state::text,
             /*
               Parked waiting for a person is a different thing from running,
               and #16 asks for it as its own clear action. Said as a boolean
               rather than left for the page to work out from the state name,
               because two surfaces deciding that separately is how they come
               to disagree.
             */
             'waiting_for_you', (j.state in ('waiting_user', 'paused')),
             'stop_asked', (j.stop_requested_at is not null),
             'since', j.created_at,
             'site', s.site
           ) as v
      from public.jobs j
      left join public.browser_sessions s
        on s.project_id = j.project_id
       and s.site = lower(split_part(split_part(
             regexp_replace(coalesce(j.pinned_config ->> 'url', ''), '^https?://', ''),
             '/', 1), ':', 1))
     where j.kind = 'browser.gather'
       and j.project_id = p_project
       and j.state in ('queued', 'running', 'retrying', 'waiting_user', 'paused')
       and not app.harness_browsing(j.job_id, j.project_id)
     order by j.created_at
     limit 20
  ) x;
$$;


--
-- Name: FUNCTION browser_now(p_project uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.browser_now(p_project uuid) IS 'The browsing the office is doing for this project right now, so the Browser tab can answer "what is it doing" in the present tense and offer a Stop beside it (#135, #16).';


--
-- Name: browser_session_establish(uuid, text, text, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.browser_session_establish(p_project uuid, p_site text, p_purpose text, p_jar text, p_by text DEFAULT 'grant'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_site text := lower(trim(coalesce(p_site, '')));
  v_ref app.vault_secret_ref;
  v_opened jsonb;
begin
  if coalesce(length(trim(coalesce(p_jar, ''))), 0) < 2 then
    return jsonb_build_object('error',
      'a session needs the signed-in browser state. Export it from the browser '
      'you signed in with and paste the whole thing.');
  end if;
  /*
    The jar is checked for SHAPE before it is stored, so a paste into the wrong
    box is refused with a sentence rather than kept for ever as a session that
    silently never works. 0359 is the same argument about a Client ID and a
    Client secret sitting next to each other.
  */
  begin
    if jsonb_typeof(p_jar::jsonb) not in ('array', 'object') then
      return jsonb_build_object('error',
        'that does not look like browser session state -- it should be the JSON '
        'a browser export gives you.');
    end if;
  exception when others then
    return jsonb_build_object('error',
      'that does not look like browser session state -- it should be the JSON '
      'a browser export gives you.');
  end;

  -- Opened FIRST, with no credential, so a refusal costs nothing: a Vault row
  -- written for a session the validation then rejects is orphaned for ever.
  v_opened := app.browser_session_open(p_project, v_site, p_purpose, null, p_by);
  if v_opened ? 'error' then return v_opened; end if;

  v_ref := app.store_secret(
    format('browser.session.%s.%s', p_project, v_site), p_jar,
    format('Signed-in browser state for %s. Established by %s.', v_site, coalesce(p_by, 'grant')));

  update public.browser_sessions
     set credential_ref = v_ref, expired_at = null, revoked_at = null,
         updated_at = app.now_utc()
   where session_id = (v_opened ->> 'session_id')::uuid;

  return jsonb_build_object('ok', true, 'session_id', v_opened -> 'session_id',
                            'site', v_site);
end;
$$;


--
-- Name: browser_session_expired(uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.browser_session_expired(p_session uuid, p_why text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  update public.browser_sessions
     set expired_at = coalesce(expired_at, app.now_utc()), updated_at = app.now_utc()
   where session_id = p_session;
  if not found then
    return jsonb_build_object('error', 'there is no session by that id');
  end if;
  return jsonb_build_object('ok', true, 'why', left(coalesce(p_why, ''), 400));
end;
$$;


--
-- Name: browser_session_forget(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.browser_session_forget(p_session uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_ref app.vault_secret_ref;
  v_site text;
begin
  select credential_ref, site into v_ref, v_site
    from public.browser_sessions where session_id = p_session;
  if not found then
    return jsonb_build_object('error', 'there is no session by that id');
  end if;

  -- The reference first, the secret second. A row pointing at a secret that is
  -- already gone raises on every read (0350); a null reference degrades alone.
  update public.browser_sessions
     set credential_ref = null, revoked_at = coalesce(revoked_at, app.now_utc()),
         updated_at = app.now_utc()
   where session_id = p_session;

  if v_ref is not null then
    delete from vault.secrets where id = v_ref::uuid;
  end if;

  return jsonb_build_object('ok', true, 'site', v_site,
    'note', format('The office can no longer sign in to %s. Nothing it already '
                   'read has been removed.', v_site));
end;
$$;


--
-- Name: browser_session_open(uuid, text, text, app.vault_secret_ref, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.browser_session_open(p_project uuid, p_site text, p_purpose text, p_ref app.vault_secret_ref, p_by text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_site text := lower(trim(coalesce(p_site, '')));
  v_id uuid;
begin
  if not exists (select 1 from public.projects where project_id = p_project) then
    return jsonb_build_object('error', 'there is no dashboard project by that id');
  end if;
  if v_site !~ '^[a-z0-9.-]+\.[a-z]{2,}$' then
    return jsonb_build_object('error',
      format('%L does not look like a site. Give me a host, like example.com.', p_site));
  end if;
  if length(trim(coalesce(p_purpose, ''))) < 12 then
    return jsonb_build_object('error',
      'say what the session is for, in a sentence. A session with no stated '
      'purpose is a session nobody can audit.');
  end if;

  insert into public.browser_sessions
    (project_id, site, purpose, credential_ref, established_by)
  values (p_project, v_site, trim(p_purpose), p_ref, coalesce(nullif(trim(coalesce(p_by, '')), ''), 'grant'))
  on conflict (project_id, site) do update
     set purpose = excluded.purpose,
         credential_ref = coalesce(excluded.credential_ref, public.browser_sessions.credential_ref),
         established_at = app.now_utc(),
         expired_at = null,
         revoked_at = null,
         updated_at = app.now_utc()
  returning session_id into v_id;

  return jsonb_build_object('ok', true, 'session_id', v_id, 'site', v_site);
end;
$_$;


--
-- Name: browser_sessions_for(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.browser_sessions_for(p_project uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(s.v order by s.ord), '[]'::jsonb) from (
    select row_number() over (order by b.established_at desc) as ord,
           jsonb_build_object(
             'session_id', b.session_id,
             'site', b.site,
             'purpose', b.purpose,
             'has_credential', b.credential_ref is not null,
             'established_at', b.established_at,
             'last_alive_at', b.last_alive_at,
             'state', case
               when b.revoked_at is not null then 'revoked'
               when b.expired_at is not null then 'signed_out'
               when b.credential_ref is null then 'needs_sign_in'
               else 'live' end,
             'actions', (select count(*)::int from public.browser_actions a
                          where a.session_id = b.session_id
                            and not app.harness_browsing(a.job_id, a.project_id))
           ) as v
      from public.browser_sessions b
     where b.project_id = p_project
  ) s;
$$;


--
-- Name: build_shots_orphaned(integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.build_shots_orphaned(p_limit integer DEFAULT 200) RETURNS TABLE(object_name text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'storage', 'pg_catalog'
    AS $$
  select o.name::text
    from storage.objects o
   where o.bucket_id = 'build'
     and not exists (
       select 1 from public.build_steps b
        where b.shot_url is not null
          and b.shot_url like '%' || o.name
     )
   order by o.created_at
   limit greatest(coalesce(p_limit, 200), 1)
$$;


--
-- Name: FUNCTION build_shots_orphaned(p_limit integer); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.build_shots_orphaned(p_limit integer) IS 'Screenshot objects in the build bucket that no build_steps row points at (#21). The handler office.prune_build_shots deletes them through the storage API; deleting the storage.objects row here would leave the bytes behind.';


--
-- Name: build_step(text, text, text, text, text, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.build_step(p_session text, p_headline text, p_towards text DEFAULT NULL::text, p_detail text DEFAULT NULL::text, p_state text DEFAULT 'doing'::text, p_produced text DEFAULT NULL::text, p_shot text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_id uuid;
begin
  insert into public.build_steps
    (session_ref, headline, towards, detail, state, produced, shot_url, finished_at)
  values (p_session, p_headline, p_towards, p_detail, p_state, p_produced, p_shot,
          case when p_state in ('done', 'blocked', 'abandoned') then app.now_utc() end)
  returning step_id into v_id;

  -- Thirty days. Older than that and it is archaeology, and the free tier is
  -- 500 MB. Pruned on write so nothing has to remember to run.
  delete from public.build_steps where started_at < app.now_utc() - interval '30 days';

  return v_id;
end;
$$;


--
-- Name: build_step_finish(uuid, text, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.build_step_finish(p_id uuid, p_state text DEFAULT 'done'::text, p_produced text DEFAULT NULL::text, p_shot text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  update public.build_steps
     set state = p_state,
         produced = coalesce(p_produced, produced),
         shot_url = coalesce(p_shot, shot_url),
         finished_at = app.now_utc()
   where step_id = p_id
  returning true
$$;


--
-- Name: calendar_ahead(integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.calendar_ahead(p_hours integer DEFAULT 24) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select jsonb_build_object(
    -- Age, always. A cached answer that does not say when it was cached is a
    -- stale answer presented as a current one, which is the defect this
    -- project keeps meeting in new costumes.
    'as_of', (select max(fetched_at) from public.calendar_events),
    'enabled', coalesce(
      (select value::text::boolean from public.system_config where key = 'calendar.enabled'), false),
    'events', coalesce((
      select jsonb_agg(row_to_json(e) order by e.starts_at)
        from (
          select summary, location, starts_at, ends_at, all_day, attendees, status, html_link
            from public.calendar_events
           where status <> 'cancelled'
             and ends_at   >= app.now_utc()
             and starts_at <= app.now_utc() + make_interval(hours => greatest(p_hours, 1))
           order by starts_at
           limit 25
        ) e
    ), '[]'::jsonb)
  )
$$;


--
-- Name: calendar_link_clear(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.calendar_link_clear(p_task_id uuid) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  delete from public.task_calendar_links where task_id = p_task_id;
$$;


--
-- Name: calendar_link_set(uuid, text, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.calendar_link_set(p_task_id uuid, p_calendar_id text, p_event_id text, p_hash text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  insert into public.task_calendar_links (task_id, calendar_id, event_id, pushed_hash, pushed_at)
  values (p_task_id, p_calendar_id, p_event_id, p_hash, app.now_utc())
  on conflict (task_id) do update
     set calendar_id = excluded.calendar_id,
         event_id    = excluded.event_id,
         pushed_hash = excluded.pushed_hash,
         pushed_at   = excluded.pushed_at;
$$;


--
-- Name: calendar_task_plan(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.calendar_task_plan() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with wanted as (
    select t.task_id,
           t.title,
           t.detail,
           t.due_on,
           p.name as project,
           md5(coalesce(t.title, '') || '|' || coalesce(t.due_on::text, '') || '|' ||
               coalesce(t.detail, '') || '|' || coalesce(p.name, '')) as hash
      from public.tasks t
      join public.projects p on p.project_id = t.project_id
     where t.due_on is not null
       and t.state in ('todo', 'doing', 'blocked')
       and not t.is_fixture
       and not p.is_fixture
  )
  select jsonb_build_object(
    'create', coalesce((
      select jsonb_agg(jsonb_build_object(
               'task_id', w.task_id, 'title', w.title, 'detail', w.detail,
               'due_on', w.due_on, 'project', w.project, 'hash', w.hash))
        from wanted w
        left join public.task_calendar_links l on l.task_id = w.task_id
       where l.task_id is null), '[]'::jsonb),
    'update', coalesce((
      select jsonb_agg(jsonb_build_object(
               'task_id', w.task_id, 'title', w.title, 'detail', w.detail,
               'due_on', w.due_on, 'project', w.project, 'hash', w.hash,
               'calendar_id', l.calendar_id, 'event_id', l.event_id))
        from wanted w
        join public.task_calendar_links l on l.task_id = w.task_id
       where l.pushed_hash is distinct from w.hash), '[]'::jsonb),
    -- A link whose task is no longer wanted. The task row may still exist
    -- (done, cancelled, or its date removed) or may be gone entirely, and the
    -- cascade takes care of the second case before we ever see it.
    'remove', coalesce((
      select jsonb_agg(jsonb_build_object(
               'task_id', l.task_id, 'calendar_id', l.calendar_id, 'event_id', l.event_id))
        from public.task_calendar_links l
        left join wanted w on w.task_id = l.task_id
       where w.task_id is null), '[]'::jsonb)
  )
$$;


--
-- Name: callback_ack(text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.callback_ack(p_bot_id text, p_action text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select jsonb_build_object(
    -- `app.resolve_secret`, the same helper `voice_refusal` uses. The token
    -- reaches the edge function and nowhere else: it is never logged, never
    -- returned to a caller that did not ask for it, and never printed.
    'token', (
      select app.resolve_secret(b.token_ref)
        from public.telegram_bots b
       where b.bot_id = p_bot_id and b.enabled and b.token_ref is not null
    ),
    'text', case p_action
      when 'useful'     then 'Noted — thank you'
      -- Says what happens next, so the question arriving in a moment reads as
      -- an answer rather than as the office starting a new conversation.
      when 'not_useful' then 'Noted. Tell me what I should have done'
      when 'undo'       then 'Undoing…'
      when 'approve'    then 'Go ahead — starting'
      when 'decline'    then 'Left alone'
      when 'mute_24h'   then 'Quiet for 24 hours'
      when 'more_detail' then 'Fetching the detail…'
      else 'Got it'
    end
  )
$$;


--
-- Name: FUNCTION callback_ack(p_bot_id text, p_action text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.callback_ack(p_bot_id text, p_action text) IS 'The toast shown the instant a Telegram button is pressed, and the token to send it with. Answering within seconds is Telegram''s requirement, so this is the webhook''s job and not the worker''s (#59).';


--
-- Name: cancel_group(uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.cancel_group(p_group uuid, p_why text DEFAULT 'the question was withdrawn'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare v_stopped integer := 0; v_job uuid;
begin
  for v_job in
    select j.job_id from public.job_branches br
      join public.jobs j on j.job_id = br.job_id
     where br.group_id = p_group
       and j.state::text not in ('complete', 'failed', 'cancelled', 'committing',
                                 'committed', 'notifying')
    union
    select g.synthesis_job_id from public.branch_groups g
     where g.group_id = p_group and g.synthesis_job_id is not null
       and (select state::text from public.jobs where job_id = g.synthesis_job_id)
             not in ('complete', 'failed', 'cancelled', 'committing', 'committed', 'notifying')
  loop
    begin
      update public.jobs set state = 'cancelled', state_reason = left(p_why, 500)
       where job_id = v_job;
      v_stopped := v_stopped + 1;
    exception when others then
      -- A state that refuses cancellation is a job mid-commit. Leave it.
      null;
    end;
  end loop;
  return jsonb_build_object('ok', true, 'stopped', v_stopped);
end;
$$;


--
-- Name: cancelling_a_question_cancels_its_branches(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.cancelling_a_question_cancels_its_branches() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
begin
  if new.state = 'cancelled' and old.state <> 'cancelled'
     and exists (select 1 from public.branch_groups where parent_job_id = new.job_id) then
    perform app.cancel_group(
      (select group_id from public.branch_groups where parent_job_id = new.job_id),
      coalesce(nullif(btrim(coalesce(new.state_reason, '')), ''), 'the question was withdrawn'));
  end if;
  return new;
end;
$$;


--
-- Name: cannot(uuid, public.impediment_kind, text, text, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.cannot(p_job_id uuid, p_kind public.impediment_kind, p_needed text, p_noticed_by text, p_detail text DEFAULT ''::text, p_understood_as text DEFAULT ''::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  j    public.jobs%rowtype;
  made public.job_impediments%rowtype;
begin
  select * into j from public.jobs where job_id = p_job_id;
  if not found then
    return jsonb_build_object('error', 'no such job');
  end if;

  insert into public.job_impediments
    (job_id, project_id, staff_slug, kind, needed_raw, detail, understood_as, noticed_by)
  values
    (p_job_id, j.project_id, j.recipient_agent, p_kind, p_needed,
     left(coalesce(p_detail, ''), 500), left(coalesce(p_understood_as, ''), 280),
     p_noticed_by)
  returning * into made;

  return jsonb_build_object(
    'impediment_id', made.impediment_id,
    'needed', made.needed,
    'counted', not made.is_fixture
  );
end;
$$;


--
-- Name: FUNCTION cannot(p_job_id uuid, p_kind public.impediment_kind, p_needed text, p_noticed_by text, p_detail text, p_understood_as text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.cannot(p_job_id uuid, p_kind public.impediment_kind, p_needed text, p_noticed_by text, p_detail text, p_understood_as text) IS 'An agent saying what it could not do, typed so it can be counted (#47). The fixture flag is derived from the job, so a verification run cannot inflate the tally.';


--
-- Name: capability_index(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.capability_index(p_staff text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select app.capability_index_core(p_staff)
      || jsonb_build_object('could', app.unused_capabilities())
$$;


--
-- Name: FUNCTION capability_index(p_staff text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.capability_index(p_staff text) IS '#51. The office''s capability index, plus `could` — reachable connector verbs nothing currently uses. Only the gap, not the whole sheet: twenty-five verbs on every prompt would cost more than they are worth, and an agent can already read its reach and its tools. Ask app.connector_sheet for the rest.';


--
-- Name: capability_index_core(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.capability_index_core(p_staff text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with connectors as (
    select k.name as service,
           (k.enabled and coalesce(h.state, 'ok') not in ('dead', 'missing')) as reachable,
           case when not k.enabled then coalesce(k.disabled_reason, 'switched off')
                when h.state in ('dead', 'missing') then coalesce(h.detail, h.state)
                else null end as detail
      from public.knowledge_connectors k
      left join lateral (
        select ch.state, ch.detail
          from public.connection_health ch
         where ch.service = k.health_service
         order by case ch.state when 'dead' then 0 when 'missing' then 1
                                when 'unknown' then 2 when 'ok' then 3 else 4 end
         limit 1
      ) h on true
     where k.connector not in ('upload', 'mcp')
  ),
  reach as (
    select * from connectors
    union all
    select * from (
      select distinct on (c.service)
             c.service,
             c.state not in ('dead', 'missing') as reachable,
             case when c.state in ('dead', 'missing') then coalesce(c.detail, c.state)
                  else null end as detail
        from public.connection_health c
       where c.service in ('Slack', 'Telegram')
         and not exists (select 1 from connectors n where n.service = c.service)
       order by c.service,
                case c.state when 'dead' then 0 when 'missing' then 1
                             when 'unknown' then 2 else 3 end
    ) surfaces
  ),
  tools as (
    select t.tool, t.level, t.enabled, t.disabled_reason,
           t.description, coalesce(t.verbs, array[]::text[]) as verbs,
           t.in_reply,
           (p_staff is null or exists (
              select 1 from public.staff_tools st
               where st.staff_slug = p_staff and st.tool = t.tool)) as granted
      from public.tool_permissions t
  ),
  declined as (
    select distinct on (r.tool)
           r.tool, r.decline_reason, r.settled_at, r.declines
      from public.tool_requests r
     where r.state = 'declined'
     order by r.tool, r.settled_at desc nulls last
  )
  select jsonb_build_object(
    'at', app.now_utc(),
    'for', coalesce(p_staff, 'the office'),
    'reach', (select coalesce(jsonb_agg(jsonb_build_object(
                'service', r.service, 'reachable', r.reachable, 'detail', r.detail)
                order by r.service), '[]'::jsonb) from reach r),
    'can', (select coalesce(jsonb_agg(jsonb_build_object(
              'tool', t.tool, 'level', t.level, 'what', t.description,
              'verbs', to_jsonb(t.verbs), 'in_reply', t.in_reply)
              order by t.tool), '[]'::jsonb)
              from tools t where t.enabled and t.granted),
    'must_ask', (select coalesce(jsonb_agg(jsonb_build_object(
                   'tool', t.tool, 'what', t.description) order by t.tool), '[]'::jsonb)
                   from tools t where t.enabled and not t.granted),
    'cannot', (select coalesce(jsonb_agg(jsonb_build_object(
                 'tool', t.tool, 'what', t.description,
                 'why', coalesce(t.disabled_reason, 'switched off'),
                 'verbs', to_jsonb(t.verbs)) order by t.tool), '[]'::jsonb)
                 from tools t where not t.enabled),
    'declined', (select coalesce(jsonb_agg(jsonb_build_object(
                   'tool', d.tool, 'why', d.decline_reason,
                   'when', d.settled_at, 'times', d.declines) order by d.tool), '[]'::jsonb)
                   from declined d)
  )
$$;


--
-- Name: FUNCTION capability_index_core(p_staff text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.capability_index_core(p_staff text) IS '#148. What the office can do, generated on every call and never stored — a capability index that can be stale is believed while wrong. Four separate answers: can / must_ask / cannot / declined, because "I may not" and "nobody may" and "we already asked" need different replies.';


--
-- Name: capacity_limit(text, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.capacity_limit(p_name text, p_default integer) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select coalesce(
    (select (value ->> p_name)::integer from public.system_config where key = 'jobs.capacity'),
    p_default
  )
$$;


--
-- Name: chores_for_credentials(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.chores_for_credentials() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  r record;
  v_key text;
  v_raised int := 0;
  v_cleared int := 0;
  v_names text[] := '{}';
begin
  for r in
    select service, credential, state, coalesce(action, '') as action,
           coalesce(owner, '') as owner
      from public.connection_health
  loop
    v_key := format('credential:%s:%s', lower(r.service), lower(r.credential));

    if r.state in ('dead', 'missing')
       and r.action <> ''
       /*
          Not a parked one. Grant asked on 6 September for Groq, OpenAI and
          OpenRouter to be left alone, and the owner column is where that
          decision lives. A chore he has already declined is the fastest way to
          make him stop reading the list.
       */
       and r.owner not ilike '%parked%'
       and r.action not ilike 'parked%'
       and r.action not ilike 'nothing%'
    then
      insert into public.tasks
        (project_id, title, detail, state, priority, assigned_to_human,
         added_by, labels, chore_key)
      values (null,
              format('Reconnect %s — %s', r.service, r.credential),
              /*
                The office's own words for what to do, verbatim. A task that
                says "fix Google" is a task he has to go and work out; the
                action column already says where the button is.
              */
              format('%s. The office cannot do this itself: %s.',
                     r.action, case r.state when 'dead' then 'the credential is refused'
                                            else 'it is not there' end),
              'todo', 20, true, 'the office', array['credential'], v_key)
      on conflict do nothing;
      if found then
        v_raised := v_raised + 1;
        v_names := v_names || format('%s / %s', r.service, r.credential);
      end if;
    else
      /*
        Healthy again, parked, or nothing to do — so the chore is finished.

        By the same pass that raises them, because a list that fills up and
        never empties is one he stops trusting, and clearing is the half nobody
        sees working.
      */
      update public.tasks
         set state = 'done', done_at = app.now_utc(), updated_at = app.now_utc()
       where chore_key = v_key and state <> 'done';
      if found then v_cleared := v_cleared + 1; end if;
    end if;
  end loop;

  return jsonb_build_object('raised', v_raised, 'cleared', v_cleared,
                            'about', to_jsonb(v_names));
end;
$$;


--
-- Name: ci_budget(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.ci_budget() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with cap as (
    select coalesce((select nullif(value #>> '{}', '')::numeric
                       from public.system_config where key = 'ci.monthly_minutes'),
                    1500)::numeric as minutes
  ), spent as (
    select app.ci_spent_this_month() as used,
           (select count(*)::int from public.ci_runs
             where settled_at is null and expires_at > app.now_utc()) as in_flight,
           (select count(*)::int from public.ci_runs
             where dispatched_at >= date_trunc('month', app.now_utc())) as runs
  )
  select jsonb_build_object(
    'cap_minutes', round(cap.minutes, 1),
    'used_minutes', round(spent.used, 1),
    'left_minutes', round(greatest(cap.minutes - spent.used, 0), 1),
    'in_flight', spent.in_flight,
    'runs_this_month', spent.runs,
    'exhausted', spent.used >= cap.minutes,
    /*
      Named so nobody reads this as GitHub's own figure. It is what the office
      believes, which is the reservation until a run says otherwise.
    */
    'source', 'the office''s own ledger, not GitHub''s billing page'
  ) from cap, spent;
$$;


--
-- Name: ci_expire_stale(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.ci_expire_stale() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_n int;
begin
  update public.ci_runs
     set settled_at = app.now_utc(), outcome = 'expired',
         detail = case when detail = '' then
           'it never reported — counted at what it reserved, because a run that '
           'died still cost something' else detail end
   where settled_at is null and expires_at <= app.now_utc();
  get diagnostics v_n = row_count;
  return jsonb_build_object('ok', true, 'expired', v_n);
end;
$$;


--
-- Name: ci_lately(integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.ci_lately(p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(x.v order by x.ord), '[]'::jsonb) from (
    select row_number() over (order by r.dispatched_at desc) as ord,
           jsonb_build_object(
             'workflow', r.workflow, 'at', r.dispatched_at, 'by', r.requested_by,
             'reason', r.reason, 'reserved', r.reserved_minutes,
             'actual', r.actual_minutes, 'outcome',
             coalesce(r.outcome, 'running'), 'detail', r.detail) as v
      from public.ci_runs r
     order by r.dispatched_at desc
     limit greatest(coalesce(p_limit, 20), 1)
  ) x;
$$;


--
-- Name: ci_may_run(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.ci_may_run(p_workflow text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  w public.ci_workflows%rowtype;
  v_cap numeric;
  v_used numeric;
  v_want numeric;
begin
  select * into w from public.ci_workflows where workflow = p_workflow;
  if not found then
    return jsonb_build_object('may', false, 'why',
      format('%L is not a workflow the office may run. The ones it may are listed '
             'in ci_workflows.', p_workflow));
  end if;
  if not w.enabled then
    return jsonb_build_object('may', false, 'why',
      format('%s is switched off: %s', p_workflow, w.disabled_reason));
  end if;

  v_cap := coalesce((select nullif(value #>> '{}', '')::numeric
                       from public.system_config where key = 'ci.monthly_minutes'), 1500);
  v_used := app.ci_spent_this_month();
  v_want := least(w.expected_minutes, w.cap_minutes);

  if v_used + v_want > v_cap then
    return jsonb_build_object('may', false, 'reserve', v_want, 'why',
      format('that would take this month past %s CI minutes — %s are already '
             'committed and this run expects %s. It resets on the first of next month.',
             round(v_cap, 0), round(v_used, 1), round(v_want, 1)));
  end if;

  return jsonb_build_object('may', true, 'reserve', v_want,
    'left_after', round(v_cap - v_used - v_want, 1));
end;
$$;


--
-- Name: ci_report(uuid, numeric, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.ci_report(p_ci_run uuid, p_minutes numeric, p_detail text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_total numeric;
  v_jobs int;
begin
  if p_minutes is null or p_minutes < 0 then
    return jsonb_build_object('error', 'a run cannot have cost less than nothing');
  end if;
  update public.ci_runs
     set actual_minutes = coalesce(actual_minutes, 0) + ceil(p_minutes),
         jobs_reported = jobs_reported + 1,
         settled_at = app.now_utc(),
         outcome = 'reported',
         detail = left(coalesce(nullif(trim(coalesce(p_detail, '')), ''), detail), 400)
   where ci_run_id = p_ci_run
  returning actual_minutes, jobs_reported into v_total, v_jobs;

  if not found then
    return jsonb_build_object('error', 'there is no dispatch by that id');
  end if;
  return jsonb_build_object('ok', true, 'total_minutes', v_total, 'jobs_reported', v_jobs);
end;
$$;


--
-- Name: ci_reserve(text, text, text, text, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.ci_reserve(p_workflow text, p_event_type text, p_reason text, p_by text, p_job uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_verdict jsonb;
  v_id uuid;
  v_minutes numeric;
begin
  -- Serialises dispatches against each other without locking anything else.
  perform pg_advisory_xact_lock(hashtext('app.ci_reserve'));

  v_verdict := app.ci_may_run(p_workflow);
  if (v_verdict ->> 'may') is distinct from 'true' then
    return v_verdict;
  end if;
  v_minutes := (v_verdict ->> 'reserve')::numeric;

  insert into public.ci_runs
    (workflow, event_type, requested_by, job_id, reason, reserved_minutes, expires_at)
  values (p_workflow, p_event_type,
          coalesce(nullif(trim(coalesce(p_by, '')), ''), 'grant'), p_job,
          left(coalesce(p_reason, ''), 400), v_minutes,
          app.now_utc() + interval '6 hours')
  returning ci_run_id into v_id;

  return jsonb_build_object('may', true, 'ci_run_id', v_id, 'reserved', v_minutes);
end;
$$;


--
-- Name: ci_spent_this_month(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.ci_spent_this_month() RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(sum(
           case when r.settled_at is null then r.reserved_minutes
                else coalesce(r.actual_minutes, r.reserved_minutes) end), 0)::numeric
    from public.ci_runs r
   where r.dispatched_at >= date_trunc('month', app.now_utc());
$$;


--
-- Name: claim_delivery(text, text, text, text, text, text, uuid, uuid, uuid, interval); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.claim_delivery(p_channel text, p_dedupe_key text, p_account_ref text, p_target_ref text, p_purpose text, p_thread_ref text DEFAULT NULL::text, p_staff_id uuid DEFAULT NULL::uuid, p_correlation_id uuid DEFAULT NULL::uuid, p_job_id uuid DEFAULT NULL::uuid, p_lease interval DEFAULT '00:02:00'::interval) RETURNS TABLE(delivery_id uuid, outcome text, message_ref text, attempt integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_row public.deliveries;
begin
  /*
    HARNESS TRAFFIC MAY NOT REACH A PRODUCTION DESTINATION. Ever, by anybody.

    This is the whole of the fix for the reminder that read "Remind me
    khgkowx8" on Grant's real Telegram. That job carried `is_fixture = true`
    AND `app.harness_job() = true`, and it was delivered anyway, because
    nothing on this path had ever asked. 162 harness deliveries had been sent
    to real destinations across 42 runs before anybody counted; 87 of them to
    Grant.

    It is DEFAULT DENY and it lives here rather than in a caller, because a
    guard in one of two call paths guards nothing and because cleanup is
    structurally too late: the send happened 0.26 seconds after the output.

    Suppressed rather than raised. A refusal that throws would fail the job and
    tell a suite its product is broken; `suppressed` is an outcome every sender
    already understands, it records the ATTEMPT where `check:leaks` can count
    it, and the suite carries on.
  */
  if not app.deliverable_to(p_job_id, p_channel, p_target_ref) then
    insert into public.deliveries
      (channel, dedupe_key, account_ref, target_ref, thread_ref, staff_id,
       correlation_id, job_id, purpose, state, suppressed_reason, lease_expires_at)
    values
      (p_channel, p_dedupe_key, p_account_ref, p_target_ref, p_thread_ref,
       p_staff_id, p_correlation_id, p_job_id, p_purpose, 'suppressed',
       'harness traffic may not reach a production destination', app.now_utc())
    on conflict (dedupe_key) do nothing
    returning * into v_row;
    if not found then
      select * into v_row from public.deliveries d where d.dedupe_key = p_dedupe_key;
    end if;
    return query select v_row.delivery_id, 'suppressed'::text, null::text, v_row.attempt;
    return;
  end if;

  -- The insert IS the lock. Concurrent duplicates cannot both succeed here.
  insert into public.deliveries
    (channel, dedupe_key, account_ref, target_ref, thread_ref, staff_id,
     correlation_id, job_id, purpose, lease_expires_at)
  values
    (p_channel, p_dedupe_key, p_account_ref, p_target_ref, p_thread_ref,
     p_staff_id, p_correlation_id, p_job_id, p_purpose, app.now_utc() + p_lease)
  on conflict (dedupe_key) do nothing
  returning * into v_row;

  if found then
    return query select v_row.delivery_id, 'claimed'::text, null::text, v_row.attempt;
    return;
  end if;

  select * into v_row from public.deliveries d
    where d.dedupe_key = p_dedupe_key
    for update;

  if v_row.state = 'sent' then
    return query select v_row.delivery_id, 'already_sent'::text, v_row.message_ref, v_row.attempt;
    return;
  elsif v_row.state = 'suppressed' then
    return query select v_row.delivery_id, 'suppressed'::text, null::text, v_row.attempt;
    return;
  elsif v_row.state = 'failed' then
    return query select v_row.delivery_id, 'failed'::text, null::text, v_row.attempt;
    return;
  end if;

  if v_row.lease_expires_at > app.now_utc() then
    return query select v_row.delivery_id, 'held'::text, null::text, v_row.attempt;
    return;
  end if;

  -- The reclaim. Fully qualified, because the bare column name is this
  -- function's own OUT parameter (0035).
  update public.deliveries
     set attempt = public.deliveries.attempt + 1,
         lease_expires_at = app.now_utc() + p_lease
   where public.deliveries.delivery_id = v_row.delivery_id
  returning * into v_row;

  return query select v_row.delivery_id, 'reclaimed'::text, null::text, v_row.attempt;
end;
$$;


--
-- Name: claim_pending_notification(text, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.claim_pending_notification(p_worker text, p_lease_seconds integer DEFAULT 120) RETURNS TABLE(job_id uuid, correlation_id uuid, project_id uuid, kind text, output_id uuid)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'app', 'public'
    AS $$
declare
  r record;
begin
  select j.job_id, j.correlation_id, j.project_id, j.kind
    into r
  from public.jobs j
  where j.state = 'notifying'
    and (j.leased_until is null or j.leased_until < now())
  order by j.updated_at
  for update skip locked
  limit 1;

  if not found then
    return;
  end if;

  update public.jobs j
     set leased_by = p_worker,
         leased_until = now() + make_interval(secs => p_lease_seconds)
   where j.job_id = r.job_id;

  return query
    select r.job_id, r.correlation_id, r.project_id, r.kind,
           (select o.output_id from public.outputs o
             where o.job_id = r.job_id
             order by o.created_at desc limit 1);
end;
$$;


--
-- Name: FUNCTION claim_pending_notification(p_worker text, p_lease_seconds integer); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.claim_pending_notification(p_worker text, p_lease_seconds integer) IS 'One job whose work is committed and whose delivery is outstanding. Leased, because delivery being idempotent stops a duplicate MESSAGE and a lease stops the duplicate ATTEMPT.';


--
-- Name: claim_undo(uuid, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.claim_undo(p_action_id uuid, p_requested_by text, p_source text DEFAULT NULL::text, OUT outcome public.undo_status, OUT won boolean) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_action public.undoable_actions;
begin
  select * into v_action from public.undoable_actions where action_id = p_action_id;
  if not found then
    raise exception 'no undoable action %', p_action_id
      using errcode = 'no_data_found';
  end if;

  -- Decide first, so the claim row can be written once and never touched again
  -- (0030: the table is append-only without exception).
  if v_action.status = 'not_undoable' then
    outcome := 'not_undoable';
  elsif v_action.status = 'undone' then
    outcome := 'undone';
  elsif v_action.status = 'expired'
     or (v_action.undo_deadline is not null and v_action.undo_deadline <= app.now_utc()) then
    outcome := 'expired';
  else
    outcome := 'undone';
  end if;

  -- The serialisation point. Exactly one caller inserts.
  insert into public.undo_requests (action_id, requested_by, source, outcome)
  values (p_action_id, p_requested_by, p_source, outcome)
  on conflict (action_id) do nothing;

  if not found then
    -- A duplicate. Report the action's current status and, crucially, that
    -- this caller is not the one that acts.
    won := false;
    outcome := (select status from public.undoable_actions where action_id = p_action_id);
    return;
  end if;

  won := true;

  -- We won the claim, so we are the one that changes the world.
  if outcome = 'undone' and v_action.status <> 'undone' then
    update public.undoable_actions
    set status = 'undone', undone_at = app.now_utc()
    where action_id = p_action_id;
  elsif outcome = 'expired' and v_action.status <> 'expired' then
    update public.undoable_actions set status = 'expired' where action_id = p_action_id;
  end if;
end;
$$;


--
-- Name: FUNCTION claim_undo(p_action_id uuid, p_requested_by text, p_source text, OUT outcome public.undo_status, OUT won boolean); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.claim_undo(p_action_id uuid, p_requested_by text, p_source text, OUT outcome public.undo_status, OUT won boolean) IS 'The claim, with the half `request_undo` cannot express: `won` says whether THIS caller is the one that may perform the reversal. Every duplicate gets false, and false is not an error.';


--
-- Name: classify_failure(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.classify_failure(p_message text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    when p_message is null or btrim(p_message) = '' then 'unknown'
    when p_message ~* '(quota|allowance|rate.?limit|usage limit|limit is spent|too many requests|429)'
      then 'quota'
    when p_message ~* '(no .{0,20}credential|not configured|missing token|no token|no api key)'
      then 'no_credential'
    when p_message ~* '(unauthori[sz]ed|forbidden|invalid.{0,10}(token|key|credential)|401|403)'
      then 'auth'
    when p_message ~* '(timed? ?out|timeout|deadline exceeded|abort)' then 'timeout'
    when p_message ~* '(not found|no such|does not exist|404|is no longer)' then 'not_found'
    when p_message ~* '(unexpected shape|could not parse|invalid json|malformed|is missing )'
      then 'bad_shape'
    when p_message ~* '(econnrefused|enotfound|network|dns|fetch failed|socket|502|503|504)'
      then 'unreachable'
    when p_message ~* '(refused|rejected|declined|denied|not permitted|violates)' then 'refused'
    else 'unknown'
  end
$$;


--
-- Name: FUNCTION classify_failure(p_message text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.classify_failure(p_message text) IS '#132. Nine coarse words, because a signature is only useful if the same failure produces the same row -- and an error message carries ids and timestamps, so its first line makes eleven rows for one problem.';


--
-- Name: config_key_is_not_a_schema(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.config_key_is_not_a_schema() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_prefix text := split_part(new.key, '.', 1);
begin
  if exists (select 1 from pg_namespace where nspname = v_prefix) then
    raise exception
      'a config key may not start with a schema name (%): a function reading '
      '''%'' makes verify:schema report a dangling reference to a relation '
      'that does not exist. Use a DOMAIN prefix — telegram., voice., web., '
      'worker. — the way every other key does.', v_prefix, new.key
      using errcode = '23514';
  end if;
  return new;
end
$$;


--
-- Name: FUNCTION config_key_is_not_a_schema(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.config_key_is_not_a_schema() IS '0493. `app.base_url` made a correct function look like it referenced a missing table. `vault.naming` is the same shape, unreferenced so far, and left alone deliberately.';


--
-- Name: connect_provider_key(text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.connect_provider_key(p_provider text, p_secret_name text) RETURNS app.vault_secret_ref
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_ref app.vault_secret_ref;
begin
  if not exists (select 1 from public.providers where provider = p_provider) then
    raise exception 'no provider called %', p_provider
      using hint = 'The providers this office knows are in public.providers.',
            errcode = '23503';
  end if;

  select id::app.vault_secret_ref into v_ref
    from vault.secrets where name = p_secret_name;

  if v_ref is null then
    -- Name what is missing and how to supply it. A credential that is not
    -- there is the commonest state during setup, not an exceptional one.
    raise exception 'there is no secret called % in this office''s vault', p_secret_name
      using hint = 'Store it first: npm run fresh:secret -- ' || p_secret_name,
            errcode = '23503';
  end if;

  update public.providers set secret_ref = v_ref, updated_at = app.now_utc()
   where provider = p_provider;

  return v_ref;
end
$$;


--
-- Name: FUNCTION connect_provider_key(p_provider text, p_secret_name text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.connect_provider_key(p_provider text, p_secret_name text) IS 'Point a provider at a credential already in the vault. Takes the secret''s NAME and returns its REFERENCE: the caller chose the name, and must never be handed the value. Without this a stored inference key is connected to nothing and every job fails for want of a credential in the same database.';


--
-- Name: connector_label(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.connector_label(p_connector text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case lower(coalesce(p_connector, ''))
    when 'notebooklm' then 'NotebookLM'
    when 'notion'     then 'Notion'
    when 'drive'      then 'Google Drive'
    when 'gmail'      then 'Gmail'
    when 'calendar'   then 'Calendar'
    when 'github'     then 'GitHub'
    when 'slack'      then 'Slack'
    when 'upload'     then 'Uploads'
    when 'mcp'        then 'MCP'
    when ''           then 'Unattached'
    else initcap(p_connector)
  end
$$;


--
-- Name: FUNCTION connector_label(p_connector text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.connector_label(p_connector text) IS 'The capitalisation a vendor uses about itself, in one place so the card, the sources row and a document byline cannot disagree (#68).';


--
-- Name: connector_purpose(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.connector_purpose(p_connector text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case lower(coalesce(p_connector, ''))
    when 'notebooklm' then 'Reads the source corpus, and makes the audio overviews.'
    when 'notion'     then 'Where project pages, docs and tasks are mirrored.'
    when 'drive'      then 'A folder per project, watched for anything that lands in it.'
    when 'github'     then 'Reads this repository — issues, code and releases.'
    when 'upload'     then 'Anything handed straight to the office, with no service behind it.'
    when 'mcp'        then 'Lets Claude and ChatGPT read the office directly.'
    when 'gmail'      then 'Reads mail. Sending needs your say-so.'
    when 'calendar'   then 'Your day, refreshed hourly.'
    when 'slack'      then 'The office floor — a channel per project.'
    else ''
  end
$$;


--
-- Name: FUNCTION connector_purpose(p_connector text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.connector_purpose(p_connector text) IS 'One line saying what a connector is FOR, for the settings card (#68). knowledge_connectors.notes is engineering reasoning and stays that way; truncating it produced sentences that stopped mid-clause.';


--
-- Name: connector_sheet(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.connector_sheet(p_connector text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'connector', c.connector,
           'name', k.name,
           'verb', c.verb,
           'returns', c.returns,
           'reach', c.reach,
           'cost', c.cost_note,
           'we_use_it_for', nullif(c.used_by, ''),
           'how_we_know', c.verified_by
         ) order by c.connector,
           -- Reachable things first: an agent reading its own sheet should
           -- meet what it CAN do before what it cannot.
           case c.reach when 'api' then 0 when 'unofficial' then 1
                        when 'browser_only' then 2 else 3 end,
           c.verb), '[]'::jsonb)
    from public.connector_capabilities c
    join public.knowledge_connectors k on k.connector = c.connector
   where p_connector is null or c.connector = p_connector
$$;


--
-- Name: contact_labels(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.contact_labels(p_owner text DEFAULT 'grant'::text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', l.label_id, 'name', l.name, 'hue', l.hue
         ) order by l.sort, l.name), '[]'::jsonb)
    from public.contact_labels l
   where l.owner = coalesce(nullif(btrim(p_owner), ''), 'grant')
$$;


--
-- Name: container_refs(uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.container_refs(p_project_id uuid, p_connector text) RETURNS TABLE(external_ref text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select a.external_ref
    from public.project_attachments a
   where a.project_id = p_project_id
     and a.connector = p_connector
     and a.external_ref is not null
$$;


--
-- Name: FUNCTION container_refs(p_project_id uuid, p_connector text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.container_refs(p_project_id uuid, p_connector text) IS '#19. A Notion object whose id is one of these is the attachment itself — the database the office writes into — not a document in it. Storing one puts an index of row titles in the corpus, where it matches every search for any row and re-syncs for ever because its fingerprint tracks every rename.';


--
-- Name: containers_stored_as_documents(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.containers_stored_as_documents() RETURNS TABLE(project_slug text, connector text, title text, external_ref text, since timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p.slug, d.connector, d.title, d.external_ref, d.created_at
    from public.documents d
    join public.project_attachments a
      on a.project_id = d.project_id and a.connector = d.connector
     and a.external_ref = d.external_ref
    join public.projects p on p.project_id = d.project_id
   order by d.created_at desc
$$;


--
-- Name: FUNCTION containers_stored_as_documents(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.containers_stored_as_documents() IS 'ADR-0013 and 0283: a connector container is a thing a dashboard project is ATTACHED to, never a document in its corpus. This should always return zero rows. It returned three after a duty ran on a worker deployed before 0283, which is why it exists as a query and not only as a check (0305).';


--
-- Name: conversation_before(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.conversation_before(p_command_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  with self as (
    select origin_channel, split_part(origin_ref, ':', 1) as chat,
           coalesce(subject, actor) as who, received_at
      from public.inbound_commands where command_id = p_command_id
  ),
  turns as (
    select c.received_at,
           coalesce(c.transcript, c.instruction) as said,
           -- The answer that went out for that turn, when there was one. Read
           -- from `outputs` through the job, because that is the text actually
           -- delivered rather than a second copy of it.
           (select left(o.body, 700) from public.outputs o
             where o.job_id = c.job_id order by o.created_at desc limit 1) as answered
      from public.inbound_commands c, self
     where c.origin_channel = self.origin_channel
       and split_part(c.origin_ref, ':', 1) = self.chat
       and coalesce(c.subject, c.actor) = self.who
       and c.callback_action is null
       and c.command_id <> p_command_id
       and c.received_at < self.received_at
       and c.received_at > self.received_at - make_interval(
             mins => coalesce(
               (select value::text::integer from public.system_config
                 where key = 'conversation.window_minutes'), 30))
     order by c.received_at desc
     limit coalesce(
       (select value::text::integer from public.system_config
         where key = 'conversation.max_turns'), 12)
  )
  select coalesce(
    jsonb_agg(jsonb_build_object('said', said, 'answered', answered)
              order by received_at asc),
    '[]'::jsonb)
    from turns
   where coalesce(trim(said), '') <> ''
$$;


--
-- Name: FUNCTION conversation_before(p_command_id uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.conversation_before(p_command_id uuid) IS 'The recent turns of one chat with one person, oldest first, with what we answered. Read by the instruction handler so a correction is understood as a correction rather than answered as a standalone sentence.';


--
-- Name: conversation_channels(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.conversation_channels() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  with want as (
    select * from (values
      ('slack',    'Slack',    'Slack'),
      ('telegram', 'Telegram', 'Telegram'),
      ('voice',    'Voice',    'Twilio'),
      ('teamhq',   'This dashboard', null)
    ) as t(channel, label, health_service)
  ),
  cred as (
    select w.channel,
           min(case h.state
                 when 'dead' then 0 when 'missing' then 1 when 'unknown' then 2
                 when 'parked' then 3 when 'ok' then 4 when 'attested' then 5
                 else 6 end) filter (where h.state is not null) as rank,
           max(h.checked_at) as checked_at,
           (array_agg(h.detail order by
              case h.state when 'dead' then 0 when 'missing' then 1 else 9 end))[1] as detail
      from want w
      left join public.connection_health h on h.service = w.health_service
     group by w.channel
  ),
  traffic as (
    select c.origin_channel as channel,
           count(*) as messages,
           max(c.received_at) as last_at
      from public.inbound_commands c
      left join public.jobs j on j.job_id = c.job_id
     where not app.harness_job(c.job_id)
     group by c.origin_channel
  ),
  trouble as (
    select d.channel,
           count(*) as recent_failures,
           max(d.updated_at) as last_failure,
           (array_agg(d.error_code order by d.updated_at desc))[1] as last_error
      from public.deliveries d
      join public.jobs j on j.job_id = d.job_id
     where d.state = 'failed'
       and not app.harness_job(j.job_id)
       and d.updated_at > app.now_utc() - interval '24 hours'
     group by d.channel
  )
  select coalesce(jsonb_agg(row order by row->>'channel'), '[]'::jsonb)
    from (
      select jsonb_build_object(
        'channel', w.channel,
        'label',   w.label,
        'messages', coalesce(t.messages, 0),
        'last_at',  t.last_at,
        'recent_failures', coalesce(tr.recent_failures, 0),
        'last_error', tr.last_error,
        'checked_at', c.checked_at,
        'state', case
          when w.health_service is null then 'here'
          when c.rank is null then 'unchecked'
          when c.rank <= 1 then
            case when coalesce(t.messages, 0) > 0 then 'disconnected' else 'never' end
          when coalesce(tr.recent_failures, 0) > 0 then 'degraded'
          when coalesce(t.messages, 0) = 0 then 'quiet'
          else 'carrying'
        end,
        'says', case
          when w.health_service is null then
            'You are reading it. Everything said here is part of the same conversation.'
          when c.rank is null then
            case when coalesce(t.messages, 0) > 0
              then 'Carrying messages, but nothing here checks the credential — so this '
                   || 'is what the traffic says, not what a probe says.'
              else 'Nothing checks this one, and nothing has come through it.'
            end
          when c.rank <= 1 then
            case when coalesce(t.messages, 0) > 0
              then 'Not connected any more. Everything already said is kept — reconnect and it carries on.'
              else 'Not connected yet. Connect it and the office can reach you there.'
            end
          when coalesce(tr.recent_failures, 0) > 0 then
            'Connected, but the provider is refusing messages. Nothing is lost; they are waiting.'
          when coalesce(t.messages, 0) = 0 then
            'Connected and ready. Nothing has come through it yet.'
          else 'Connected and carrying the conversation.'
        end
      ) as row
        from want w
        left join cred c on c.channel = w.channel
        left join traffic t on t.channel = w.channel
        left join trouble tr on tr.channel = w.channel
    ) rows
$$;


--
-- Name: FUNCTION conversation_channels(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.conversation_channels() IS 'Issue #198. Which state each conversation surface is in — never, quiet, carrying, degraded or disconnected — from the credential, the traffic and the last day of delivery failures together. Derived, never stored.';


--
-- Name: conversation_extent(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.conversation_extent(p_command_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  with self as (
    select origin_channel, split_part(origin_ref, ':', 1) as chat,
           coalesce(subject, actor) as who, received_at
      from public.inbound_commands where command_id = p_command_id
  ),
  mine as (
    select c.received_at
      from public.inbound_commands c, self
     where c.origin_channel = self.origin_channel
       and split_part(c.origin_ref, ':', 1) = self.chat
       and coalesce(c.subject, c.actor) = self.who
       and c.callback_action is null
       and c.received_at <= self.received_at
  )
  select jsonb_build_object(
    'turns_total', (select count(*)::int from mine),
    'oldest_minutes_ago',
      coalesce((select round(extract(epoch from (app.now_utc() - min(received_at))) / 60)::int
                  from mine), 0),
    'window_turns', coalesce(
      (select value::text::integer from public.system_config
        where key = 'conversation.max_turns'), 12),
    'window_minutes', coalesce(
      (select value::text::integer from public.system_config
        where key = 'conversation.window_minutes'), 30)
  )
$$;


--
-- Name: conversation_growth(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.conversation_growth() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  with per_surface as (
    select
      c.origin_channel as surface,
      count(*) as rows,
      min(c.received_at) as first_seen,
      max(c.received_at) as last_seen,
      -- At least one day, so a surface that started this morning reports its
      -- own count rather than dividing by zero and claiming infinity.
      greatest(
        1,
        ceil(extract(epoch from (max(c.received_at) - min(c.received_at))) / 86400.0)
      ) as days
      from public.inbound_commands c
      left join public.jobs j on j.job_id = c.job_id
     where coalesce(j.is_fixture, false) = false
     group by c.origin_channel
  ),
  sizes as (
    select
      pg_total_relation_size('public.inbound_commands') as inbound_bytes,
      pg_total_relation_size('public.outputs') as outputs_bytes,
      pg_database_size(current_database()) as db_bytes,
      (select count(*) from public.inbound_commands) as inbound_rows,
      (select count(*) from public.outputs) as output_rows
  ),
  rate as (
    select
      coalesce(sum(p.rows / p.days), 0) as messages_a_day
      from per_surface p
  )
  select jsonb_build_object(
    'measured_at', now(),
    'surfaces', coalesce(
      (select jsonb_agg(jsonb_build_object(
          'surface',   p.surface,
          'rows',      p.rows,
          'first_seen', p.first_seen,
          'last_seen',  p.last_seen,
          'a_day',     round((p.rows / p.days)::numeric, 1)
        ) order by p.rows desc)
         from per_surface p),
      '[]'::jsonb),
    'messages_a_day', round((select messages_a_day from rate)::numeric, 1),
    'bytes_a_message', case
      when (select inbound_rows + output_rows from sizes) = 0 then 0
      else round(
        ((select inbound_bytes + outputs_bytes from sizes)::numeric
          / (select inbound_rows + output_rows from sizes)::numeric), 0)
    end,
    'db_bytes', (select db_bytes from sizes),
    'tier_bytes', 500 * 1024 * 1024,
    /*
      Years of room at the CURRENT rate, which is the only honest projection —
      a rate measured over ten days cannot be extrapolated with a growth curve
      it has never demonstrated. Two message rows per message (his and the
      answer) is the assumption, and it is stated rather than buried.
    */
    'years_of_room', case
      when (select messages_a_day from rate) <= 0 then null
      else round(
        ((500 * 1024 * 1024 - (select db_bytes from sizes))::numeric
          / greatest(1,
              (select messages_a_day from rate)::numeric * 2
              * greatest(1, case
                  when (select inbound_rows + output_rows from sizes) = 0 then 1
                  else ((select inbound_bytes + outputs_bytes from sizes)::numeric
                        / (select inbound_rows + output_rows from sizes)::numeric)
                end)
              * 365)
        ), 1)
    end
  )
$$;


--
-- Name: FUNCTION conversation_growth(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.conversation_growth() IS 'Issue #204. How fast the conversation is growing, per surface, and how much room is left at that rate. Measured rather than guessed, and readable without an agent.';


--
-- Name: conversation_history(uuid, integer, timestamp with time zone); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.conversation_history(p_project_id uuid, p_limit integer DEFAULT 50, p_before timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  with bounded as (select greatest(1, least(coalesce(p_limit, 50), 200)) as n),
  said as (
    select
      c.received_at as at,
      jsonb_build_object(
        'message_id',   c.command_id,
        'kind',         'said',
        'at',           c.received_at,
        'from',         'grant',
        'name',         'Grant',
        -- A voice note's transcript IS the message; the instruction column
        -- holds a placeholder for one. 0089's six-messages-in-43-seconds.
        'body',         coalesce(nullif(btrim(c.transcript), ''), c.instruction),
        'surface',      c.origin_channel,
        'addressed_to', c.addressed_to,
        'spoken',       c.voice_file_id is not null,
        -- 0340. Reconstructed history is marked so a reader can say so.
        'backfilled',   coalesce((c.context->>'backfilled')::boolean, false)
      ) as v
      from public.inbound_commands c
      left join public.jobs j on j.job_id = c.job_id
     where c.project_id = p_project_id
       and coalesce(j.is_fixture, false) = false
       and (p_before is null or c.received_at < p_before)
     order by c.received_at desc
     limit (select n from bounded)
  ),
  answered as (
    select
      o.created_at as at,
      jsonb_build_object(
        'message_id',    o.output_id,
        'kind',          'answered',
        'at',            o.created_at,
        'from',          coalesce(s.slug, 'the-office'),
        'name',          coalesce(s.name, 'The team'),
        'body',          o.body,
        'confidence',    o.confidence::text,
        'evidence',      o.evidence::text,
        'deterministic', o.deterministic,
        'job',           o.job_id,
        /*
          Whether this answer actually reached him (#202).

          A LEFT JOIN over the job's deliveries, aggregated — one answer can go
          to several surfaces, and #202 is explicit that one surface failing
          must not stop the others. So this reports the worst outcome across
          them rather than the first: an answer that reached Telegram and not
          Slack is partly delivered, and saying "delivered" would be a claim.

          Null when there are no delivery rows at all, which is the ordinary
          case for an answer read here in the studio — the studio is not a
          delivery, and marking every one of them "undelivered" would be the
          alarming wording for the normal state, which is #119's mistake.
        */
        'delivery',      dstate.worst,
        'undelivered',   coalesce(dstate.failed, 0)
      ) as v
      from public.outputs o
      join public.jobs j on j.job_id = o.job_id
      left join public.staff s on s.staff_id = o.staff_id
      left join lateral (
        select
          count(*) filter (where d.state = 'failed') as failed,
          case
            when count(*) filter (where d.state = 'failed') > 0 then 'failed'
            when count(*) filter (where d.state = 'claimed') > 0 then 'sending'
            when count(*) > 0 then 'sent'
            else null
          end as worst
          from public.deliveries d
         where d.job_id = o.job_id
      ) dstate on true
       -- An OR, not a coalesce: see 0344. A function wrapped around the column
       -- is opaque to the planner and reads every job in the table.
     where (
             j.project_id = p_project_id
             or (j.project_id is null and p_project_id = app.unnamed_project())
           )
       and not j.is_fixture
       and (p_before is null or o.created_at < p_before)
     order by o.created_at desc
     limit (select n from bounded)
  ),
  recent as (
    select at, v
      from (select at, v from said union all select at, v from answered) both_sides
     order by at desc
     limit (select n from bounded)
  )
  -- Named column in the aggregate, per 0306. Ascending, because the window was
  -- taken from the recent end but a conversation is read forwards.
  select coalesce(jsonb_agg(r.v order by r.at), '[]'::jsonb) from recent r
$$;


--
-- Name: create_automation(text, text, integer, text, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.create_automation(p_slug text, p_instruction text, p_every_minutes integer DEFAULT 1440, p_at_time text DEFAULT NULL::text, p_who text DEFAULT NULL::text, p_by text DEFAULT 'grant'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
declare
  v_project uuid;
  v_name    text;
  v_staff   uuid;
  v_named   text := nullif(btrim(coalesce(p_who, '')), '');
  v_what    text := btrim(coalesce(p_instruction, ''));
  v_at      time := case when btrim(coalesce(p_at_time, '')) = '' then null
                         else btrim(p_at_time)::time end;
  v_stem    text;
  v_slug    text;
  v_n       int := 1;
  v_id      uuid;
begin
  select project_id, name into v_project, v_name
    from public.projects where slug = p_slug and status <> 'archived';
  if v_project is null then
    return jsonb_build_object('ok', false, 'error', format('no active project called %s', p_slug));
  end if;

  -- Twenty characters, matching `responsibilities_description_substantive`.
  -- Checked here so the message is a sentence rather than a constraint name;
  -- the column still enforces it, which is what makes this a better error and
  -- not the only guard.
  if length(v_what) < 20 then
    return jsonb_build_object(
      'ok', false,
      'error', 'Say what should happen in a sentence — this is the instruction the team will be given.');
  end if;

  if v_named is not null then
    select staff_id into v_staff from public.staff where slug = v_named and active;
    if v_staff is null then
      return jsonb_build_object('ok', false, 'error', format('nobody here is called %s', v_named));
    end if;
    -- An automation addressed to somebody who is not on this project would
    -- never produce anything, and the reason would be two tables away. 0323's
    -- rule, enforced at the point the decision is made.
    if not (v_named = any (app.staff_on_project(v_project))) then
      return jsonb_build_object(
        'ok', false,
        'error', format('%s is not on this project — put them on it first, in Team.', v_named));
    end if;
  else
    -- See the header. Not a placeholder: this is who actually has it.
    select staff_id into v_staff from public.staff where slug = 'chief-of-staff';
  end if;

  if p_every_minutes < 10 or p_every_minutes > 20160 then
    return jsonb_build_object(
      'ok', false,
      'error', 'Anything from every ten minutes to once a fortnight.');
  end if;
  -- `responsibilities_one_schedule`. A time of day only means something on a
  -- period of a day or more; "every hour at 09:00" is two schedules.
  if v_at is not null and p_every_minutes < 1440 then
    return jsonb_build_object(
      'ok', false,
      'error', 'A time of day needs a daily or slower schedule.');
  end if;

  v_stem := regexp_replace(
              regexp_replace(lower(btrim(coalesce(v_name, 'project'))), '[^a-z0-9]+', '-', 'g'),
              '(^-+|-+$)', '', 'g');
  v_stem := left(coalesce(nullif(v_stem, ''), 'project'), 40) || '-auto';
  v_slug := v_stem;
  while exists (select 1 from public.responsibilities where slug = v_slug) loop
    v_n := v_n + 1;
    v_slug := v_stem || '-' || v_n::text;
  end loop;

  insert into public.responsibilities
    (slug, staff_id, project_id, description, job_kind, period_minutes, at_time,
     enabled, pinned_config, recipient_agent, created_by)
  values
    (v_slug, v_staff, v_project, v_what, 'office.instruction', p_every_minutes, v_at,
     true, jsonb_build_object('instruction', v_what), v_named, p_by)
  returning responsibility_id into v_id;

  return jsonb_build_object(
    'ok', true, 'automation', v_slug, 'id', v_id,
    'whose', coalesce(v_named, 'chief-of-staff'),
    'when', app.say_schedule(p_every_minutes, v_at, 'UTC'));
end;
$_$;


--
-- Name: create_temporary_specialist(text, text, text, text, text[], text, text, timestamp with time zone, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.create_temporary_specialist(p_slug text, p_name text, p_title text, p_responsibilities text, p_expertise text[], p_communication_style text, p_justification text, p_expires_at timestamp with time zone, p_job_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_id uuid;
begin
  if p_expires_at is null or p_expires_at <= app.now_utc() then
    raise exception
      'a temporary specialist must expire in the future (got %). §9 keeps the '
      'specialist set small, and an expiry in the past would make a permanent '
      'role by accident.', p_expires_at
      using errcode = 'check_violation';
  end if;

  insert into public.staff
    (slug, name, title, permanent, responsibilities, expertise,
     communication_style, justification, expires_at, requested_for_job)
  values
    (p_slug, p_name, p_title, false, p_responsibilities, p_expertise,
     p_communication_style, p_justification, p_expires_at, p_job_id)
  returning staff_id into v_id;

  return v_id;
end;
$$;


--
-- Name: FUNCTION create_temporary_specialist(p_slug text, p_name text, p_title text, p_responsibilities text, p_expertise text[], p_communication_style text, p_justification text, p_expires_at timestamp with time zone, p_job_id uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.create_temporary_specialist(p_slug text, p_name text, p_title text, p_responsibilities text, p_expertise text[], p_communication_style text, p_justification text, p_expires_at timestamp with time zone, p_job_id uuid) IS 'The only route by which the application role may add staff, and it can only add TEMPORARY staff. `permanent` is hard-coded false here rather than passed in: a parameter would be an argument, and an argument can be true.';


--
-- Name: credential_clean(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.credential_clean(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$ select regexp_replace(coalesce(p_value, ''), '[\s ​-‏﻿]', '', 'g') $$;


--
-- Name: FUNCTION credential_clean(p_value text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.credential_clean(p_value text) IS 'Strip every space, tab, newline, non-breaking space and zero-width character from a pasted credential (0359, 0377). One definition, so the Slack form and the Google form cannot disagree about what is invisible.';


--
-- Name: credential_shape(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.credential_shape(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select case
    when app.credential_clean(p_value) ~* '^GOCSPX-'      then 'a Google client secret (GOCSPX-)'
    when app.credential_clean(p_value) ~* '^ya29\.'       then 'a Google access token (ya29.)'
    when app.credential_clean(p_value) ~  '^1//'          then 'a Google refresh token'
    when app.credential_clean(p_value) ~* '^xoxb-'        then 'a Slack bot token (xoxb-)'
    when app.credential_clean(p_value) ~* '^xoxp-'        then 'a Slack user token (xoxp-)'
    when app.credential_clean(p_value) ~* '^xapp-'        then 'a Slack app-level token (xapp-)'
    when app.credential_clean(p_value) ~* '^xoxe'         then 'a Slack configuration token (xoxe-)'
    when app.credential_clean(p_value) ~  '^gh[pousr]_'   then 'a GitHub token'
    when app.credential_clean(p_value) ~  '^github_pat_'  then 'a GitHub personal access token'
    when app.credential_clean(p_value) ~  '^(secret_|ntn_)' then 'a Notion integration token'
    when app.credential_clean(p_value) ~  '^sk-'          then 'an API secret key (sk-)'
    when app.credential_clean(p_value) ~  '^AIza'         then 'a Google API key (AIza)'
    when app.credential_clean(p_value) ~  '^eyJ[A-Za-z0-9_-]{10,}\.' then 'a signed token (a JWT)'
    else null
  end
$$;


--
-- Name: FUNCTION credential_shape(p_value text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.credential_shape(p_value text) IS 'The CLASS of credential a pasted value looks like, or null. Returns a description a person can act on and never any characters from the value (0359, 0377). A prefix is public; what follows it is the credential.';


--
-- Name: current_project(public.project_scope_kind, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.current_project(p_scope_kind public.project_scope_kind, p_scope_ref text) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  /*
    The latest row, then the guard — in that order, and the order is the whole
    fix. Filtering first lets a fixture switch fall THROUGH to an older real
    one, which points a chat at a project from two switches ago while looking
    entirely reasonable. Filtering after means a fixture switch reads as no
    scope, which is what 0164 wanted and says so.

    A left join, because un-scoping is a switch to NULL — the table is
    append-only and there is no other way to say it — and an inner join drops
    exactly that row.

    0361: `seq desc`, not `switch_id desc`. The id is a random uuid, so ordering
    by it picked one of two same-transaction switches at random and "the latest
    switch wins" was true only on average.
  */
  select case when latest.is_fixture then null else latest.project_id end
    from (
      select s.project_id, coalesce(p.is_fixture, false) as is_fixture
        from public.project_switches s
        left join public.projects p on p.project_id = s.project_id
       where s.scope_kind = p_scope_kind
         and s.scope_ref = p_scope_ref
       order by s.switched_at desc, s.seq desc
       limit 1
    ) latest
$$;


--
-- Name: FUNCTION current_project(p_scope_kind public.project_scope_kind, p_scope_ref text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.current_project(p_scope_kind public.project_scope_kind, p_scope_ref text) IS 'The latest switch for a scope. Returns null both when nothing was ever set and when the last switch was an explicit un-scoping - which are the same answer to the caller: no scope. A switch naming a fixture also reads as no scope, and does not fall through to an older real one (0164, 0291). Ties inside one transaction are broken by seq, not by a random uuid (0361).';


--
-- Name: decide_output(uuid, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.decide_output(p_output uuid, p_verdict text, p_why text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare v_now text; v_job uuid;
begin
  /*
    Only the two a person presses.

    `approved` is deliberately NOT settable here: an output becomes approved by
    being IMPORTED (0317), which is the step that creates the document. Letting
    a button set the status directly would produce an output marked approved
    with nothing in the project — the half-built gate this Issue is about.
  */
  if p_verdict not in ('rejected', 'pending') then
    return jsonb_build_object('ok', false, 'error',
      format('%s is not a decision this can make — import it to approve it', p_verdict));
  end if;

  select oo.reviewer_status::text, oo.job_id into v_now, v_job
    from public.outputs oo where oo.output_id = p_output;
  if v_now is null then
    return jsonb_build_object('ok', false, 'error', 'no such output');
  end if;

  update public.outputs
     set reviewer_status = p_verdict::reviewer_status,
         reviewed_at = case when p_verdict = 'pending' then null else app.now_utc() end,
         review_notes = nullif(btrim(coalesce(p_why, '')), '')
   where output_id = p_output;

  return jsonb_build_object('ok', true, 'was', v_now, 'now', p_verdict, 'job', v_job);
end;
$$;


--
-- Name: FUNCTION decide_output(p_output uuid, p_verdict text, p_why text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.decide_output(p_output uuid, p_verdict text, p_why text) IS '#28. The other half of the import gate — declining an output, and undoing that. `approved` is not settable here on purpose: an output becomes approved by being IMPORTED, and a button that set the status alone would leave it marked approved with nothing in the project. 0321.';


--
-- Name: decide_proposal(uuid, text, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.decide_proposal(p_proposal_id uuid, p_state text, p_note text DEFAULT NULL::text, p_by text DEFAULT 'grant'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_was text;
  v_title text;
  v_remedy text;
  v_argument text;
begin
  select state, title, remedy, argument
    into v_was, v_title, v_remedy, v_argument
    from public.proposals where proposal_id = p_proposal_id;
  if v_was is null then
    return jsonb_build_object('error', 'there is no such proposal');
  end if;
  if p_state not in ('open', 'approved', 'declined', 'done') then
    return jsonb_build_object('error', format('%L is not a state a proposal can be in', p_state));
  end if;

  update public.proposals
     set state = p_state,
         decided_at = case when p_state = 'open' then null else app.now_utc() end,
         decided_by = case when p_state = 'open' then null else p_by end,
         decided_note = nullif(btrim(coalesce(p_note, '')), '')
   where proposal_id = p_proposal_id;

  /*
    A settled proposal is a decision the office should not have to rediscover
    (#129).

    Only when it SETTLES. Reopening one is Grant changing his mind about
    whether to decide, not a decision — and writing a row for it would put
    "open" in a log whose whole purpose is to say what was concluded.

    What it ruled out is the proposal's own remedy when the answer was no: an
    agent about to propose the same thing again can find that it was declined,
    which is #129's second bullet exactly. `times_seen` goes into the reason,
    because a wall hit nine times and declined is a different fact from one hit
    once.
  */
  if p_state in ('approved', 'declined') then
    begin
      perform app.record_decision_made(
        format('Should the office be able to %s?', coalesce(nullif(btrim(v_title), ''), 'do this')),
        case when p_state = 'approved' then coalesce(nullif(btrim(v_remedy), ''), 'yes')
             else 'No, not for now' end,
        case when p_state = 'declined'
             then array[coalesce(nullif(btrim(v_remedy), ''), 'the thing proposed')]
             else array[]::text[] end,
        coalesce(nullif(btrim(p_note), ''),
                 nullif(btrim(v_argument), ''),
                 'Decided on the proposals page.'),
        p_by, null, null, null);
    exception when others then
      -- A memory that cannot be written must not undo a verdict that was.
      null;
    end;
  end if;

  return jsonb_build_object('ok', true, 'was', v_was, 'now', p_state);
end;
$$;


--
-- Name: FUNCTION decide_proposal(p_proposal_id uuid, p_state text, p_note text, p_by text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.decide_proposal(p_proposal_id uuid, p_state text, p_note text, p_by text) IS '#49. Reopening a declined proposal is allowed and deliberate: if the world changes it should be askable again — but only by a person saying so, never by the office deciding on its own that the decline has expired.';


--
-- Name: decide_suggestion(uuid, boolean, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.decide_suggestion(p_suggestion_id uuid, p_accept boolean, p_by text DEFAULT 'grant'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  s      public.suggestions;
  v_did  jsonb;
begin
  select * into s from public.suggestions where suggestion_id = p_suggestion_id;
  if s.suggestion_id is null then
    return jsonb_build_object('error', 'there is no such suggestion');
  end if;
  if s.state <> 'open' then
    return jsonb_build_object('already', s.state);
  end if;

  if not p_accept then
    /*
      Dismissed is a decision, and the count is the office being told it is not
      taking a hint. `raise_suggestions` reads it; so does the page, loudly,
      above zero.
    */
    update public.suggestions
       set state = 'dismissed', settled_at = app.now_utc(),
           dismissals = coalesce(dismissals, 0) + 1
     where suggestion_id = p_suggestion_id;
    return jsonb_build_object('accepted', false, 'state', 'dismissed');
  end if;

  if s.offer_kind = 'learn' then
    -- The only path by which a correction becomes a rule, and it is reachable
    -- only from a press. `app.learn` answers in JSONB, not with an id.
    v_did := app.learn(
      (s.offer_args ->> 'scope')::lesson_scope,
      s.body,
      p_by,
      nullif(s.offer_args ->> 'project_id', '')::uuid,
      nullif(s.offer_args ->> 'staff', ''),
      null,
      nullif(s.offer_args ->> 'from_job', '')::uuid,
      0.9,
      null);
  end if;

  update public.suggestions
     set state = 'acted', settled_at = app.now_utc()
   where suggestion_id = p_suggestion_id;

  return jsonb_build_object('accepted', true, 'state', 'acted',
                            'lesson_id', v_did -> 'lesson_id',
                            'did', coalesce(s.offer_kind, 'nothing but noting it'));
end;
$$;


--
-- Name: FUNCTION decide_suggestion(p_suggestion_id uuid, p_accept boolean, p_by text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.decide_suggestion(p_suggestion_id uuid, p_accept boolean, p_by text) IS 'One press (#147, 0392). Accepting PERFORMS the offer - for a drafted standing rule that is app.learn, the only path by which a correction becomes a rule. States are the four the table allows: acted on a press, dismissed on a decline.';


--
-- Name: decisions_about(text, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.decisions_about(p_text text, p_limit integer DEFAULT 4) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select coalesce(jsonb_agg(q.v order by q.rank desc, q.at desc), '[]'::jsonb)
    from (
      select d.decided_at as at,
             ts_rank(d.search, websearch_to_tsquery('english', p_text))
               + extensions.similarity(d.question, p_text) as rank,
             jsonb_build_object(
               'id', d.decision_id,
               'question', d.question,
               'chose', d.chose,
               'ruled_out', to_jsonb(d.ruled_out),
               'because', d.because,
               'by', d.decided_by,
               'at', d.decided_at,
               'project', p.name,
               'supersedes', d.supersedes) as v
        from public.decisions_live d
        left join public.projects p on p.project_id = d.project_id
       where not d.is_fixture
         and (d.search @@ websearch_to_tsquery('english', p_text)
              or extensions.similarity(d.question, p_text) > 0.25
              -- The options it beat, which the generated vector cannot hold
              -- (see the column comment). "Did we look at Drive?" has to find
              -- the decision that ruled Drive out.
              or extensions.similarity(array_to_string(d.ruled_out, ' '), p_text) > 0.25)
       order by 2 desc, 1 desc
       limit greatest(1, least(coalesce(p_limit, 4), 10))
    ) q;
$$;


--
-- Name: decisions_so_far(integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.decisions_so_far(p_limit integer DEFAULT 40) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select coalesce(jsonb_agg(q.v order by q.at desc), '[]'::jsonb)
    from (
      select d.decided_at as at,
             jsonb_build_object(
               'id', d.decision_id,
               'question', d.question,
               'chose', d.chose,
               'ruled_out', to_jsonb(d.ruled_out),
               'because', d.because,
               'by', d.decided_by,
               'at', d.decided_at,
               'project', p.name,
               'supersedes', d.supersedes,
               'live', not exists (select 1 from public.decisions n
                                    where n.supersedes = d.decision_id)) as v
        from public.decisions d
        left join public.projects p on p.project_id = d.project_id
       where not d.is_fixture
       order by d.decided_at desc
       limit greatest(1, least(coalesce(p_limit, 40), 200))
    ) q;
$$;


--
-- Name: decline_tool(uuid, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.decline_tool(p_request_id uuid, p_by text DEFAULT 'grant'::text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  req    public.tool_requests%rowtype;
  before integer;
begin
  if p_by is distinct from 'grant' then
    return jsonb_build_object('error',
      'only Grant answers a request for reach (ADR-0018).');
  end if;
  if length(btrim(coalesce(p_reason, ''))) < 8 then
    return jsonb_build_object('error',
      'a decline needs a reason — it is what makes it worth revisiting in three months');
  end if;

  select * into req from public.tool_requests where request_id = p_request_id;
  if not found then
    return jsonb_build_object('error', 'no such request: ' || p_request_id::text);
  end if;
  if req.state <> 'open' then
    return jsonb_build_object('error', 'that request was already ' || req.state);
  end if;

  -- Carried forward from every previous refusal of this exact ask, so the
  -- silence lengthens rather than resetting to ninety days each time.
  select coalesce(max(declines), 0) into before
    from public.tool_requests
   where tool = req.tool and asked_by = req.asked_by and state = 'declined';

  update public.tool_requests
     set state = 'declined', settled_at = app.now_utc(),
         decided_by = p_by, decline_reason = btrim(p_reason),
         declines = before + 1
   where request_id = p_request_id;

  perform public.append_event(
    extensions.gen_random_uuid(), 'user', p_by, 'approval', 'tool.declined',
    true, null, null,
    jsonb_build_object('tool', req.tool, 'asked_by', req.asked_by,
                       'declines', before + 1),
    left(btrim(p_reason), 1000), '[]'::jsonb, null, req.tool,
    'app.request_tool(...) again once the silence expires', null);

  return jsonb_build_object(
    'declined', true, 'tool', req.tool, 'declines', before + 1,
    'silent_until', app.now_utc() + ((before + 1) * interval '90 days'));
end;
$$;


--
-- Name: FUNCTION decline_tool(p_request_id uuid, p_by text, p_reason text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.decline_tool(p_request_id uuid, p_by text, p_reason text) IS 'Grant answering no, durably and specifically. Keyed on the exact tool and person, so a no to one thing never becomes a no to its neighbour, and ninety days per refusal so it does not need repeating (ADR-0018).';


--
-- Name: defer_over_budget(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.defer_over_budget() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_held int := 0;
  v_row  record;
  v_why  text;
begin
  for v_row in
    select distinct j.recipient_agent as agent
      from public.jobs j
     where j.state = 'queued'
       and (j.not_before is null or j.not_before <= app.now_utc())
       and not coalesce(app.harness_job(j.job_id), false)
  loop
    v_why := app.over_budget(v_row.agent);
    continue when v_why is null;
    update public.jobs j
       set not_before = date_trunc('day', app.now_utc()) + interval '1 day',
           state_reason = v_why,
           updated_at = app.now_utc()
     where j.state = 'queued'
       and j.recipient_agent is not distinct from v_row.agent
       and (j.not_before is null or j.not_before <= app.now_utc())
       and not coalesce(app.harness_job(j.job_id), false);
    v_held := v_held + 1;
  end loop;
  return jsonb_build_object('agents_held', v_held);
end;
$$;


--
-- Name: delegation_health(integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.delegation_health(p_days integer DEFAULT 30) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with live as (
    select * from public.jobs
     where not is_fixture
       and created_at > app.now_utc() - make_interval(days => greatest(coalesce(p_days, 30), 1))
  )
  select jsonb_build_object(
    'jobs', (select count(*) from live),
    'addressed', (select count(*) from live where recipient_agent is not null),
    -- The one that matters. A job addressed to the chief of staff is the
    -- office NOT delegating, and counting it would make the rate look healthy.
    'delegated', (select count(*) from live
                   where recipient_agent is not null and recipient_agent <> 'chief-of-staff'),
    'to_whom', (select coalesce(jsonb_object_agg(a, n), '{}'::jsonb)
                  from (select recipient_agent as a, count(*) as n from live
                         where recipient_agent is not null group by 1) x),
    'consultations', (select count(*) from public.consultations c
                       where c.job_id in (select job_id from live)),
    'judged', (select count(*) from public.consultations c
                where c.job_id in (select job_id from live) and c.changed_outcome is not null),
    'helped', (select count(*) from public.consultations c
                where c.job_id in (select job_id from live) and c.changed_outcome),
    'outputs_without_author', (select count(*) from public.outputs o
                                where o.job_id in (select job_id from live) and o.staff_id is null)
  )
$$;


--
-- Name: deliverable_to(uuid, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.deliverable_to(p_job_id uuid, p_channel text, p_target_ref text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case
    when p_job_id is null then true
    when not app.harness_job(p_job_id) then true
    else exists (select 1 from public.test_destinations t
                  where t.channel = p_channel and t.target_ref = p_target_ref)
  end
$$;


--
-- Name: dequeue_job(text, boolean, boolean, text[], text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.dequeue_job(p_worker text, p_can_transcribe boolean DEFAULT true, p_can_subprocess boolean DEFAULT true, p_kinds text[] DEFAULT NULL::text[], p_requested_by text DEFAULT NULL::text) RETURNS TABLE(job_id uuid, kind text, correlation_id uuid, project_id uuid, idempotency_key text, attempt integer, pinned_config jsonb)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'app', 'public'
    AS $$
declare
  v_limit       integer;
  v_active      integer;
  v_lease       integer;
  v_job_id      uuid;
  v_may_reflect boolean;
begin
  if p_worker is null or length(trim(p_worker)) = 0 then
    raise exception 'a worker identity is required to dequeue'
      using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtext('ai_team_hq.job_dequeue'));

  /*
    The same limit, counted over the same work the claim can reach.

    Unscoped, that is the whole queue, exactly as it has always been. Scoped,
    it is that scope's own jobs — because a caller that cannot CLAIM another
    scope's work should not be BLOCKED by it either, which is the whole of
    #184.
  */
  v_limit := app.capacity_limit('max_concurrent_jobs', 3);
  select count(*) into v_active
  from public.jobs
  where state in (
    'running', 'output_created', 'quality_review', 'committing', 'committed', 'notifying'
  )
    and (p_requested_by is null or requested_by = p_requested_by);

  if v_active >= v_limit then
    return;
  end if;

  -- 0216: asked once per dequeue rather than once per candidate row. A
  -- stable function in a WHERE clause is not guaranteed to be hoisted, and
  -- the budget cannot change during a single call anyway.
  v_may_reflect := app.self_improvement_within_budget();

  select j.job_id into v_job_id
  from public.jobs j
  where j.state = 'queued'
    and j.attempt < j.max_attempts
    -- 0074: a delayed job is not a queued job yet.
    and (j.not_before is null or j.not_before <= now())
    -- 0125: an untranscribed voice note needs a worker that can hear. The Edge
    -- worker cannot — no subprocesses, no Python — and it reports that about
    -- itself at GET /functions/v1/worker. Tests the TRANSCRIPT rather than the
    -- audio, so a note already transcribed is ordinary work any worker may
    -- finish.
    and (
      p_can_transcribe
      or not exists (
        select 1 from public.inbound_commands c
         where c.job_id = j.job_id
           and c.voice_file_id is not null
           and coalesce(trim(c.transcript), '') = ''
      )
    )
    -- 0137: and the same argument for everything else that needs a local
    -- process. A kind not in the table runs anywhere.
    and (
      p_can_subprocess
      or not exists (
        select 1 from public.job_kind_needs n
         where n.kind = j.kind and n.needs_subprocess
      )
    )
    -- 0147: and the most obvious form of the same rule, which was missing.
    -- A worker that holds five handlers must not claim a job needing a sixth.
    -- Null means "everything", which is what every caller meant before this
    -- argument existed.
    and (p_kinds is null or j.kind = any(p_kinds))
    -- 0329: and one step further, for #184. A worker that exists to run ONE
    -- job must not claim a different one, however well it could handle it.
    and (p_requested_by is null or j.requested_by = p_requested_by)
    /*
      0216: and the office does not keep thinking about itself once today's
      budget is spent (#53, ADR-0018).

      Here rather than in the handlers because a check in the caller is a check
      in one of the callers. Work FOR Grant is untouched — only the kinds in
      `self_improvement_kinds` wait, and they wait rather than fail, so the
      queue drains itself when the rolling window moves.
    */
    and (
      v_may_reflect
      or not exists (
        select 1 from public.self_improvement_kinds s where s.kind = j.kind
      )
    )
  order by j.priority asc, j.created_at asc
  for update skip locked
  limit 1;

  if v_job_id is null then
    return;
  end if;

  v_lease := coalesce(
    (select value::text::integer from public.system_config where key = 'jobs.lease_seconds'),
    300
  );

  update public.jobs j
  set state        = 'running',
      leased_by    = p_worker,
      leased_until = now() + make_interval(secs => v_lease),
      attempt      = j.attempt + 1,
      state_reason = format('dequeued by %s', p_worker)
  where j.job_id = v_job_id;

  return query
    select j.job_id, j.kind, j.correlation_id, j.project_id,
           j.idempotency_key, j.attempt, j.pinned_config
    from public.jobs j
    where j.job_id = v_job_id;
end
$$;


--
-- Name: FUNCTION dequeue_job(p_worker text, p_can_transcribe boolean, p_can_subprocess boolean, p_kinds text[], p_requested_by text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.dequeue_job(p_worker text, p_can_transcribe boolean, p_can_subprocess boolean, p_kinds text[], p_requested_by text) IS '#184, 0329-30. Claim one job. `p_requested_by` narrows BOTH the claim and the capacity question to work asked for by that exact name, so a caller that cannot reach another scope''s work is not blocked by it either. Null — what every office worker passes — behaves exactly as before.';


--
-- Name: discard_document(uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.discard_document(p_document uuid, p_why text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare v_title text; v_was text;
begin
  select title, state into v_title, v_was
    from public.documents where document_id = p_document;
  if v_title is null then
    return jsonb_build_object('ok', false, 'error', 'no such document');
  end if;
  if v_was = 'archived' then
    -- Already gone. Reported as ok with nothing changed, because a second
    -- press of Discard is a person making sure, not an error.
    return jsonb_build_object('ok', true, 'title', v_title, 'already', true);
  end if;

  update public.documents set state = 'archived' where document_id = p_document;
  return jsonb_build_object('ok', true, 'title', v_title, 'was', v_was,
                            'why', nullif(btrim(coalesce(p_why, '')), ''));
end;
$$;


--
-- Name: FUNCTION discard_document(p_document uuid, p_why text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.discard_document(p_document uuid, p_why text) IS 'Take a document out of the project (#28). Writes `archived`, which is what the state constraint permits -- it wrote `rejected` from the day it was created and raised 23514 every time, so nothing has ever been discarded.';


--
-- Name: dispatch_due_responsibilities(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.dispatch_due_responsibilities() RETURNS TABLE(duty_slug text, duty_kind text, outcome text, fired_job_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  d record;
  v_job uuid;
begin
  for d in select r.*, due.idempotency_key
             from app.due_responsibilities() due
             join public.responsibilities r
               on r.responsibility_id = due.responsibility_id loop
    begin
      insert into public.jobs
        (correlation_id, project_id, idempotency_key, kind, requested_by, announce,
         pinned_config, recipient_agent)
      values
        (gen_random_uuid(), d.project_id, d.idempotency_key, d.job_kind,
         'duty:' || d.slug, true,
         coalesce(d.pinned_config, '{}'::jsonb), d.recipient_agent)
      returning job_id into v_job;

      update public.responsibilities
         set last_run_at = app.now_utc()
       where responsibility_id = d.responsibility_id;

      return query select d.slug, d.job_kind, 'fired'::text, v_job;
    exception
      when unique_violation then
        -- Stamped here too. A live job carrying this period's key exists, so
        -- the duty HAS fired this period; leaving it unstamped only buys a
        -- failed insert every tick until the period turns over.
        update public.responsibilities
           set last_run_at = app.now_utc()
         where responsibility_id = d.responsibility_id;
        return query select d.slug, d.job_kind, 'already_fired'::text, null::uuid;
    end;
  end loop;
end;
$$;


--
-- Name: FUNCTION dispatch_due_responsibilities(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.dispatch_due_responsibilities() IS 'Fires every due duty from public.responsibilities, once per period. The unique index on jobs.idempotency_key is what makes that true; this function catches its violation and reports it as the normal outcome it is.';


--
-- Name: drive_folders_to_check(integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.drive_folders_to_check(p_minutes integer DEFAULT 10) RETURNS TABLE(attachment_id uuid, project_id uuid, project_name text, folder_id text, page_token text, primed boolean, reconcile_due boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select w.attachment_id, a.project_id, p.name, w.folder_id, w.page_token, w.primed,
         /*
           Due only when there is something to reconcile AGAINST.

           A folder the office has never imported from holds no documents, so a
           listing could only ever conclude "nothing is missing" -- the
           found-nothing shape, paid for with two hundred rows a day. The
           EXISTS is what keeps the backstop proportionate to the corpus rather
           than to the number of folders attached.
         */
         (exists (select 1 from public.documents d
                   where d.connector = 'drive'
                     and d.external_parent_ref = w.folder_id
                     and d.external_ref is not null)
          and (w.last_reconciled_at is null
               or w.last_reconciled_at <= app.now_utc() - interval '1 day')) as reconcile_due
    from public.drive_watch w
    join public.project_attachments a on a.attachment_id = w.attachment_id and a.enabled
    join public.projects p on p.project_id = a.project_id
   where p.status = 'active'
     and not p.is_fixture
     and (w.last_checked_at is null
          or w.last_checked_at <= app.now_utc()
             - make_interval(mins => greatest(coalesce(p_minutes, 10), 1)))
     -- A folder that has failed repeatedly stops being polled and says so,
     -- rather than burning a request every ten minutes for ever.
     and w.failures < 5
   order by w.last_checked_at nulls first
$$;


--
-- Name: drive_reconcile(uuid, text, text[], text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.drive_reconcile(p_attachment uuid, p_folder_id text, p_seen text[], p_error text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare v_r jsonb; v_note text;
begin
  if p_error is not null then
    /*
      A listing that failed is NOT an empty folder, and handing `{}` to
      `reconcile_vanished` would say every document in it had been deleted.
      The guard would refuse that -- and relying on a guard to catch a caller's
      own mistake is how a guard comes to be the only thing standing between a
      failed request and a wiped corpus.
    */
    update public.drive_watch
       set last_reconciled_at = app.now_utc(),
           last_reconcile_note = left('could not list the folder: ' || p_error, 400)
     where attachment_id = p_attachment;
    return jsonb_build_object('ok', false, 'error', p_error);
  end if;

  select app.reconcile_vanished('drive', p_folder_id, coalesce(p_seen, '{}'::text[])) into v_r;

  v_note := case
    when coalesce((v_r ->> 'ok')::boolean, false) = false
      then left(coalesce(v_r ->> 'error', 'reconcile refused'), 400)
    else format('%s held, %s absent; marked %s, archived %s, returned %s, restored %s',
                v_r ->> 'held', v_r ->> 'absent', v_r ->> 'marked',
                v_r ->> 'archived', v_r ->> 'returned', v_r ->> 'restored')
  end;

  update public.drive_watch
     set last_reconciled_at = app.now_utc(),
         last_reconcile_note = v_note
   where attachment_id = p_attachment;

  return v_r || jsonb_build_object('note', v_note);
end;
$$;


--
-- Name: drive_watch_checked(uuid, text, boolean, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.drive_watch_checked(p_attachment_id uuid, p_page_token text, p_saw_changes boolean DEFAULT false, p_error text DEFAULT NULL::text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  update public.drive_watch
     set page_token      = coalesce(p_page_token, page_token),
         primed          = primed or p_page_token is not null,
         last_checked_at = app.now_utc(),
         last_change_at  = case when p_saw_changes then app.now_utc() else last_change_at end,
         failures        = case when p_error is null then 0 else failures + 1 end,
         last_error      = p_error,
         updated_at      = app.now_utc()
   where attachment_id = p_attachment_id
$$;


--
-- Name: due_responsibilities(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.due_responsibilities() RETURNS TABLE(responsibility_id uuid, slug text, staff_id uuid, project_id uuid, job_kind text, idempotency_key text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with z as (select app.grant_timezone() as tz)
  select
    r.responsibility_id, r.slug, r.staff_id, r.project_id, r.job_kind,
    case
      when r.at_time is null
        -- The window index, unchanged: two attempts inside the same period
        -- produce the same key and collide on 0005's unique index.
        then 'duty:' || r.slug || ':' ||
             (floor(extract(epoch from app.now_utc()) / (r.period_minutes * 60)))::bigint::text
        -- The local date. Two passes on the same day produce the same key,
        -- which is what stops him being briefed twice.
        else 'duty:' || r.slug || ':' ||
             to_char((app.now_utc() at time zone coalesce(r.timezone, z.tz))::date, 'YYYY-MM-DD')
    end
  from public.responsibilities r
  join public.staff s on s.staff_id = r.staff_id and s.active
  cross join z
  where r.enabled
    and case
      when r.at_time is null then
        r.last_run_at is null
        or r.last_run_at <= app.now_utc() - make_interval(mins => r.period_minutes)
      else
        -- Past this morning's anchor, and not already done since it. Comparing
        -- against the anchor rather than against "24h ago" is the whole point:
        -- a run that happened at 07:02 does not push tomorrow's to 07:02 + 24h.
        app.now_utc() >= (
          ((app.now_utc() at time zone coalesce(r.timezone, z.tz))::date + r.at_time)
            at time zone coalesce(r.timezone, z.tz)
        )
        and (
          r.last_run_at is null
          or r.last_run_at < (
            ((app.now_utc() at time zone coalesce(r.timezone, z.tz))::date + r.at_time)
              at time zone coalesce(r.timezone, z.tz)
          )
        )
    end;
$$;


--
-- Name: FUNCTION due_responsibilities(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.due_responsibilities() IS 'Due duties with the idempotency key each must use. Two flavours: an interval duty keyed on its window index, and a wall-clock duty keyed on the local date. The key is derived here, once, because "every caller derives it the same way" is not something you get by documenting it.';


--
-- Name: enforce_delegation_depth(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_delegation_depth() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_parent_depth integer;
  v_max integer;
begin
  if new.parent_job_id is null then
    return new;
  end if;

  select coalesce((value #>> '{}')::integer, 3)
    into v_max
    from public.system_config where key = 'agents.max_delegation_depth';
  if v_max is null then v_max := 3; end if;

  v_parent_depth := app.job_depth(new.parent_job_id);

  if v_parent_depth + 1 > v_max then
    raise exception
      'job cannot be created at delegation depth %: the limit is %. §9 caps '
      'delegation because delegation that spawns delegation is how one question '
      'becomes a thousand jobs. If this work genuinely needs another level, it '
      'needs a person to say so, not a deeper default.',
      v_parent_depth + 1, v_max
      using errcode = 'check_violation';
  end if;

  return new;
end;
$$;


--
-- Name: FUNCTION enforce_delegation_depth(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.enforce_delegation_depth() IS '§9''s runaway-delegation guard. A trigger rather than an enqueue-path check because there is more than one enqueue path and there will be more later.';


--
-- Name: enforce_deterministic_claim(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_deterministic_claim() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_correlation uuid;
  v_calls integer;
begin
  if not new.deterministic then
    return new;
  end if;

  if new.model is not null then
    raise exception
      'output % cannot be marked deterministic: it records model %. §16 defines '
      'the review exemption by HOW the answer was produced, and a deterministic '
      'code path does not have a model.', coalesce(new.output_id::text, '(new)'), new.model
      using errcode = 'check_violation';
  end if;

  select correlation_id into v_correlation from public.jobs where job_id = new.job_id;

  select count(*) into v_calls
  from public.inference_usage
  where correlation_id = v_correlation;

  if v_calls > 0 then
    raise exception
      'output cannot be marked deterministic: job % has % recorded inference '
      'attempt(s) against correlation %. §16 says the exemption must be defined '
      'by how the answer was produced because that is checkable - and the '
      'record says a model was called. Mark it deterministic only on a code '
      'path that makes no inference call, or send it to review.',
      new.job_id, v_calls, v_correlation
      using errcode = 'check_violation';
  end if;

  return new;
end;
$$;


--
-- Name: FUNCTION enforce_deterministic_claim(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.enforce_deterministic_claim() IS '§16: the review exemption is checkable, so it is checked. An output claiming a deterministic code path must not name a model, and must not come from a job with recorded inference usage.';


--
-- Name: enforce_job_transition(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_job_transition() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'app', 'public'
    AS $$
begin
  if new.state = old.state then
    return new;
  end if;

  if not exists (
    select 1 from app.job_transitions_allowed
    where from_state = old.state and to_state = new.state
  ) then
    raise exception
      'illegal job transition % -> % for job %',
      old.state, new.state, old.job_id
      using errcode = '23514',
            hint = format(
              'Allowed from %s: %s',
              old.state,
              coalesce(
                (select string_agg(to_state::text, ', ' order by to_state)
                 from app.job_transitions_allowed where from_state = old.state),
                '(none — terminal)'
              )
            );
  end if;

  -- Log it. Doing this in the trigger rather than in application code is what
  -- makes "every transition is a committed database write" true by
  -- construction: there is no code path that can move a job without logging it.
  insert into public.job_state_transitions (job_id, from_state, to_state, reason, attempt)
  values (new.job_id, old.state, new.state, new.state_reason, new.attempt);

  -- Keep the timestamps honest rather than trusting callers to.
  if new.state = 'running' and old.started_at is null then
    new.started_at := now();
  end if;
  if new.state in ('complete', 'cancelled', 'failed') then
    new.finished_at := coalesce(new.finished_at, now());
  else
    new.finished_at := null;
  end if;

  return new;
end
$$;


--
-- Name: enforce_notebook_sync_transition(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_notebook_sync_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if old.state = new.state then
    return new;
  end if;

  if old.state = 'uncertain' and new.state = 'in_flight' then
    raise exception
      'refusing to retry an ambiguous Notebook write without reconciling first '
      '(sync_id %, uncertain since %). §7: reconcile actual Notebook state, '
      'then move to reconciling. Undocumented operations may not be cleanly '
      'idempotent.', old.sync_id, old.uncertain_since
      using errcode = 'check_violation';
  end if;

  -- A terminal row does not come back to life. Re-queue by inserting, which
  -- the partial unique index permits once the old row is abandoned.
  if old.state in ('applied', 'abandoned') then
    raise exception
      'Notebook sync % is already %; insert a new row rather than reviving it',
      old.sync_id, old.state
      using errcode = 'check_violation';
  end if;

  return new;
end;
$$;


--
-- Name: enforce_prompt_version(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_prompt_version() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.prompt_version = old.prompt_version then
    return new;
  end if;

  if new.prompt_version < old.prompt_version then
    raise exception
      'staff % prompt_version cannot go backwards (% -> %). A pinned version '
      'must mean one thing forever, or §6''s configuration pinning stops '
      'explaining anything.', new.slug, old.prompt_version, new.prompt_version
      using errcode = 'check_violation';
  end if;

  if not exists (
    select 1 from public.staff_prompts
    where staff_id = new.staff_id and version = new.prompt_version
  ) then
    raise exception
      'staff % cannot point at prompt version %: no such version exists. §21 '
      'versions the prompt, not the number.', new.slug, new.prompt_version
      using errcode = 'foreign_key_violation';
  end if;

  return new;
end;
$$;


--
-- Name: enforce_review_gate(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_review_gate() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_unreviewed integer;
  v_total integer;
begin
  if new.state <> 'committed' or old.state = 'committed' then
    return new;
  end if;

  select count(*), count(*) filter (
    where reviewer_status = 'pending' and not deterministic
  )
  into v_total, v_unreviewed
  from public.outputs where job_id = new.job_id;

  -- A job with no outputs at all commits freely: plenty of work produces no
  -- substantive output, and requiring one would make the gate a nuisance
  -- rather than a control.
  if v_total = 0 then
    return new;
  end if;

  if v_unreviewed > 0 then
    raise exception
      'job % cannot reach committed: % of % output(s) are unreviewed. §10: the '
      'commit step reads reviewer_status, and an output without it cannot be '
      'committed. Review them, or mark them deterministic if they came from a '
      'deterministic path.', new.job_id, v_unreviewed, v_total
      using errcode = 'check_violation';
  end if;

  -- A rejected output is not a reviewed output for this purpose. Committing
  -- work whose own reviewer rejected it is the failure the gate exists to
  -- prevent, dressed as compliance.
  if exists (
    select 1 from public.outputs
    where job_id = new.job_id and reviewer_status = 'rejected'
  ) then
    raise exception
      'job % cannot reach committed: at least one output was REJECTED by review. '
      'Committing work its own reviewer rejected is the failure the gate exists '
      'to prevent.', new.job_id
      using errcode = 'check_violation';
  end if;

  return new;
end;
$$;


--
-- Name: FUNCTION enforce_review_gate(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.enforce_review_gate() IS '§10 THE GATE. A trigger rather than a worker check, because a worker check is bypassed by a second worker or by a hand-run UPDATE during an incident - exactly when someone would be tempted.';


--
-- Name: enforce_specialist_cap(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_specialist_cap() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_live integer;
  v_max integer;
begin
  if new.permanent or not new.active then
    return new;
  end if;

  v_max := app.temporary_specialist_slots();
  select count(*) into v_live
  from public.staff
  where not permanent and active
    and (expires_at is null or expires_at > app.now_utc())
    and staff_id <> new.staff_id;

  if v_live + 1 > v_max then
    raise exception
      'cannot create temporary specialist %: % of % slots are already in use. '
      '§9 keeps the specialist set small on purpose - a roster that grows '
      'whenever an agent wants a second opinion is how a team stops being one.',
      new.slug, v_live, v_max
      using errcode = 'check_violation';
  end if;

  return new;
end;
$$;


--
-- Name: enforce_staff_permanence(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_staff_permanence() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.permanent and not old.permanent then
    raise exception
      'staff % cannot be promoted from temporary to permanent. §21 reserves the '
      'shape of the team: a ninth permanent role is Grant''s decision, not a '
      'field update. Create it as permanent, deliberately, if that is what is '
      'wanted.', new.slug
      using errcode = 'check_violation';
  end if;
  return new;
end;
$$;


--
-- Name: enforce_switch_target_active(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_switch_target_active() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_status text;
begin
  if new.project_id is null then
    return new;
  end if;

  select status::text into v_status from public.projects where project_id = new.project_id;

  if v_status <> 'active' then
    raise exception
      'cannot switch to project %: it is %. Switching into an archived project '
      'would file new work somewhere nobody is looking.', new.project_id, v_status
      using errcode = 'check_violation';
  end if;

  return new;
end;
$$;


--
-- Name: enqueue_child(uuid, text, jsonb, interval, boolean, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enqueue_child(p_parent uuid, p_kind text, p_payload jsonb DEFAULT '{}'::jsonb, p_delay interval DEFAULT '00:00:00'::interval, p_announce boolean DEFAULT true, p_project uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_parent public.jobs;
  v_id uuid;
begin
  select * into v_parent from public.jobs where job_id = p_parent;
  if not found then
    raise exception 'no job % to hang a child on', p_parent using errcode = '23503';
  end if;

  insert into public.jobs
    (parent_job_id, correlation_id, project_id, idempotency_key, kind,
     requested_by, priority, pinned_config, not_before, announce)
  values (
    p_parent, v_parent.correlation_id,
    coalesce(p_project, v_parent.project_id),
    format('child-%s-%s', left(p_kind, 40), gen_random_uuid()),
    p_kind, v_parent.requested_by, v_parent.priority,
    coalesce(p_payload, '{}'::jsonb),
    case when p_delay <= interval '0' then null else now() + p_delay end,
    p_announce
  )
  returning job_id into v_id;

  return v_id;
end;
$$;


--
-- Name: FUNCTION enqueue_child(p_parent uuid, p_kind text, p_payload jsonb, p_delay interval, p_announce boolean, p_project uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.enqueue_child(p_parent uuid, p_kind text, p_payload jsonb, p_delay interval, p_announce boolean, p_project uuid) IS 'One step of work spawning the next. The child carries the parent''s correlation, its own idempotency key, and the parent''s project unless the caller names another - which two callers previously tried to do with a CTE that could not see the row it had just inserted, and neither noticed.';


--
-- Name: enqueue_inbound(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enqueue_inbound(p_command_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  c record;
  v_project uuid;
  v_job uuid;
begin
  select * into c from public.inbound_commands where command_id = p_command_id;
  if not found then
    return jsonb_build_object('error', 'no such command');
  end if;
  if c.job_id is not null then
    -- Already turned into work. Idempotent because a webhook is at-least-once
    -- and the same instruction arriving twice must not be done twice.
    return jsonb_build_object('job_id', c.job_id, 'already', true);
  end if;
  -- 0075: a recording is an instruction whose words have not been read yet.
  if coalesce(trim(c.instruction), '') = '' and c.voice_file_id is null then
    return jsonb_build_object('error', 'nothing to do: the command carries no instruction');
  end if;

  /*
    The asset's project when the command names one (#27, 0313).

    The fallback below — most recently updated — is right for a message that
    arrives out of nowhere and wrong for a button pressed on a document that
    plainly belongs somewhere. Validated against `projects` rather than
    trusted: the context is written by a caller, and a project id that does not
    resolve should fall back rather than file the job nowhere.
  */
  select p.project_id into v_project
    from public.projects p
   where p.project_id = nullif(c.context->>'project_id', '')::uuid;

  /*
    0337. The project the CALLER named, when it named one.

    0335 gave inbound_commands a project_id and 0336 made this function write
    its answer back to it - but nothing ever READ it, so a surface that knows
    perfectly well which project it is sending from had that knowledge thrown
    away in favour of "most recently updated". A column no writer honours is
    the web.search trap in a new place: it claims something that is not true.

    Below the context project, which is more specific still (#27: a button
    pressed on a document names that document's project). Above the fallback,
    which is a guess.

    Compared against unnamed_project() rather than null, because the column is
    NOT NULL and defaults to Unnamed - so "unset" reads as Unnamed here, and an
    adapter that could not resolve a project still reaches the heuristic rather
    than sending everything to the reserved project. That default is what keeps
    a message from being lost; it is not a routing instruction.
  */
  if v_project is null and c.project_id is distinct from app.unnamed_project() then
    v_project := c.project_id;
  end if;

  /*
    0338. The channel the message came from, when Slack is where it came from.

    #187 gives every dashboard project its own named channel and 0014 has
    mapped channel to project since the beginning - deliberately in Postgres
    rather than in a channel topic, because "a topic is editable by anyone in
    the channel and is lost with the channel". Nothing had ever asked that
    table which project a message belonged to.

    So a question typed in #legacy-coaching-course was filed against whichever
    project happened to have been touched most recently, and its answer went
    into that project's conversation. The mapping existed, the reader existed,
    and no line of code joined them.

    origin_ref is `channel:ts` for a Slack message - the message branch of
    toCanonicalCommand builds it that way and its comment says why the ts is
    the message's own rather than the thread parent's. split_part is safe on a
    ref of any other shape: it returns the whole string, which matches no
    channel_id and falls through.

    Only ACTIVE mappings. An archived channel's project is not where new work
    should go, and slack_channel_map keeps the row so the history still
    resolves.
  */
  if v_project is null and c.origin_channel = 'slack' then
    select m.project_id into v_project
      from public.slack_channel_map m
     where m.channel_id = split_part(c.origin_ref, ':', 1)
       and m.active
       and m.project_id is not null;
  end if;

  /*
    0341. Nothing above could say which project this is.

    Grant, 13 September, asked what should happen to a message in a general
    Telegram chat that names no project: "you can just go in unnamed project as
    a title or category or whatever" (ADR-0024).

    Until now the answer was the line below: the most recently updated active
    project. That is a guess, and its quality is entirely a matter of whether
    he happens to have been working on the thing he is now talking about. When
    it is wrong it is silently wrong - his message and the answer to it are
    filed against a project he never mentioned, and both appear in that
    project's conversation.

    A setting rather than a constant, per §4 and because the cost of each
    choice is real and only he can weigh them. `true` files an unresolvable
    message under Unnamed, which is honest and loses the guess. `false` is the
    old behaviour, which is useful exactly when the guess is right.

    Whichever it is, everything above still wins: an asset's project, a project
    the surface named, and a Slack channel's project are all resolutions rather
    than guesses, so this only decides what happens when there is nothing to go
    on at all.
  */
  if v_project is null
     and coalesce(
           (select value::text::boolean from public.system_config
             where key = 'routing.unnamed_when_unresolved'), true) then
    v_project := app.unnamed_project();
  end if;

  if v_project is null then
    select project_id into v_project
      from public.projects where status = 'active'
     order by updated_at desc
     limit 1;
  end if;

  if v_project is null then
    return jsonb_build_object('error', 'no active project to attach this to');
  end if;

  insert into public.jobs
    (correlation_id, project_id, idempotency_key, kind, requested_by, priority, pinned_config)
  values (gen_random_uuid(), v_project,
          format('inbound-%s', p_command_id),
          'office.instruction',
          format('%s:%s', c.origin_channel, coalesce(c.subject, c.actor)),
          -- 10, not 150. See the header: lower is sooner, and at 150 every
          -- routine duty in the building was claimed ahead of a message Grant
          -- was waiting on.
          10,
          jsonb_build_object(
            'instruction', c.instruction,
            'addressed_to', c.addressed_to,
            'addressed_also', to_jsonb(coalesce(c.addressed_also, '{}'::text[])),
            'origin_channel', c.origin_channel,
            'origin_ref', c.origin_ref,
            'command_id', p_command_id,
            'voice_file_id', c.voice_file_id,
            'voice_seconds', c.voice_seconds,
            -- The asset and the action, as facts (#27).
            'context', c.context
          ))
  on conflict (idempotency_key)
    where state <> all (array['complete'::public.job_state,
                              'cancelled'::public.job_state,
                              'failed'::public.job_state])
    do nothing
  returning job_id into v_job;

  -- THE LOSER OF THE RACE WANTS THE WINNER'S JOB (0528).
  -- `do nothing` returns no row, so v_job is null exactly when
  -- another call inserted first. Reading it back is the whole
  -- point: both callers must be told the same job id, which is
  -- what idempotent means to the adapter that asked.
  if v_job is null then
    select job_id into v_job from public.jobs
     where idempotency_key = format('inbound-%s', p_command_id)
       and state <> all (array['complete'::public.job_state,
                               'cancelled'::public.job_state,
                               'failed'::public.job_state]);
    if v_job is null then
      raise exception 'could not record what you said: the job for' 
        ' command % was neither inserted nor found', p_command_id;
    end if;
  end if;

  /*
    0336. The command's project is set to whatever the job resolved to.

    Added because #192 gave inbound_commands a project of its own and this
    function chooses the job's project independently - so the two could
    disagree and split one exchange across two conversations: Grant's message
    under the column's default, the office's answer under the job's project.

    Measured before changing anything: 193 of 194 enqueued commands reach the
    "most recently updated active project" fallback above, and exactly one has
    ever named a project in its context. So the heuristic is not an edge case,
    it is the path - which is why this reconciles the command TO the job rather
    than the other way round. Where work is ROUTED is a different decision from
    where a conversation GROUPS, and ADR-0024 was the latter.
  */
  update public.inbound_commands
     set job_id = v_job, processed_at = app.now_utc(), project_id = v_project
   where command_id = p_command_id;

  return jsonb_build_object('job_id', v_job, 'already', false, 'spoken', c.voice_file_id is not null);
end;
$$;


--
-- Name: enqueue_orphans(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enqueue_orphans() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app', 'public'
    AS $$
declare
  v_count integer := 0;
  r record;
begin
  for r in
    select c.command_id
      from public.inbound_commands c
     where c.job_id is null
       -- An instruction, not a reaction, a join notice or a button press.
       -- Those are canonical commands too and none of them is work; presses
       -- go through processCallbacks at the top of every pass.
       and coalesce(trim(c.instruction), '') <> ''
       and c.callback_action is null
       and c.received_at > app.now_utc() - interval '24 hours'
       and c.received_at < app.now_utc() - interval '1 minute'
     order by c.received_at
     limit 20
  loop
    begin
      perform app.enqueue_inbound(r.command_id);
      v_count := v_count + 1;
    exception when others then
      -- One command that cannot be enqueued must not stop the rest. The next
      -- pass tries again; after 24 hours it stops trying, because a command
      -- that has failed for a day needs a person rather than a retry.
      null;
    end;
  end loop;
  return v_count;
end
$$;


--
-- Name: FUNCTION enqueue_orphans(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.enqueue_orphans() IS 'Turn inbound instructions that never became jobs into jobs. A floor under the adapters, not a replacement for them: the webhook enqueueing directly is what makes a reply arrive in seconds, and this is what makes it arrive at all. Bounded to the last 24 hours — older than that needs a person.';


--
-- Name: eval_case_dimensions_exist(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.eval_case_dimensions_exist() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_unknown text;
begin
  select string_agg(d, ', ')
    into v_unknown
    from unnest(new.dimensions) as d
   where not exists (select 1 from public.breadth_dimensions b where b.dimension = d);

  if v_unknown is not null then
    raise exception
      'no such coverage dimension: %. Add it to public.breadth_dimensions first, '
      'or fix the spelling -- an unknown dimension does not fail, it silently '
      'creates a zero in the matrix and hides this case from the count.',
      v_unknown
      using errcode = 'check_violation';
  end if;

  return new;
end;
$$;


--
-- Name: eval_latest(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.eval_latest() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select coalesce(jsonb_agg(r order by r.at desc), '[]'::jsonb)
    from (
      select run_id, at, judge_model, judge_version, cases, agreed, note,
             (select round(avg(s.score), 2) from public.eval_scores s
               where s.run_id = e.run_id) as mean_score
        from public.eval_runs e
       order by at desc limit 2
    ) r
$$;


--
-- Name: eval_run_record(text, text, jsonb, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.eval_run_record(p_model text, p_version text, p_scores jsonb, p_note text DEFAULT ''::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_run uuid;
  v_n   int;
  v_ok  int;
begin
  if jsonb_typeof(p_scores) <> 'array' or jsonb_array_length(p_scores) = 0 then
    return jsonb_build_object('error', 'a run with no scores is not a run');
  end if;

  insert into public.eval_runs (judge_model, judge_version, cases, agreed, note)
  values (p_model, p_version, 0, 0, coalesce(p_note, ''))
  returning run_id into v_run;

  insert into public.eval_scores (run_id, case_id, score, verdict, reason, ms)
  select v_run,
         (e ->> 'case_id')::uuid,
         (e ->> 'score')::int,
         e ->> 'verdict',
         coalesce(e ->> 'reason', ''),
         nullif(e ->> 'ms', '')::int
    from jsonb_array_elements(p_scores) e;

  select count(*)::int,
         count(*) filter (where s.verdict = c.expect)::int
    into v_n, v_ok
    from public.eval_scores s
    join public.eval_cases c using (case_id)
   where s.run_id = v_run;

  update public.eval_runs set cases = v_n, agreed = v_ok where run_id = v_run;

  return jsonb_build_object(
    'run_id', v_run, 'cases', v_n, 'agreed', v_ok,
    'disagreed', coalesce((
      select jsonb_agg(jsonb_build_object(
               'slug', c.slug, 'expected', c.expect, 'judged', s.verdict,
               'score', s.score, 'reason', s.reason) order by c.slug)
        from public.eval_scores s join public.eval_cases c using (case_id)
       where s.run_id = v_run and s.verdict <> c.expect), '[]'::jsonb)
  );
end;
$$;


--
-- Name: eval_set(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.eval_set() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'case_id', c.case_id, 'slug', c.slug, 'ask', c.ask,
           'answer', c.answer, 'expect', c.expect, 'issue', c.issue,
           'why', c.why, 'context', c.context
         ) order by c.slug), '[]'::jsonb)
    from public.eval_cases c where c.active
$$;


--
-- Name: expire_temporary_staff(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.expire_temporary_staff() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_count integer;
begin
  update public.staff
  set active = false
  where not permanent and active and expires_at is not null
    and expires_at <= app.now_utc();
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;


--
-- Name: FUNCTION expire_temporary_staff(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.expire_temporary_staff() IS 'Deactivates temporary specialists past their expiry. Deactivates rather than deletes: their outputs and consultations still reference them, and a dangling author is worse than an inactive one.';


--
-- Name: expire_undo_offers(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.expire_undo_offers() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_count integer;
begin
  update public.undoable_actions
  set status = 'expired'
  where status = 'available' and undo_deadline is not null
    and undo_deadline <= app.now_utc();
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;


--
-- Name: export_path(text, uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.export_path(p_title text, p_id uuid, p_ext text DEFAULT 'md'::text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
  select 'documents/'
      || coalesce(nullif(left(regexp_replace(
             regexp_replace(lower(btrim(coalesce(p_title, ''))), '[^a-z0-9]+', '-', 'g'),
             '(^-+|-+$)', '', 'g'), 60), ''), 'untitled')
      || '-' || left(replace(p_id::text, '-', ''), 8)
      || '.' || p_ext
$_$;


--
-- Name: failure_seen(text, text, text, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.failure_seen(p_job_kind text, p_message text, p_subject text DEFAULT NULL::text, p_job_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_class text := app.classify_failure(p_message);
  v_subject text := coalesce(btrim(p_subject), '');
  v_seen int;
  v_first timestamptz;
begin
  if v_subject <> ''
     and not (
       (v_subject ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        or v_subject ~ '^[a-z0-9][a-z0-9_.:-]{0,39}$')
       and v_subject !~
         '(xox[abeprs]-|sbp_[A-Za-z0-9]{16}|ntn_[A-Za-z0-9]{16}|secret_[A-Za-z0-9]{16}|sk-[A-Za-z0-9_-]{12}|AIza[A-Za-z0-9_-]{20}|gh[posur]_[A-Za-z0-9]{20}|github_pat_|eyJ[A-Za-z0-9_-]{10}\.[A-Za-z0-9_-]{10})'
     )
  then
    v_subject := '';
  end if;

  /*
    Harness traffic is not counted (0491).

    A suite that deliberately fails -- `research.explodes` exists to --
    was writing into the tally that feeds Grant's morning briefing and a
    weight-75 suggestion. The answer is still a jsonb the caller can log,
    so a trace of a fixture job still says what happened; it simply does
    not become a recommendation.
  */
  if p_job_id is not null and app.harness_job(p_job_id) then
    return jsonb_build_object(
      'class', v_class, 'subject', v_subject, 'seen', 0,
      'first_seen', app.now_utc(), 'harness', true,
      'note', format('%s failure on harness traffic, not counted', v_class));
  end if;

  insert into public.failure_signatures
    (job_kind, error_class, subject, seen, first_seen, last_seen, last_job_id)
  values (p_job_kind, v_class, v_subject, 1, app.now_utc(), app.now_utc(), p_job_id)
  on conflict (job_kind, error_class, subject) do update
    set seen = public.failure_signatures.seen + 1,
        last_seen = app.now_utc(),
        last_job_id = coalesce(excluded.last_job_id, public.failure_signatures.last_job_id)
  returning seen, first_seen into v_seen, v_first;

  return jsonb_build_object(
    'class', v_class, 'subject', v_subject, 'seen', v_seen,
    'first_seen', v_first,
    'note', case when v_seen = 1 then format('first %s failure for %s', v_class, p_job_kind)
                 else format('%s has failed with %s %s times since %s',
                             p_job_kind, v_class, v_seen, to_char(v_first, 'FMDD Mon')) end);
end;
$_$;


--
-- Name: fan_in_over(uuid, text, jsonb, text, timestamp with time zone); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.fan_in_over(p_parent uuid, p_objective text, p_branches jsonb, p_synthesis_kind text DEFAULT 'office.synthesise'::text, p_deadline timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_group uuid; v_cap integer; v_count integer; v_branch jsonb;
  v_synth uuid; v_seen jsonb := '[]'::jsonb;
begin
  if not exists (select 1 from public.jobs where job_id = p_parent) then
    return jsonb_build_object('error', 'no such parent job');
  end if;
  if exists (select 1 from public.branch_groups where parent_job_id = p_parent) then
    -- Idempotent: a retried parent must not ask for a second answer.
    return jsonb_build_object('ok', true, 'already', true,
      'group', (select group_id from public.branch_groups where parent_job_id = p_parent));
  end if;

  v_count := coalesce(jsonb_array_length(p_branches), 0);
  if v_count < 2 then
    return jsonb_build_object('error',
      'a fan-in over fewer than two branches is just a job');
  end if;
  /*
    `system_config.value` is JSONB, not text.

    The first version wrote `nullif(value, '')::integer` and every call raised
    22P02 from inside a SECURITY DEFINER function — an empty string is not
    valid JSON, so the comparison itself threw before the cast was reached.
    `#>> '{}'` is how you get the scalar out, and CLAUDE.md's rule applies:
    query `information_schema` for the TYPE before writing the expression.
  */
  select coalesce(nullif(value #>> '{}', '')::integer, 3) into v_cap
    from public.system_config where key = 'agents.max_specialists_per_job';
  v_cap := coalesce(v_cap, 3);
  if v_count > v_cap then
    return jsonb_build_object('error',
      format('%s branches and the office allows %s at once', v_count, v_cap), 'cap', v_cap);
  end if;

  /*
    Every branch is checked BEFORE anything is written.

    The first version validated inside the insert loop, so a bad third branch
    returned an error and left a group with two branches in it — a refusal that
    changed something, which is the shape of a teardown that matches nothing.
    A function that says no must leave nothing behind.
  */
  for v_branch in select * from jsonb_array_elements(p_branches) loop
    if not exists (select 1 from public.staff where slug = v_branch ->> 'agent') then
      return jsonb_build_object('error',
        format('%L is nobody on the roster', v_branch ->> 'agent'));
    end if;
    if not exists (select 1 from public.jobs
                    where job_id = (v_branch ->> 'job_id')::uuid
                      and parent_job_id = p_parent) then
      -- A branch that is not a child of this parent is somebody else's work,
      -- and a group that could claim it would make the collaboration record a
      -- claim rather than a fact.
      return jsonb_build_object('error',
        format('job %L is not a child of this one', v_branch ->> 'job_id'));
    end if;
  end loop;

  insert into public.branch_groups (parent_job_id, objective, deadline)
  values (p_parent, p_objective, p_deadline)
  returning group_id into v_group;

  for v_branch in select * from jsonb_array_elements(p_branches) loop
    insert into public.job_branches (group_id, job_id, agent, purpose, required)
    values (v_group, (v_branch ->> 'job_id')::uuid, v_branch ->> 'agent',
            coalesce(nullif(btrim(coalesce(v_branch ->> 'purpose', '')), ''),
                     'part of the question'),
            coalesce((v_branch ->> 'required')::boolean, false));
    v_seen := v_seen || jsonb_build_object('job_id', v_branch ->> 'job_id',
                                           'agent', v_branch ->> 'agent');
  end loop;

  /*
    The answer is a child too, queued immediately.

    It does not wait in the database; it wakes, asks `fan_in_ready`, and pauses
    itself with `dependency_wait` when the branches are not in yet (#263). That
    is cheaper than a scheduler and it means a person looking at the job can
    see, in words, which branch it is waiting for.
  */
  v_synth := app.enqueue_child(p_parent, p_synthesis_kind,
    jsonb_build_object('group', v_group, 'objective', p_objective), interval '0', true, null);
  update public.branch_groups set synthesis_job_id = v_synth where group_id = v_group;

  return jsonb_build_object('ok', true, 'group', v_group,
    'branches', v_seen, 'synthesis', v_synth);
end;
$$;


--
-- Name: fan_in_ready(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.fan_in_ready(p_group uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  with b as (
    select br.agent, coalesce(s.name, br.agent) as name, br.purpose, br.required,
           j.state::text as state, j.job_id,
           exists (select 1 from public.outputs o where o.job_id = j.job_id) as answered
      from public.job_branches br
      join public.jobs j on j.job_id = br.job_id
      left join public.staff s on s.slug = br.agent
     where br.group_id = p_group
  ),
  g as (select deadline from public.branch_groups where group_id = p_group)
  select jsonb_build_object(
    'group', p_group,
    'total', (select count(*) from b),
    'done', (select count(*) from b where state = 'complete'),
    'failed', (select count(*) from b where state in ('failed', 'cancelled')),
    'running', (select count(*) from b where state not in ('complete', 'failed', 'cancelled')),
    'past_deadline', (select deadline is not null and deadline < app.now_utc() from g),
    /*
      Ready when every REQUIRED branch has settled and either every branch has,
      or the deadline has passed. A required branch that failed still counts as
      settled: the answer must then say the domain is missing rather than wait
      for ever.
    */
    'ready', (
      select not exists (
        select 1 from b where b.required
          and b.state not in ('complete', 'failed', 'cancelled'))
        and (
          not exists (select 1 from b where b.state not in ('complete', 'failed', 'cancelled'))
          or (select deadline is not null and deadline < app.now_utc() from g))),
    'waiting_for', coalesce((
      select jsonb_agg(jsonb_build_object('agent', b.agent, 'name', b.name,
                                          'purpose', b.purpose,
                                          'required', b.required, 'state', b.state)
             order by b.required desc, b.agent)
        from b where b.state not in ('complete', 'failed', 'cancelled')), '[]'::jsonb),
    /*
      The lost branches carry the person's NAME as well as the slug, because
      the gate that stops a synthesis crediting them matches on what a model
      would write. A model writes "Ruby", never "growth-director".
    */
    'lost', coalesce((
      select jsonb_agg(jsonb_build_object('agent', b.agent, 'name', b.name,
                                          'purpose', b.purpose,
                                          'required', b.required, 'state', b.state)
             order by b.agent)
        from b where b.state in ('failed', 'cancelled')), '[]'::jsonb)
  );
$$;


--
-- Name: fire_pending_signals(integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.fire_pending_signals(p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare v_signal uuid; v_out jsonb := '[]'::jsonb;
begin
  for v_signal in
    select s.signal_id from public.signals s
     where s.received_at > app.now_utc() - interval '1 hour'
       and not exists (select 1 from public.trigger_firings f where f.signal_id = s.signal_id)
       and exists (select 1 from public.event_triggers t
                    where t.source = s.source and t.event_type = s.event_type)
     order by s.received_at
     limit greatest(1, least(100, coalesce(p_limit, 20)))
  loop
    v_out := v_out || app.fire_triggers_for(v_signal);
  end loop;
  return jsonb_build_object('ok', true, 'looked_at', jsonb_array_length(v_out),
                            'decisions', v_out);
end;
$$;


--
-- Name: FUNCTION fire_pending_signals(p_limit integer); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.fire_pending_signals(p_limit integer) IS 'Decide what to do about signals nobody has decided about yet (#264). Only those with a trigger that could match and only those from the last hour -- a signal from before a restart is not news.';


--
-- Name: fire_triggers_for(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.fire_triggers_for(p_signal uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  e public.signals%rowtype; t public.event_triggers%rowtype;
  v_out jsonb := '[]'::jsonb; v_job uuid; v_decision text; v_why text;
  v_last timestamptz; v_recent integer;
begin
  select * into e from public.signals where signal_id = p_signal;
  if not found then
    return jsonb_build_object('error', 'no such signal');
  end if;

  for t in
    select * from public.event_triggers
     where source = e.source and event_type = e.event_type
       and (project_id is null or project_id = e.project_id)
     order by name
  loop
    v_job := null; v_decision := null; v_why := '';

    if not t.enabled then
      v_decision := 'disabled'; v_why := 'the trigger is switched off';
    elsif t.not_before_event_at is not null and e.happened_at < t.not_before_event_at then
      v_decision := 'too_old';
      v_why := format('it happened at %s and this trigger ignores anything before %s',
                      e.happened_at, t.not_before_event_at);
    elsif not app.signal_matches(e, t.filters) then
      v_decision := 'filtered_out'; v_why := 'the filters did not match';
    else
      /*
        The loop guard. An event the office caused, by a job THIS trigger
        created, must not fire it again -- which is the shape of every runaway
        automation: a trigger whose action produces another matching event.
      */
      if e.caused_by_job is not null and exists (
        select 1 from public.trigger_firings f
         where f.trigger_id = t.trigger_id and f.job_id = e.caused_by_job) then
        v_decision := 'would_have_looped';
        v_why := 'this event was caused by a job this trigger started';
      else
        select max(at) into v_last from public.trigger_firings
         where trigger_id = t.trigger_id and decision = 'fired';
        select count(*) into v_recent from public.trigger_firings
         where trigger_id = t.trigger_id and decision = 'fired'
           and at > app.now_utc() - interval '1 hour';

        if t.debounce_seconds > 0 and v_last is not null
           and v_last > app.now_utc() - make_interval(secs => t.debounce_seconds) then
          v_decision := 'debounced';
          v_why := format('another fired %s seconds ago and the window is %s',
                          round(extract(epoch from (app.now_utc() - v_last))), t.debounce_seconds);
        elsif t.cooldown_seconds > 0 and v_last is not null
              and v_last > app.now_utc() - make_interval(secs => t.cooldown_seconds) then
          v_decision := 'cooling_down';
          v_why := format('it last fired %s seconds ago and the cooldown is %s',
                          round(extract(epoch from (app.now_utc() - v_last))), t.cooldown_seconds);
        elsif v_recent >= t.max_per_hour then
          v_decision := 'rate_limited';
          v_why := format('%s already this hour and the limit is %s', v_recent, t.max_per_hour);
        end if;
      end if;
    end if;

    if v_decision is null then
      /*
        A real job, on the ordinary queue, with the ordinary everything.

        `requested_by` says a trigger asked, which makes trigger-started work
        countable and keeps it out of the readings that count what GRANT asked
        for -- the distinction `duty:` already draws for a schedule.
      */
      insert into public.jobs
        (kind, idempotency_key, correlation_id, requested_by, project_id, state,
         recipient_agent, announce, pinned_config)
      values (t.job_kind,
              format('trigger-%s-%s', left(t.name, 40), e.signal_id),
              gen_random_uuid(),
              format('trigger:%s', t.name),
              coalesce(e.project_id, t.project_id),
              'queued', t.recipient_agent, false,
              t.payload || jsonb_build_object(
                'event', jsonb_build_object(
                  'id', e.signal_id, 'source', e.source, 'type', e.event_type,
                  'summary', e.summary, 'detail', e.detail,
                  'happened_at', e.happened_at),
                'trigger', t.name,
                'needs_approval', t.needs_approval))
      returning job_id into v_job;
      v_decision := 'fired'; v_why := format('started %s', t.job_kind);
    end if;

    insert into public.trigger_firings (trigger_id, signal_id, job_id, decision, why)
    values (t.trigger_id, e.signal_id, v_job, v_decision, v_why)
    on conflict (trigger_id, signal_id) do nothing;

    v_out := v_out || jsonb_build_object('trigger', t.name, 'decision', v_decision,
                                         'why', v_why, 'job', v_job);
  end loop;

  return jsonb_build_object('ok', true, 'signal', p_signal, 'triggers', v_out);
end;
$$;


--
-- Name: folder_id_from(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.folder_id_from(p_url text) RETURNS text
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
  select nullif(
    coalesce(
      -- .../folders/<id>
      (regexp_match(coalesce(p_url, ''), '/folders/([A-Za-z0-9_-]{10,})'))[1],
      -- ...?id=<id>
      (regexp_match(coalesce(p_url, ''), '[?&]id=([A-Za-z0-9_-]{10,})'))[1],
      -- a bare id, pasted on its own
      (regexp_match(btrim(coalesce(p_url, '')), '^([A-Za-z0-9_-]{10,})$'))[1]
    ), '')
$_$;


--
-- Name: FUNCTION folder_id_from(p_url text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.folder_id_from(p_url text) IS 'The folder id out of whatever Grant pasted — a share link, a query-string link, or the bare id. One implementation, because three callers deriving it themselves is three regexes that drift.';


--
-- Name: forget_mail_before(integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.forget_mail_before(p_days integer DEFAULT 180) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare v_cut timestamptz; v_gone integer;
begin
  if coalesce(p_days, 0) < 30 then
    return jsonb_build_object('ok', false,
      'error', 'a retention shorter than 30 days would drop mail the office is still answering from');
  end if;
  v_cut := app.now_utc() - make_interval(days => p_days);
  delete from public.mail_messages where sent_at is not null and sent_at < v_cut;
  get diagnostics v_gone = row_count;
  return jsonb_build_object('ok', true, 'removed', v_gone, 'before', v_cut);
end;
$$;


--
-- Name: forget_mail_bodies_before(integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.forget_mail_bodies_before(p_days integer DEFAULT 90) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare v_cut timestamptz; v_gone integer;
begin
  if coalesce(p_days, 0) < 7 then
    return jsonb_build_object('ok', false,
      'error', 'a body retention shorter than 7 days would drop correspondence mid-conversation');
  end if;
  v_cut := app.now_utc() - make_interval(days => p_days);
  update public.mail_messages
     set body = null,
         body_at = null,
         /*
           Not 'bulk' and not 'no text part' -- both would be false. A body the
           office aged out is a fourth state, and saying one of the other three
           is how a reader comes to report a deliberate withholding as a fact
           about the message.
         */
         body_withheld = null
   where body is not null
     and body_at < v_cut;
  get diagnostics v_gone = row_count;
  return jsonb_build_object('ok', true, 'forgotten', v_gone, 'before', v_cut);
end;
$$;


--
-- Name: free_tier_headroom(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.free_tier_headroom() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  -- The Supabase free tier, as documented, in bytes. Named here so the numbers
  -- below are a comparison rather than a magic constant three lines long.
  db_limit      bigint := 500 * 1024 * 1024;
  storage_limit bigint := 1024 * 1024 * 1024;
  db_bytes      bigint;
  storage_bytes bigint;
begin
  select pg_catalog.pg_database_size(pg_catalog.current_database()) into db_bytes;

  /*
    `metadata->>'size'`, not a column.

    `storage.objects` has no size column — the byte count lives in the metadata
    the storage API writes when the object is uploaded. An object whose metadata
    is missing counts as zero rather than nulling the whole sum, because one
    unmeasurable file must not make the total unreadable.
  */
  select coalesce(sum(coalesce((o.metadata->>'size')::bigint, 0)), 0)
    into storage_bytes
    from storage.objects o;

  return jsonb_build_object(
    'database', jsonb_build_object(
      'bytes', db_bytes,
      'limit_bytes', db_limit,
      'percent', round((db_bytes::numeric / db_limit) * 100, 1),
      'human', pg_catalog.pg_size_pretty(db_bytes),
      'limit_human', pg_catalog.pg_size_pretty(db_limit)
    ),
    'storage', jsonb_build_object(
      'bytes', storage_bytes,
      'limit_bytes', storage_limit,
      'percent', round((storage_bytes::numeric / storage_limit) * 100, 1),
      'human', pg_catalog.pg_size_pretty(storage_bytes),
      'limit_human', pg_catalog.pg_size_pretty(storage_limit),
      'objects', (select count(*) from storage.objects)
    ),
    -- The five biggest tables, because "the database is at 61%" is a fact and
    -- "and 70% of that is one table of embeddings" is an action.
    'largest', coalesce((
      select jsonb_agg(x)
        from (
          select jsonb_build_object(
                   'table', n.nspname || '.' || c.relname,
                   'bytes', pg_catalog.pg_total_relation_size(c.oid),
                   'human', pg_catalog.pg_size_pretty(pg_catalog.pg_total_relation_size(c.oid))
                 ) as x
            from pg_catalog.pg_class c
            join pg_catalog.pg_namespace n on n.oid = c.relnamespace
           where c.relkind = 'r' and n.nspname not in ('pg_catalog', 'information_schema')
           order by pg_catalog.pg_total_relation_size(c.oid) desc
           limit 5
        ) t
    ), '[]'::jsonb),
    'measured_at', app.now_utc()
  );
end;
$$;


--
-- Name: FUNCTION free_tier_headroom(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.free_tier_headroom() IS 'Real database and storage usage against the Supabase free tier, measured from pg_database_size and storage.objects metadata. The Management API has no usage endpoint for a project-scoped token, and the figure on the Settings page was invented.';


--
-- Name: github_dispatch(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.github_dispatch() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select jsonb_build_object(
    'repository', (select value #>> '{}' from public.system_config
                    where key = 'github.repository'),
    'token', (select decrypted_secret from vault.decrypted_secrets
               where name = 'github.dispatch_token')
  )
$$;


--
-- Name: google_revoke_begin(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.google_revoke_begin() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_token text;
  v_job   uuid;
  v_old   uuid;
begin
  select decrypted_secret into v_token
    from vault.decrypted_secrets where name = 'google.refresh_token';

  if v_token is null or btrim(v_token) = '' then
    return jsonb_build_object('parked', false, 'job_id', null);
  end if;

  -- Overwrite rather than accumulate: a second Disconnect before the first
  -- revoke has run must not leave two live tokens parked.
  select id into v_old from vault.secrets where name = 'google.revoking_refresh_token';
  if v_old is null then
    perform vault.create_secret(v_token, 'google.revoking_refresh_token',
      'A Google refresh token awaiting revocation at Google (#109). Deleted by '
      || 'app.google_revoke_finish whether the revoke succeeds or fails.');
  else
    perform vault.update_secret(v_old, v_token, 'google.revoking_refresh_token');
  end if;

  -- The office's copy goes NOW. `app.vault_secret` refuses any name outside
  -- its list and `googleAccess` asks for this one, so from this statement on
  -- nothing in the office can use the credential.
  delete from vault.secrets where name = 'google.refresh_token';

  insert into public.jobs
    (correlation_id, project_id, idempotency_key, kind, requested_by, priority)
  values (gen_random_uuid(), null,
          format('google-revoke-%s', gen_random_uuid()),
          'google.revoke', 'grant', 400)
  returning job_id into v_job;

  return jsonb_build_object('parked', true, 'job_id', v_job);
end;
$$;


--
-- Name: google_revoke_finish(boolean, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.google_revoke_finish(p_ok boolean, p_detail text DEFAULT ''::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_gone int := 0;
begin
  delete from vault.secrets where name = 'google.revoking_refresh_token';
  get diagnostics v_gone = row_count;

  update public.connection_health
     set state = 'missing',
         detail = case when p_ok
           then 'signed out, and the grant is revoked at Google'
           else 'signed out here; Google did not confirm the revoke'
                || case when btrim(coalesce(p_detail, '')) = '' then ''
                        else ' (' || left(btrim(p_detail), 120) || ')' end
         end,
         action = case when p_ok
           then 'Sign in with Google on the Set up page'
           -- The honest instruction when we could not do it ourselves, and the
           -- reason this branch says something different rather than
           -- pretending: a person who thinks a grant is dead does not go and
           -- kill it.
           else 'Revoke it yourself at https://myaccount.google.com/permissions'
         end,
         checked_at = app.now_utc()
   where service = 'google_calendar';

  return jsonb_build_object('ok', true, 'parked_copy_removed', v_gone, 'revoked', p_ok);
end;
$$;


--
-- Name: google_scopes_in_use(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.google_scopes_in_use() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  /*
    Distinct, because two services can legitimately want the same scope and a
    consent URL that repeats one is not wrong but is untidy in the one place a
    person reads it carefully. Ordered, so the same set produces the same
    string and a diff of a consent URL means something.
  */
  select coalesce(
    (select string_agg(s, ' ' order by s)
       from (
         select distinct unnest(string_to_array(g.scopes, ' ')) as s
           from public.google_services g
          where g.offered
            and exists (
              select 1 from public.tool_permissions t
               where t.enabled and t.tool like g.slug || '.%')
       ) x
      where s <> ''),
    '')
$$;


--
-- Name: FUNCTION google_scopes_in_use(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.google_scopes_in_use() IS 'Every Google scope the office actually has an enabled capability for (#172). The default for the Connect Google button, which asked for Calendar alone while Gmail and Drive share the same refresh token.';


--
-- Name: google_service_scopes(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.google_service_scopes(p_slug text) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  select coalesce(
    (select scopes from public.google_services where slug = p_slug and offered),
    ''
  )
$$;


--
-- Name: grant_standing(text, uuid, text, text, timestamp with time zone); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.grant_standing(p_tool text, p_project uuid, p_reason text, p_by text, p_until timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare v_id uuid;
begin
  if coalesce(btrim(p_reason), '') = '' then
    return jsonb_build_object('ok', false,
      'error', 'a standing authorization needs a reason — it is what makes it reviewable later');
  end if;

  -- Replace rather than collide. Saying it again with a better reason is the
  -- common case, and the unique index would otherwise refuse it.
  update public.standing_authorizations
     set revoked_at = app.now_utc(), revoked_reason = 'replaced by a newer standing authorization'
   where tool = p_tool and revoked_at is null
     and project_id is not distinct from p_project;

  insert into public.standing_authorizations (project_id, tool, reason, granted_by, expires_at)
  values (p_project, p_tool, btrim(p_reason), p_by, p_until)
  returning authorization_id into v_id;

  return jsonb_build_object('ok', true, 'authorization', v_id, 'tool', p_tool,
    'scope', case when p_project is null then 'everywhere' else 'this project' end);
end;
$$;


--
-- Name: grant_timezone(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.grant_timezone() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(
    (select value #>> '{}' from public.system_config where key = 'grant.timezone'),
    'Europe/London')
$$;


--
-- Name: FUNCTION grant_timezone(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.grant_timezone() IS 'The zone a wall-clock duty is measured in. Read from config rather than hardcoded, because he moves and the briefing should follow him.';


--
-- Name: guess_reach(text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.guess_reach(p_name text, p_description text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  with words as (
    select
      -- Separators become spaces so a snake_case or dotted name reads as
      -- words, and camelCase gains a boundary before each capital.
      lower(regexp_replace(
        regexp_replace(coalesce(p_name, ''), '([a-z0-9])([A-Z])', '\1 \2', 'g'),
        '[^a-zA-Z0-9]+', ' ', 'g')) as name,
      lower(regexp_replace(coalesce(p_description, ''), '[^a-zA-Z0-9]+', ' ', 'g')) as descr
  ),
  patterns as (
    select
      '\m(delete|destroy|remove|purge|drop|wipe|revoke|cancel|uninstall|terminate)\M' as gone,
      '\m(pay|charge|order|purchase|buy|invoice|transfer|wire|refund|subscribe)\M' as money,
      '\m(send|post|create|update|write|add|set|put|patch|upload|publish|invite)\M' as writes,
      '\m(get|list|read|search|find|fetch|query|show|describe|lookup|count)\M' as looks
  ),
  /*
    The name is evidence and the description is a claim. Each is judged on its
    own, and only then are they combined — by taking the MORE dangerous of the
    two, never the less.
  */
  judged as (
    select
      case
        when w.name ~ p.gone   then 4
        when w.name ~ p.money  then 3
        when w.name ~ p.writes then 2
        when w.name ~ p.looks  then 1
        else 0
      end as by_name,
      case
        when w.descr ~ p.gone   then 4
        when w.descr ~ p.money  then 3
        when w.descr ~ p.writes then 2
        else 0   -- a description saying "read only" carries no weight at all
      end as by_description,
      w.name ~ p.looks as name_only_looks
    from words w, patterns p
  )
  select case greatest(by_name, by_description)
    when 4 then jsonb_build_object('reach', 'destructive',
      'why', case when by_name = 4 then 'the tool''s NAME says it removes something'
                  else 'the provider says it removes something' end)
    when 3 then jsonb_build_object('reach', 'destructive',
      'why', 'it moves money, which the office treats as destructive until a person says otherwise')
    when 2 then jsonb_build_object('reach', 'write',
      'why', case when by_name = 2 then 'the tool''s NAME says it changes something outside'
                  else 'the provider says it changes something outside' end)
    when 1 then jsonb_build_object('reach', 'read',
      'why', 'the tool''s name says it only looks, and nothing contradicts it')
    else jsonb_build_object('reach', 'unknown',
      'why', 'nothing in the name says what it does')
  end
  from judged;
$$;


--
-- Name: FUNCTION guess_reach(p_name text, p_description text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.guess_reach(p_name text, p_description text) IS 'What reach a discovered tool probably has. The NAME is evidence and the DESCRIPTION is a claim: the description may only ever make a tool look more dangerous, never less, because a hostile server writes its own description.';


--
-- Name: guess_reference_kind(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.guess_reference_kind(p_url text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
  select case
    when p_url ~* '/api/|api\.|/v[0-9]+/|\.json$|graphql' then 'api'
    when p_url ~* 'drive\.google\.com/drive/folders|dropbox\.com/home|/folder/' then 'folder'
    when p_url ~* '\.(pdf|docx?|pptx?|xlsx?|csv|md|txt)($|\?)' then 'document'
    when p_url ~* '^[a-z][a-z0-9+.-]*:' and p_url !~* '^https?:' then 'application'
    else 'website'
  end
$_$;


--
-- Name: guess_reference_title(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.guess_reference_title(p_url text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
  select nullif(
    btrim(regexp_replace(
      regexp_replace(lower(btrim(coalesce(p_url, ''))), '^https?://(www\.)?', ''),
      '[?#].*$', '')),
    '')
$_$;


--
-- Name: harness_browsing(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.harness_browsing(p_job uuid, p_project uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    -- a harness job, whatever the project says
    (p_job is not null and app.harness_job(p_job))
    -- or a fixture project, whatever the job says
    or (p_project is not null and exists (
          select 1 from public.projects x
           where x.project_id = p_project and x.is_fixture))
    -- or nothing that can vouch for it at all
    or (p_job is null and p_project is null);
$$;


--
-- Name: FUNCTION harness_browsing(p_job uuid, p_project uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.harness_browsing(p_job uuid, p_project uuid) IS 'Is this browsing row the harness talking to itself? Derived from the job and the project because an append-only copy would freeze the answer. Either witness may exclude; neither may confirm -- hence or, not coalesce.';


--
-- Name: harness_escapes(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.harness_escapes() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'since', app.harness_guard_since(),
    'escaped', coalesce((
      select jsonb_agg(jsonb_build_object(
               'channel', d.channel, 'target', d.target_ref,
               'by', j.requested_by, 'at', d.sent_at) order by d.sent_at desc)
        from public.deliveries d
        join public.jobs j on j.job_id = d.job_id
       where app.harness_job(d.job_id)
         and d.sent_at is not null
         and d.created_at > app.harness_guard_since()), '[]'::jsonb),
    'refused', coalesce((
      select count(*)::int from public.deliveries d
       where app.harness_job(d.job_id)
         and d.state = 'suppressed'
         and d.suppressed_reason like '%production destination%'
         and d.created_at > app.harness_guard_since()), 0),
    /*
      And the historical total, reported rather than hidden. The number is the
      argument for the guard and nobody should have to dig for it.
    */
    'before_the_guard', coalesce((
      select count(*)::int from public.deliveries d
       where app.harness_job(d.job_id) and d.sent_at is not null
         and d.created_at <= app.harness_guard_since()), 0))
$$;


--
-- Name: harness_guard_since(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.harness_guard_since() RETURNS timestamp with time zone
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(
    (select applied_at from app.schema_migrations
      where name like '0523_%' limit 1),
    /*
      Not `now()` as the fallback. If the row is ever missing, a fallback of
      "now" would make the window empty and every escape invisible — the
      found-nothing shape, on the one check that must not have it. An
      impossible past makes the check count EVERYTHING and go loudly red,
      which is the safe direction to fail in.
    */
    '-infinity'::timestamptz)
$$;


--
-- Name: harness_job(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.harness_job(p_job_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select coalesce(
    (select j.is_fixture or coalesce(p.is_fixture, false)
       from public.jobs j
       left join public.projects p on p.project_id = j.project_id
      where j.job_id = p_job_id),
    false)
$$;


--
-- Name: FUNCTION harness_job(p_job_id uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.harness_job(p_job_id uuid) IS 'True when a job is harness traffic - by its own generated is_fixture, or because it belongs to a fixture PROJECT, which the generated column cannot see (#212). NULL job means not harness: an unattributable row is real.';


--
-- Name: harness_label(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.harness_label(p_name text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  -- The same prefixes `jobs.is_fixture` is generated from, in one place.
  -- Separator-anchored, so a real capability called `verification_report`
  -- is not swept by a rule about `verify-`.
  select coalesce(p_name, '') ~ '^(fixture|verify|probe|gate|ledger-proof)[-_.:]'
      or coalesce(p_name, '') ~ ':(fixture|verify|probe|gate)[-_.:]'
$$;


--
-- Name: FUNCTION harness_label(p_name text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.harness_label(p_name text) IS 'Does this name belong to the harness (0473)? One predicate, so a reader that must keep test traffic off a page Grant reads does not invent its own.';


--
-- Name: harness_proposal(text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.harness_proposal(p_staff text, p_needed text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case
           -- No evidence at all: not harness. See the header — an absent
           -- witness excludes nothing.
           when not exists (
             select 1 from public.job_impediments i
              where i.staff_slug = p_staff and i.needed = p_needed
           ) then false
           -- Harness only when EVERY impediment behind it is harness traffic.
           -- One real occurrence makes the proposal real, which is the safe
           -- direction: a genuine gap can never be hidden by a suite that
           -- happened to hit the same wall.
           else not exists (
             select 1
               from public.job_impediments i
               left join public.jobs j on j.job_id = i.job_id
              where i.staff_slug = p_staff
                and i.needed = p_needed
                and not (coalesce(i.is_fixture, false)
                         or coalesce(j.is_fixture, false)
                         or coalesce(app.harness_job(i.job_id), false))
           )
         end
     -- And the cheap half: a name that DOES announce itself still counts.
     or app.harness_label(p_needed)
$$;


--
-- Name: FUNCTION harness_proposal(p_staff text, p_needed text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.harness_proposal(p_staff text, p_needed text) IS '#49/#272. Whether a proposal is harness traffic, DERIVED from the impediments that evidenced it rather than guessed from its wording. verify:proposes names its subject to read like a real one on purpose (#45), so no pattern over `needed` can ever be right; what a suite cannot fake is the provenance of its own jobs.';


--
-- Name: harness_task(boolean, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.harness_task(p_is_fixture boolean, p_job uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select coalesce(p_is_fixture, false)
      or (p_job is not null and app.harness_job(p_job))
$$;


--
-- Name: FUNCTION harness_task(p_is_fixture boolean, p_job uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.harness_task(p_is_fixture boolean, p_job uuid) IS 'Is this task harness traffic? Derived from the row flag and the job that made it (0530).';


--
-- Name: held_for_budget(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.held_for_budget() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select jsonb_build_object(
    'jobs', count(*),
    'why', coalesce((array_agg(distinct j.state_reason))[1], null),
    'until', min(j.not_before))
    from public.jobs j
   where j.state = 'queued'
     and j.not_before > app.now_utc()
     and j.state_reason like '%daily limit%'
     and not coalesce(app.harness_job(j.job_id), false)
$$;


--
-- Name: hq_activity(integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_activity(p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(row_to_json(a)), '[]'::jsonb) from (
    select c.job_id, j.kind, j.project_id, p.name as project_name,
           c.from_state::text as from_state, c.to_state::text as to_state,
           c.reason, c.attempt, c.occurred_at
    from public.job_state_transitions c
    join public.jobs j on j.job_id = c.job_id
    left join public.projects p on p.project_id = j.project_id
    order by c.occurred_at desc
    limit least(greatest(p_limit, 1), 200)
  ) a;
$$;


--
-- Name: hq_answer_blocker(uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_answer_blocker(p_blocker_id uuid, p_answer text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  b        public.blockers;
  v_answer text := btrim(coalesce(p_answer, ''));
  v_next   text;
  v_was    text;
  v_standing jsonb;
  v_started integer := 0;
begin
  select * into b from public.blockers where blocker_id = p_blocker_id;
  if not found then
    return jsonb_build_object('error', 'there is nothing here to answer');
  end if;
  if b.state <> 'open' then
    -- Not an error. Answering something already answered is what two open tabs
    -- produces, and the honest reply is what it was answered with.
    return jsonb_build_object('ok', false, 'already', true,
      'state', b.state::text, 'resolution', b.resolution);
  end if;
  if v_answer = '' then
    return jsonb_build_object('error', 'say what the answer is');
  end if;

  if array_length(b.approval_options, 1) is not null
     and not (v_answer = any (b.approval_options)) then
    return jsonb_build_object('error', format(
      'that is not one of the answers this asks for: %s',
      array_to_string(b.approval_options, ', ')));
  end if;

  /*
    A generation approval is answered by the function that already knows what
    approving one MEANS — it queues the follow-on job. Resolving the row here
    instead would mark it answered and queue nothing.
  */
  select pinned_config ->> 'approval_next' into v_next
    from public.jobs where job_id = b.job_id;
  if v_next is not null then
    return app.answer_generation_approval(
      p_blocker_id,
      -- The affirmative half of whatever this blocker offered. Matched against
      -- the words agents actually use rather than assuming the first option is
      -- the yes, which is true today and is not a rule anybody wrote down.
      lower(v_answer) in ('yes', 'approve', 'approved', 'go ahead', 'ok', 'do it'),
      'grant'
    ) || jsonb_build_object('ok', true, 'answer', v_answer);
  end if;

  /*
    "From now on" becomes a row, not a sentence (#15).

    The Drive watcher has offered "do not ask again" as an option since it was
    written, and nothing could honour it -- there was nowhere to write the
    answer. Now the blocker NAMES the tool a standing authorization would cover
    and which of its options grants one, so this does not have to read English
    to find out. `blockers.approval_options` is free text a handler composes;
    deciding a permission by matching words in it would be the parsing defect
    #130 is about, one layer up.

    Scoped to the blocker's own project. A question asked about one project is
    not consent for every project, and `grant_standing` takes null for
    everywhere only when a caller passes it deliberately.

    Never fatal, and never silent: if the grant is refused (a level-3 tool, an
    unknown one) the answer still resolves the blocker and the outcome says
    what happened, because losing Grant's answer to protect a permission would
    be the worse of the two.
  */
  if b.standing_tool is not null
     and b.standing_option is not null
     and v_answer = b.standing_option then
    v_standing := app.grant_standing(
      b.standing_tool, b.project_id,
      format('You answered "%s" on %s.', v_answer, b.created_at::date), 'grant', null);
  end if;

  /*
    And the office remembers it decided this (#129).

    The options Grant did NOT pick are `ruled_out`, which is the field the
    Issue is about and the one that would otherwise be skipped: *"we chose
    Notion" is worth a fraction of "we chose Notion over Drive because..."*.
    They are right here, in `approval_options`, and no model is needed to know
    what they were.

    `decided_by` is 'grant', which is what lets the reader treat this as a
    record of what HE said rather than as the office's own prose.

    Never fatal. Losing his answer to protect a memory of it would be the wrong
    way round, and a write allowed to fail must say so rather than vanish --
    which is why the failure is recorded rather than swallowed.
  */
  begin
    perform app.record_decision_made(
      b.requested_action,
      v_answer,
      (select array_agg(o) from unnest(coalesce(b.approval_options, array[]::text[])) o
        where o <> v_answer),
      coalesce(nullif(btrim(b.why_needed), ''), 'You answered the question the office asked.'),
      'grant', b.project_id, b.job_id, null);
  exception when others then
    perform app.cannot(b.job_id, 'not_capable', 'remember this decision',
                       'hq_answer_blocker', left(sqlerrm, 400), null);
  end;

  /*
    And the answer DOES the thing (#257).

    `handlers/drive.ts` has offered "Add them to the project as source
    documents" since #62, and answering it has never been able to work: the
    page token advances whether or not Grant was asked, so by the time he
    answers, those files are no longer in the change list and there is nothing
    left to act on. A dead option on a question he can see.

    So the blocker carries WHAT ANSWERING PERFORMS, written by the handler that
    raised it: a job kind and one payload per thing. Not a model's words and
    not an interpretation of the option text -- the parsing defect #130 is
    about, on a path that enqueues work.

    Bounded on purpose: through `app.enqueue_child`, on the blocker's own job,
    so the child inherits the project and the requester and
    `enforce_delegation_depth` caps it. Nothing here can reach a project the
    question did not come from.

    Never fatal, and never silent: a failure here is an impediment, because
    losing his answer to protect a queue would be the wrong way round.
  */
  if b.on_answer is not null
     and b.on_answer ? 'option'
     and v_answer = (b.on_answer ->> 'option')
     and coalesce(b.on_answer ->> 'kind', '') <> '' then
    begin
      select count(*) into v_started
        from jsonb_array_elements(coalesce(b.on_answer -> 'payloads', '[]'::jsonb)) as pay
       where app.enqueue_child(b.job_id, b.on_answer ->> 'kind', pay, interval '0', false)
             is not null;
    exception when others then
      perform app.cannot(b.job_id, 'not_capable',
                         format('do what answering %L promised', v_answer),
                         'hq_answer_blocker', left(sqlerrm, 400), null);
    end;
  end if;

  update public.blockers
     set state = 'resolved',
         resolved_at = app.now_utc(),
         resolution = format('%s — answered by grant', v_answer)
   where blocker_id = p_blocker_id;

  /*
    And the job is let go, by the road the state machine allows.

    A resolved blocker whose job is still parked in `waiting_user` is a job
    nothing will ever pick up — the interface would say answered and nothing
    would run. But `waiting_user -> queued` is not an edge, and 0290's header
    says why it should not be: `queued` means nobody has looked at this yet.

    So: park it, then queue it. Both transitions are written to
    `job_state_transitions` by the trigger, and the ledger reads as what
    happened — the wait ended, then the job went back in the queue.
  */
  -- One definition, in app.let_job_go (0496, 0497). A second copy here is
  -- two writers of one field, which is what 0472 exists to stop.
  perform app.let_job_go(b.job_id, format('answered: %s', v_answer));

  return jsonb_build_object('ok', true, 'answer', v_answer, 'blocker', p_blocker_id,
    -- Null when the answer granted nothing, which is the common case.
    'standing', v_standing,
    -- How many jobs answering actually started. Zero is the common case
    -- and is not an error; a number he can hold against what he was
    -- promised is the point (0350's rule about a claim with nothing
    -- behind it).
    'started', v_started);
end;
$$;


--
-- Name: hq_appearance(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_appearance(p_owner text DEFAULT 'grant'::text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select coalesce((select a.settings from public.appearance_settings a
                    where a.owner = coalesce(nullif(btrim(p_owner), ''), 'grant')),
                  '{}'::jsonb)
$$;


--
-- Name: FUNCTION hq_appearance(p_owner text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.hq_appearance(p_owner text) IS 'What this person chose, or an empty object (#124, 0400). Empty means nothing has been chosen, NOT that the defaults are these - the defaults live in the page, where they can be seen beside the thing they affect.';


--
-- Name: hq_appearance_set(jsonb, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_appearance_set(p_settings jsonb, p_owner text DEFAULT 'grant'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_owner text := coalesce(nullif(btrim(p_owner), ''), 'grant');
begin
  if p_settings is null or jsonb_typeof(p_settings) <> 'object' then
    return jsonb_build_object('error', 'appearance must be an object');
  end if;
  /*
    Checked here as well as by the constraint, so the answer is a sentence the
    page can show rather than a 23514 the adapter turns into "upstream failed".
    An uploaded texture is the only value that can approach this.
  */
  if length(p_settings::text) > 98304 then
    return jsonb_build_object('error',
      'that is too large to keep - an uploaded texture should be resized first');
  end if;

  insert into public.appearance_settings (owner, settings, updated_at)
  values (v_owner, p_settings, app.now_utc())
  on conflict (owner) do update
    set settings = excluded.settings, updated_at = excluded.updated_at;

  return jsonb_build_object('saved', true, 'settings', p_settings);
end;
$$;


--
-- Name: FUNCTION hq_appearance_set(p_settings jsonb, p_owner text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.hq_appearance_set(p_settings jsonb, p_owner text) IS 'Remember how the studio should look (#124, 0400). The whole object at once, because that is how the page holds it and a partial write would need the caller to know which keys exist.';


--
-- Name: hq_artifacts(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_artifacts() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select coalesce(jsonb_agg(a order by a.created_at desc), '[]'::jsonb)
    from (
      select ar.artifact_id, ar.kind, ar.title, ar.url,
             ar.url is not null as openable,
             -- Whether the office started it, or merely found it in the
             -- notebook and adopted it (#260). Grant's own audio overview is
             -- not the office's work and should not read as it.
             ar.requested_by_job is not null as mine,
             ar.state, ar.detail, ar.created_at, ar.ready_at, p.name as project
        from public.artifacts ar
        join public.projects p using (project_id)
       order by ar.created_at desc
       limit 40
    ) a
$$;


--
-- Name: FUNCTION hq_artifacts(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.hq_artifacts() IS 'What the notebook has made for us and where to open it. The answer to "display the results as a link" on the surface that is a page.';


--
-- Name: hq_attach(text, text, text, text, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_attach(p_slug text, p_connector text, p_ref text, p_role text DEFAULT 'source'::text, p_kind text DEFAULT NULL::text, p_display text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_project uuid;
  v_row     public.project_attachments%rowtype;
begin
  select project_id into v_project from public.projects where slug = p_slug;
  if v_project is null then
    return jsonb_build_object('error', format('no project called %L', p_slug));
  end if;

  -- The registry, not a list. A connector that is registered and enabled can
  -- be attached; one that is not says why in its own words.
  if not exists (
    select 1 from public.knowledge_connectors k
     where k.connector = p_connector and k.enabled
  ) then
    return jsonb_build_object(
      'error', format('%L is not a connector this office has', p_connector),
      'reason', (select k.disabled_reason from public.knowledge_connectors k
                  where k.connector = p_connector),
      'connectors', (select jsonb_agg(k.connector order by k.connector)
                       from public.knowledge_connectors k where k.enabled));
  end if;

  /*
    Drive has its own front door, and it does three things this one cannot:
    reads the folder id out of a pasted share link, refuses a folder another
    project already watches, and creates the `drive_watch` row.

    An attachment without that row is a folder nobody looks at — which is
    indistinguishable from one being watched until nothing is ever reported.
  */
  if p_connector = 'drive' then
    return app.attach_drive_folder(v_project, p_ref, p_display, 'grant');
  end if;

  insert into public.project_attachments
    (project_id, connector, external_ref, display_name, role, artifact_kind)
  values
    (v_project, p_connector, btrim(p_ref),
     nullif(btrim(coalesce(p_display, '')), ''), p_role, p_kind)
  on conflict do nothing
  returning * into v_row;

  if v_row.attachment_id is null then
    select * into v_row from public.project_attachments
     where project_id = v_project and connector = p_connector
       and external_ref = btrim(p_ref);
  end if;

  return jsonb_build_object(
    'attachment_id', v_row.attachment_id,
    'connector', p_connector,
    'role', p_role);
end;
$$;


--
-- Name: FUNCTION hq_attach(p_slug text, p_connector text, p_ref text, p_role text, p_kind text, p_display text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.hq_attach(p_slug text, p_connector text, p_ref text, p_role text, p_kind text, p_display text) IS 'Attach something to a dashboard project. The allowed connectors come from `knowledge_connectors`, not from a list in here — registering a connector should be the whole job of adding one (#62). Drive delegates to attach_drive_folder, which also starts the watch.';


--
-- Name: hq_autonomy_set(text, uuid, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_autonomy_set(p_level text, p_project_id uuid DEFAULT NULL::uuid, p_by text DEFAULT 'grant'::text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_was text;
begin
  if p_level not in ('observe', 'suggest', 'act_with_review', 'act') then
    return jsonb_build_object('error',
      format('%L is not an autonomy level. They are: observe, suggest, '
             || 'act_with_review, act.', p_level));
  end if;

  select a.level::text into v_was
    from public.autonomy_settings a
   where a.project_id is not distinct from p_project_id
   order by a.set_at desc limit 1;

  insert into public.autonomy_settings (project_id, level, set_by, reason)
  values (p_project_id, p_level::public.autonomy_level, p_by,
          coalesce(nullif(btrim(p_reason), ''),
                   format('Set from the dashboard on %s.',
                          to_char(app.now_utc(), 'FMDD Mon YYYY'))));

  -- How much the office may do without asking is exactly the kind of change
  -- that must be answerable three months later.
  perform public.append_event(
    extensions.gen_random_uuid(), 'user', p_by, 'settings', 'autonomy.changed',
    true, p_project_id,
    jsonb_build_object('level', v_was),
    jsonb_build_object('level', p_level),
    format('Autonomy %s → %s.', coalesce(v_was, 'unset'), p_level),
    '[]'::jsonb, null, null,
    'app.hq_autonomy_set with the previous level', null);

  return jsonb_build_object('level', p_level, 'was', v_was,
                            'scope', case when p_project_id is null
                                          then 'the whole office'
                                          else 'this project' end);
end;
$$;


--
-- Name: FUNCTION hq_autonomy_set(p_level text, p_project_id uuid, p_by text, p_reason text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.hq_autonomy_set(p_level text, p_project_id uuid, p_by text, p_reason text) IS 'Set how much the office does without asking (#15). A new row, never an update: "when did it start acting on its own" must stay answerable.';


--
-- Name: hq_bot_assign(text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_bot_assign(p_username text, p_staff_slug text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_is_pager boolean;
  v_current  text;
  v jsonb;
begin
  select is_pager, staff_slug into v_is_pager, v_current
    from public.telegram_bots where username = p_username and enabled;
  if not found then
    return jsonb_build_object('error', format('no bot called %L', p_username));
  end if;
  if v_is_pager then
    return jsonb_build_object(
      'error', 'the pager is not assignable — every notification path assumes it exists and belongs to nobody'
    );
  end if;

  if p_staff_slug is not null then
    if not exists (select 1 from public.staff where slug = p_staff_slug and active) then
      return jsonb_build_object('error', format('no active staff member called %L', p_staff_slug));
    end if;
    -- One bot each. Two people on one bot would make "who is this message
    -- from" unanswerable, and 0097 already paid for a version of that
    -- confusion.
    if exists (
      select 1 from public.telegram_bots
       where staff_slug = p_staff_slug and enabled and username <> p_username
    ) then
      return jsonb_build_object(
        'error', format('%s already has a bot — free it first', p_staff_slug)
      );
    end if;
  end if;

  update public.telegram_bots
     set staff_slug = p_staff_slug, updated_at = app.now_utc()
   where username = p_username
  returning jsonb_build_object(
    'username', username,
    'staff_slug', staff_slug,
    'was', v_current
  ) into v;
  return v;
end;
$$;


--
-- Name: hq_bots(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_bots() RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  select jsonb_build_object(
    'owned', (select count(*)::int from public.telegram_bots where enabled),
    'limit', coalesce((select (value #>> '{}')::int from public.system_config
                        where key = 'telegram.bot_limit'), 20),
    'bots', coalesce((
      select jsonb_agg(jsonb_build_object(
        'username', b.username,
        'staff_slug', b.staff_slug,
        'staff_name', s.name,
        'is_pager', b.is_pager,
        'origin', b.origin,
        'spare', b.staff_slug is null and not b.is_pager
      ) order by b.is_pager desc, s.name nulls last, b.username)
      from public.telegram_bots b
      left join public.staff s on s.slug = b.staff_slug
      where b.enabled), '[]'::jsonb)
  )
$$;


--
-- Name: hq_build(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_build() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select jsonb_build_object(
    -- The one thing he actually wants at a glance: is anything happening.
    'now', (
      select jsonb_build_object(
               'headline', b.headline, 'towards', b.towards,
               'detail', b.detail, 'since', b.started_at)
        from public.build_steps b
       where b.state = 'doing'
       order by b.started_at desc limit 1
    ),
    'blocked', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'headline', b.headline, 'detail', b.detail, 'since', b.started_at)
             order by b.started_at), '[]'::jsonb)
        from public.build_steps b
       where b.state = 'blocked'
    ),
    'steps', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'headline', b.headline,
               'towards', b.towards,
               'detail', b.detail,
               'state', b.state,
               'produced', b.produced,
               'shot', b.shot_url,
               'started_at', b.started_at,
               'finished_at', b.finished_at,
               'minutes', case when b.finished_at is null then null
                          else round(extract(epoch from (b.finished_at - b.started_at)) / 60.0) end)
             order by b.started_at desc), '[]'::jsonb)
        from (select * from public.build_steps order by started_at desc limit 40) b
    ),
    'today', (
      select jsonb_build_object(
        'done', count(*) filter (where state = 'done'),
        'doing', count(*) filter (where state = 'doing'),
        'blocked', count(*) filter (where state = 'blocked'))
        from public.build_steps
       where started_at > app.now_utc() - interval '24 hours'
    )
  )
$$;


--
-- Name: FUNCTION hq_build(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.hq_build() IS 'The build diary for the dashboard: what is happening now, what is blocked, and the last forty steps with their screenshots (0170).';


--
-- Name: hq_connection_choose(text, text, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_connection_choose(p_slug text, p_connector text, p_choice text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_project uuid;
begin
  select project_id into v_project from public.projects where slug = p_slug and status = 'active';
  if v_project is null then
    return jsonb_build_object('error', format('no active project called %L', p_slug));
  end if;
  if not exists (select 1 from public.knowledge_connectors where connector = p_connector and enabled) then
    return jsonb_build_object('error', format('%L is not a connector', p_connector));
  end if;

  -- `clear` removes the decision rather than storing a third value, so
  -- "changed my mind" and "never considered" end up in the same state — which
  -- they are.
  if p_choice = 'clear' then
    delete from public.project_connector_choices
     where project_id = v_project and connector = p_connector;
    return jsonb_build_object('ok', true, 'choice', null);
  end if;

  if p_choice not in ('declined', 'wanted') then
    return jsonb_build_object('error', 'choice must be declined, wanted or clear');
  end if;

  -- Refused rather than silently overwritten: a project that IS connected has
  -- no business also being marked as not wanting the connection, and the way
  -- to stop using one is to detach it.
  if exists (
    select 1 from public.project_attachments
     where project_id = v_project and connector = p_connector and enabled
  ) then
    return jsonb_build_object(
      'error', format('%s is already attached to %s — detach it first', p_connector, p_slug)
    );
  end if;

  insert into public.project_connector_choices (project_id, connector, choice, reason)
  values (v_project, p_connector, p_choice, nullif(btrim(coalesce(p_reason, '')), ''))
  on conflict (project_id, connector) do update
    set choice = excluded.choice, reason = excluded.reason, decided_at = app.now_utc();

  return jsonb_build_object('ok', true, 'choice', p_choice, 'connector', p_connector);
end;
$$;


--
-- Name: hq_connections(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_connections() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select coalesce(
    jsonb_build_object(
      'checked_at', (select max(checked_at) from public.connection_health),
      -- What of Grant's correspondence the office is holding the words
      -- of, right now (#172, ADR-0038). Beside the credential that makes
      -- it possible, because that is where he would go to stop it.
      'mail_bodies', app.mail_bodies_held(),
      'rows', (
        select jsonb_agg(
                 jsonb_build_object(
                   'service', c.service,
                   'credential', c.credential,
                   'state', c.state,
                   'detail', c.detail,
                   'owner', c.owner,
                   'action', c.action,
                   'checked_at', c.checked_at,
                   'age_minutes', round(extract(epoch from (app.now_utc() - c.checked_at)) / 60)
                 )
                 order by
                   case c.state
                     when 'dead' then 0 when 'missing' then 1 when 'unknown' then 2
                     when 'ok' then 3 when 'attested' then 4 else 5
                   end,
                   c.service
               )
          from public.connection_health c
      )
    ),
    '{}'::jsonb
  )
$$;


--
-- Name: FUNCTION hq_connections(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.hq_connections() IS 'Team HQ''s connections view. Problems first, then everything working - a list sorted alphabetically buries the one row that matters.';


--
-- Name: hq_contact_add(text, text, text, text, text, text, text, text, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_contact_add(p_project text, p_name text, p_role text DEFAULT NULL::text, p_org text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_instagram text DEFAULT NULL::text, p_website text DEFAULT NULL::text, p_kind text DEFAULT 'person'::text, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_project uuid;
  v_name    text := btrim(coalesce(p_name, ''));
  v_kind    text := lower(btrim(coalesce(nullif(p_kind, ''), 'person')));
  v         jsonb;
begin
  if v_name = '' then
    return jsonb_build_object('error', 'a contact needs a name');
  end if;
  if v_kind not in ('person', 'company', 'collaborator', 'supplier') then
    return jsonb_build_object('error', format(
      '%L is not a kind — it is one of person, company, collaborator, supplier', v_kind));
  end if;

  select project_id into v_project
    from public.projects
   where slug = p_project and coalesce(status, '') <> 'archived' and not is_fixture;
  if v_project is null then
    return jsonb_build_object('error', format('no dashboard project called %L', p_project));
  end if;

  -- The same name twice on one project is almost always a mistake rather than
  -- twins. Refused with the name in it, so the answer is obvious.
  if exists (select 1 from public.contacts
              where project_id = v_project and lower(btrim(name)) = lower(v_name)) then
    return jsonb_build_object('error', format('%s is already a contact on this project', v_name));
  end if;

  insert into public.contacts (project_id, kind, name, role, org, email, phone,
                               instagram, website, note)
  values (v_project, v_kind, v_name,
          btrim(coalesce(p_role, '')), btrim(coalesce(p_org, '')),
          btrim(coalesce(p_email, '')), btrim(coalesce(p_phone, '')),
          btrim(coalesce(p_instagram, '')), btrim(coalesce(p_website, '')),
          btrim(coalesce(p_note, '')))
  returning jsonb_build_object('id', contact_id, 'name', name, 'kind', kind) into v;

  return v;
end;
$$;


--
-- Name: hq_contact_fields_set(uuid, jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_contact_fields_set(p_contact_id uuid, p_fields jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_was  jsonb;
  v_bad  int;
  v_undo uuid;
begin
  if not exists (select 1 from public.contacts where contact_id = p_contact_id) then
    return jsonb_build_object('error', 'no such contact');
  end if;
  if p_fields is null or jsonb_typeof(p_fields) <> 'array' then
    return jsonb_build_object('error', 'fields must be an array');
  end if;

  select count(*) into v_bad from jsonb_array_elements(p_fields) e
   where jsonb_typeof(e) <> 'object'
      or coalesce(jsonb_typeof(e -> 'label'), 'missing') <> 'string'
      or btrim(coalesce(e ->> 'label', '')) = ''
      or coalesce(jsonb_typeof(e -> 'value'), 'string') <> 'string';
  if v_bad > 0 then
    return jsonb_build_object('error',
      format('%s field(s) are not {label, value} with a label that says something', v_bad));
  end if;

  select fields into v_was from public.contacts where contact_id = p_contact_id;
  update public.contacts set fields = p_fields where contact_id = p_contact_id;

  v_undo := app.undo_offer(
    'contact.fields',
    format('Changed the fields on %s',
           (select name from public.contacts where contact_id = p_contact_id)),
    jsonb_build_object('action', 'contact_fields_set',
                       'args', jsonb_build_object('p_contact_id', p_contact_id,
                                                  'p_fields', v_was)));

  return jsonb_build_object('ok', true, 'undo', v_undo, 'fields', p_fields);
end;
$$;


--
-- Name: hq_contact_label_add(text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_contact_label_add(p_name text, p_hue text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_name text := btrim(coalesce(p_name, ''));
  v_hue  text := nullif(btrim(coalesce(p_hue, '')), '');
  v_id   uuid;
begin
  if v_name = '' then
    return jsonb_build_object('error', 'a label needs a name');
  end if;

  select label_id into v_id from public.contact_labels
   where owner = 'grant' and app.normalise_name(name) = app.normalise_name(v_name);
  if v_id is not null then
    return jsonb_build_object('error', format('there is already a label called %L', v_name));
  end if;

  /*
    The next hue in the ring rather than a random one, matching what the page
    did: `HUES[labels.length % HUES.length]`. Two labels created in a row should
    look different, which a random pick does not guarantee.
  */
  insert into public.contact_labels (owner, name, hue, sort)
  values ('grant', v_name,
          coalesce(v_hue, (array['p-rust', 'p-amber', 'p-moss', 'p-slate', 'p-iris', 'p-plum'])[
            (select count(*) from public.contact_labels where owner = 'grant') % 6 + 1]),
          coalesce((select max(sort) + 1 from public.contact_labels where owner = 'grant'), 0))
  returning label_id into v_id;

  return jsonb_build_object('ok', true, 'label', v_id, 'labels', app.contact_labels('grant'));
end;
$$;


--
-- Name: hq_contact_label_remove(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_contact_label_remove(p_label_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare v_n int;
begin
  if not exists (select 1 from public.contact_labels
                  where owner = 'grant' and label_id = p_label_id) then
    return jsonb_build_object('error', 'no such label');
  end if;

  select count(*) into v_n from public.contact_label_links
   where owner = 'grant' and label_id = p_label_id;

  -- The links go with it, by the foreign key's cascade.
  delete from public.contact_labels where owner = 'grant' and label_id = p_label_id;

  /*
    No undo offered, and that is deliberate rather than an omission.

    #118's rule is that an offer is made only where the inverse is EXACT.
    Recreating the label would give it a new id, so every contact it was on
    stays unlabelled and the reversal silently does less than it says. The
    honest answer is to say so, which `undo_none` is for.
  */
  perform app.undo_none(
    'contact.label_remove',
    format('Deleted a label — putting it back would give it a new id, so the %s '
           || 'contact(s) it was on would stay unlabelled', v_n));

  return jsonb_build_object('ok', true, 'removed_from', v_n, 'undo', null,
                            'labels', app.contact_labels('grant'));
end;
$$;


--
-- Name: hq_contact_label_rename(uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_contact_label_rename(p_label_id uuid, p_name text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_name text := btrim(coalesce(p_name, ''));
  v_was  text;
  v_undo uuid;
begin
  if v_name = '' then
    return jsonb_build_object('error', 'a label needs a name');
  end if;

  select name into v_was from public.contact_labels
   where owner = 'grant' and label_id = p_label_id;
  if v_was is null then
    return jsonb_build_object('error', 'no such label');
  end if;

  if exists (select 1 from public.contact_labels
              where owner = 'grant' and label_id <> p_label_id
                and app.normalise_name(name) = app.normalise_name(v_name)) then
    return jsonb_build_object('error', format('there is already a label called %L', v_name));
  end if;

  update public.contact_labels set name = v_name
   where owner = 'grant' and label_id = p_label_id;

  -- The exact inverse, recorded while the previous value is still known (#118).
  v_undo := app.undo_offer(
    'contact.label_rename',
    format('Renamed the label %s to %s', v_was, v_name),
    jsonb_build_object('action', 'contact_label_rename',
                       'args', jsonb_build_object('p_label_id', p_label_id,
                                                  'p_name', v_was)));

  return jsonb_build_object('ok', true, 'undo', v_undo,
                            'labels', app.contact_labels('grant'));
end;
$$;


--
-- Name: hq_contact_labels_set(uuid, jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_contact_labels_set(p_contact_id uuid, p_labels jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_ids  uuid[];
  v_was  jsonb;
  v_bad  int;
  v_undo uuid;
begin
  if not exists (select 1 from public.contacts where contact_id = p_contact_id) then
    return jsonb_build_object('error', 'no such contact');
  end if;
  if p_labels is null or jsonb_typeof(p_labels) <> 'array' then
    return jsonb_build_object('error', 'labels must be an array of label ids');
  end if;

  select coalesce(array_agg((e #>> '{}')::uuid), array[]::uuid[]) into v_ids
    from jsonb_array_elements(p_labels) e;

  select count(*) into v_bad from unnest(v_ids) id
   where not exists (select 1 from public.contact_labels
                      where owner = 'grant' and label_id = id);
  if v_bad > 0 then
    return jsonb_build_object('error', format('%s of those labels do not exist', v_bad));
  end if;

  select coalesce(jsonb_agg(label_id), '[]'::jsonb) into v_was
    from public.contact_label_links where contact_id = p_contact_id;

  delete from public.contact_label_links where contact_id = p_contact_id;
  insert into public.contact_label_links (contact_id, owner, label_id)
  select p_contact_id, 'grant', id from unnest(v_ids) id;

  update public.contacts set labels_set = true where contact_id = p_contact_id;

  v_undo := app.undo_offer(
    'contact.labels',
    format('Changed the labels on %s',
           (select name from public.contacts where contact_id = p_contact_id)),
    jsonb_build_object('action', 'contact_labels_set',
                       'args', jsonb_build_object('p_contact_id', p_contact_id,
                                                  'p_labels', v_was)));

  return jsonb_build_object('ok', true, 'undo', v_undo, 'labels', to_jsonb(v_ids));
end;
$$;


--
-- Name: hq_cost_per_outcome(integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_cost_per_outcome(p_days integer DEFAULT 30) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $_$
  with window_start as (
    select app.now_utc() - make_interval(days => greatest(1, least(365, p_days))) as t
  ),
  -- Every usage row in the window, priced.
  priced as (
    select u.usage_id,
           u.job_id,
           u.correlation_id,
           u.outcome::text as outcome,
           u.model_id,
           u.cost_usd,
           u.prompt_tokens,
           u.completion_tokens,
           round(
             (u.prompt_tokens     / 1000000.0) * pr.input_usd_per_mtok +
             (u.completion_tokens / 1000000.0) * pr.output_usd_per_mtok
           , 6) as modelled_usd
      from public.inference_usage u
      cross join window_start w
      left join lateral app.model_price_at(u.model_id, u.occurred_at) pr on true
     where u.occurred_at > w.t
  ),
  -- Completed work in the window. Only completed: a cost per outcome divided
  -- by attempts is a cost per attempt, and the two differ most exactly when a
  -- kind of work is going badly, which is when the number matters.
  done as (
    select j.job_id, j.kind, j.correlation_id,
           extract(epoch from (j.finished_at - j.started_at)) as secs
      from public.jobs j
      cross join window_start w
     where j.state = 'complete' and j.finished_at > w.t
  ),
  by_kind as (
    select d.kind,
           count(*)::int                                        as outcomes,
           count(p.usage_id)::int                               as calls,
           coalesce(sum(p.prompt_tokens + p.completion_tokens), 0)::bigint as tokens,
           coalesce(sum(p.cost_usd), 0)::numeric(14,6)          as spent_usd,
           coalesce(sum(p.modelled_usd), 0)::numeric(14,6)      as modelled_usd,
           round(avg(d.secs)::numeric, 1)                       as avg_secs
      from done d
      left join priced p on p.job_id = d.job_id
     group by d.kind
  ),
  by_staff as (
    -- `staff_behind_job` returns a SLUG, and `staff.staff_id` is a uuid. The
    -- first version joined the two and Postgres refused with "operator does
    -- not exist: uuid = text", which is the error doing its job.
    select coalesce(app.staff_behind_job(d.job_id), 'unassigned') as slug,
           count(*)::int                                   as outcomes,
           coalesce(sum(p.modelled_usd), 0)::numeric(14,6) as modelled_usd,
           coalesce(sum(p.cost_usd), 0)::numeric(14,6)     as spent_usd
      from done d
      left join priced p on p.job_id = d.job_id
     group by 1
  ),
  -- The honesty column. Calls in the window that no completed job can claim,
  -- either because job_id was never written (everything before this migration)
  -- or because the job they belong to has not finished.
  gap as (
    select count(*) filter (where p.job_id is null)::int as unattributed_calls,
           count(*)::int                                 as total_calls,
           coalesce(sum(p.modelled_usd) filter (where p.job_id is null), 0)::numeric(14,6)
             as unattributed_modelled_usd
      from priced p
  )
  select jsonb_build_object(
    'generated_at', app.now_utc(),
    'window_days', greatest(1, least(365, p_days)),
    -- Said in words on the page, because a reader who does not know that every
    -- provider here is free-tier will read $0.00 as a bug.
    'measured_note',
      'Measured spend is what providers actually charged. It is currently zero '
      'because the router refuses any call a provider prices above zero.',
    'modelled_note',
      'Modelled cost is what the same tokens would have cost on a paid model, '
      'from the published prices in model_prices. It was never charged.',
    'coverage', (
      select jsonb_build_object(
        'total_calls', g.total_calls,
        'unattributed_calls', g.unattributed_calls,
        'unattributed_modelled_usd', g.unattributed_modelled_usd,
        'attributed_pct', case when g.total_calls = 0 then 100
             else round(100.0 * (g.total_calls - g.unattributed_calls) / g.total_calls) end
      ) from gap g
    ),
    'totals', (
      select jsonb_build_object(
        'outcomes', coalesce(sum(outcomes), 0),
        'calls', coalesce(sum(calls), 0),
        'tokens', coalesce(sum(tokens), 0),
        'spent_usd', coalesce(sum(spent_usd), 0),
        'modelled_usd', coalesce(sum(modelled_usd), 0)
      ) from by_kind
    ),
    'by_kind', coalesce((
      select jsonb_agg(jsonb_build_object(
        'kind', k.kind,
        'outcomes', k.outcomes,
        'calls', k.calls,
        'tokens', k.tokens,
        'avg_secs', k.avg_secs,
        'spent_usd', k.spent_usd,
        'modelled_usd', k.modelled_usd,
        'modelled_usd_each', round(k.modelled_usd / greatest(k.outcomes, 1), 6)
      ) order by k.modelled_usd desc, k.outcomes desc)
      from by_kind k), '[]'::jsonb),
    'by_staff', coalesce((
      select jsonb_agg(jsonb_build_object(
        'slug', s.slug,
        'name', coalesce((select st.name from public.staff st where st.slug = s.slug),
                         'Unassigned'),
        'outcomes', s.outcomes,
        'spent_usd', s.spent_usd,
        'modelled_usd', s.modelled_usd
      ) order by s.modelled_usd desc, s.outcomes desc)
      from by_staff s), '[]'::jsonb)
  )
$_$;


--
-- Name: hq_create_project(text, text, text, text, boolean); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_create_project(p_name text, p_connector text, p_ref text, p_display text DEFAULT NULL::text, p_force boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_slug   text;
  v_prefix text;
  v_id     uuid;
  v_n      integer := 0;
  v_near   jsonb;
begin
  if coalesce(trim(p_name), '') = '' then
    return jsonb_build_object('error', 'a project needs a name');
  end if;
  if coalesce(trim(p_ref), '') = '' then
    return jsonb_build_object(
      'error', 'a project needs at least one source: a notebook or a Notion database'
    );
  end if;
  if p_connector not in ('notebooklm', 'notion', 'upload', 'github') then
    return jsonb_build_object('error', format('%L is not a connector', p_connector));
  end if;

  if not p_force then
    select jsonb_agg(jsonb_build_object(
             'project_id', r.project_id, 'slug', r.slug, 'name', r.name,
             'confidence', r.confidence, 'how', r.how) order by r.confidence desc)
      into v_near
      from app.resolve_project_by_name(p_name) r
     where r.confidence >= 0.55;

    if v_near is not null then
      return jsonb_build_object(
        'needs_confirmation', true,
        'candidates', v_near,
        'question', format(
          'There is already something by that name. Did you mean one of these, '
          'or is %L genuinely new?', trim(p_name))
      );
    end if;
  end if;

  v_slug := left(trim(both '-' from regexp_replace(lower(p_name), '[^a-z0-9]+', '-', 'g')), 60);
  if v_slug = '' then v_slug := 'project'; end if;
  v_prefix := left(v_slug, 48);

  while exists (select 1 from public.projects where slug = v_slug) loop
    v_n := v_n + 1;
    v_slug := left(v_prefix, 56) || '-' || v_n::text;
    if v_n > 50 then
      return jsonb_build_object('error', 'could not find a free slug for that name');
    end if;
  end loop;

  insert into public.projects (slug, name, channel_prefix, status, icon)
  values (v_slug, trim(p_name), v_prefix, 'active', app.icon_for_name(p_name))
  returning project_id into v_id;

  insert into public.project_attachments
    (project_id, connector, external_ref, display_name, role, ref_kind)
  values (v_id, p_connector, trim(p_ref),
          coalesce(nullif(trim(coalesce(p_display, '')), ''), trim(p_name)), 'source',
          case p_connector when 'notebooklm' then 'notebook'
                           when 'github' then 'repository'
                           when 'notion' then 'database' end);

  perform app.add_project_alias(v_id, trim(p_name), 'name', 1.0);

  return jsonb_build_object(
    'project_id', v_id, 'slug', v_slug, 'name', trim(p_name),
    'needs_you', case when p_connector <> 'notion'
                 then 'a Notion Teamspace, which only you can create' end
  );
end;
$$;


--
-- Name: hq_dashboard_layout_reset(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_dashboard_layout_reset(p_slug text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_project uuid;
begin
  select project_id into v_project
    from public.projects
   where slug = p_slug and status = 'active';
  if v_project is null then
    return jsonb_build_object('error', format('no active dashboard project called %s', p_slug));
  end if;
  delete from public.dashboard_layouts
   where project_id = v_project and owner = 'grant';
  return jsonb_build_object('ok', true);
end;
$$;


--
-- Name: hq_dashboard_layout_set(text, jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_dashboard_layout_set(p_slug text, p_panels jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_project uuid;
  v_bad     int;
  v_was     jsonb;
  v_undo    uuid;
begin
  select project_id into v_project
    from public.projects
   where slug = p_slug and status = 'active';
  if v_project is null then
    return jsonb_build_object('error', format('no active dashboard project called %s', p_slug));
  end if;

  if jsonb_typeof(p_panels) <> 'array' then
    return jsonb_build_object('error', 'panels must be an array');
  end if;

  select panels into v_was
    from public.dashboard_layouts
   where project_id = v_project and owner = 'grant';

  -- Nothing left on the board is a reset, not a layout.
  if jsonb_array_length(p_panels) = 0 then
    delete from public.dashboard_layouts
     where project_id = v_project and owner = 'grant';
    if v_was is not null then
      v_undo := app.undo_offer(
        'dashboard.layout',
        format('Emptied the board on %s', p_slug),
        jsonb_build_object('action', 'dashboard_layout_set',
                           'args', jsonb_build_object('p_slug', p_slug, 'p_panels', v_was)));
    end if;
    return jsonb_build_object('ok', true, 'panels', 0, 'undo', v_undo,
      'note', 'the board was emptied, so it is back to its default');
  end if;

  -- `coalesce(..., 'missing')`, so an absent key is a failure rather than a
  -- NULL that the WHERE clause quietly drops.
  select count(*) into v_bad
    from jsonb_array_elements(p_panels) e
   where coalesce(jsonb_typeof(e), 'missing') <> 'object'
      or coalesce(jsonb_typeof(e -> 'id'), 'missing') <> 'string'
      or coalesce(jsonb_typeof(e -> 'x'), 'missing') <> 'number'
      or coalesce(jsonb_typeof(e -> 'y'), 'missing') <> 'number'
      or coalesce(jsonb_typeof(e -> 'w'), 'missing') <> 'number'
      or coalesce(jsonb_typeof(e -> 'h'), 'missing') <> 'number';
  if v_bad > 0 then
    return jsonb_build_object('error',
      format('%s panel(s) are not {id, x, y, w, h} -- nothing was saved', v_bad));
  end if;

  insert into public.dashboard_layouts (project_id, owner, panels, updated_at)
  values (v_project, 'grant', p_panels, now())
  on conflict (owner, project_id)
    do update set panels = excluded.panels, updated_at = now();

  /*
    There are two inverses here and they are different operations.

    If an arrangement existed, undo restores it. If there was NONE — this is
    the first time the board has been arranged — undo has to REMOVE the row,
    not write an empty one, because a saved empty arrangement and no saved
    arrangement are different states: the second falls back to the default and
    the first does not. `dashboard_layout_reset` is that operation and it
    already exists.
  */
  if v_was is null then
    v_undo := app.undo_offer(
      'dashboard.layout',
      format('Arranged the board on %s', p_slug),
      jsonb_build_object('action', 'dashboard_layout_reset',
                         'args', jsonb_build_object('p_slug', p_slug)));
  elsif v_was is distinct from p_panels then
    v_undo := app.undo_offer(
      'dashboard.layout',
      format('Rearranged the board on %s', p_slug),
      jsonb_build_object('action', 'dashboard_layout_set',
                         'args', jsonb_build_object('p_slug', p_slug, 'p_panels', v_was)));
  end if;

  return jsonb_build_object('ok', true, 'panels', jsonb_array_length(p_panels), 'undo', v_undo);
end;
$$;


--
-- Name: hq_detach(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_detach(p_attachment_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_project uuid;
  v_was_enabled boolean;
  v_was_reason  text;
  v_what        text;
  v_undo        uuid;
begin
  select project_id, enabled, disabled_reason, coalesce(display_name, external_ref)
    into v_project, v_was_enabled, v_was_reason, v_what
    from public.project_attachments where attachment_id = p_attachment_id;
  if v_project is null then return jsonb_build_object('error', 'no such attachment'); end if;

  -- Disabled, not deleted, and the documents it fed are untouched. ADR-0013:
  -- closing a route loses the route, never the corpus.
  update public.project_attachments
     set enabled = false, disabled_reason = 'detached from Team HQ'
   where attachment_id = p_attachment_id;

  -- Detaching something already detached changes nothing, so there is nothing
  -- to take back.
  if v_was_enabled then
    v_undo := app.undo_offer(
      'attachment.detach',
      format('Detached %s', left(coalesce(v_what, 'a source'), 60)),
      jsonb_build_object('action', 'reattach',
                         'args', jsonb_build_object(
                           'p_attachment_id', p_attachment_id::text,
                           'p_reason', v_was_reason)));
  end if;

  return jsonb_build_object('detached', p_attachment_id, 'undo', v_undo);
end;
$$;


--
-- Name: hq_disconnect(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_disconnect(p_service text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_key     text := lower(btrim(coalesce(p_service, '')));
  v_gone    int  := 0;
  v_had     boolean;
begin
  -- The Google family is one consent behind three services, so any of them
  -- disconnects the account. 0112 already does the work correctly; calling it
  -- rather than repeating it means there is one description of what signing
  -- out of Google means.
  if v_key in ('google', 'drive', 'calendar', 'gmail') then
    select exists (select 1 from vault.secrets where name = 'google.refresh_token')
      into v_had;
    if not v_had then
      return jsonb_build_object('ok', true, 'service', 'Google', 'removed', 0,
        'note', 'Google was already signed out here -- nothing to remove.',
        'revoke_at', 'https://myaccount.google.com/permissions');
    end if;
    perform app.hq_forget_google();
    return jsonb_build_object('ok', true, 'service', 'Google', 'removed', 1,
      'note', 'Signed out. Calendar reading is off and the refresh token is deleted. '
              || 'The client id and secret stay -- they are the registration, not the consent, '
              || 'so signing in again does not need the console step.',
      'revoke_at', 'https://myaccount.google.com/permissions');
  end if;

  if v_key = 'notion' then
    delete from vault.secrets where name = 'notion.integration_token';
    get diagnostics v_gone = row_count;
    if v_gone = 0 then
      return jsonb_build_object('ok', true, 'service', 'Notion', 'removed', 0,
        'note', 'There was no Notion token here to remove.',
        'revoke_at', 'https://www.notion.so/profile/integrations');
    end if;
    update public.connection_health
       set state = 'missing',
           detail = 'disconnected at your request',
           action = 'Add a Notion integration token in Setting up',
           checked_at = app.now_utc()
     where service = 'Notion';
    return jsonb_build_object('ok', true, 'service', 'Notion', 'removed', v_gone,
      'note', 'Disconnected. The office can no longer read Notion. '
              || 'Pages it already imported stay -- ADR-0013: a route may be closed and the corpus is kept.',
      'revoke_at', 'https://www.notion.so/profile/integrations');
  end if;

  if v_key in ('notebooklm', 'notebook') then
    delete from vault.secrets where name = 'notebook.storage_state';
    get diagnostics v_gone = row_count;
    -- Off as well as gone: a duty running hourly against a credential that was
    -- deliberately removed is a red light he caused and cannot explain.
    update public.system_config set value = to_jsonb(false) where key = 'notebook.enabled';
    return jsonb_build_object('ok', true, 'service', 'NotebookLM', 'removed', v_gone,
      'note', case when v_gone = 0
                then 'There was no NotebookLM session here to remove; generation is switched off.'
                else 'Disconnected and generation switched off. Notebooks already attached to a '
                     || 'dashboard project stay attached, and what they produced stays.' end,
      'revoke_at', 'https://notebooklm.google.com');
  end if;

  /*
    Slack (#198, #109).

    Everything of ours goes: the bot token and the short-lived config tokens.
    The office stops posting and stops reading within one worker pass, which is
    real and immediate and is the part a database can do.

    What it CANNOT do is revoke the token at Slack or uninstall the app, both
    of which need an outbound call or a person. So neither is claimed. The
    answer names `auth.revoke` because a future #109 needs the endpoint, and
    names the uninstall page because that is the step only Grant can take.
  */
  if v_key = 'slack' then
    delete from vault.secrets
     where name in ('slack.bot_token', 'slack.config_access_token',
                    'slack.config_refresh_token', 'slack.app_token',
                    'slack.signing_secret');
    get diagnostics v_gone = row_count;

    if v_gone = 0 then
      return jsonb_build_object(
        'ok', false, 'service', 'Slack', 'removed', 0,
        'error', 'Nothing was removed, so nothing was disconnected. There are no '
                 || 'Slack credentials in the vault to take away. The dashboard is '
                 || 'left alone deliberately: saying a credential is missing when it '
                 || 'is not is worse than failing to remove it.');
    end if;

    update public.connection_health
       set state = 'missing',
           detail = 'disconnected at your request',
           action = 'Reconnect in Setting up, or uninstall the app at Slack to finish it',
           checked_at = app.now_utc()
     where service = 'Slack';

    return jsonb_build_object(
      'ok', true, 'service', 'Slack', 'removed', v_gone,
      'stopped', 'The office can no longer read or post in Slack. Every message '
                 || 'already there stays, and so does everything the office recorded from it '
                 || '-- losing a channel loses a surface, not the conversation.',
      /*
        Said plainly, because #109 is a real defect and shipping a Disconnect
        that implied otherwise would inherit it. This is the honest partial:
        it names what did not happen as clearly as what did.
      */
      'not_revoked', 'The token was deleted here, NOT revoked at Slack, and the app is '
                     || 'still installed in the workspace. Nothing can use the token now -- '
                     || 'it is gone -- but Slack has not been told to invalidate it.',
      'to_finish', jsonb_build_array(
        'Open https://api.slack.com/apps and choose Agentic Team Grant.',
        'Go to Settings, then Install App, and press Revoke All OAuth Tokens.',
        'To remove it from the workspace entirely: Settings, then Basic Information, '
          || 'then Delete App at the bottom.'
      ),
      'revoke_at', 'https://api.slack.com/apps',
      'note', 'Reconnecting means installing the app again and pasting a new bot token '
              || 'in Setting up. The channels the office made stay where they are.'
    );
  end if;

  /*
    Telegram (#198, #70).

    Grant, 13 September: "we don't need a different bot for each role. In fact,
    we only need the chief of staff." So this deletes the chief's token, which
    is the one that reaches him, and reports the staff bots separately rather
    than silently taking eight things away with one press.

    No API can revoke a Telegram bot token. Only BotFather's /revoke can, in a
    chat window, by a person. That is not a gap waiting for #109 to close --
    there is nothing to automate -- so the steps are given in full.
  */
  if v_key = 'telegram' then
    delete from vault.secrets s
     where s.id in (select b.token_ref from public.telegram_bots b
                     where b.staff_slug = 'chief-of-staff' and b.token_ref is not null)
        or s.name in ('telegram.bot_token', 'telegram.chief_bot_token',
                      'telegram.chief.bot_token');
    get diagnostics v_gone = row_count;

    if v_gone = 0 then
      return jsonb_build_object(
        'ok', false, 'service', 'Telegram', 'removed', 0,
        'error', 'Nothing was removed, so nothing was disconnected. There is no chief '
                 || 'bot token in the vault to take away. The dashboard is left alone '
                 || 'deliberately: saying a credential is missing when it is not is '
                 || 'worse than failing to remove it.');
    end if;

    update public.telegram_bots
       set enabled = false,
           token_ref = null,
           disabled_reason = 'disconnected at your request'
     where staff_slug = 'chief-of-staff';

    -- Off as well as gone, for 0112's reason: a duty polling a credential that
    -- was deliberately removed is a red light he caused and cannot explain.
    update public.system_config
       set value = to_jsonb(false)
     where key = 'telegram.enabled';

    update public.connection_health
       set state = 'missing',
           detail = 'disconnected at your request',
           action = 'Reconnect in Setting up with a bot token from BotFather',
           checked_at = app.now_utc()
     where service = 'Telegram' and credential like '%chief%';

    return jsonb_build_object(
      'ok', true, 'service', 'Telegram', 'removed', v_gone,
      'stopped', 'The office can no longer send or receive on Telegram. Everything '
                 || 'already said there is kept and still in the conversation.',
      'not_revoked', 'Telegram has no API that revokes a bot token -- only BotFather can, '
                     || 'and only a person can ask it. The token is deleted here, so nothing '
                     || 'of ours can use it, but it is still a valid token until you revoke it.',
      'to_finish', jsonb_build_array(
        'Open Telegram and message @BotFather.',
        'Send /revoke and choose @agenticteamgrantbot.',
        'BotFather replies with a new token, which invalidates the old one. '
          || 'Paste the new one into Setting up if you want the office back on Telegram.'
      ),
      'revoke_at', 'https://t.me/BotFather',
      'note', 'The staff bots are separate and were NOT touched -- they are handed back '
              || 'one at a time in Settings, Channels. Issue #70 records the decision to '
              || 'retire them: Telegram is one bot, the chief of staff, and individual '
              || 'people are reached in Slack and here.'
    );
  end if;

  -- Everything else: refused, with the reason. A Disconnect that did nothing
  -- is the failure this issue describes, and so is one that turns the office
  -- off without saying that is what it does.
  return jsonb_build_object('error', case v_key
    when 'openrouter' then
      'OpenRouter is how the team thinks -- removing the key stops every agent. '
      || 'Change or remove it in Settings, Models, where the consequence is on the page.'
    when 'github' then
      'GitHub holds the office''s own code and its two tokens do different jobs. '
      || 'Disconnecting it from here would be one button for two decisions.'
    when 'supabase' then
      'Supabase IS the office -- this function is running inside it.'
    when 'mcp' then
      'The MCP server has no stored credential to remove. Revoke a client''s token '
      || 'on the MCP screen instead.'
    else format('There is no disconnect for %s.', coalesce(nullif(v_key, ''), 'that'))
  end);
end;
$$;


--
-- Name: FUNCTION hq_disconnect(p_service text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.hq_disconnect(p_service text) IS 'Issues #198, #109. Removes our copy of a credential and says, exactly, what that did and did not stop. Never claims a revoke it cannot perform.';


--
-- Name: hq_disconnect_recording(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_disconnect_recording(p_service text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare v_result jsonb;
begin
  v_result := app.hq_disconnect(p_service);
  -- A refusal changed nothing, so there is nothing to say about undo.
  if v_result ? 'error' then return v_result; end if;

  perform app.undo_none(
    'service.disconnect',
    format('Disconnected %s — the credential was deleted and cannot be put back from here',
           coalesce(v_result ->> 'service', p_service)));

  return v_result || jsonb_build_object('undo', null);
end;
$$;


--
-- Name: hq_document_move(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_document_move(p_document_id uuid, p_project_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_was_project uuid;
  v_was_name    text;
  v_to_name     text;
  v_title       text;
  v_holds       int;
  v_undo        uuid;
begin
  select d.project_id, d.title into v_was_project, v_title
    from public.documents d where d.document_id = p_document_id;
  if v_title is null then
    return jsonb_build_object('error', 'there is no document with that id');
  end if;
  if v_was_project = p_project_id then
    return jsonb_build_object('moved', false, 'unchanged', true);
  end if;
  select p.name into v_to_name from public.projects p where p.project_id = p_project_id;
  if v_to_name is null then
    return jsonb_build_object('error', 'there is no project with that id');
  end if;
  select p.name into v_was_name from public.projects p where p.project_id = v_was_project;

  /*
    What would be orphaned, counted before anything moves.

    A collection belongs to a project, so moving a document out of one leaves a
    membership pointing across a boundary that nothing in the interface can
    draw. Refusing and naming the holder is better than a silent success that
    produces a row only a query can see.
  */
  select count(*) into v_holds
    from public.document_collections dc
    join public.collections c on c.collection_id = dc.collection_id
   where dc.document_id = p_document_id
     and c.project_id is distinct from p_project_id;
  if v_holds > 0 then
    return jsonb_build_object('error',
      format('%s is in %s collection(s) on %s. Take it out of those first, or it '
             || 'would belong to a collection in a project it is not in.',
             left(v_title, 40), v_holds, coalesce(v_was_name, 'the other project')));
  end if;

  update public.documents
     set project_id = p_project_id, updated_at = app.now_utc()
   where document_id = p_document_id;

  v_undo := app.undo_offer(
    'document.move',
    format('Moved %s to %s', left(v_title, 40), v_to_name),
    jsonb_build_object('action', 'document_move',
                       'args', jsonb_build_object('p_document_id', p_document_id,
                                                  'p_project_id', v_was_project)));

  return jsonb_build_object('moved', true, 'to', v_to_name,
                            'from', v_was_name, 'undo', v_undo);
end;
$$;


--
-- Name: hq_document_pin(uuid, boolean); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_document_pin(p_document_id uuid, p_pinned boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_title text;
begin
  select d.title into v_title from public.documents d where d.document_id = p_document_id;
  if v_title is null then
    return jsonb_build_object('error', 'there is no document with that id');
  end if;
  update public.documents
     set pinned = coalesce(p_pinned, false), updated_at = app.now_utc()
   where document_id = p_document_id;
  /*
    No undo on a pin, deliberately. It is its own inverse and it is one press
    away — offering a strip to take back a toggle is furniture, and #118's bar
    means something precisely because it does not appear for everything.
  */
  return jsonb_build_object('pinned', coalesce(p_pinned, false), 'title', v_title);
end;
$$;


--
-- Name: hq_document_restore(uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_document_restore(p_document_id uuid, p_state text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_state text := coalesce(nullif(btrim(coalesce(p_state, '')), ''), 'approved');
begin
  -- Never write a word the column does not have. The default is the one a
  -- document reaches by being approved, which is where a current document
  -- normally sits; anything else must come from the undo payload, which is the
  -- only thing that remembers.
  if v_state not in ('draft', 'review', 'approved', 'archived') then
    v_state := 'approved';
  end if;
  update public.documents
     set state = v_state, superseded_by = null, updated_at = app.now_utc()
   where document_id = p_document_id;
  return jsonb_build_object('restored', true, 'state', v_state);
end;
$$;


--
-- Name: hq_document_supersede(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_document_supersede(p_document_id uuid, p_by_document_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_title text;
  v_by    text;
  v_was   text;
  v_undo  uuid;
begin
  if p_document_id = p_by_document_id then
    return jsonb_build_object('error', 'a document cannot supersede itself');
  end if;
  select d.title, d.state into v_title, v_was
    from public.documents d where d.document_id = p_document_id;
  select d.title into v_by from public.documents d where d.document_id = p_by_document_id;
  if v_title is null or v_by is null then
    return jsonb_build_object('error', 'one of those documents does not exist');
  end if;

  update public.documents
     set state = 'archived', superseded_by = p_by_document_id, updated_at = app.now_utc()
   where document_id = p_document_id;

  v_undo := app.undo_offer(
    'document.supersede',
    format('Marked %s superseded', left(v_title, 50)),
    jsonb_build_object('action', 'document_restore',
                       'args', jsonb_build_object('p_document_id', p_document_id,
                                                  'p_state', coalesce(v_was, 'approved'))));

  return jsonb_build_object('superseded', true, 'by', v_by, 'was', v_was, 'undo', v_undo);
end;
$$;


--
-- Name: hq_editable_settings(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_editable_settings() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select jsonb_agg(row_to_json(k) order by k.ord)
    from (
      values
        (1, 'Where things live', 'db.project_ref', 'The Supabase project the tooling connects to. Declared, not live: changing it tells the next run where to look and moves nothing.'),
        (2, 'Where things live', 'db.region', 'Where that project is hosted. Recorded for this page; not enforced.'),
        (3, 'Where things live', 'backup.s3_bucket', 'The bucket nightly backups are written to.'),
        (4, 'Where things live', 'backup.s3_endpoint', 'The S3 endpoint for that bucket.'),
        (5, 'Where things live', 'backup.s3_region', 'The region for that bucket.'),
        (6, 'Where things live', 'grant.timezone', 'The timezone every date in this system is reported in. Checked against the list Postgres knows, because a timezone that does not exist silently makes everything UTC.'),

        (10, 'How the team behaves', 'notebook.enabled', 'Whether the team may use NotebookLM at all.'),
        (11, 'How the team behaves', 'calendar.enabled', 'Whether your calendar is read. Needs Google connected first.'),
        (12, 'How the team behaves', 'calendar.calendar_id', 'Which calendar to read. "primary" is the account''s own.'),
        (13, 'How the team behaves', 'knowledge.read_new_sources', 'Whether a source arriving in an established project starts a research job. Off makes the corpus passive: documents are stored and nobody looks at them.'),
        (14, 'How the team behaves', 'notebook.sync_interval_minutes', 'How often the notebook is checked for new sources.'),
        (15, 'How the team behaves', 'conversation.window_minutes', 'How far back a reply looks for the messages before it. A chat has no "conversation ended" event, so this is a window rather than a session.'),
        (16, 'How the team behaves', 'conversation.max_turns', 'How many of those turns to carry. Enough to hold a real exchange; not so many that the question being answered is buried.'),

        (20, 'Limits', 'agents.max_simultaneous_jobs', 'How many jobs run at once.'),
        (21, 'Limits', 'agents.max_delegation_depth', 'How far one piece of work may delegate before it has to come back to you.'),
        (22, 'Limits', 'agents.max_specialists_per_job', 'How many people one job may convene.'),
        (23, 'Limits', 'agents.max_live_specialists', 'How many temporary specialists may exist at once.'),
        (24, 'Limits', 'agents.max_investigations_per_project_per_day', 'How much unprompted digging one project may generate in a day.'),
        (25, 'Limits', 'notebook.window_units', 'Our estimate of the notebook allowance in one five-hour window. A guess until a refusal measures it.'),
        (26, 'Limits', 'notebook.week_units', 'The weekly ceiling, same currency, same caveat.'),
        (27, 'Limits', 'knowledge.new_source_jobs_per_hour', 'Ceiling on research jobs started by arriving sources. A bulk paste into an established project looks exactly like news, and this is what makes that survivable.'),
        (28, 'Limits', 'knowledge.new_source_min_chars', 'Below this a document is not worth convening anyone over.'),
        (29, 'Limits', 'ui.needs_me_cap', 'How many things may sit at the top of Today before the rest are folded away.')
    ) as k(ord, "group", key, description)
$$;


--
-- Name: hq_forget_google(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_forget_google() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_started jsonb;
begin
  -- Parks the token and enqueues the revoke. Returns parked=false when there
  -- was nothing stored, which is not an error: signing out twice is allowed.
  v_started := app.google_revoke_begin();

  delete from public.system_config where key = 'google.granted_scopes';

  -- Everything that reads Google goes off with it. Leaving `calendar.enabled`
  -- true would mean an hourly duty failing forever against a credential that
  -- was deliberately removed, and a red light he caused and cannot explain.
  update public.system_config set value = to_jsonb(false) where key = 'calendar.enabled';

  update public.connection_health
     set state = 'missing',
         detail = case when (v_started->>'parked')::boolean
           then 'signed out at your request; revoking at Google'
           else 'signed out at your request' end,
         action = 'Sign in with Google on the Set up page',
         checked_at = app.now_utc()
   where service = 'google_calendar';

  return jsonb_build_object('ok', true, 'revoking', coalesce((v_started->>'parked')::boolean, false),
                            'job_id', v_started->>'job_id');
end;
$$;


--
-- Name: FUNCTION hq_forget_google(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.hq_forget_google() IS 'Signs out of Google here AND asks the worker to revoke the grant at Google (#109). The refresh token is parked under another name rather than deleted, because the revoke endpoint needs it; app.vault_secret gates the read, so nothing in the office can use it from the moment this runs.';


--
-- Name: hq_forget_vikunja(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_forget_vikunja() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_kept    int;
  v_links   int;
  v_secrets int;
begin
  select count(*)::int into v_kept from public.tasks
   where assigned_to_human and not coalesce(is_fixture, false);
  select count(*)::int into v_links from public.task_links where provider = 'vikunja';

  perform app.task_provider_forget('vikunja');
  delete from public.system_config where key in ('vikunja.base_url', 'vikunja.project_id');

  select count(*)::int into v_secrets from vault.secrets where name = 'vikunja.api_token';
  /* The Vault is a TABLE for removal. There is no `delete_secret`. */
  delete from vault.secrets where name = 'vikunja.api_token';

  update public.responsibilities set enabled = false where job_kind = 'tasks.sync';

  return jsonb_build_object('ok', true,
    'tasks_kept', v_kept, 'links_removed', v_links, 'credential_removed', v_secrets > 0,
    'note', 'every task is still here - Vikunja was a projection, never the list');
end;
$$;


--
-- Name: hq_google(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_google() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  with granted as (
    select coalesce(
      (select value #>> '{}' from public.system_config where key = 'google.granted_scopes'), ''
    ) as s
  )
  select jsonb_build_object(
    'client_id', coalesce(
      (select value #>> '{}' from public.system_config where key = 'google.client_id'), ''),
    'redirect_uri', coalesce(
      (select value #>> '{}' from public.system_config where key = 'google.redirect_uri'), ''),
    'has_secret', exists (
      select 1 from vault.decrypted_secrets where name = 'google.client_secret'),
    'has_refresh_token', exists (
      select 1 from vault.decrypted_secrets where name = 'google.refresh_token'),
    -- True once the one-time registration is done. Until then no Connect
    -- button can work, and the page says so instead of offering four that fail.
    'ready', coalesce(
      (select value #>> '{}' from public.system_config where key = 'google.client_id'), '') <> ''
      and exists (select 1 from vault.decrypted_secrets where name = 'google.client_secret'),
    'calendar_enabled', coalesce(
      (select value::text::boolean from public.system_config where key = 'calendar.enabled'), false),
    'services', coalesce((
      select jsonb_agg(jsonb_build_object(
        'slug', s.slug,
        'name', s.name,
        'does', s.does,
        -- Connected means Google actually returned every scope this needs.
        -- Derived, never stored: see the header.
        'connected', (
          select bool_and(position(scope in g.s) > 0)
          from unnest(string_to_array(s.scopes, ' ')) as scope
        ),
        'scopes', s.scopes
      ) order by s.sort, s.name)
      from public.google_services s, granted g
      where s.offered
    ), '[]'::jsonb)
  )
$$;


--
-- Name: hq_governance(integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_governance(p_limit integer DEFAULT 40) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select jsonb_build_object(
    'at', app.now_utc(),

    /*
      What it learned. Scoped, traceable to the job that learned it, and
      retractable — #54's first box, all four parts, because a lesson you
      cannot place is one you cannot judge.
    */
    'lessons', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'id', l.lesson_id,
               'body', l.body,
               'scope', l.scope::text,
               'where', coalesce(p.name, l.staff_slug, l.job_kind, 'everywhere'),
               'who', l.learned_by,
               'job', l.from_job,
               'seen', l.observations,
               'at', l.created_at
             ) order by l.created_at desc), '[]'::jsonb)
        from (select * from public.lessons_live where not is_fixture order by created_at desc
               limit greatest(coalesce(p_limit, 40), 1)) l
        left join public.projects p on p.project_id = l.project_id
    ),

    /*
      What it wants (#49). Open first, then recently settled — a decline that
      vanishes from the page is a decline Grant cannot remember making, and
      the whole value of the row is that it is durable.
    */
    'proposals', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'id', r.proposal_id,
               'who', r.staff_slug,
               'title', r.title,
               'remedy', r.remedy,
               'argument', r.argument,
               'cost', nullif(r.cost_note, ''),
               'state', r.state,
               'times', r.times_seen,
               'decided', r.decided_at,
               'note', r.decided_note
             ) order by (r.state = 'open') desc, r.times_seen desc, r.last_seen desc),
             '[]'::jsonb)
        from (
          select * from public.proposals
           where not app.harness_proposal(staff_slug, needed) and (state = 'open'
              or decided_at > app.now_utc() - interval '30 days')
           order by (state = 'open') desc, times_seen desc
           limit greatest(coalesce(p_limit, 40), 1)
        ) r
    ),

    /*
      What it noticed (#52), and what became of it. `dismissals` matters as
      much as the suggestion: a thing offered four times and dismissed four
      times is the office failing to take a hint.
    */
    'noticed', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'id', s.suggestion_id,
               'kind', s.kind,
               'body', s.body,
               'because', s.because,
               'weight', s.weight,
               'state', s.state,
               'dismissed', s.dismissals,
               'offer', s.offer_kind,
               'project', p.name,
               'at', s.raised_at
             ) order by (s.state = 'open') desc, s.weight desc, s.raised_at desc),
             '[]'::jsonb)
        from (select * from public.suggestions
               order by (state = 'open') desc, weight desc, raised_at desc
               limit greatest(coalesce(p_limit, 40), 1)) s
        left join public.projects p on p.project_id = s.project_id
    ),

    /*
      What each agent can actually do — and, #54's own judgement, the most
      useful list on the page: what it has TRIED and could not do.

      Not the whole capability index per agent: that is eight copies of a
      mostly identical structure and would be the largest payload the studio
      fetches. The remit, the count of tools held, and the walls hit.
    */
    /*
      What it is ASKING FOR (#272, and ADR-0018's missing half).

      `tool_requests` has held rows since ADR-0018 and `public.hq_approve_tool`
      and `public.hq_decline_tool` have existed beside it the whole time. Both
      were in `check:callers`' baseline, which is to say the office could ask
      Grant for a capability and Grant had nowhere to answer -- the approvals
      on record were all made by a script. CLAUDE.md's standing complaint, word
      for word: a capability that exists only as a script an agent runs is a
      capability Grant does not have.

      Open first, then whatever settled in the last thirty days, because a
      decline has to be durable to be worth anything (#49) and one that
      vanishes is one he cannot remember making. `because` is JSONB holding
      counts, not a sentence -- the page renders it as chips, never as text.
    */
    'requests', (
      select coalesce(jsonb_agg(q.v order by q.ord, q.at desc), '[]'::jsonb)
        from (
          select case r.state when 'open' then 0 else 1 end as ord,
                 r.raised_at as at,
                 jsonb_build_object(
                   'id', r.request_id,
                   'tool', r.tool,
                   'who', r.asked_by,
                   'who_name', coalesce(s.name, r.asked_by),
                   'what_for', r.what_for,
                   'because', coalesce(r.because, '{}'::jsonb),
                   'state', r.state,
                   'declines', coalesce(r.declines, 0),
                   'at', r.raised_at,
                   'settled', r.settled_at,
                   'reason', nullif(r.decline_reason, '')) as v
            from public.tool_requests r
            left join public.staff s on s.slug = r.asked_by
           where r.state = 'open'
              or r.settled_at > app.now_utc() - interval '30 days'
           order by 1, 2 desc
           limit p_limit
        ) q
    ),

    /*
      Work whose only exit is a person noticing (#272, #211).

      Folded into this payload rather than given its own section: it is the
      same screen and the same question — what is the office unable to finish
      — so a second request would be a second round trip for one number.
    */
    'stranded', app.hq_stranded_work(),

    /*
      How the office is scoring against Grant's own judgement (#272).

      `eval_latest` has existed since the evaluator did and nothing has ever
      shown it, so the one number that says whether the office is getting
      better or worse lived where only a script could see it.
    */
    'scoring', app.eval_latest(),

    'agents', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'slug', s.slug,
               'name', s.name,
               'remit', s.title,
               'expertise', coalesce(s.expertise, array[]::text[]),
               'tools', (select count(*)::int from public.staff_tools t
                          where t.staff_slug = s.slug),
               /*
                 The tool NAMES, from the same join the count above uses.

                 Not from app.what_i_can_do, which computed the same thing a
                 second time and which 0452 drops: capabilityBrief in
                 TypeScript is the live answer to "what can this agent do"
                 because it builds every prompt, and a page reading an
                 independent second implementation is two lists that will
                 disagree. One source, two readers.
               */
               'can', (select coalesce(jsonb_agg(t.tool order by t.tool), '[]'::jsonb)
                         from public.staff_tools t where t.staff_slug = s.slug),
               'tried_and_could_not', (
                 select coalesce(jsonb_agg(jsonb_build_object(
                          'kind', i.kind, 'needed', i.needed, 'times', i.times)
                        order by i.times desc), '[]'::jsonb)
                   from app.impediments_tally(90, 1, false) i
                  where i.staff_slug = s.slug
               )
             ) order by case s.slug when 'chief-of-staff' then 0 else 1 end, s.name),
             '[]'::jsonb)
        from public.staff s where s.active and s.slug not like 'fixture-%'
    )
  )
$$;


--
-- Name: hq_mcp(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_mcp() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'url', (select case
              when nullif(btrim(coalesce(value #>> '{}', '')), '') is null then null
              else 'https://' || (value #>> '{}') || '.supabase.co/functions/v1/mcp'
            end
            from public.system_config where key = 'db.project_ref'),
    -- What a client would actually see. Level and description come straight
    -- from the permissions table, so a tool turned off says so here rather
    -- than being quietly missing.
    'tools', (select coalesce(jsonb_agg(jsonb_build_object(
                       'tool', t.tool,
                       'level', t.level,
                       'what', t.description,
                       'on', t.enabled,
                       'why_off', nullif(coalesce(t.disabled_reason, ''), '')
                     ) order by t.enabled desc, t.tool), '[]'::jsonb)
                from public.tool_permissions t),
    'clients', (select coalesce(jsonb_agg(jsonb_build_object(
                         'name', c.display_name,
                         'on', c.enabled,
                         'why_off', nullif(coalesce(c.disabled_reason, ''), ''),
                         'calls', c.calls,
                         'last', case when c.last_seen_at is null then null
                                      else app.ago(c.last_seen_at) end
                       ) order by c.last_seen_at desc nulls last), '[]'::jsonb)
                  from public.mcp_clients c),
    'recent', (select coalesce(jsonb_agg(jsonb_build_object(
                        'tool', k.tool,
                        'outcome', k.outcome,
                        'rows', k.rows_returned,
                        'when', app.ago(k.called_at)
                      ) order by k.called_at desc), '[]'::jsonb)
                 from (select * from public.mcp_calls
                        order by called_at desc limit 8) k),
    -- Explicit, every time, with the real steps. His standing instruction.
    'steps', jsonb_build_array(
      'Copy the server URL above.',
      'In the client you want to connect — Claude Desktop, an editor, anything that speaks MCP — add it as a remote MCP server at that URL.',
      'It will ask for a bearer token. Run npm run hq:token, which sends the token to you on Telegram. The token is never shown on this page.',
      'The client then sees the tools listed above, minus any that are switched off.')
  )
$$;


--
-- Name: FUNCTION hq_mcp(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.hq_mcp() IS 'The MCP server address, the tools a client would see, and the steps to connect. The url is NULL until system_config.db.project_ref names this office project: there is nothing to guess it from, and a well-formed URL pointing at somebody else''s project is worse than no URL at all.';


--
-- Name: hq_office_chat(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_office_chat() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with room as (
    select c.chat_id, max(c.title) as title, count(*)::int as bots_present
      from public.telegram_chats c
      join public.telegram_bots b on b.bot_id = c.bot_id and b.enabled
     where c.chat_type in ('group', 'supergroup')
     group by c.chat_id
     order by count(*) desc
     limit 1
  ),
  expected as (select count(*)::int as n from public.telegram_bots where enabled)
  select jsonb_build_object(
    'exists', (select count(*) from room) > 0,
    'chat_id', (select chat_id from room),
    'title', (select title from room),
    'bots_present', coalesce((select bots_present from room), 0),
    'bots_expected', (select n from expected),
    'missing', coalesce(
      (select jsonb_agg(b.username order by b.username)
         from public.telegram_bots b
        where b.enabled
          and not exists (
            select 1 from public.telegram_chats c
             where c.bot_id = b.bot_id
               and c.chat_id = (select chat_id from room))),
      '[]'::jsonb),
    'direct_to_grant', coalesce(
      (select value #>> '{}' from public.system_config where key = 'telegram.direct_to_grant'), '')
  );
$$;


--
-- Name: hq_overview(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_overview() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select app.hq_overview_base() || jsonb_build_object('calendar', app.calendar_ahead(24))
$$;


--
-- Name: hq_overview_base(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_overview_base() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'generated_at', app.now_utc(),
    'counts', jsonb_build_object(
      'live_jobs', (
        select count(*)::int from public.jobs
        where state not in ('complete', 'cancelled', 'failed')
      ),
      'needs_me', (select count(*)::int from public.needs_me),
      'needs_me_overdue', (select count(*)::int from public.needs_me where overdue),
      'active_projects', (select count(*)::int from public.projects where status = 'active'),
      'undo_offers', (select count(*)::int from public.undo_offers)
    ),
    -- Capped, and the cap is reported. A list that silently shows 7 of 40 looks
    -- healthy exactly when it stops being useful.
    'needs_me', coalesce((
      select jsonb_agg(row_to_json(n)) from (
        select blocker_id, project_id, requested_action, why_needed,
               consequences_of_delay, approval_options, real_deadline, overdue,
               work_can_continue, created_at
        from public.needs_me
        order by overdue desc, real_deadline nulls last, created_at
        limit 20
      ) n
    ), '[]'::jsonb),
    'today', coalesce((
      select jsonb_agg(row_to_json(t)) from (
        select job_id, project_id, project_name, kind, state, intent_class,
               priority, state_reason, waiting_on, minutes_since_change
        from public.today
        order by priority desc, minutes_since_change desc
        limit 40
      ) t
    ), '[]'::jsonb),
    'projects', coalesce((
      select jsonb_agg(row_to_json(p)) from (
        select project_id, slug, name, open_blockers, overdue_blockers,
               live_jobs, failed_jobs_24h, stalled_jobs, hours_since_sync,
               has_brief, brief_is_stale
        from app.project_attention()
      ) p
    ), '[]'::jsonb)
  );
$$;


--
-- Name: hq_plane_layout(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_plane_layout(p_project_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select coalesce(
    (select jsonb_build_object('at', l.at, 'view', l.view)
       from public.plane_layouts l
      where l.owner = 'grant' and l.project_id = p_project_id),
    jsonb_build_object('at', '{}'::jsonb, 'view', '{}'::jsonb))
$$;


--
-- Name: hq_plane_layout_reset(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_plane_layout_reset(p_project_id uuid) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  with gone as (
    delete from public.plane_layouts
     where owner = 'grant' and project_id = p_project_id
    returning 1)
  select jsonb_build_object('reset', true, 'had_one', exists (select 1 from gone))
$$;


--
-- Name: hq_plane_layout_set(uuid, jsonb, jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_plane_layout_set(p_project_id uuid, p_at jsonb, p_view jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
begin
  if jsonb_typeof(p_at) is distinct from 'object' then
    return jsonb_build_object('error', 'the arrangement is a map of node id to position');
  end if;
  insert into public.plane_layouts (owner, project_id, at, view)
  values ('grant', p_project_id, p_at, coalesce(p_view, '{}'::jsonb))
  on conflict (owner, project_id) do update
    set at = excluded.at, view = excluded.view, updated_at = app.now_utc();
  return jsonb_build_object('saved', true, 'cards', (select count(*) from jsonb_object_keys(p_at)));
end;
$$;


--
-- Name: hq_portfolio_tasks(integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_portfolio_tasks(p_limit integer DEFAULT 200) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with today as (
    select (app.now_utc() at time zone app.grant_timezone())::date as d
  ),
  open_tasks as (
    select t.task_id, t.title, t.detail, t.state, t.priority, t.due_on, t.starts_on,
           t.is_milestone, t.parent_task_id, t.blocked_on, t.added_by,
           t.updated_at, t.created_at, t.project_id,
           p.slug as project_slug, p.name as project_name,
           s.slug as owner_slug, s.name as owner_name,
           /*
             An agent put it there, so Grant has not agreed to it. `added_by`
             already carried this and nothing had ever read it -- which is why
             #139's proposals and #130's extracted tasks have somewhere to land
             without a new column.
           */
           (t.added_by is distinct from 'grant') as suggested
      from public.tasks t
      left join public.projects p on p.project_id = t.project_id
      left join public.staff s on s.staff_id = t.assignee_staff
     where not t.is_fixture and not t.assigned_to_human
       and t.state in ('todo', 'doing', 'blocked')
       -- A task on an archived project is not work; the project was put away.
       and (t.project_id is null or p.status = 'active')
  ),
  ranked as (
    select o.*,
           (o.due_on is not null and o.due_on < (select d from today)) as overdue,
           /*
             Nothing has happened to it in a fortnight and nothing is stopping
             it. `blocked` is excluded deliberately: a blocked task is not
             neglected, it is waiting, and flagging it as stale would bury the
             ones that genuinely are.
           */
           (o.state in ('todo', 'doing')
            and o.updated_at < app.now_utc() - interval '14 days') as stale,
           (o.state = 'blocked') as waiting,
           (o.assignee_slug_missing) as unowned
      from (select oo.*, (oo.owner_slug is null) as assignee_slug_missing from open_tasks oo) o
  )
  select jsonb_build_object(
    'at', app.now_utc(),
    'today', (select d from today),
    'counts', jsonb_build_object(
      'open',     (select count(*) from ranked),
      'overdue',  (select count(*) from ranked where overdue),
      'waiting',  (select count(*) from ranked where waiting),
      'stale',    (select count(*) from ranked where stale),
      'unowned',  (select count(*) from ranked where unowned),
      'suggested',(select count(*) from ranked where suggested),
      'no_project',(select count(*) from ranked where project_id is null)),
    'tasks', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'id', r.task_id, 'title', r.title, 'detail', nullif(r.detail, ''),
               'state', r.state, 'priority', r.priority,
               'due_on', r.due_on, 'starts_on', r.starts_on,
               'milestone', r.is_milestone, 'parent', r.parent_task_id,
               'blocked_on', nullif(r.blocked_on, ''),
               'project', r.project_slug, 'project_name', r.project_name,
               'owner', r.owner_slug, 'owner_name', r.owner_name,
               'overdue', r.overdue, 'stale', r.stale,
               'waiting', r.waiting, 'unowned', r.unowned,
               'suggested', r.suggested,
               'added_by', r.added_by)
             /*
               What to do next, as an ordering rather than an opinion.

               Overdue first, then a date approaching, then what he marked
               important, then a milestone, then oldest. Dated work outranks
               undated work because a date is a commitment somebody else may be
               waiting on -- priority alone would let a P1 with no date sit
               above something due this morning.
             */
             order by r.overdue desc,
                      (r.due_on is null), r.due_on asc nulls last,
                      r.priority asc, r.is_milestone desc, r.created_at asc)
             , '[]'::jsonb)
        from (select * from ranked
               order by overdue desc, (due_on is null), due_on asc nulls last,
                        priority asc, is_milestone desc, created_at asc
               limit greatest(coalesce(p_limit, 200), 1)) r
    )
  )
$$;


--
-- Name: FUNCTION hq_portfolio_tasks(p_limit integer); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.hq_portfolio_tasks(p_limit integer) IS '#173. One row per task across every project and none. overdue/stale/waiting are computed on read in Grant''s timezone -- a stored overdue flag is wrong the moment midnight passes.';


--
-- Name: hq_project_look(text, text, text, text, text[]); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_project_look(p_slug text, p_icon text DEFAULT NULL::text, p_hue text DEFAULT NULL::text, p_image text DEFAULT NULL::text, p_clear text[] DEFAULT ARRAY[]::text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_project uuid;
  v_icon    text;
  v_hue     text;
  v_clear   text[] := array[]::text[];
  v_undo    uuid;
  v_touched_image boolean;
begin
  select project_id, icon, icon_hue into v_project, v_icon, v_hue
    from public.projects
   where slug = p_slug and status = 'active';
  if v_project is null then
    return jsonb_build_object('error', format('no active dashboard project called %s', p_slug));
  end if;

  if p_hue is not null and p_hue not in
     ('p-rust', 'p-amber', 'p-moss', 'p-slate', 'p-iris', 'p-plum') then
    return jsonb_build_object('error', format('%s is not one of the palette colours', p_hue));
  end if;

  -- The new one. A URL to somewhere else is the likeliest mistake and the one
  -- worth naming: an image the office does not hold is an image that vanishes
  -- when that host does.
  if p_image is not null and p_image not like 'data:image/%' then
    return jsonb_build_object('error',
      'an image has to be sent as data, not as a link -- the page resizes it to 256px '
      || 'and encodes it before it gets here, so a link means something else called this');
  end if;

  if p_image is not null and length(p_image) > 98304 then
    return jsonb_build_object('error',
      'that image is too large once encoded -- it is resized to 256px before it is sent, '
      || 'so an image this big means the resize did not run');
  end if;

  if not app.icon_key_ok(p_icon) then
    return jsonb_build_object('error',
      format('%L is not the shape of an icon key -- lowercase letters, digits '
             || 'and single hyphens, two to forty characters', p_icon));
  end if;

  update public.projects
     set icon     = case when 'icon'  = any(p_clear) then null
                         else coalesce(p_icon, icon) end,
         icon_hue = case when 'hue'   = any(p_clear) then null
                         else coalesce(p_hue, icon_hue) end,
         image    = case when 'image' = any(p_clear) then null
                         else coalesce(p_image, image) end
   where project_id = v_project;

  v_touched_image := p_image is not null or 'image' = any(p_clear);

  if v_touched_image then
    -- Exact would mean keeping the previous 96 KB data URL for a two-minute
    -- offer, on every change, for ever. That is a hoard, not an undo. Say so
    -- rather than offering a partial restore that quietly leaves the old photo
    -- gone.
    v_undo := null;
    perform app.undo_none('project.photo',
      format('Changed the photo on %s — the previous one is not kept', p_slug));
  else
    if v_icon is null then v_clear := array_append(v_clear, 'icon'); end if;
    if v_hue  is null then v_clear := array_append(v_clear, 'hue'); end if;
    v_undo := app.undo_offer(
      'project.look',
      format('Changed how %s looks', p_slug),
      jsonb_build_object('action', 'project_look',
                         'args', jsonb_build_object(
                           'p_slug', p_slug, 'p_icon', v_icon, 'p_hue', v_hue,
                           'p_clear', to_jsonb(v_clear))));
  end if;

  return (
    select jsonb_build_object('ok', true, 'slug', p_slug,
             'icon', pr.icon, 'hue', pr.icon_hue, 'undo', v_undo,
             'image', case when pr.image is null then null else 'set' end)
      from public.projects pr where pr.project_id = v_project
  );
end;
$$;


--
-- Name: hq_project_seen(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_project_seen(p_project_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
begin
  insert into public.project_seen (owner, project_id, at)
  values ('grant', p_project_id, app.now_utc())
  on conflict (owner, project_id) do update set at = app.now_utc();
  return jsonb_build_object('seen', true);
end;
$$;


--
-- Name: hq_projects(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_projects() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select coalesce(jsonb_agg(x order by x->>'name'), '[]'::jsonb) from (
    select jsonb_build_object(
             'project_id', p.project_id,
             'slug', p.slug,
             'name', p.name,
             'description', p.description,
             'purpose', p.purpose,
             'channel_prefix', p.channel_prefix,
             'status', p.status,
             'documents', (select count(*) from public.documents d
                            where d.project_id = p.project_id
                              and d.mirrors_document_id is null),
             -- Shown separately rather than hidden: a mirror is real, it is
             -- just not new material, and "12 documents, 12 mirrored to Notion"
             -- is a more useful sentence than either number alone.
             'mirrored', (select count(*) from public.documents d
                           where d.project_id = p.project_id
                             and d.mirrors_document_id is not null),
             'aliases', (select coalesce(jsonb_agg(jsonb_build_object(
                              'alias', a.alias, 'source', a.source) order by a.confidence desc, a.alias), '[]'::jsonb)
                           from public.project_aliases a
                          where a.project_id = p.project_id and a.source <> 'name'),
             'connections', (select coalesce(jsonb_agg(to_jsonb(c)), '[]'::jsonb)
                               from app.project_connections(p.project_id) c),
             'channels', (select coalesce(jsonb_agg(jsonb_build_object(
                              'name', m.channel_name, 'discipline', m.discipline) order by m.channel_name), '[]'::jsonb)
                            from public.slack_channel_map m
                           where m.project_id = p.project_id and m.active),
             'attachments', (select coalesce(jsonb_agg(jsonb_build_object(
                                 'attachment_id', a.attachment_id,
                                 'connector', a.connector,
                                 'external_ref', a.external_ref,
                                 'display_name', a.display_name,
                                 'role', a.role,
                                 'artifact_kind', a.artifact_kind) order by a.role, a.connector), '[]'::jsonb)
                               from public.project_attachments a
                              where a.project_id = p.project_id and a.enabled)
           ) as x
      from public.projects p
     where p.status = 'active'
  ) s
$$;


--
-- Name: hq_pulse(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_pulse() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select jsonb_build_object(
    'at', app.now_utc(),
    /*
      The digest. Anything that changes what the studio DRAWS has to move one of
      these, and nothing else should -- a digest that changes when nothing
      visible did is a page that redraws for no reason, which is worse than a
      stale one because it interrupts.
    */
    'jobs_running', (select count(*)::int from public.jobs
                      where state in ('running', 'queued') and not is_fixture),
    'jobs_done', (select count(*)::int from public.jobs
                   where state = 'complete' and not is_fixture),
    'outputs', (select count(*)::int from public.outputs o
                 join public.jobs j using (job_id) where not j.is_fixture),
    'tasks_open', (select count(*)::int from public.tasks
                    where state in ('todo', 'doing', 'blocked') and not is_fixture),
    'documents', (select count(*)::int from public.documents),
    /*
      0343. Something was SAID.

      Most conversation already moves this digest by accident: a message
      becomes a job, and `jobs_running` counts it. Most is not all — a
      backfilled message makes no job (0340), and neither does a button press.
      Without this the studio's chat would sit still while the conversation
      grew underneath it, which is exactly the "photograph, not a window"
      this function exists to stop.
    */
    'messages', (select count(*)::int from public.inbound_commands),
    -- The most recent moment anything the page shows was touched. Catches an
    -- edit that leaves every count identical -- a task renamed, a project
    -- given an icon -- which the counts alone cannot see.
    'latest', greatest(
      (select max(updated_at) from public.jobs where not is_fixture),
      (select max(created_at) from public.outputs),
      (select max(updated_at) from public.tasks where not is_fixture),
      (select max(updated_at) from public.projects),
      -- And an edit that changes no count: a message arriving on a surface
      -- whose job already existed.
      (select max(received_at) from public.inbound_commands)
    )
  )
$$;


--
-- Name: hq_reattach(uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_reattach(p_attachment_id uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare v_found uuid;
begin
  select attachment_id into v_found
    from public.project_attachments where attachment_id = p_attachment_id;
  if v_found is null then
    return jsonb_build_object('error', 'no such attachment');
  end if;

  -- `project_attachments` carries `check (enabled or disabled_reason is not
  -- null)`, so re-enabling and clearing the reason must happen in one
  -- statement. They do.
  update public.project_attachments
     set enabled = true, disabled_reason = p_reason
   where attachment_id = p_attachment_id;

  return jsonb_build_object('reattached', p_attachment_id);
end;
$$;


--
-- Name: hq_rename_project(text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_rename_project(p_slug text, p_name text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_prefix text;
  v_id uuid;
  v_was text;
  v_fixture boolean;
  v_undo uuid;
  v_taken text;
begin
  if coalesce(trim(p_name), '') = '' then
    return jsonb_build_object('error', 'a project needs a name');
  end if;
  select project_id, name, is_fixture into v_id, v_was, v_fixture
    from public.projects where slug = p_slug;
  if v_id is null then
    return jsonb_build_object('error', format('no project %L', p_slug));
  end if;

  /*
    0365. The check hq_create_project has always had, on the writer that never
    did. Excludes this project so renaming to its own name stays a no-op, and
    excludes archived projects so a retired probe cannot hold a name hostage.
  */
  select p.slug into v_taken
    from public.projects p
   where p.project_id <> v_id
     and p.status <> 'archived'
     and lower(trim(p.name)) = lower(trim(p_name))
   limit 1;
  if v_taken is not null then
    return jsonb_build_object('error', format(
      '%L already belongs to the project %L, and two projects answering to one name '
      || 'is how work lands in the wrong place. Rename or archive that one first.',
      trim(p_name), v_taken));
  end if;

  v_prefix := left(trim(both '-' from regexp_replace(lower(p_name), '[^a-z0-9]+', '-', 'g')), 48);
  update public.projects
     set name = trim(p_name), channel_prefix = nullif(v_prefix, '')
   where project_id = v_id;

  -- The Slack channels follow, but not from here: renaming a channel is a
  -- Slack API call and this is SQL. The page reports that the rename is
  -- pending and the worker carries it out, rather than the page claiming a
  -- rename it cannot perform.
  --
  -- A fixture project has no channels, so there is nothing for the worker to
  -- do and the job would be real work queued against a project nobody can see.
  if not coalesce(v_fixture, false) then
    insert into public.jobs
      (correlation_id, project_id, idempotency_key, kind, requested_by, priority, pinned_config)
    values (gen_random_uuid(), v_id, format('rename-%s-%s', v_id, gen_random_uuid()),
            'office.rename_channels', 'hq', 300,
            jsonb_build_object('prefix', v_prefix));
  end if;

  -- The slug does not change on a rename, so the inverse addresses the same
  -- project. Undoing also enqueues a second rename job, which is right: the
  -- channels followed the name out and have to follow it back.
  if trim(p_name) is distinct from v_was then
    v_undo := app.undo_offer(
      'project.rename',
      format('Renamed to %s', trim(p_name)),
      jsonb_build_object('action', 'rename_project',
                         'args', jsonb_build_object('p_slug', p_slug, 'p_name', v_was)));
  end if;

  return jsonb_build_object(
    'slug', p_slug, 'name', trim(p_name), 'channel_prefix', v_prefix,
    'undo', v_undo,
    'note', case when coalesce(v_fixture, false)
                 then 'a fixture project has no channels to rename'
                 else 'channels will be renamed by the worker on its next pass' end
  );
end;
$$;


--
-- Name: hq_retire_skill(uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_retire_skill(p_skill_id uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select app.retire_skill(
    p_skill_id, 'grant',
    -- A default that is honest rather than a default that is empty. He clicked
    -- the button; "Grant retired this from the dashboard" is exactly what
    -- happened and it beats an eight-character placeholder.
    coalesce(nullif(btrim(p_reason), ''), 'Retired by Grant from the dashboard')
  )
$$;


--
-- Name: hq_routing(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_routing() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select jsonb_build_object(
    'direct_to_grant',
      coalesce((select value #>> '{}' from public.system_config
                 where key = 'telegram.direct_to_grant'), ''),
    'only_chief_speaks',
      coalesce((select (value #>> '{}')::boolean from public.system_config
                 where key = 'telegram.only_chief_speaks'), false),
    'pager_floor',
      coalesce((select value #>> '{}' from public.system_config
                 where key = 'telegram.pager_floor'), 'routine'),
    'office_group', app.hq_office_chat(),
    'people', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'slug', s.slug, 'name', s.name, 'title', s.title,
               'bot', (select b.username from public.telegram_bots b
                        where b.staff_slug = s.slug limit 1))
             order by s.name), '[]'::jsonb)
        from public.staff s where s.active
    ),
    'duties', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'slug', r.slug, 'description', r.description,
               'enabled', r.enabled, 'every_minutes', r.period_minutes,
               'last_run_at', r.last_run_at)
             order by r.slug), '[]'::jsonb)
        from public.responsibilities r
    )
  )
$$;


--
-- Name: hq_routing_set(text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_routing_set(p_what text, p_value text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_floor text;
begin
  if p_what = 'direct_to_grant' then
    if p_value <> '' and not exists (
      select 1 from public.staff where slug = p_value and active
    ) then
      return jsonb_build_object('error', format('no active staff member "%s"', p_value));
    end if;
    update public.system_config set value = to_jsonb(p_value)
     where key = 'telegram.direct_to_grant';
    return jsonb_build_object('ok', true, 'direct_to_grant', p_value);

  elsif p_what = 'only_chief_speaks' then
    -- The work is unaffected either way. This is about who sends.
    update public.system_config
       set value = to_jsonb(lower(trim(p_value)) in ('true', 'on', 'yes', '1'))
     where key = 'telegram.only_chief_speaks';
    return jsonb_build_object(
      'ok', true,
      'only_chief_speaks', lower(trim(p_value)) in ('true', 'on', 'yes', '1')
    );

  elsif p_what = 'pager_floor' then
    v_floor := lower(trim(p_value));
    if v_floor not in ('trivial', 'routine', 'important', 'urgent', 'blocker') then
      return jsonb_build_object('error', format('"%s" is not a severity', p_value));
    end if;
    update public.system_config set value = to_jsonb(v_floor)
     where key = 'telegram.pager_floor';
    return jsonb_build_object('ok', true, 'pager_floor', v_floor);

  elsif p_what like 'duty:%' then
    if not exists (select 1 from public.responsibilities where slug = substring(p_what from 6)) then
      return jsonb_build_object('error', format('no duty "%s"', substring(p_what from 6)));
    end if;
    update public.responsibilities
       set enabled = (lower(trim(p_value)) in ('on', 'true', 'yes', '1')),
           updated_at = app.now_utc()
     where slug = substring(p_what from 6);
    return jsonb_build_object('ok', true, p_what, p_value);
  end if;

  return jsonb_build_object('error', format('"%s" is not a routing setting', p_what));
end;
$$;


--
-- Name: hq_series(integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_series(p_days integer DEFAULT 30) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with span as (
    select
      least(greatest(p_days, 7), 90) as days,
      coalesce(
        (select value #>> '{}' from public.system_config where key = 'grant.timezone'),
        'UTC'
      ) as tz
  ),
  days as (
    select (generate_series(
      (app.now_utc() at time zone (select tz from span))::date - ((select days from span) - 1),
      (app.now_utc() at time zone (select tz from span))::date,
      interval '1 day'
    ))::date as day
  )
  select jsonb_build_object(
    'timezone', (select tz from span),
    'days', (select days from span),
    'inference_cost_usd', coalesce((
      select jsonb_agg(jsonb_build_array(d.day, round(coalesce(u.cost, 0), 6)) order by d.day)
      from days d
      left join (
        select (occurred_at at time zone (select tz from span))::date as day,
               sum(cost_usd) as cost
        from public.inference_usage
        group by 1
      ) u on u.day = d.day
    ), '[]'::jsonb),
    'inference_calls', coalesce((
      select jsonb_agg(jsonb_build_array(d.day, coalesce(u.n, 0)) order by d.day)
      from days d
      left join (
        select (occurred_at at time zone (select tz from span))::date as day,
               count(*)::int as n
        from public.inference_usage
        group by 1
      ) u on u.day = d.day
    ), '[]'::jsonb),
    'jobs_completed', coalesce((
      select jsonb_agg(jsonb_build_array(d.day, coalesce(j.n, 0)) order by d.day)
      from days d
      left join (
        select (occurred_at at time zone (select tz from span))::date as day,
               count(*)::int as n
        from public.job_state_transitions
        where to_state = 'complete'
        group by 1
      ) j on j.day = d.day
    ), '[]'::jsonb),
    'messages_sent', coalesce((
      select jsonb_agg(jsonb_build_array(d.day, coalesce(m.n, 0)) order by d.day)
      from days d
      left join (
        select (sent_at at time zone (select tz from span))::date as day,
               count(*)::int as n
        from public.deliveries
        where sent_at is not null
        group by 1
      ) m on m.day = d.day
    ), '[]'::jsonb)
  );
$$;


--
-- Name: hq_set_google_credentials(text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_set_google_credentials(p_client_id text, p_secret text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_a   text := app.credential_clean(p_client_id);
  v_b   text := app.credential_clean(p_secret);
  v_id  text;
  v_sec text;
  v_seen text;
begin
  if v_a = '' and v_b = '' then
    return jsonb_build_object('error', 'there is nothing to save');
  end if;

  /*
    Sorted by shape, whichever box they arrived in.

    Only ONE of the two is ever required: the client ID may be saved on its own
    (it is not a secret and the page shows it), and the secret may be saved on
    its own (the ID is already stored from last time).
  */
  if v_a ~* '^GOCSPX-' then
    v_sec := v_a; v_id := v_b;
  elsif v_b ~* '^GOCSPX-' then
    v_sec := v_b; v_id := v_a;
  elsif v_b = '' then
    v_id := v_a;
  elsif v_a = '' then
    /*
      Something in the secret box that is not a secret. Refusing is right -
      storing it would put an unknown value in the vault under a name that
      says client secret - and the message has to say what it recognised.
    */
    v_seen := app.credential_shape(v_b);
    return jsonb_build_object('error',
      case when v_seen is null
        then 'that does not look like a Google client secret - they start GOCSPX-, on the '
             || 'Credentials page of the Google Cloud console'
        else 'that looks like ' || v_seen || ', not a Google client secret - they start GOCSPX-' end);
  else
    v_id := v_a; v_sec := v_b;
    if v_sec !~* '^GOCSPX-' then
      v_seen := app.credential_shape(v_sec);
      return jsonb_build_object('error',
        case when v_seen is null
          then 'neither of those is a Google client secret - the one you want starts GOCSPX-'
          else 'that looks like ' || v_seen || ', not a Google client secret - they start GOCSPX-' end);
    end if;
  end if;

  /*
    And the client ID may not be a credential of any kind.

    The box is plain text and the page renders what is stored in it, so this is
    the one refusal here that protects a secret rather than a configuration.
  */
  if v_id is not null and v_id <> '' then
    v_seen := app.credential_shape(v_id);
    if v_seen is not null then
      return jsonb_build_object('error',
        'the client ID box has ' || v_seen || ' in it. Nothing was saved. A client ID is not '
        || 'a secret and this page shows it, so a credential must not go there.');
    end if;
    perform app.hq_set_setting('google.client_id', v_id);
  end if;

  if v_sec is not null and v_sec <> '' then
    perform app.store_secret('google.client_secret', v_sec,
      'Google Cloud OAuth client secret, entered on the web front end.');
  end if;

  return jsonb_build_object(
    'stored', true,
    'client_id', (v_id is not null and v_id <> ''),
    'secret', (v_sec is not null and v_sec <> ''));
end;
$$;


--
-- Name: FUNCTION hq_set_google_credentials(p_client_id text, p_secret text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.hq_set_google_credentials(p_client_id text, p_secret text) IS 'Save the Google client ID and client secret together, in EITHER order, sorted by shape (§35, after 0359). Strips invisible characters first, so a valid credential is never refused for a reason nobody can see, and refuses a credential in the client ID box, which the page renders in plain text.';


--
-- Name: hq_set_google_secret(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_set_google_secret(p_secret text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_secret text := app.credential_clean(p_secret);
  v_seen   text;
begin
  if v_secret = '' then
    return jsonb_build_object('error', 'the secret is empty');
  end if;
  -- Case-insensitively, and after the invisible characters are gone. Both
  -- were ways a correct credential got refused (0359 cost three attempts on
  -- the Slack form for exactly this).
  if v_secret !~* '^GOCSPX-' then
    v_seen := app.credential_shape(v_secret);
    return jsonb_build_object('error',
      case when v_seen is null
        then 'that does not look like a Google client secret - they start GOCSPX-'
        else 'that looks like ' || v_seen || ', not a Google client secret - they start GOCSPX-' end);
  end if;
  perform app.store_secret('google.client_secret', v_secret,
    'Google Cloud OAuth client secret, entered on the web front end.');
  return jsonb_build_object('stored', true);
end;
$$;


--
-- Name: hq_set_setting(text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_set_setting(p_key text, p_value text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_json jsonb;
  v_num  numeric;
begin
  if p_key not in (
    -- Where things live.
    'db.project_ref', 'db.region',
    'backup.s3_bucket', 'backup.s3_endpoint', 'backup.s3_region',
    -- Google, still settable so the setup card can write the client id.
    'google.client_id', 'google.redirect_uri', 'google.scopes',
    -- Integrations, on and off.
    'calendar.enabled', 'calendar.calendar_id', 'calendar.sync_tasks',
    'notebook.enabled', 'knowledge.read_new_sources',
    -- Numbers Grant should be able to turn down without a deploy.
    'notebook.window_units', 'notebook.week_units', 'notebook.sync_interval_minutes',
    'agents.max_simultaneous_jobs', 'agents.max_delegation_depth',
    'agents.max_specialists_per_job', 'agents.max_live_specialists',
    'agents.max_investigations_per_project_per_day',
    'conversation.window_minutes', 'conversation.max_turns',
    'knowledge.new_source_jobs_per_hour', 'knowledge.new_source_min_chars',
    'ui.needs_me_cap', 'grant.timezone',
    -- #259 Phase 2: where the task provider lives. The TOKEN is not here;
    -- it goes to the Vault through `hq_set_vikunja`, sorted by shape.
    'vikunja.base_url', 'vikunja.project_id'
  ) then
    return jsonb_build_object('error', format('%L is not a setting this page may change', p_key));
  end if;

  if app.credential_shape(p_value) is not null then
    return jsonb_build_object('error',
      'that value looks like ' || app.credential_shape(p_value) ||
      '. Nothing was saved. Settings are stored in plain text and shown on the page, '
      'so a credential cannot be kept in one - it goes to the vault through its own box.');
  end if;

  -- Booleans stay booleans. 'false' as a STRING is truthy in every language
  -- that will read this, which is the kind of bug that turns an integration on.
  if p_key in ('calendar.enabled', 'calendar.sync_tasks', 'notebook.enabled', 'knowledge.read_new_sources') then
    if lower(trim(p_value)) not in ('true', 'false') then
      return jsonb_build_object('error', 'that setting is on or off');
    end if;
    v_json := to_jsonb(lower(trim(p_value))::boolean);

  elsif p_key in (
    'notebook.window_units', 'notebook.week_units', 'notebook.sync_interval_minutes',
    'agents.max_simultaneous_jobs', 'agents.max_delegation_depth',
    'agents.max_specialists_per_job', 'agents.max_live_specialists',
    'agents.max_investigations_per_project_per_day',
    'conversation.window_minutes', 'conversation.max_turns',
    'knowledge.new_source_jobs_per_hour', 'knowledge.new_source_min_chars',
    'ui.needs_me_cap'
  ) then
    begin
      v_num := trim(p_value)::numeric;
    exception when others then
      return jsonb_build_object('error', 'that setting is a number');
    end;
    if v_num <> trunc(v_num) then
      return jsonb_build_object('error', 'that setting is a whole number');
    end if;
    -- Each key's own range. A wrong number here is not a rejected form, it is
    -- a system behaving oddly a day later.
    if v_num < 1 then
      return jsonb_build_object('error', 'that setting must be at least 1 — zero would stop the team');
    end if;
    if p_key like 'agents.max%' and v_num > 20 then
      return jsonb_build_object('error', 'that is high enough to be a runaway; 20 is the ceiling');
    end if;
    if p_key = 'conversation.window_minutes' and v_num > 240 then
      return jsonb_build_object(
        'error', 'over four hours of context would make every reply expensive; 240 is the ceiling');
    end if;
    if p_key = 'conversation.max_turns' and v_num > 40 then
      return jsonb_build_object('error', '40 turns is the ceiling — beyond it the question gets buried');
    end if;
    if p_key = 'notebook.sync_interval_minutes' and v_num < 5 then
      return jsonb_build_object('error', 'syncing more often than every five minutes achieves nothing');
    end if;
    v_json := to_jsonb(v_num::bigint);

  elsif p_key = 'grant.timezone' then
    -- Checked against Postgres's own list rather than a regex. A timezone that
    -- does not exist makes every date in the system silently UTC.
    if not exists (select 1 from pg_timezone_names where name = trim(p_value)) then
      return jsonb_build_object('error', format('%L is not a timezone Postgres knows', p_value));
    end if;
    v_json := to_jsonb(trim(p_value));

  else
    v_json := to_jsonb(trim(p_value));
  end if;

  insert into public.system_config (key, value, description)
  values (p_key, v_json, 'set from Team HQ')
  on conflict (key) do update set value = excluded.value;

  return jsonb_build_object('ok', true, 'key', p_key, 'value', v_json);
end;
$$;


--
-- Name: hq_set_slack_credentials(text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_set_slack_credentials(p_bot_token text, p_signing_secret text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
declare
  v_a    text;
  v_b    text;
  v_bot  text;
  v_sig  text;
  v_ref_bot uuid;
  v_ref_sig uuid;
  v_app  text;
  v_seen text;
begin
  /*
    Everything that is not part of the credential, removed.

    A value copied out of a browser can carry a trailing newline, a
    non-breaking space, or a zero-width character from the surrounding markup.
    None of them are visible in a password field and all of them break a
    prefix match.
  */
  v_a := regexp_replace(coalesce(p_bot_token, ''), '[\s ​-‏﻿]', '', 'g');
  v_b := regexp_replace(coalesce(p_signing_secret, ''), '[\s ​-‏﻿]', '', 'g');

  if v_a = '' or v_b = '' then
    return jsonb_build_object('error',
      'both the bot token and the signing secret are needed - reinstalling gives you both');
  end if;

  -- Sorted by shape. Whichever box they arrived in.
  if v_a ~* '^xoxb-' then
    v_bot := v_a; v_sig := v_b;
  elsif v_b ~* '^xoxb-' then
    v_bot := v_b; v_sig := v_a;
  else
    /*
      Neither is a bot token. Name the CLASS, never the characters.

      Slack's prefixes are public; what follows them is the credential. This
      says which known kind of thing it recognised so the mistake is
      actionable, and nothing more.
    */
    v_seen := case
      when v_a ~* '^xapp-' or v_b ~* '^xapp-' then 'an app-level token (xapp-)'
      when v_a ~* '^xoxe' or v_b ~* '^xoxe' then 'a configuration token (xoxe-)'
      when v_a ~* '^xoxp-' or v_b ~* '^xoxp-' then 'a user token (xoxp-)'
      when v_a ~ '^[0-9a-f]{32}$' and v_b ~ '^[0-9a-f]{32}$' then 'two signing secrets'
      else 'neither of them' end;
    return jsonb_build_object('error',
      'no bot token among those - ' || v_seen || '. The one you want starts xoxb- and is on '
      || 'the Install App page, under Bot User OAuth Token.');
  end if;

  if v_sig !~ '^[0-9a-f]{32}$' then
    return jsonb_build_object('error',
      'the other value is not a signing secret - it is 32 characters of 0-9 and a-f, on '
      || 'Basic Information under App Credentials.');
  end if;

  select slack_app_id into v_app from public.slack_app_credentials limit 1;
  if v_app is null then
    return jsonb_build_object('error', 'there is no Slack app row to attach these to');
  end if;

  perform app.store_secret('slack.bot_token', v_bot,
    'Bot user OAuth token for the AI Team HQ app, entered on the web front end.');
  perform app.store_secret('slack.signing_secret', v_sig,
    'Slack request signing secret, entered on the web front end.');

  select id into v_ref_bot from vault.secrets where name = 'slack.bot_token';
  select id into v_ref_sig from vault.secrets where name = 'slack.signing_secret';

  update public.slack_app_credentials
     set bot_token_ref = v_ref_bot,
         signing_secret_ref = v_ref_sig,
         enabled = true,
         disabled_reason = null,
         revoked_at = null,
         installed_at = app.now_utc(),
         updated_at = app.now_utc()
   where slack_app_id = v_app;

  update public.connection_health
     set state = 'ok',
         detail = 'reconnected from the web front end',
         action = 'Setting up -> Slack on the web front end',
         checked_at = app.now_utc()
   where service = 'Slack';

  return jsonb_build_object('stored', true, 'app', v_app);
end;
$_$;


--
-- Name: FUNCTION hq_set_slack_credentials(p_bot_token text, p_signing_secret text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.hq_set_slack_credentials(p_bot_token text, p_signing_secret text) IS 'Put Slack back from the page (#210). Takes the two values in EITHER order and sorts them by shape, because the ordering carried no information and getting it wrong cost three attempts. Refusals name the class of thing recognised, never any characters from the value.';


--
-- Name: hq_set_vikunja(text, integer, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_set_vikunja(p_base_url text, p_project_id integer, p_api_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_url  text := regexp_replace(coalesce(p_base_url, ''), '[\s​-‏﻿]', '', 'g');
  v_tok  text := regexp_replace(coalesce(p_api_token, ''), '[\s​-‏﻿]', '', 'g');
  v_said jsonb;
begin
  if v_url = '' or v_tok = '' then
    return jsonb_build_object('error',
      'Vikunja needs its address and an API token. Settings - API tokens, in Vikunja.');
  end if;
  if v_url ~* '^(tk_|xox[abposr]-|ghp_|github_pat_|sk-|AKIA|glpat-)' then
    return jsonb_build_object('error',
      'that looks like a credential rather than an address - the token goes in the other box');
  end if;
  if v_url !~* '^https?://' then
    return jsonb_build_object('error',
      'the address needs to start http:// or https:// - for example https://tasks.example.com');
  end if;
  if v_tok !~* '^tk_' then
    return jsonb_build_object('error',
      'that does not look like a Vikunja API token - they start tk_');
  end if;
  if coalesce(p_project_id, 0) < 1 then
    return jsonb_build_object('error',
      'which Vikunja project should the office keep in step? Its id is in the URL when you open it.');
  end if;

  v_url := regexp_replace(v_url, '/+$', '');

  /*
    THE ANSWER IS READ, not discarded. `perform` threw away a refusal and let
    this function report success about nothing at all.
  */
  v_said := app.hq_set_setting('vikunja.base_url', v_url);
  if v_said ? 'error' then return v_said; end if;
  v_said := app.hq_set_setting('vikunja.project_id', p_project_id::text);
  if v_said ? 'error' then return v_said; end if;
  perform app.store_secret('vikunja.api_token', v_tok,
    'The Vikunja API token the task sync uses. #259 Phase 2.');

  /* AND READ BACK, because two writes that both said ok can still leave the
     office unable to answer "am I connected". */
  if (app.vikunja_settings() ->> 'configured')::boolean is not true then
    return jsonb_build_object('error',
      'the address and token were accepted but the office cannot read them back');
  end if;

  update public.responsibilities set enabled = true where job_kind = 'tasks.sync';

  return jsonb_build_object('ok', true, 'url', v_url, 'project', p_project_id,
    'note', 'the office will keep your tasks in step from now on');
end;
$_$;


--
-- Name: hq_settings(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_settings() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select jsonb_build_object(
    'live', jsonb_build_object(
      'database', current_database(),
      'server', 'PostgreSQL ' || split_part(current_setting('server_version'), ' ', 1),
      'size', pg_size_pretty(pg_database_size(current_database())),
      'tables', (select count(*)::int from information_schema.tables
                  where table_schema = 'public' and table_type = 'BASE TABLE')
    ),
    'settings', coalesce((
      select jsonb_object_agg(c.key, jsonb_build_object(
               'value', c.value, 'description', c.description))
        from public.system_config c
       where c.key in (select e ->> 'key' from jsonb_array_elements(app.hq_editable_settings()) e)
    ), '{}'::jsonb),
    -- The shape the page renders: key, group and sentence together, so it does
    -- not have to hold its own copy of any of the three.
    'editable', app.hq_editable_settings(),
    'notebook', app.notebook_allowance(),
    'google', app.hq_google()
  )
$$;


--
-- Name: hq_setup(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_setup() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select app.hq_setup_services() || jsonb_build_object(
    'google', app.hq_google(),
    -- #210. Shaped like `google` above, for the same reason: the page needs to
    -- know whether to offer a form, and matching a DISPLAY NAME is how the
    -- first attempt failed -- Slack is listed as "The office" in `services`,
    -- so a condition on the name "Slack" could never fire.
    'slack', app.hq_slack_setup(),
    -- Only the keys this page switches. The generic settings form on the
    -- Advanced page is where the rest belong, and a setup screen that shipped
    -- every configuration value would be the Advanced page with a different
    -- name.
    'settings', jsonb_build_object(
      'calendar.enabled', coalesce(
        (select value::text::boolean from public.system_config where key = 'calendar.enabled'),
        false),
      'notebook.enabled', coalesce(
        (select value::text::boolean from public.system_config where key = 'notebook.enabled'),
        false)
    )
  )
$$;


--
-- Name: hq_setup_services(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_setup_services() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  with svc as (
    select
      1 as ord, 'database' as key, 'Database' as name, 'Supabase Postgres' as vendor,
      'ready' as state,
      'Everything the team knows and everything it has done. The single source of truth.' as does,
      format('%s, %s', (select value #>> '{}' from public.system_config where key = 'db.project_ref'),
                       (select value #>> '{}' from public.system_config where key = 'db.region')) as detail,
      null::text as action, null::text as href

    union all
    select 2, 'inference', 'The team''s thinking', 'OpenRouter',
      case when exists (select 1 from public.providers p
                         where p.provider = 'openrouter' and p.secret_ref is not null)
           then 'ready' else 'action' end,
      'The models the team writes with. Free ones are used first; a paid one only when nothing free can do the job.',
      coalesce((select count(*)::text || ' usable model(s)' from public.usable_models), 'none'),
      case when exists (select 1 from public.providers p
                         where p.provider = 'openrouter' and p.secret_ref is not null)
           then null else 'Add an OpenRouter key' end,
      'https://openrouter.ai/settings/keys'

    union all
    select 3, 'slack', 'The office', 'Slack',
      case when exists (select 1 from public.slack_app_credentials
                         where enabled and revoked_at is null)
           then 'ready' else 'action' end,
      'Where the team works. Results arrive in the project channel, presented as the person who produced them, with buttons you can press.',
      coalesce((select count(*)::text || ' channel(s)' from public.slack_channel_map where active), '0'),
      case when exists (select 1 from public.slack_app_credentials
                         where enabled and revoked_at is null)
           then null else 'Install the Slack app' end,
      'https://api.slack.com/apps'

    union all
    select 4, 'telegram', 'The pager', 'Telegram',
      case when (select count(*) from public.telegram_bots where enabled and token_ref is not null) >= 1
           then 'ready' else 'action' end,
      'Eight bots, one per person, in your pocket. Send a voice note or a link and it becomes work.',
      (select count(*)::text || ' of ' || count(*) filter (where expected)::text || ' bot(s) ready'
         from public.telegram_bots where expected),
      case when (select count(*) from public.telegram_bots where enabled and token_ref is not null) >= 1
           then null else 'Create bots with BotFather' end,
      'https://t.me/BotFather'

    union all
    select 5, 'notion', 'Your own notes', 'Notion',
      case
        when not exists (select 1 from vault.secrets where name = 'notion.integration_token')
          then 'action'
        when not exists (
          select 1 from public.documents d join public.projects p using (project_id)
           where d.connector = 'notion' and p.status = 'active')
          then 'action'
        else 'ready'
      end,
      'Pages you share with the integration become part of what the team can read and cite.',
      -- Live projects only. The count was including documents on projects
      -- archived days ago, on a page whose job is to say what is true now.
      coalesce((select count(*)::text || ' page(s) synced'
                  from public.documents d join public.projects p using (project_id)
                 where d.connector = 'notion' and p.status = 'active'), '0'),
      case
        when not exists (select 1 from vault.secrets where name = 'notion.integration_token')
          then 'Add a Notion integration token'
        else 'Share a page with the integration'
      end,
      'https://www.notion.so/profile/integrations'

    union all
    select 6, 'google', 'Google account', 'Google',
      case
        when coalesce((select value #>> '{}' from public.system_config
                        where key = 'google.client_id'), '') = ''
          then 'action'
        when not exists (select 1 from vault.secrets where name = 'google.refresh_token')
          then 'action'
        else 'ready'
      end,
      'Signing in once lets the team read your calendar, and later your mail and files. Nothing is read until you switch that service on.',
      case
        when exists (select 1 from vault.secrets where name = 'google.refresh_token')
          then 'signed in'
        else 'not signed in'
      end,
      case
        when coalesce((select value #>> '{}' from public.system_config
                        where key = 'google.client_id'), '') = ''
          then 'Set up Google sign-in (once)'
        when not exists (select 1 from vault.secrets where name = 'google.refresh_token')
          then 'Sign in with Google'
        else null
      end,
      null

    union all
    select 7, 'calendar', 'Calendar', 'Google',
      case
        when not exists (select 1 from vault.secrets where name = 'google.refresh_token') then 'off'
        when coalesce((select value::text::boolean from public.system_config
                        where key = 'calendar.enabled'), false) then 'ready'
        else 'off'
      end,
      'Your diary, so the team can answer what you have on without asking you.',
      coalesce((select count(*)::text || ' event(s) cached' from public.calendar_events), '0'),
      null, null

    union all
    -- Mail. Same three states as the calendar, and for the same reason: §17
    -- separates "connected" from "switched on", so a service Grant turned off
    -- must read as off rather than as an outstanding task.
    select 7, 'gmail', 'Mail', 'Gmail',
      case
        when not exists (select 1 from vault.secrets where name = 'google.refresh_token') then 'off'
        when coalesce((select value::text::boolean from public.system_config
                        where key = 'gmail.enabled'), false) then 'ready'
        else 'off'
      end,
      'Your inbox, so the team can answer who has been in touch and about what. '
      'Headers and a preview only — never the body of a message, never attachments.',
      coalesce((select count(*)::text || ' message(s) cached'
                  from public.mail_messages where vanished_at is null), '0'),
      null, null

    union all
    select 8, 'notebook', 'Notebooks', 'Google NotebookLM',
      case
        when not exists (select 1 from vault.secrets where name = 'notebook.storage_state')
          then 'action'
        when coalesce((select value::text::boolean from public.system_config
                        where key = 'notebook.enabled'), false) then 'ready'
        else 'off'
      end,
      'Audio overviews, mind maps and briefings, made from the sources in a project. Every generation asks you first.',
      coalesce((select count(*)::text || ' notebook(s) attached'
                  from public.project_attachments a join public.projects p using (project_id)
                 where a.connector = 'notebooklm' and a.enabled and p.status = 'active'), '0'),
      case when exists (select 1 from vault.secrets where name = 'notebook.storage_state')
           then null else 'Connect a NotebookLM session' end,
      null

    union all
    select 9, 'backup', 'Backups', 'Supabase Storage',
      -- The DUTY and its last run, not a credential sitting in the vault.
      -- The row this replaces checked for a Backblaze bucket key that has
      -- nothing to do with any backup this system takes, and read "ready"
      -- because the key was still there long after the thing that used it
      -- stopped existing.
      case
        when not exists (select 1 from public.responsibilities
                          where slug = 'nightly-backup' and enabled) then 'off'
        when (select last_run_at from public.responsibilities where slug = 'nightly-backup')
             > app.now_utc() - interval '48 hours' then 'ready'
        else 'action'
      end,
      'A copy of everything every night, and a restore rehearsed from it. Holds no '
      'credentials, and lives in this same Supabase project — so it survives losing '
      'the code or a laptop, and not losing the project.',
      coalesce(
        (select case
           when r.last_run_at is null then 'enabled, not run yet'
           else format('last taken %s', app.ago(r.last_run_at))
         end
         from public.responsibilities r where r.slug = 'nightly-backup'),
        'no backup duty'),
      case
        when (select last_run_at from public.responsibilities where slug = 'nightly-backup')
             > app.now_utc() - interval '48 hours' then null
        else 'Take one now'
      end,
      null

    union all
    -- 0142: the office group. A Telegram bot cannot create one, so this row is
    -- the only place the instruction can live where Grant will find it again.
    select 12, 'office_group', 'The team''s group chat', 'Telegram',
      case when (app.hq_office_chat() ->> 'exists')::boolean then 'ready' else 'action' end,
      'One room where the whole team posts, so only the Chief of Staff messages '
      'you directly.',
      case when (app.hq_office_chat() ->> 'exists')::boolean
        then format('%s of %s bots are in %s',
                    app.hq_office_chat() ->> 'bots_present',
                    app.hq_office_chat() ->> 'bots_expected',
                    coalesce(app.hq_office_chat() ->> 'title', 'the group'))
        else 'Telegram will not let a bot create a group, so this one is yours to make: '
             'new group, add all eight bots, call it AI Team HQ. They register themselves.'
      end,
      case when (app.hq_office_chat() ->> 'exists')::boolean then null
        else 'Make the group' end,
      case when (app.hq_office_chat() ->> 'exists')::boolean then null
        else 'https://web.telegram.org/a/' end

  )
  select jsonb_build_object(
    'generated_at', app.now_utc(),
    'ready', (select count(*) from svc where state = 'ready'),
    'needs_you', (select count(*) from svc where state = 'action'),
    'services', (select jsonb_agg(row_to_json(s) order by s.ord) from svc s)
  )
$$;


--
-- Name: hq_slack_setup(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_slack_setup() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select coalesce(
    (select jsonb_build_object(
       'app_id', c.slack_app_id,
       'enabled', c.enabled,
       -- Both halves, deliberately. A bot token without a signing secret can
       -- post and cannot verify anything inbound, which reads as connected
       -- and is half a connection (0356 takes them together for this reason).
       'has_bot_token', exists (select 1 from vault.secrets s where s.id = c.bot_token_ref),
       'has_signing_secret', exists (select 1 from vault.secrets s where s.id = c.signing_secret_ref),
       'ready', c.enabled
                and exists (select 1 from vault.secrets s where s.id = c.bot_token_ref)
                and exists (select 1 from vault.secrets s where s.id = c.signing_secret_ref),
       'why_off', c.disabled_reason)
       from public.slack_app_credentials c limit 1),
    jsonb_build_object('ready', false, 'has_bot_token', false,
      'has_signing_secret', false, 'why_off', 'no Slack app is registered here'))
$$;


--
-- Name: FUNCTION hq_slack_setup(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.hq_slack_setup() IS 'Whether Slack can actually be used, for the setup page (#210). Derived from whether the vault references RESOLVE, never from the values themselves.';


--
-- Name: hq_staff(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_staff() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'avatar_base', (
      select value #>> '{}' from public.system_config where key = 'staff.avatar_base_url'
    ),
    'staff', coalesce((
      select jsonb_agg(row_to_json(s) order by s.permanent desc, s.name) from (
        select staff_id, slug, name, title, responsibilities, expertise,
               communication_style, permanent, active, avatar_ref, prompt_version,
               (select count(*)::int from public.routing_decisions r
                 where st.slug = any (r.roster)) as jobs_convened_for
        from public.staff st
        where active
      ) s
    ), '[]'::jsonb)
  );
$$;


--
-- Name: hq_staff_hire(text, text, text, timestamp with time zone, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_staff_hire(p_name text, p_title text, p_justification text, p_expires_at timestamp with time zone, p_remit text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_slug   text;
  v_name   text := btrim(coalesce(p_name, ''));
  v_title  text := btrim(coalesce(p_title, ''));
  v_why    text := btrim(coalesce(p_justification, ''));
  v_remit  text := btrim(coalesce(p_remit, ''));
  v        jsonb;
begin
  if v_name = '' then
    return jsonb_build_object('error', 'a person needs a name');
  end if;
  if v_title = '' then
    return jsonb_build_object('error', 'say what they are here to do');
  end if;
  if v_why = '' then
    return jsonb_build_object('error', 'say why they are needed — a hire with no reason is how a team grows without anyone deciding to grow it');
  end if;
  -- The number, not just "longer". staff_temporary_is_justified wants 30.
  if length(v_why) < 30 then
    return jsonb_build_object('error', format(
      'say a little more about why — %s characters so far, and a temporary hire needs at least 30',
      length(v_why)));
  end if;
  if p_expires_at is null then
    return jsonb_build_object('error', 'say when they go — someone brought in for a piece of work needs an end');
  end if;
  if p_expires_at <= now() then
    return jsonb_build_object('error', 'that expiry is in the past');
  end if;
  if p_expires_at > now() + interval '180 days' then
    return jsonb_build_object('error', 'six months is the longest a temporary agent can be booked for — make them permanent deliberately instead');
  end if;

  v_slug := btrim(regexp_replace(lower(v_name), '[^a-z0-9]+', '-', 'g'), '-');
  if v_slug = '' then
    return jsonb_build_object('error', 'that name does not make a usable slug');
  end if;

  -- The name first: this is the check that let a second Claire through, since
  -- her slug is `chief-of-staff` and nothing derived from her name matches it.
  if exists (select 1 from public.staff where lower(btrim(name)) = lower(v_name)) then
    return jsonb_build_object('error', format('%s is already on the roster', v_name));
  end if;
  if exists (select 1 from public.staff where slug = v_slug) then
    return jsonb_build_object('error', format(
      'that name collapses onto the handle %L, which someone already has — try a fuller name', v_slug));
  end if;

  -- A real sentence, not padding to clear a length check.
  if length(v_remit) < 20 then
    v_remit := format('Brought in to work on %s, and nothing else.', v_title);
  end if;

  begin
    insert into public.staff (
      slug, name, title, permanent, active, justification, expires_at,
      responsibilities, communication_style
    )
    values (
      v_slug, v_name, v_title, false, true, v_why, p_expires_at,
      v_remit,
      'Brought in for a piece of work. Says what they found and what they could not, and stops there.'
    )
    returning jsonb_build_object(
      'slug', slug, 'name', name, 'title', title,
      'expires_at', expires_at, 'permanent', permanent
    ) into v;
  exception when check_violation then
    -- The specialist cap, in its own words. See the note above.
    return jsonb_build_object('error', SQLERRM);
  end;

  return v;
end;
$$;


--
-- Name: hq_staff_procedures(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_staff_procedures(p_slug text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'skill_id', s.skill_id,
           'name', s.name,
           'scope', s.scope::text,
           'when_to_use', s.when_to_use,
           'procedure', s.procedure,
           'version', s.version,
           'authored_by', s.authored_by,
           'tools', coalesce((
             select array_agg(st.tool order by st.tool)
               from public.skill_tools st where st.skill_id = s.skill_id
           ), array[]::text[]),
           -- How many jobs have been shown it. A procedure with a lot of use
           -- and a poor record is the one worth arguing with; one with none is
           -- just noise in the prompt.
           'uses', (select count(*)::int from public.skill_uses u where u.skill_id = s.skill_id)
         ) order by case s.scope when 'staff' then 0 else 1 end, s.created_at desc),
         '[]'::jsonb)
    from public.skills_live s
   where s.scope = 'global'
      or (s.scope = 'staff' and s.staff_slug = p_slug)
$$;


--
-- Name: FUNCTION hq_staff_procedures(p_slug text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.hq_staff_procedures(p_slug text) IS 'The written-down procedures that shape one person''s work, theirs and the team''s (#50). Named apart from `skills` on the same payload, which is staff.expertise and is routing vocabulary rather than method.';


--
-- Name: hq_staff_retire(text, boolean); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_staff_retire(p_slug text, p_active boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v jsonb;
begin
  if p_slug = 'chief-of-staff' and not p_active then
    -- Everything unaddressed routes through the Chief of Staff. Retiring them
    -- is not a smaller team, it is a team nothing reaches.
    return jsonb_build_object('error', 'the Chief of Staff cannot be retired — every unaddressed message routes through them');
  end if;
  update public.staff set active = p_active where slug = p_slug
  returning jsonb_build_object('slug', slug, 'name', name, 'active', active) into v;
  return coalesce(v, jsonb_build_object('error', format('no one called %L', p_slug)));
end;
$$;


--
-- Name: hq_staff_tool_set(text, text, boolean, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_staff_tool_set(p_slug text, p_tool text, p_granted boolean, p_by text DEFAULT 'grant'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_enabled boolean;
  v_reason  text;
  v_changed boolean;
begin
  if not exists (select 1 from public.staff where slug = p_slug) then
    return jsonb_build_object('error', format('no one called %L', p_slug));
  end if;

  select enabled, disabled_reason into v_enabled, v_reason
    from public.tool_permissions where tool = p_tool;
  if not found then
    return jsonb_build_object('error', format('there is no tool called %L', p_tool));
  end if;

  -- Refused rather than accepted-and-ignored. A checkbox that ticks and then
  -- does nothing is worse than one that refuses and says why: the first one
  -- teaches you the permission is on.
  if p_granted and not v_enabled then
    return jsonb_build_object(
      'error', format('%s is switched off for everyone: %s', p_tool, coalesce(v_reason, 'no reason recorded'))
    );
  end if;

  if p_granted then
    insert into public.staff_tools (staff_slug, tool, granted_by, note)
    values (p_slug, p_tool, p_by, 'Granted from the team page.')
    on conflict (staff_slug, tool) do nothing;
  else
    delete from public.staff_tools where staff_slug = p_slug and tool = p_tool;
  end if;
  v_changed := found;

  /*
    The ledger, in the same words the request path uses.

    `tool.granted` and `tool.revoked` are the action types already on record —
    a third spelling for the same fact would make the two doors unjoinable,
    which is what 0311 was spent undoing in a different vocabulary.
  */
  if v_changed then
    perform public.append_event(
      extensions.gen_random_uuid(), 'user', p_by, 'approval',
      case when p_granted then 'tool.granted' else 'tool.revoked' end,
      true, null,
      jsonb_build_object('held', not p_granted),
      jsonb_build_object('held', p_granted),
      format('%s %s holds %s.', p_slug,
             case when p_granted then 'now' else 'no longer' end, p_tool),
      '[]'::jsonb, null, p_tool,
      case when p_granted then 'app.revoke_tool' else 'app.hq_staff_tool_set on again' end,
      null);
  end if;

  return jsonb_build_object('slug', p_slug, 'tool', p_tool, 'granted', p_granted,
                            'changed', v_changed);
end;
$$;


--
-- Name: FUNCTION hq_staff_tool_set(p_slug text, p_tool text, p_granted boolean, p_by text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.hq_staff_tool_set(p_slug text, p_tool text, p_granted boolean, p_by text) IS 'Grant or take back one tool from one person, and record it (0472). The only writer: app.revoke_tool calls this, because the team page wrote nothing to the ledger for months while the request path recorded every change.';


--
-- Name: hq_staff_tools(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_staff_tools(p_slug text) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'tool', t.tool,
           'description', t.description,
           'level', t.level,
           'granted', st.staff_slug is not null,
           'available', t.enabled,
           'unavailable_because', t.disabled_reason
         ) order by t.level, t.tool), '[]'::jsonb)
    from public.tool_permissions t
    left join public.staff_tools st
      on st.tool = t.tool and st.staff_slug = p_slug
$$;


--
-- Name: hq_staff_update(text, text, text, text, text, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_staff_update(p_slug text, p_name text DEFAULT NULL::text, p_title text DEFAULT NULL::text, p_pronouns text DEFAULT NULL::text, p_remit text DEFAULT NULL::text, p_skills text DEFAULT NULL::text, p_style text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_skills text[];
  v_before integer;
  v        jsonb;
begin
  if not exists (select 1 from public.staff where slug = p_slug) then
    return jsonb_build_object('error', format('no one called %L', p_slug));
  end if;

  if p_name is not null and trim(p_name) ~ '\s' then
    return jsonb_build_object(
      'error', 'first names only — "' || trim(p_name) || '" has more than one word'
    );
  end if;

  select coalesce(array_length(expertise, 1), 0) into v_before
    from public.staff where slug = p_slug;

  if p_skills is not null then
    select array_agg(distinct lower(btrim(t)) order by lower(btrim(t)))
      into v_skills
      from unnest(string_to_array(p_skills, ',')) as t
     where btrim(t) <> '';

    if v_skills is null then
      -- Emptying the list is allowed; sending only commas is a typo.
      if trim(p_skills) <> '' then
        return jsonb_build_object('error', 'skills must be a comma-separated list');
      end if;
      v_skills := array[]::text[];
    end if;

    /*
      Thirty, not twelve.

      Twelve was a writing constraint — "a prompt listing thirty skills
      describes nobody" — and it was right while these words only shaped a
      voice. They now decide who Grant's request reaches, and the words he
      types ("instagram", "seo", "funnel") are not descriptions of a person.
      A bound still exists because an unbounded list is a person who matches
      everything, which is the same as nobody being chosen.
    */
    if array_length(v_skills, 1) > 30 then
      return jsonb_build_object(
        'error', 'thirty subject words is the most one person can usefully own');
    end if;
  end if;

  update public.staff
     set name       = coalesce(nullif(trim(coalesce(p_name, '')), ''), name),
         title      = coalesce(nullif(trim(coalesce(p_title, '')), ''), title),
         pronouns   = coalesce(nullif(trim(coalesce(p_pronouns, '')), ''), pronouns),
         responsibilities =
                      coalesce(nullif(trim(coalesce(p_remit, '')), ''), responsibilities),
         communication_style =
                      coalesce(nullif(trim(coalesce(p_style, '')), ''), communication_style),
         expertise  = coalesce(v_skills, expertise),
         updated_at = app.now_utc()
   where slug = p_slug
  returning jsonb_build_object(
    'slug', slug, 'name', name, 'title', title, 'pronouns', pronouns,
    'skills', expertise,
    /*
      Said out loud, because it is now consequential.

      Clearing the list makes someone unroutable — they would never be picked
      for anything again, and nothing about the page would look wrong. The
      count of what went lets the caller say so at the moment it happens.
    */
    'skills_removed', greatest(v_before - coalesce(array_length(expertise, 1), 0), 0)
  ) into v;

  return v;
end;
$$;


--
-- Name: FUNCTION hq_staff_update(p_slug text, p_name text, p_title text, p_pronouns text, p_remit text, p_skills text, p_style text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.hq_staff_update(p_slug text, p_name text, p_title text, p_pronouns text, p_remit text, p_skills text, p_style text) IS 'Edit a person. Since 0200 their skills also decide who work is routed to, so the cap is thirty rather than twelve and clearing the list reports how many words went — an unroutable specialist is invisible otherwise.';


--
-- Name: hq_store_google_refresh(text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_store_google_refresh(p_refresh_token text, p_scopes text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
begin
  if coalesce(trim(p_refresh_token), '') = '' then
    return jsonb_build_object('error', 'no refresh token');
  end if;
  perform app.store_secret('google.refresh_token', trim(p_refresh_token),
    format('Google refresh token, granted %s. Scopes: %s', app.now_utc(), p_scopes));

  insert into public.system_config (key, value, description)
  values ('google.granted_scopes', to_jsonb(p_scopes),
          'What Google actually granted, which can be less than what was asked for.')
  on conflict (key) do update set value = excluded.value;

  -- The light goes green because a token exists, not because we hope one does.
  insert into public.connection_health (service, credential, state, detail, owner, action)
  values ('google_calendar', 'oauth_client', 'ok',
          'connected — a refresh token is in the vault', 'grant', '')
  on conflict (service, credential) do update
    set state = excluded.state, detail = excluded.detail,
        action = excluded.action, checked_at = app.now_utc();

  return jsonb_build_object('stored', true);
end;
$$;


--
-- Name: hq_stranded_work(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_stranded_work() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with stuck as (
    select j.kind, count(*)::int as waiting, min(j.created_at) as oldest
      from public.jobs j
      join public.job_kind_needs n on n.kind = j.kind and n.needs_subprocess
     where j.state = 'queued'
     group by j.kind
  )
  select jsonb_build_object(
    'total', coalesce((select sum(waiting) from stuck), 0),
    'oldest', (select min(oldest) from stuck),
    'kinds', coalesce(
      (select jsonb_agg(jsonb_build_object('kind', kind, 'waiting', waiting)
                        order by waiting desc) from stuck),
      '[]'::jsonb),
    'why', 'These need a runtime that can run a local process. The only worker '
           'is a Supabase Edge Function, and Deno has none. They wait rather '
           'than fail, so they run the moment one exists.'
  );
$$;


--
-- Name: hq_studio(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_studio() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select app.hq_studio_core()
      || jsonb_build_object('contactLabels', app.contact_labels('grant'),
                            'appearance', app.hq_appearance('grant'))
$$;


--
-- Name: FUNCTION hq_studio(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.hq_studio() IS '#110. The studio payload, plus the labels Grant defined for contacts. A wrapper rather than an edit so the core function stays the one 0222 built section by section; a top-level key does not belong in its per-project CTE.';


--
-- Name: hq_studio_core(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_studio_core() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  with people as (
    select coalesce(jsonb_agg(jsonb_build_object(
             'slug', s.slug,
             'name', s.name,
             'role', s.title,
             'avatar_ref', s.avatar_ref,
             'expertise', coalesce(s.expertise, array[]::text[]),
             'state', case when j.running > 0 then 'busy' else 'idle' end,
             'doing', j.doing
           ) order by case s.slug when 'chief-of-staff' then 0 else 1 end, s.name),
           '[]'::jsonb) as v
      from public.staff s
      left join lateral (
        select count(*) as running,
               (array_agg(jj.kind order by jj.updated_at desc))[1] as doing
          from public.jobs jj
         where jj.recipient_agent = s.slug
           and jj.state in ('running', 'queued')
           and not jj.is_fixture
      ) j on true
     where s.active and s.slug not like 'fixture-%'
  ),

  projects as (
    select coalesce(jsonb_agg(t order by t.name), '[]'::jsonb) as v
      from (
        select
          p.project_id as id,
          p.slug, p.name,
          coalesce(nullif(btrim(p.purpose), ''), '') as purpose,

          coalesce((
            select array_agg(distinct app.connector_label(a.connector)
                             order by app.connector_label(a.connector))
              from public.project_attachments a
             where a.project_id = p.project_id and a.enabled
          ), array[]::text[]) as connectors,

          (select count(*)::int from public.documents d
            where d.project_id = p.project_id) as docs,
          (select count(*)::int from public.tasks tk
            where tk.project_id = p.project_id and not tk.is_fixture
              and tk.state = 'done') as done,
          (select count(*)::int from public.tasks tk
            where tk.project_id = p.project_id and not tk.is_fixture) as total,

          (select format('%s by %s', left(tk.title, 40), to_char(tk.due_on, 'FMDD Mon'))
             from public.tasks tk
            where tk.project_id = p.project_id and not tk.is_fixture
              and tk.due_on is not null and tk.state in ('todo', 'doing')
            order by tk.due_on limit 1) as next,

          app.studio_documents(p.project_id) as documents,
          app.studio_tasks(p.project_id)     as tasks,
          app.studio_sources(p.project_id)   as sources,
          app.studio_activity(p.project_id)  as activity,
          /*
            What is waiting on Grant, in the project (#151, migration 0289).

            The landing page has shown this since 0240 and a project never did,
            so the one genuinely urgent category was visible exactly where he
            could not act on it. Same view, same order — a list that disagreed
            with the banner would make "the urgent one" depend on which room he
            was standing in.
          */
          app.studio_waiting(p.project_id) as waiting,
          /*
            Real, since #71 and migration 0286. This was an honest empty literal
            because there was nowhere for a module to be written — and honest
            or not it was permanent, which is what the Issue objected to.

            It is not a new table. A module is a MILESTONE that gathers
            documents; 0286's header has the mapping and the reasoning.
          */
          app.studio_modules(p.project_id) as modules,
          -- Contacts are real now (#24, migration 0245). This was an honest
          -- empty literal because there was no table; there is one, and the
          -- function returns it in the shape the contact card already draws.
          app.studio_contacts(p.project_id) as contacts,
          -- Real work, not an empty array (0228). AI Team went honestly empty
          -- when data.js was replaced, and an empty tab because nothing was
          -- asked looks identical to one because nobody wired it.
          app.studio_requests(p.project_id) as requests,

          -- The arrangement he made, so it is his on every device (#81).
          (select l.panels from public.dashboard_layouts l
            where l.project_id = p.project_id and l.owner = 'grant') as layout,

          -- What the project LOOKS like, when he has said (#83).
          p.icon, p.icon_hue as "iconHue", p.image

        from public.projects p
        where p.status = 'active' and not p.is_fixture
      ) t
  ),

  waiting as (
    select case when n.blocker_id is null then null else jsonb_build_object(
             'what', n.requested_action,
             'who', coalesce(n.originating_agent, 'The team'),
             'when', to_char(n.created_at, 'FMDD Mon'),
             'slug', (select p.slug from public.projects p where p.project_id = n.project_id),
             'blocker', n.blocker_id,
             'note', case when n.work_can_continue
                          then 'Everything else on that project is carrying on.'
                          else 'Nothing else on that project moves until you answer.' end
           ) end as v
      from (select * from public.needs_me
             order by overdue desc, real_deadline nulls last limit 1) n
     union all select null limit 1
  )

  select jsonb_build_object(
    'crew', (select v from people),
    'projects', (select v from projects),
    'waiting', (select v from waiting),
    'avatar_base', (select value #>> '{}' from public.system_config
                     where key = 'staff.avatar_base_url'),
    'connectors', (select coalesce(jsonb_agg(jsonb_build_object(
                            'connector', k.connector,
                            'name', app.connector_label(k.connector),
                            'enabled', k.enabled
                          ) order by k.name), '[]'::jsonb)
                     from public.knowledge_connectors k),
    'health', (
      select jsonb_build_object(
        'stalled', coalesce(sum(s.n), 0),
        'kinds', coalesce(jsonb_agg(jsonb_build_object(
                   'kind', s.kind, 'n', s.n,
                   'oldest_minutes', s.oldest_minutes) order by s.n desc)
                 filter (where s.kind is not null), '[]'::jsonb))
        from app.jobs_stuck_queued() s
    ),
    'generated_at', app.now_utc()
  )
$$;


--
-- Name: FUNCTION hq_studio_core(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.hq_studio_core() IS 'Everything the studio renders, assembled from one function per section (#68). Includes the real queue per project as of 0229.';


--
-- Name: hq_studio_lately(integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_studio_lately(p_limit integer DEFAULT 40) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  with
  -- A window to summarise from, deliberately wider than the page: collapsing
  -- forty rows into eight and then showing eight is a shorter page, not a
  -- better one.
  recent as (
    select e.event_id, e.actor, e.actor_kind, e.action_type, e.rationale_summary,
           e.project_id, e.occurred_at, e.reversible, e.reversal_method,
           p.name as project_name
      from public.events e
      left join public.projects p on p.project_id = e.project_id
     where p.project_id is null or not p.is_fixture
     order by e.occurred_at desc
     limit greatest(coalesce(p_limit, 40), 1) * 10
  ),
  ranked as (
    select r.*,
           row_number() over (partition by r.actor, r.action_type, r.project_id
                              order by r.occurred_at desc) as n
      from recent r
  ),
  kept as (
    select jsonb_build_object(
             'id', k.event_id,
             'who', k.actor,
             'kind', k.actor_kind,
             'verb', app.action_in_words(k.action_type) ->> 'verb',
             'what', app.action_in_words(k.action_type) ->> 'what',
             'why', k.rationale_summary,
             'project', k.project_name,
             'when', to_char(k.occurred_at, 'FMDD Mon HH24:MI'),
             'at', k.occurred_at,
             'reversible', k.reversible,
             'undo_with', k.reversal_method
           ) as v, k.occurred_at as at
      from ranked k
     where k.n <= 2
  ),
  -- The rest of each group, as one row that says how many and when the last of
  -- them was. Placed at the newest of the ones it stands for, so it sits
  -- directly under the two that are shown rather than at the bottom of the day.
  folded as (
    select jsonb_build_object(
             'id', null,
             'who', f.actor,
             'kind', min(f.actor_kind),
             'verb', app.action_in_words(f.action_type) ->> 'verb',
             'what', app.action_in_words(f.action_type) ->> 'what',
             'why', null,
             'project', min(f.project_name),
             'when', to_char(max(f.occurred_at), 'FMDD Mon HH24:MI'),
             'at', max(f.occurred_at),
             'times', count(*)::int,
             'reversible', false,
             'undo_with', null
           ) as v, max(f.occurred_at) as at
      from ranked f
     where f.n > 2
     group by f.actor, f.action_type, f.project_id
  ),
  office as (
    select coalesce(jsonb_agg(x.v order by x.at desc), '[]'::jsonb) as v
      from (
        select v, at from kept
        union all
        select v, at from folded
        order by at desc
        limit greatest(coalesce(p_limit, 40), 1)
      ) x
  ),
  building as (select app.hq_build() as v),
  today as (
    select jsonb_build_object(
      'events', (select count(*)::int
                   from public.events e
                   left join public.projects p on p.project_id = e.project_id
                  where e.occurred_at > app.now_utc() - interval '24 hours'
                    and (p.project_id is null or not p.is_fixture)),
      'jobs_done', (select count(*)::int from public.jobs j
                     where not app.harness_job(j.job_id) and j.state = 'complete'
                       and j.updated_at > app.now_utc() - interval '24 hours'),
      'jobs_failed', (select count(*)::int from public.jobs j
                       where not app.harness_job(j.job_id) and j.state = 'failed'
                         and j.updated_at > app.now_utc() - interval '24 hours')
    ) as v
  )
  select jsonb_build_object(
    'office', (select v from office),
    'building', (select v from building),
    'today', (select v from today),
    'generated_at', app.now_utc()
  )
$$;


--
-- Name: FUNCTION hq_studio_lately(p_limit integer); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.hq_studio_lately(p_limit integer) IS 'What the office did and what is being built, as one page (#68). Reads public.events rather than job_state_transitions: four rows per job is how something happened, not what happened.';


--
-- Name: hq_studio_settings(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_studio_settings() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  with
  settable as (
    select array[
      'db.project_ref', 'db.region',
      'backup.s3_bucket', 'backup.s3_endpoint', 'backup.s3_region',
      'google.client_id', 'google.redirect_uri', 'google.scopes',
      'calendar.enabled', 'calendar.calendar_id', 'calendar.sync_tasks',
      'notebook.enabled', 'knowledge.read_new_sources',
      'notebook.window_units', 'notebook.week_units', 'notebook.sync_interval_minutes',
      'agents.max_simultaneous_jobs', 'agents.max_delegation_depth',
      'agents.max_specialists_per_job', 'agents.max_live_specialists',
      'agents.max_investigations_per_project_per_day',
      'conversation.window_minutes', 'conversation.max_turns',
      'ui.needs_me_cap', 'grant.timezone'
    ]::text[] as keys
  ),

  team as (
    select coalesce(jsonb_agg(jsonb_build_object(
             'slug', s.slug, 'name', s.name, 'role', s.title,
             'pronouns', s.pronouns, 'remit', s.responsibilities,
             'style', s.communication_style,
             'expertise', coalesce(s.expertise, array[]::text[]),
             'avatar_ref', s.avatar_ref, 'active', s.active,
             'permanent', s.permanent, 'bot', b.username,
             'tools', app.hq_staff_tools(s.slug),
             'procedures', app.hq_staff_procedures(s.slug)
           ) order by case s.slug when 'chief-of-staff' then 0 else 1 end, s.name),
           '[]'::jsonb) as v
      from public.staff s
      left join public.telegram_bots b
        on b.staff_slug = s.slug and b.enabled and not b.is_pager
     where s.slug not like 'fixture-%'
  ),

  spare_bots as (
    select coalesce(jsonb_agg(jsonb_build_object('username', b.username)
                              order by b.username), '[]'::jsonb) as v
      from public.telegram_bots b
     where b.enabled and not b.is_pager and b.staff_slug is null
  ),

  behaviours as (
    select jsonb_build_array(
      jsonb_build_object(
        'id', 'autonomy',
        'name', 'How much the team does without asking',
        'kind', 'choice',
        'value', coalesce((select a.level::text from public.autonomy_settings a
                            where a.project_id is null
                            order by a.set_at desc limit 1), 'suggest'),
        'settable', true,
        'via', 'autonomy',
        'options', app.autonomy_choices()),

      jsonb_build_object(
        'id', 'chief',
        'name', 'Only the Chief of Staff messages me',
        'kind', 'switch',
        'value', coalesce((select (value #>> '{}')::boolean from public.system_config
                            where key = 'telegram.only_chief_speaks'), true),
        'settable', true,
        'via', 'routing:only_chief_speaks',
        'note', 'Everyone else still works and still writes output. They just do not send.'),

      jsonb_build_object(
        'id', 'read_new_sources',
        'name', 'Read new sources as they appear',
        'kind', 'switch',
        'value', coalesce((select (value #>> '{}')::boolean from public.system_config
                            where key = 'knowledge.read_new_sources'), false),
        'settable', (select 'knowledge.read_new_sources' = any(keys) from settable),
        'via', 'setting:knowledge.read_new_sources',
        'note', 'A document that lands in a connected folder gets read without being asked.'),

      jsonb_build_object(
        'id', 'notebook',
        'name', 'Use NotebookLM',
        'kind', 'switch',
        'value', coalesce((select (value #>> '{}')::boolean from public.system_config
                            where key = 'notebook.enabled'), false),
        'settable', (select 'notebook.enabled' = any(keys) from settable),
        'via', 'setting:notebook.enabled',
        'note', 'Reading and writing notebooks, and the audio overviews.'),

      -- Tasks into the diary (#94, ADR-0020). Off until he turns it on:
      -- writing into a real calendar is not something to begin because a
      -- feature shipped. The duty is already scheduled and already checks this
      -- switch before calling Google once, so turning it on here starts it
      -- working within the hour with nothing else to do.
      jsonb_build_object(
        'id', 'calendar_tasks',
        'name', 'Put dated tasks in my Google Calendar',
        'kind', 'switch',
        'value', coalesce((select (value #>> '{}')::boolean from public.system_config
                            where key = 'calendar.sync_tasks'), false),
        'settable', (select 'calendar.sync_tasks' = any(keys) from settable),
        'via', 'setting:calendar.sync_tasks',
        'note', 'One way only. A task with a due date becomes an all-day event and '
                'comes away when it is done. The diary never changes a task, and '
                'nothing that the office did not create is ever touched.'),

      jsonb_build_object(
        'id', 'browser', 'name', 'Agents may drive a browser',
        'kind', 'switch', 'value', false, 'settable', false,
        'note', 'Not built yet — tracked as issue 16. Shown because it is coming, '
                'and off because nothing can do it.'),

      jsonb_build_object(
        'id', 'undo', 'name', 'Keep everything undoable',
        'kind', 'switch', 'value', true, 'settable', false,
        'note', 'Always on. The ledger is append-only by design, so this is a '
                'statement of how the office works rather than a choice.')
    ) as v
  ),

  connections as (
    select coalesce(jsonb_agg(jsonb_build_object(
             'key', k.connector,
             'name', coalesce(nullif(k.name, ''), app.connector_label(k.connector)),
             'state', case
               when not k.enabled then 'off'
               when k.health_service is null then 'unchecked'
               else coalesce(h.state, 'unchecked') end,
             'last', case when h.checked_at is null then ''
                          else to_char(h.checked_at, 'FMDD Mon HH24:MI') end,
             -- What it is FOR, in one line. `notes` is engineering reasoning
             -- and belongs to the engineer; see 0226.
             'used', coalesce(nullif(app.connector_purpose(k.connector), ''),
                              left(coalesce(k.notes, ''), 90)),
             'detail', coalesce(
               case when not k.enabled then k.disabled_reason else h.detail end, ''),
             'action', h.action
           ) order by k.name), '[]'::jsonb) as v
      from public.knowledge_connectors k
      left join lateral (
        select ch.state, ch.detail, ch.checked_at, ch.action
          from public.connection_health ch
         where ch.service = k.health_service
         order by case ch.state
                    when 'dead' then 0 when 'missing' then 1
                    when 'unknown' then 2 when 'ok' then 3 else 4 end
         limit 1
      ) h on true
     -- A harness connector is not one of Grant's (0505). Filtered by the
     -- CLASS rather than by a run's names: the next crashed suite picks a
     -- prefix nobody listed, and five of these sat on his Connections page
     -- for two days because nothing was looking.
     where k.connector not like 'fixture\_%'
  ),

  channels as (
    select coalesce(jsonb_agg(jsonb_build_object(
             'key', c.key, 'name', c.name, 'role', c.role,
             'state', case
               when h.state is null then 'unchecked'
               when h.state in ('dead', 'missing') then 'degraded'
               when h.state = 'attested' then 'ok'
               else h.state end,
             'detail', coalesce(h.detail, c.fallback),
             /*
               What this channel actually is, and what governs it (#93).

               The cards were read-only: a name, a role and a state, with
               nothing to press. Grant asked for each entry to open something
               that works, and for Telegram the two things that matter are
               settings nobody could see -- `telegram.only_chief_speaks`, which
               is the single most consequential switch in the office, and
               `telegram.direct_to_grant`, which is a DIFFERENT setting that is
               routinely confused with it.

               `who` lists the bots, and since #70 that list is the decision
               made visible: one enabled bot, the chief of staff's, and seven
               shown with `on: false` beside whose they were. Grant, 13
               September: "we don't need a different bot for each role. In
               fact, we only need the chief of staff."

               This comment used to say the opposite — that #70 was VISIBLE
               here as a live defect, the chief having no row while
               staff.telegram_username claimed she had one. 0352 settled it:
               the pager is hers, the mirror is no longer read, and the two
               tables agree. Left as a correction rather than deleted, because
               a comment describing a fixed defect as current is the same
               failure as a comment claiming a property nothing checks.
             */
             'who', case c.key when 'telegram' then (
                 select coalesce(jsonb_agg(jsonb_build_object(
                          'username', b.username,
                          'whose', coalesce(s.name, case when b.is_pager then 'The pager' else 'Nobody' end),
                          'pager', b.is_pager,
                          'on', b.enabled
                        ) order by b.is_pager desc, s.name nulls last), '[]'::jsonb)
                   from public.telegram_bots b
                   left join public.staff s on s.slug = b.staff_slug)
               else '[]'::jsonb end,
             'settings', case c.key
               when 'telegram' then jsonb_build_array(
                 jsonb_build_object(
                   'key', 'telegram.direct_to_grant',
                   'name', 'Whose bot may use your private chat',
                   'kind', 'text',
                   'value', coalesce((select value #>> '{}' from public.system_config
                                       where key = 'telegram.direct_to_grant'), ''),
                   'note', 'A staff slug, or empty to let everyone message you directly. This decides WHICH CHAT someone lands in. It is NOT the same as "Only the Chief of Staff messages me" on the Behaviour tab, which decides WHO SENDS AT ALL.'),
                 jsonb_build_object(
                   'key', 'telegram.only_chief_speaks',
                   'name', 'Only the Chief of Staff messages me',
                   'kind', 'switch',
                   'value', coalesce((select (value #>> '{}')::boolean from public.system_config
                                       where key = 'telegram.only_chief_speaks'), false),
                   'note', 'Changed on the Behaviour tab. Shown here because these two are read together, and separating them is how they get confused.'))
               else '[]'::jsonb end,
             -- Explicit, with the real handles in it. Section 25 and his
             -- standing instruction: full instructions every time, never
             -- "you know the one".
             'steps', case c.key
               when 'telegram' then 'Open Telegram and message the bot named in "Who" below. It answers as Claire. A thumbs up or down on any reply teaches the office something.'
               when 'slack' then 'The office posts to one channel per dashboard project, plus a queue channel. Reacting with a thumbs up or down is read as feedback.'
               when 'voice' then 'Press "Call the team" in the sidebar. The browser asks for the microphone once. Talk over her whenever you like.'
               when 'mail' then 'Read only. The office can search and draft, and cannot send: section 11 keeps sending off by policy whatever the permission allows.'
               else '' end
           ) order by c.sort), '[]'::jsonb) as v
      from (values
        ('telegram', 'Telegram', 'Claire, and the pager', 'Telegram', 1,
         'Decisions buzz. Everything else is silent.'),
        ('slack', 'Slack', 'The office floor', 'Slack', 2,
         'One channel per project, plus the queue.'),
        ('voice', 'Voice', 'Calling the team', 'OpenAI', 3,
         'Claire, with the whole office behind her.'),
        ('mail', 'Email', 'Inbound only', 'Google', 4,
         'Read, not sent. Sending needs your say-so.')
      ) as c(key, name, role, service, sort, fallback)
      left join lateral (
        select ch.state, ch.detail from public.connection_health ch
         where ch.service = c.service
         order by case ch.state
                    when 'dead' then 0 when 'missing' then 1
                    when 'unknown' then 2 when 'ok' then 3 else 4 end
         limit 1
      ) h on true
  )

  select jsonb_build_object(
    'team', (select v from team),
    'spare_bots', (select v from spare_bots),
    'behaviours', (select v from behaviours),
    'connections', (select v from connections),
    -- What of Grant's correspondence the office is holding the WORDS of
    -- (#172, ADR-0038). Beside the credential that makes it possible,
    -- because the Connections pane is where he would go to stop it. An
    -- authorisation with nothing showing what it produced is a setting
    -- with no reader, which is #15's defect on the most personal corpus
    -- the office holds.
    'mail_bodies', app.mail_bodies_held(),
    'channels', (select v from channels),
    'usage', app.usage_overview(),
    'headroom', app.free_tier_headroom(),
    'self_improvement', app.self_improvement_headroom(),
    'generated_at', app.now_utc()
  )
$$;


--
-- Name: FUNCTION hq_studio_settings(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.hq_studio_settings() IS 'Everything the studio Settings viewer renders, in the shapes settings.js already exports (#68). Each behaviour carries `settable`, read from the same allow-list hq_set_setting enforces, so a control is never offered for something the API will refuse.';


--
-- Name: hq_task_add(text, text, text, date, text, boolean); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_task_add(p_project text, p_title text, p_detail text DEFAULT NULL::text, p_due_on date DEFAULT NULL::date, p_assignee text DEFAULT NULL::text, p_milestone boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_project uuid;
begin
  if coalesce(btrim(p_project), '') <> '' then
    select project_id into v_project
      from public.projects
     where slug = btrim(p_project)
       and coalesce(status, '') <> 'archived'
       and not is_fixture;
    if v_project is null then
      return jsonb_build_object('error', format('no dashboard project called %L', p_project));
    end if;
  end if;

  return app.task_add(v_project, p_title, p_detail, p_due_on, p_assignee, p_milestone);
end;
$$;


--
-- Name: hq_task_state(text, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_task_state(p_task_id text, p_state text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_id       uuid;
  v          jsonb;
  v_was      text;
  v_was_why  text;
  v_title    text;
  v_undo     uuid;
begin
  begin
    v_id := p_task_id::uuid;
  exception when others then
    return jsonb_build_object('error', 'that is not a task id');
  end;

  if p_state not in ('todo', 'doing', 'blocked', 'done', 'cancelled') then
    return jsonb_build_object('error', format(
      '%L is not a state — it is one of todo, doing, blocked, done, cancelled', p_state));
  end if;

  -- blocked_needs_a_reason. Said here, with the reason why, rather than
  -- arriving as a constraint name.
  if p_state = 'blocked' and coalesce(btrim(p_reason), '') = '' then
    return jsonb_build_object('error',
      'say what it is blocked on — a blocked task with no reason cannot be unblocked by anyone but the person who blocked it');
  end if;

  select state, blocked_on, title into v_was, v_was_why, v_title
    from public.tasks where task_id = v_id;
  if v_was is null then
    return jsonb_build_object('error', 'no such task');
  end if;

  /*
    done_at moves with the state, in both directions.

    `(state = 'done') = (done_at is not null)` is a check constraint, so
    marking done without a timestamp fails AND so does re-opening a done task
    without clearing one. Handling only the first is the bug that looks fixed.
  */
  update public.tasks
     set state      = p_state,
         done_at    = case when p_state = 'done' then coalesce(done_at, app.now_utc()) else null end,
         blocked_on = case when p_state = 'blocked' then btrim(p_reason) else '' end
   where task_id = v_id
  returning jsonb_build_object('id', task_id, 'title', title, 'state', state) into v;

  if p_state is distinct from v_was then
    v_undo := app.undo_offer(
      'task.state',
      format('%s marked %s', left(v_title, 60), p_state),
      jsonb_build_object('action', 'task_state',
                         'args', jsonb_build_object(
                           'p_task_id', p_task_id, 'p_state', v_was,
                           'p_reason', nullif(v_was_why, ''))));
  end if;

  return coalesce(v, jsonb_build_object('error', 'no such task')) || jsonb_build_object('undo', v_undo);
end;
$$;


--
-- Name: hq_task_update(text, text, text, date, date, text, text, boolean, integer, text[]); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_task_update(p_task_id text, p_title text DEFAULT NULL::text, p_detail text DEFAULT NULL::text, p_due_on date DEFAULT NULL::date, p_starts_on date DEFAULT NULL::date, p_assignee text DEFAULT NULL::text, p_parent text DEFAULT NULL::text, p_milestone boolean DEFAULT NULL::boolean, p_priority integer DEFAULT NULL::integer, p_clear text[] DEFAULT ARRAY[]::text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_id      uuid;
  v_project uuid;
  v_found   boolean;
  v_staff   uuid;
  v_parent  uuid;
  v_title   text;
  v         jsonb;
  v_was     record;
  v_back    jsonb;
  v_clear   text[] := array[]::text[];
  v_undo    uuid;
begin
  begin
    v_id := p_task_id::uuid;
  exception when others then
    return jsonb_build_object('error', format('%L is not a task id', p_task_id));
  end;

  -- Existence and project are now two questions, not one: a task legitimately
  -- has no project, so a null project_id no longer means "no such task".
  select true, t.project_id into v_found, v_project
    from public.tasks t where t.task_id = v_id;
  if not coalesce(v_found, false) then
    return jsonb_build_object('error', 'no task with that id');
  end if;

  if p_title is not null then
    v_title := btrim(p_title);
    if v_title = '' then
      return jsonb_build_object('error', 'a task needs a title -- rename it to something, or leave it');
    end if;
  end if;

  if coalesce(btrim(p_assignee), '') <> '' then
    select staff_id into v_staff from public.staff where slug = btrim(p_assignee);
    if v_staff is null then
      return jsonb_build_object('error', format('nobody here is called %L', btrim(p_assignee)));
    end if;
  end if;

  if coalesce(btrim(p_parent), '') <> '' then
    begin
      v_parent := btrim(p_parent)::uuid;
    exception when others then
      return jsonb_build_object('error', format('%L is not a task id', p_parent));
    end;
    if v_parent = v_id then
      return jsonb_build_object('error', 'a task cannot be its own parent');
    end if;
    if not exists (select 1 from public.tasks where task_id = v_parent
                    and project_id is not distinct from v_project) then
      return jsonb_build_object('error',
        case when v_project is null
             then 'that parent belongs to a project and this task does not'
             else 'that parent is not a task on the same dashboard project' end);
    end if;
    -- The cycle. A -> B -> A is invisible to a single-level comparison, so
    -- walk the proposed parent's own ancestry and refuse if this task is in it.
    if exists (
      with recursive up as (
        select task_id, parent_task_id from public.tasks where task_id = v_parent
        union all
        select t.task_id, t.parent_task_id
          from public.tasks t join up on t.task_id = up.parent_task_id
      )
      select 1 from up where task_id = v_id
    ) then
      return jsonb_build_object('error',
        'that would make a loop -- the task you picked is already under this one');
    end if;
  end if;

  select t.title, t.detail, t.due_on, t.starts_on, t.parent_task_id,
         t.is_milestone, t.priority,
         (select s.slug from public.staff s where s.staff_id = t.assignee_staff) as assignee
    into v_was
    from public.tasks t where t.task_id = v_id;

  update public.tasks
     set title             = coalesce(v_title, title),
         detail            = case when 'detail' = any(p_clear) then ''
                                  else coalesce(btrim(p_detail), detail) end,
         due_on            = case when 'due_on' = any(p_clear) then null
                                  else coalesce(p_due_on, due_on) end,
         starts_on         = case when 'starts_on' = any(p_clear) then null
                                  else coalesce(p_starts_on, starts_on) end,
         assignee_staff    = case when 'assignee' = any(p_clear) then null
                                  else coalesce(v_staff, assignee_staff) end,
         parent_task_id    = case when 'parent' = any(p_clear) then null
                                  else coalesce(v_parent, parent_task_id) end,
         is_milestone      = coalesce(p_milestone, is_milestone),
         priority          = coalesce(p_priority, priority),
         updated_at        = app.now_utc()
   where task_id = v_id;

  if coalesce(v_was.detail, '') = '' then v_clear := array_append(v_clear, 'detail'); end if;
  if v_was.due_on     is null   then v_clear := array_append(v_clear, 'due_on'); end if;
  if v_was.starts_on  is null   then v_clear := array_append(v_clear, 'starts_on'); end if;
  if v_was.assignee   is null   then v_clear := array_append(v_clear, 'assignee'); end if;
  if v_was.parent_task_id is null then v_clear := array_append(v_clear, 'parent'); end if;

  v_back := jsonb_build_object(
    'p_task_id',   p_task_id,
    'p_title',     v_was.title,
    'p_detail',    nullif(coalesce(v_was.detail, ''), ''),
    'p_due_on',    v_was.due_on,
    'p_starts_on', v_was.starts_on,
    'p_assignee',  v_was.assignee,
    'p_parent',    v_was.parent_task_id,
    'p_milestone', v_was.is_milestone,
    'p_priority',  v_was.priority,
    'p_clear',     to_jsonb(v_clear));

  v_undo := app.undo_offer(
    'task.update',
    format('Edited %s', left(v_was.title, 60)),
    jsonb_build_object('action', 'task_update', 'args', v_back));

  select jsonb_build_object(
           'id', t.task_id, 'title', t.title, 'detail', t.detail,
           'state', t.state, 'due_on', t.due_on, 'starts_on', t.starts_on,
           'milestone', t.is_milestone, 'priority', t.priority,
           'parent', t.parent_task_id, 'undo', v_undo,
           'assignee', (select s.slug from public.staff s where s.staff_id = t.assignee_staff)
         )
    into v
    from public.tasks t where t.task_id = v_id;
  return v;
end;
$$;


--
-- Name: hq_team(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_team() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select jsonb_build_object(
    'bots', (app.hq_bots() -> 'bots'),
    'avatar_base', (
      select value #>> '{}' from public.system_config where key = 'staff.avatar_base_url'
    ),
    'staff', coalesce((
      select jsonb_agg(t order by t.sort, t.name)
        from (
          select s.slug, s.name, s.title, s.pronouns, s.responsibilities,
                 -- #70, 0352: from the registry rather than from the copy of it
                 -- on this row. `enabled` is the point — a person whose bot has
                 -- been retired has no bot, and saying otherwise is the
                 -- disagreement this Issue was opened about.
                 (select b.username from public.telegram_bots b
                   where b.staff_slug = s.slug and b.enabled
                   limit 1) as telegram_username,
                 s.avatar_ref, s.active, s.permanent,
                 s.prompt_version,
                 coalesce(s.expertise, array[]::text[]) as skills,
                 s.communication_style,
                 app.hq_staff_tools(s.slug) as tools,
                 -- How they work, as opposed to what they know about.
                 app.hq_staff_procedures(s.slug) as procedures,
                 case s.slug when 'chief-of-staff' then 0 else 1 end as sort,
                 (select count(*)::int
                    from public.routing_decisions r
                   where r.roster[1] = s.slug) as convened_for
            from public.staff s
           where s.slug not like 'fixture-%'
        ) t
    ), '[]'::jsonb)
  )
$$;


--
-- Name: FUNCTION hq_team(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.hq_team() IS 'The roster as the front end edits it: names, titles, pronouns, remits, skills, per-person tool grants, bot links, and the avatar host. Retired people included, because a page that hides them offers no way to bring one back.';


--
-- Name: hq_undo(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_undo(p_action_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_id       uuid;
  v_action   public.undoable_actions;
  v_outcome  public.undo_status;
  v_args     jsonb;
  v_did      jsonb;
begin
  begin
    v_id := p_action_id::uuid;
  exception when others then
    return jsonb_build_object('error', 'that is not an action id');
  end;

  select * into v_action from public.undoable_actions where action_id = v_id;
  if not found then
    return jsonb_build_object('error', 'there is nothing here to undo');
  end if;

  v_outcome := app.request_undo(v_id, 'grant', 'studio');

  if v_outcome <> 'undone' then
    -- Not a failure. A lapsed offer and an already-undone action are both
    -- normal, and both need words the page can show without alarm.
    return jsonb_build_object('ok', false, 'outcome', v_outcome,
      'note', case v_outcome
        when 'expired'      then 'That offer has lapsed.'
        when 'not_undoable' then 'That one cannot be undone.'
        else 'Already undone.' end);
  end if;

  /*
    From here on we are performing the reversal, and nothing it calls may
    record an undo of its own. Transaction-local, so it lifts by itself.
  */
  perform set_config('app.undoing', '1', true);

  v_args := v_action.reversal -> 'args';
  case v_action.reversal ->> 'action'
    when 'rename_project' then
      v_did := app.hq_rename_project(v_args ->> 'p_slug', v_args ->> 'p_name');
    when 'task_state' then
      v_did := app.hq_task_state(v_args ->> 'p_task_id', v_args ->> 'p_state',
                                 v_args ->> 'p_reason');
    when 'task_update' then
      v_did := app.hq_task_update(
        v_args ->> 'p_task_id', v_args ->> 'p_title', v_args ->> 'p_detail',
        (v_args ->> 'p_due_on')::date, (v_args ->> 'p_starts_on')::date,
        v_args ->> 'p_assignee', v_args ->> 'p_parent',
        (v_args ->> 'p_milestone')::boolean, (v_args ->> 'p_priority')::int,
        coalesce(
          (select array_agg(x #>> '{}') from jsonb_array_elements(v_args -> 'p_clear') x),
          array[]::text[]));
    when 'project_look' then
      v_did := app.hq_project_look(
        v_args ->> 'p_slug', v_args ->> 'p_icon', v_args ->> 'p_hue', null,
        coalesce(
          (select array_agg(x #>> '{}') from jsonb_array_elements(v_args -> 'p_clear') x),
          array[]::text[]));
    when 'dashboard_layout_set' then
      v_did := app.hq_dashboard_layout_set(v_args ->> 'p_slug', v_args -> 'p_panels');
    when 'dashboard_layout_reset' then
      v_did := app.hq_dashboard_layout_reset(v_args ->> 'p_slug');
    when 'unarchive_project' then
      v_did := app.unarchive_project(v_args ->> 'p_slug');
    when 'reattach' then
      v_did := app.hq_reattach((v_args ->> 'p_attachment_id')::uuid, v_args ->> 'p_reason');
    -- #110, migration 0285.
    when 'contact_label_rename' then
      v_did := app.hq_contact_label_rename((v_args ->> 'p_label_id')::uuid,
                                           v_args ->> 'p_name');
    when 'contact_labels_set' then
      v_did := app.hq_contact_labels_set((v_args ->> 'p_contact_id')::uuid,
                                         v_args -> 'p_labels');
    when 'contact_fields_set' then
      v_did := app.hq_contact_fields_set((v_args ->> 'p_contact_id')::uuid,
                                         v_args -> 'p_fields');
    -- #130, migration 0398.
    when 'tasks_from_job' then
      v_did := app.undo_tasks_from_job((v_args ->> 'p_job')::uuid);
    else
      -- A reversal naming something this function cannot perform is a bug in
      -- whoever recorded it, and raising rolls back the claim so the offer is
      -- not silently consumed.
      raise exception 'no way to perform the reversal %', v_action.reversal ->> 'action'
        using errcode = 'feature_not_supported';
  end case;

  /*
    The inner RPCs answer a refusal as `{"error": ...}` rather than raising.
    Left alone, that would leave the action marked undone with nothing
    reversed — the worst outcome available, because the interface would say it
    worked. Raise, so the claim rolls back with it and the offer survives.
  */
  if v_did ? 'error' then
    raise exception 'could not undo: %', v_did ->> 'error'
      using errcode = 'raise_exception';
  end if;

  return jsonb_build_object('ok', true, 'outcome', 'undone',
    'kind', v_action.kind, 'note', format('Undone — %s', v_action.description));
end;
$$;


--
-- Name: FUNCTION hq_undo(p_action_id text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.hq_undo(p_action_id text) IS 'Performs the exact inverse recorded when the action happened. Raises if the reversal fails, so the claim rolls back with it: either the world moved back and the row says undone, or neither did.';


--
-- Name: hq_usage(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_usage() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'inference', jsonb_build_object(
      'provenance', 'measured',
      'note', 'Every inference attempt is recorded locally, successes and failures alike.',
      'calls_30d', (
        select count(*)::int from public.inference_usage
        where occurred_at > app.now_utc() - interval '30 days'
      ),
      'cost_usd_30d', (
        select coalesce(sum(cost_usd), 0)::numeric(12,6) from public.inference_usage
        where occurred_at > app.now_utc() - interval '30 days'
      ),
      'by_outcome', coalesce((
        select jsonb_object_agg(outcome, n) from (
          select outcome::text as outcome, count(*)::int as n
          from public.inference_usage
          where occurred_at > app.now_utc() - interval '30 days'
          group by 1
        ) o
      ), '{}'::jsonb)
    ),
    'tts', jsonb_build_object(
      'provenance', 'measured',
      'note', 'Counted by us: Google exposes no live counter for Chirp 3.',
      'characters_this_month', app.tts_characters_this_month('google.chirp3-hd'),
      'monthly_free_allowance', 1000000
    ),
    'notebook', jsonb_build_object(
      -- The important one. There is no API for this and there never was; the
      -- figures come from a capability probe, and calling them anything but
      -- estimated would be the exact misrepresentation §11 forbids.
      'provenance', 'estimated',
      'note', 'Notebook publishes no usage counters. These are inferred from a capability probe and may be wrong.',
      'detected_tier', (select detected_tier from public.notebook_budget),
      'notebook_limit', (select notebook_limit from public.notebook_budget),
      'source_limit', (select source_limit from public.notebook_budget),
      'daily_chat_budget', (select daily_chat_budget from public.notebook_budget),
      'computed_at', (select computed_at from public.notebook_budget)
    ),
    'queue', jsonb_build_object(
      'provenance', 'measured',
      'max_concurrent', app.capacity_limit('max_concurrent_jobs', 3),
      'in_flight', (
        select count(*)::int from public.jobs
        where state not in ('complete', 'cancelled', 'failed')
      )
    ),
    'delivery', coalesce((
      select jsonb_agg(row_to_json(d)) from (
        select channel, state, deliveries, needed_more_than_one_attempt, leases_expired
        from public.delivery_health
      ) d
    ), '[]'::jsonb),
    'models', coalesce((
      -- Explicitly WITHOUT secret_ref and base_url. A secret reference is not a
      -- secret, and it is still not something a dashboard needs.
      select jsonb_agg(row_to_json(m)) from (
        select provider, model_id, priority, last_success_at
        from public.usable_models
        order by priority, provider
      ) m
    ), '[]'::jsonb)
  );
$$;


--
-- Name: hq_workspace_layout(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_workspace_layout() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select jsonb_build_object(
    'panels', (select panels from public.workspace_layouts where owner = 'grant'),
    'at',     (select updated_at from public.workspace_layouts where owner = 'grant')
  );
$$;


--
-- Name: hq_workspace_layout_reset(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_workspace_layout_reset() RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  with gone as (delete from public.workspace_layouts where owner = 'grant' returning 1)
  select jsonb_build_object('ok', true, 'removed', (select count(*) from gone));
$$;


--
-- Name: hq_workspace_layout_set(jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.hq_workspace_layout_set(p_panels jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_bad int;
begin
  if jsonb_typeof(p_panels) <> 'array' then
    return jsonb_build_object('error', 'panels must be an array');
  end if;

  if jsonb_array_length(p_panels) = 0 then
    delete from public.workspace_layouts where owner = 'grant';
    return jsonb_build_object('ok', true, 'panels', 0,
      'note', 'the home screen was emptied, so it is back to its default');
  end if;

  select count(*) into v_bad
    from jsonb_array_elements(p_panels) e
   where jsonb_typeof(e) <> 'object'
      or jsonb_typeof(e -> 'id') <> 'string'
      or jsonb_typeof(e -> 'x') <> 'number'
      or jsonb_typeof(e -> 'y') <> 'number'
      or jsonb_typeof(e -> 'w') <> 'number'
      or jsonb_typeof(e -> 'h') <> 'number';
  if v_bad > 0 then
    return jsonb_build_object('error',
      format('%s panel(s) are not {id, x, y, w, h} -- nothing was saved', v_bad));
  end if;

  insert into public.workspace_layouts (owner, panels, updated_at)
  values ('grant', p_panels, now())
  on conflict (owner)
    do update set panels = excluded.panels, updated_at = now();

  return jsonb_build_object('ok', true, 'panels', jsonb_array_length(p_panels));
end;
$$;


--
-- Name: icon_for_name(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.icon_for_name(p_name text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select d.icon
    from public.icon_defaults d
   where lower(coalesce(p_name, '')) ~ ('\y' || d.term || '\y')
   order by length(d.term) desc, d.term
   limit 1
$$;


--
-- Name: FUNCTION icon_for_name(p_name text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.icon_for_name(p_name text) IS 'A mark that fits the name, or null. Never a random one. #221';


