-- Name: icon_key_ok(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.icon_key_ok(p_key text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$ select p_key is null or p_key ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and length(p_key) between 2 and 40 $_$;


--
-- Name: FUNCTION icon_key_ok(p_key text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.icon_key_ok(p_key text) IS 'The SHAPE of an icon key, never a list of them. #221';


--
-- Name: impediment_inherits_fixture(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.impediment_inherits_fixture() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  -- The caller does not get a say. Harness traffic must not be able to present
  -- itself as the office struggling, whatever it passes.
  select j.is_fixture into new.is_fixture
    from public.jobs j where j.job_id = new.job_id;
  new.is_fixture := coalesce(new.is_fixture, false);
  return new;
end;
$$;


--
-- Name: FUNCTION impediment_inherits_fixture(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.impediment_inherits_fixture() IS 'Copies jobs.is_fixture onto the impediment, overriding the caller. A GENERATED column cannot read another table, so this is how the same guarantee is reached.';


--
-- Name: impediments_tally(integer, integer, boolean); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.impediments_tally(p_days integer DEFAULT 30, p_min integer DEFAULT 2, p_include_fixtures boolean DEFAULT false) RETURNS TABLE(kind public.impediment_kind, needed text, staff_slug text, times integer, first_seen timestamp with time zone, last_seen timestamp with time zone, projects integer, for_instance text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select i.kind,
         i.needed,
         i.staff_slug,
         count(*)::int                        as times,
         min(i.created_at)                    as first_seen,
         max(i.created_at)                    as last_seen,
         count(distinct i.project_id)::int    as projects,
         (array_agg(i.detail order by i.created_at desc)
            filter (where btrim(i.detail) <> ''))[1] as for_instance
    from public.job_impediments i
    left join public.jobs j on j.job_id = i.job_id
   where (
           coalesce(p_include_fixtures, false)
           -- Either witness may exclude; neither may include. See the header.
           or not (coalesce(j.is_fixture, false) or i.is_fixture)
         )
     and i.created_at >= app.now_utc() - make_interval(days => greatest(coalesce(p_days, 30), 1))
   group by i.kind, i.needed, i.staff_slug
  having count(*) >= greatest(coalesce(p_min, 2), 1)
   order by count(*) desc, max(i.created_at) desc
$$;


--
-- Name: FUNCTION impediments_tally(p_days integer, p_min integer, p_include_fixtures boolean); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.impediments_tally(p_days integer, p_min integer, p_include_fixtures boolean) IS 'What the office tried and could not do (#49), read by the Governance tab (#54). A row is harness traffic if EITHER the job says so (generated, always current) or the ledger copy says so (frozen at insert by §6, correctable never). Each witness can only exclude, never include — 0304, after 0303 used coalesce and let two probe rows back onto the page it was written to clear.';


--
-- Name: import_output(uuid, text, text[], uuid, uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.import_output(p_output uuid, p_collection text DEFAULT NULL::text, p_tags text[] DEFAULT NULL::text[], p_related_task uuid DEFAULT NULL::uuid, p_related_source uuid DEFAULT NULL::uuid, p_title text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  o          record;
  v_project  uuid;
  v_author   text;
  v_title    text;
  v_document uuid;
  v_meta     jsonb;
  v_declared jsonb;
  v_tags     text[];
  v_collection text;
begin
  select oo.output_id, oo.body, oo.job_id, oo.staff_id, oo.reviewer_status,
         oo.shape, oo.facts
    into o
    from public.outputs oo where oo.output_id = p_output;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'no such output');
  end if;
  if coalesce(btrim(o.body), '') = '' then
    return jsonb_build_object('ok', false, 'error', 'that output has no text to import');
  end if;

  select j.project_id into v_project from public.jobs j where j.job_id = o.job_id;
  if v_project is null then
    return jsonb_build_object('ok', false, 'error', 'that output is not attached to a project');
  end if;

  select s.slug into v_author from public.staff s where s.staff_id = o.staff_id;

  /*
    What the output said about itself, if anything. Guarded on the shape being
    one the registry knows AND the facts being an object: a shape naming
    something that is not declared cannot be trusted to carry the keys it
    would imply, and 0272's trigger means such a row should not exist anyway.
  */
  v_declared := case
    when o.shape is not null
     and jsonb_typeof(coalesce(o.facts, 'null'::jsonb)) = 'object'
     and exists (select 1 from public.output_shapes s where s.shape = o.shape)
    then o.facts
    else '{}'::jsonb
  end;

  v_title := coalesce(
    nullif(btrim(coalesce(p_title, '')), ''),
    nullif(btrim(coalesce(v_declared ->> 'title', '')), ''),
    nullif(btrim(split_part(o.body, E'\n', 1)), ''),
    'Untitled');
  v_title := left(v_title, 200);

  /*
    Tags the same way. `array_length` rather than `= '{}'`, because the sheet
    sends an empty array when the box is left alone and that means "none
    given", not "none wanted".
  */
  v_tags := case
    when p_tags is not null and coalesce(array_length(p_tags, 1), 0) > 0 then p_tags
    when jsonb_typeof(v_declared -> 'tags') = 'array'
      then (select array_agg(btrim(t)) from jsonb_array_elements_text(v_declared -> 'tags') t
             where btrim(t) <> '')
    else p_tags
  end;

  -- And the collection, in the same order: the sheet, then what the output
  -- suggested about itself, then nothing.
  v_collection := coalesce(
    nullif(btrim(coalesce(p_collection, '')), ''),
    nullif(btrim(coalesce(v_declared ->> 'suggested_collection', '')), ''));

  insert into public.documents
    (project_id, connector, external_parent_ref, external_ref, title, doc_type, content,
     content_fingerprint, content_chars, fetched_at, origin, state,
     produced_by, produced_by_job)
  values (v_project, 'upload', null, format('output:%s', p_output), v_title, 'note', o.body,
          encode(extensions.digest(o.body, 'sha256'), 'hex'), length(o.body),
          app.now_utc(), 'made', 'draft',
          coalesce(v_author, ''), o.job_id)
  on conflict (project_id, external_ref) where external_ref like 'output:%'
  do update set title = excluded.title
  returning document_id into v_document;

  /*
    Everything after the document goes through `app.approve_document`, exactly
    as it did before — the collection, the tags and the two relations keep
    their own refusals, and this function keeps having one place where a
    document becomes part of the project.

    The first draft of 0417 rewrote this half from memory and invented
    `a file_in_collection`, `a tag_document taking a uuid and text` and a relate
    with a signature nothing has. It failed on the first real run, which is the
    cheap direction — CLAUDE.md's rule about guessing names, applied to
    functions rather than columns.
  */
  v_meta := app.approve_document(v_document, v_collection, v_tags, p_related_task,
                                 p_related_source);
  if coalesce((v_meta->>'ok')::boolean, false) is not true then
    return jsonb_build_object('ok', false, 'document', v_document,
                              'error', v_meta->>'error');
  end if;

  update public.outputs
     set reviewer_status = 'approved', reviewed_by = null, reviewed_at = app.now_utc()
   where output_id = p_output;

  return jsonb_build_object(
    'ok', true, 'document', v_document, 'title', v_title,
    -- Whether the title came from what the output DECLARED rather than from
    -- its first line, so #130's gain is visible rather than inferred.
    'title_from_structure', v_declared ? 'title',
    'collection', v_meta->'collection', 'tags', v_meta->'tags', 'source', v_meta->'source');
end;
$$;


--
-- Name: FUNCTION import_output(p_output uuid, p_collection text, p_tags text[], p_related_task uuid, p_related_source uuid, p_title text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.import_output(p_output uuid, p_collection text, p_tags text[], p_related_task uuid, p_related_source uuid, p_title text) IS '#28. Where an agent OUTPUT becomes a project DOCUMENT — the step the specification draws as its own box. Provenance (produced_by, produced_by_job) comes from the output rather than from a parameter, so it cannot be passed wrongly, and the job and agent edges are then DERIVED rather than stored, which is what makes them unremovable. 0317.';


--
-- Name: inbound_addressed_also_is_real(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.inbound_addressed_also_is_real() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare v_clean text[];
begin
  if new.addressed_also is null or cardinality(new.addressed_also) = 0 then
    new.addressed_also := '{}';
    return new;
  end if;

  select coalesce(array_agg(distinct s.slug order by s.slug), '{}')
    into v_clean
    from unnest(new.addressed_also) as t(slug)
    join public.staff s on s.slug = t.slug and s.active
   where new.addressed_to is null or s.slug <> new.addressed_to;

  new.addressed_also := v_clean;
  return new;
end;
$$;


--
-- Name: job_depth(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.job_depth(p_job_id uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with recursive ancestry as (
    select job_id, parent_job_id, 0 as depth
      from public.jobs where job_id = p_job_id
    union all
    select j.job_id, j.parent_job_id, a.depth + 1
      from public.jobs j join ancestry a on j.job_id = a.parent_job_id
      -- Belt and braces against a cycle the CHECK cannot see. `no_self_parent`
      -- stops a job parenting itself; it cannot stop A->B->A, and a recursive
      -- CTE over a cycle does not terminate.
      where a.depth < 50
  )
  select coalesce(max(depth), 0) from ancestry;
$$;


--
-- Name: FUNCTION job_depth(p_job_id uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.job_depth(p_job_id uuid) IS 'How many parents a job has above it. Bounded at 50 so a parent cycle fails as a wrong number rather than as a hung query.';


--
-- Name: job_plan(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.job_plan(p_job_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(
    (select jsonb_build_object(
              'tool', p.tool, 'reaches', to_jsonb(p.reaches), 'steps', p.steps,
              'summary', p.summary, 'writes', p.planned_writes,
              'at', p.planned_at)
       from public.job_plans p where p.job_id = p_job_id),
    jsonb_build_object('none', true))
$$;


--
-- Name: job_plan_set(uuid, text, text[], jsonb, text, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.job_plan_set(p_job_id uuid, p_tool text, p_reaches text[], p_steps jsonb, p_summary text, p_writes integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_bad int;
begin
  if jsonb_typeof(p_steps) <> 'array' then
    return jsonb_build_object('error', 'steps must be an array');
  end if;

  -- `coalesce(..., 'missing')`, because `jsonb_typeof(e -> 'k')` is NULL when
  -- the key is ABSENT and a NULL comparison is dropped by the where clause --
  -- so a step missing a field entirely would pass a naive check. Migration
  -- 0251 learned this the hard way on the dashboard layout.
  select count(*) into v_bad
    from jsonb_array_elements(p_steps) e
   where coalesce(jsonb_typeof(e), 'missing') <> 'object'
      or coalesce(e ->> 'verb', '') not in ('create', 'update', 'remove', 'send')
      or coalesce(jsonb_typeof(e -> 'what'), 'missing') <> 'string'
      or coalesce(jsonb_typeof(e -> 'where'), 'missing') <> 'string'
      or coalesce(jsonb_typeof(e -> 'writes'), 'missing') <> 'number';
  if v_bad > 0 then
    return jsonb_build_object('error',
      format('%s step(s) are not {verb, what, where, writes} -- nothing was recorded', v_bad));
  end if;

  insert into public.job_plans
    (job_id, tool, reaches, steps, summary, planned_writes, planned_at)
  values (p_job_id, p_tool, coalesce(p_reaches, array[]::text[]), p_steps,
          p_summary, greatest(coalesce(p_writes, 0), 0), app.now_utc())
  on conflict (job_id) do update
    set tool = excluded.tool, reaches = excluded.reaches, steps = excluded.steps,
        summary = excluded.summary, planned_writes = excluded.planned_writes,
        planned_at = excluded.planned_at;

  return jsonb_build_object('ok', true, 'steps', jsonb_array_length(p_steps));
end;
$$;


--
-- Name: job_plan_text(uuid, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.job_plan_text(p_job_id uuid, p_most integer DEFAULT 12) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with p as (
    select * from public.job_plans where job_id = p_job_id
  ),
  lines as (
    select string_agg(
             format('· %s %s → %s', e ->> 'verb', e ->> 'what', e ->> 'where'),
             E'\n' order by n)                                              as body,
           (select count(*) from p, jsonb_array_elements(p.steps))          as total
      from p, lateral jsonb_array_elements(p.steps) with ordinality as t(e, n)
     where n <= p_most
  )
  select case
    when (select count(*) from p) = 0 then ''
    when (select jsonb_array_length(steps) from p) = 0
      then format(E'\n\nWhat it would do — %s', (select summary from p))
    else format(E'\n\nWhat it would do — %s\n%s%s',
                (select summary from p),
                (select body from lines),
                case when (select total from lines) > p_most
                     then format(E'\n· …and %s more',
                                 (select total from lines) - p_most)
                     else '' end)
  end
$$;


--
-- Name: FUNCTION job_plan_text(p_job_id uuid, p_most integer); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.job_plan_text(p_job_id uuid, p_most integer) IS '#131. The plan a job intends, rendered once here rather than four times in four channels -- so an approval cannot reach one surface with its plan and another without it.';


--
-- Name: job_progress(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.job_progress(p_job uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select jsonb_build_object(
    'job', p_job,
    'state', (select state::text from public.jobs where job_id = p_job),
    'steps', coalesce((
      select jsonb_agg(jsonb_build_object(
               'step', s.step,
               'ordinal', s.ordinal,
               'done', s.finished_at is not null,
               'began_at', s.began_at,
               'finished_at', s.finished_at,
               /*
                 Named for what it MEANS to a resume, not for what happened.

                 The first version called this `acted_outside`, and the first
                 real job showed a `store` step carrying
                 `document:bcf9fa85-…` next to `acted_outside: false` — which
                 reads as a contradiction and is not one. The question a
                 person needs answered is not "did anything happen" (the
                 effect column says that) but "if this had been interrupted,
                 could it have been retried": `local` can, `external` cannot.
               */
               'unrepeatable', s.effect_kind = 'external',
               'effect', s.effect_ref)
             order by s.ordinal, s.began_at)
        from public.job_steps s where s.job_id = p_job), '[]'::jsonb),
    'paused', (
      select jsonb_build_object(
               'reason', p.reason, 'detail', p.detail, 'resume_when', p.resume_when,
               'resumable', p.resumable, 'since', p.at, 'expires_at', p.expires_at)
        from public.job_pauses p
       where p.job_id = p_job and p.resumed_at is null
       order by p.at desc limit 1)
  );
$$;


--
-- Name: job_steps_are_written_once(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.job_steps_are_written_once() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception 'a step that happened cannot be unhappened (job %, step %)',
      old.job_id, old.step using errcode = '23514';
  end if;
  if old.finished_at is not null then
    raise exception 'step % of job % already finished at %; it cannot be changed',
      old.step, old.job_id, old.finished_at using errcode = '23514';
  end if;
  if new.step <> old.step or new.job_id <> old.job_id or new.effect_kind <> old.effect_kind then
    raise exception 'a step may be finished, not redefined (job %, step %)',
      old.job_id, old.step using errcode = '23514';
  end if;
  return new;
end;
$$;


--
-- Name: job_trace(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.job_trace(p_job_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select jsonb_build_object(
    'job_id', p_job_id,
    'kind', (select j.kind from public.jobs j where j.job_id = p_job_id),
    'state', (select j.state from public.jobs j where j.job_id = p_job_id),
    'steps', (select coalesce(j.trace_steps, 0) from public.jobs j where j.job_id = p_job_id),
    'tokens', (select j.trace_tokens from public.jobs j where j.job_id = p_job_id),
    'pence', (select j.trace_pence from public.jobs j where j.job_id = p_job_id),
    'ms', (select j.trace_ms from public.jobs j where j.job_id = p_job_id),
    'trace', coalesce((
      select jsonb_agg(jsonb_build_object(
               'step', t.step, 'at', t.at, 'kind', t.kind, 'detail', t.detail,
               'tokens_in', t.tokens_in, 'tokens_out', t.tokens_out,
               'pence', t.cost_pence, 'ms', t.ms
             ) order by t.step)
        from public.job_traces t where t.job_id = p_job_id), '[]'::jsonb)
  )
$$;


--
-- Name: job_trace_add(uuid, text, jsonb, integer, integer, numeric, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.job_trace_add(p_job_id uuid, p_kind text, p_detail jsonb DEFAULT '{}'::jsonb, p_tokens_in integer DEFAULT NULL::integer, p_tokens_out integer DEFAULT NULL::integer, p_cost_pence numeric DEFAULT NULL::numeric, p_ms integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_step int;
begin
  select coalesce(max(step), 0) + 1 into v_step
    from public.job_traces where job_id = p_job_id;

  insert into public.job_traces
    (job_id, step, kind, detail, tokens_in, tokens_out, cost_pence, ms)
  values
    (p_job_id, v_step, p_kind, coalesce(p_detail, '{}'::jsonb),
     p_tokens_in, p_tokens_out, p_cost_pence, p_ms);

  update public.jobs
     set trace_steps  = v_step,
         trace_tokens = coalesce(trace_tokens, 0)
                        + coalesce(p_tokens_in, 0) + coalesce(p_tokens_out, 0),
         trace_pence  = coalesce(trace_pence, 0) + coalesce(p_cost_pence, 0),
         trace_ms     = coalesce(trace_ms, 0) + coalesce(p_ms, 0)
   where job_id = p_job_id;

  return v_step;
end;
$$;


--
-- Name: job_trace_prune(integer, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.job_trace_prune(p_days integer DEFAULT 30, p_limit integer DEFAULT 5000) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_gone int;
begin
  with old as (
    select job_id, step from public.job_traces
     where at < app.now_utc() - make_interval(days => p_days)
     order by at
     limit p_limit
  )
  delete from public.job_traces t
   using old
   where t.job_id = old.job_id and t.step = old.step;
  get diagnostics v_gone = row_count;

  return jsonb_build_object('ok', true, 'removed', v_gone,
    'more', v_gone >= p_limit,
    'note', case when v_gone = 0 then 'nothing older than the window'
                 else format('%s step(s) older than %s days dropped; the rollups stay', v_gone, p_days) end);
end;
$$;


--
-- Name: jobs_stuck_queued(integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.jobs_stuck_queued(p_floor_minutes integer DEFAULT 60) RETURNS TABLE(kind text, n bigint, oldest_minutes integer, period_minutes integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with limits as (
    -- One row per kind a duty creates, carrying how long is too long for it.
    -- Aggregated because two duties can share a kind, and the SHORTER period
    -- is the honest threshold: whichever duty fires more often is the one
    -- falling behind first.
    select r.job_kind as kind, min(r.period_minutes) as period
      from public.responsibilities r
     where r.enabled
     group by r.job_kind
  )
  select j.kind,
         count(*) as n,
         max(extract(epoch from (app.now_utc() - j.created_at)) / 60)::int as oldest_minutes,
         coalesce(l.period, p_floor_minutes) as period_minutes
    from public.jobs j
    left join limits l on l.kind = j.kind
   -- app.harness_job, not j.is_fixture (0355). The generated column cannot see
   -- a job whose PROJECT is a fixture, and 140 rows differ today.
   where not app.harness_job(j.job_id)
     and j.state = 'queued'
     and j.created_at < app.now_utc()
         - make_interval(mins => coalesce(l.period, p_floor_minutes))
   group by j.kind, l.period
   order by count(*) desc, j.kind
$$;


--
-- Name: FUNCTION jobs_stuck_queued(p_floor_minutes integer); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.jobs_stuck_queued(p_floor_minutes integer) IS '#112. A queued job is not a failed job, which is why nine of them went unnoticed for eight hours. Too long is the period of the duty that made the job -- an hourly kind queued for over an hour means the last one was not taken before the next arrived.';


--
-- Name: jobs_waiting(integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.jobs_waiting(p_minutes integer DEFAULT 15) RETURNS TABLE(kind text, n bigint, oldest_minutes integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select j.kind,
         count(*) as n,
         max(extract(epoch from (app.now_utc() - j.created_at)) / 60)::int as oldest_minutes
    from public.jobs j
   where not app.harness_job(j.job_id)
     and j.state in ('queued', 'retrying')
     and j.created_at < app.now_utc() - make_interval(mins => p_minutes)
   group by j.kind
   order by max(j.created_at) asc, j.kind
$$;


--
-- Name: FUNCTION jobs_waiting(p_minutes integer); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.jobs_waiting(p_minutes integer) IS 'Work accepted and never picked up, at the threshold a person notices. #236';


--
-- Name: judge_consultation(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.judge_consultation(p_job_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_status text;
  v_n      int;
begin
  select o.reviewer_status into v_status
    from public.outputs o
   where o.job_id = p_job_id and o.reviewer_status is not null
   order by o.created_at desc
   limit 1;

  if v_status is null or v_status = 'pending' then
    return 0;
  end if;

  update public.consultations
     set changed_outcome = (v_status = 'approved'),
         outcome_note = format('inferred from the review of this job''s output: %s', v_status)
   where job_id = p_job_id
     and changed_outcome is null;

  get diagnostics v_n = row_count;
  return v_n;
end;
$$;


--
-- Name: judge_consultation_on_review(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.judge_consultation_on_review() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
begin
  if new.reviewer_status is distinct from old.reviewer_status
     and coalesce(new.reviewer_status, 'pending') <> 'pending' then
    perform app.judge_consultation(new.job_id);
  end if;
  return new;
end $$;


--
-- Name: kick_worker(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.kick_worker() RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_secret text;
  v_ref    text;
begin
  -- Before anything else. A paused office must cost nothing, not merely
  -- decline late.
  if app.worker_paused() then
    return null;
  end if;

  select decrypted_secret into v_secret
    from vault.decrypted_secrets where name = 'worker.kick_secret';
  if v_secret is null or v_secret = '' then
    return null;
  end if;

  select value #>> '{}' into v_ref from public.system_config where key = 'db.project_ref';
  if v_ref is null or v_ref = '' then return null; end if;

  return net.http_post(
    url     := format('https://%s.supabase.co/functions/v1/worker', v_ref),
    headers := jsonb_build_object(
      'Authorization', 'Bearer ' || v_secret,
      'Content-Type',  'application/json'
    ),
    body    := jsonb_build_object('source', 'pg_cron'),
    timeout_milliseconds := 120000
  );
end;
$$;


--
-- Name: learn(public.lesson_scope, text, text, uuid, text, text, uuid, numeric, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.learn(p_scope public.lesson_scope, p_body text, p_learned_by text, p_project_id uuid DEFAULT NULL::uuid, p_staff_slug text DEFAULT NULL::text, p_job_kind text DEFAULT NULL::text, p_from_job uuid DEFAULT NULL::uuid, p_confidence numeric DEFAULT 0.50, p_supersedes uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  prior public.lessons%rowtype;
  seen  integer := 1;
  made  public.lessons%rowtype;
begin
  if p_supersedes is not null then
    select * into prior from public.lessons where lesson_id = p_supersedes;
    if not found then
      return jsonb_build_object('error', 'nothing to supersede: ' || p_supersedes::text);
    end if;
    -- Superseding a row that is already superseded would lose the newer belief.
    if exists (select 1 from public.lessons where supersedes = p_supersedes) then
      return jsonb_build_object('error', 'that lesson has already been revised');
    end if;
    seen := prior.observations + 1;
  end if;

  insert into public.lessons
    (row_kind, scope, project_id, staff_slug, job_kind, body,
     learned_by, from_job, confidence, observations, supersedes)
  values
    ('lesson', p_scope, p_project_id, p_staff_slug, p_job_kind, p_body,
     p_learned_by, p_from_job, least(greatest(p_confidence, 0), 1), seen, p_supersedes)
  returning * into made;

  /*
    Into the ledger (#53).

    `actor_kind` is decided by who says they learned it: Grant teaching the
    office in a Telegram message is a user acting, and an agent drawing its own
    conclusion is the autonomous case this issue is actually about. Conflating
    them would make "what has it decided by itself" unanswerable, which is the
    one question the ledger exists to answer here.
  */
  perform public.append_event(
    coalesce((select correlation_id from public.jobs where job_id = p_from_job),
             extensions.gen_random_uuid()),
    case when p_learned_by = 'grant' then 'user' else 'agent' end,
    p_learned_by, 'learning', 'office.learned',
    true, p_project_id, null,
    jsonb_build_object('lesson_id', made.lesson_id, 'scope', p_scope,
                       'observations', made.observations),
    left(p_body, 1000), '[]'::jsonb, null, null,
    'app.unlearn(lesson_id, by, reason)',
    p_from_job);

  return jsonb_build_object(
    'lesson_id', made.lesson_id,
    'observations', made.observations,
    'replaced', p_supersedes
  );
end;
$$;


--
-- Name: FUNCTION learn(p_scope public.lesson_scope, p_body text, p_learned_by text, p_project_id uuid, p_staff_slug text, p_job_kind text, p_from_job uuid, p_confidence numeric, p_supersedes uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.learn(p_scope public.lesson_scope, p_body text, p_learned_by text, p_project_id uuid, p_staff_slug text, p_job_kind text, p_from_job uuid, p_confidence numeric, p_supersedes uuid) IS 'Record a lesson, or strengthen an existing one by superseding it. Never updates: the previous belief stays readable (#48). Appends to the ledger with a real reversal method (#53).';


--
-- Name: lessons_for(uuid, text, text, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.lessons_for(p_project_id uuid DEFAULT NULL::uuid, p_staff_slug text DEFAULT NULL::text, p_job_kind text DEFAULT NULL::text, p_limit integer DEFAULT 8) RETURNS TABLE(lesson_id uuid, scope public.lesson_scope, body text, observations integer, confidence numeric, learned_by text, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select l.lesson_id, l.scope, l.body, l.observations, l.confidence,
         l.learned_by, l.created_at
    from public.lessons_live l
   where (l.scope = 'global')
      or (l.scope = 'project' and l.project_id = p_project_id)
      or (l.scope = 'staff'   and l.staff_slug = p_staff_slug)
      or (l.scope = 'kind'    and l.job_kind   = p_job_kind)
   order by
     -- Specificity first. The general lesson is usually already reflected in
     -- how the office is built; the specific one is what nobody knew.
     case l.scope when 'staff' then 0 when 'kind' then 1 when 'project' then 2 else 3 end,
     l.observations desc,
     l.confidence desc,
     l.created_at desc
   limit greatest(coalesce(p_limit, 8), 0)
$$;


--
-- Name: FUNCTION lessons_for(p_project_id uuid, p_staff_slug text, p_job_kind text, p_limit integer); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.lessons_for(p_project_id uuid, p_staff_slug text, p_job_kind text, p_limit integer) IS 'The lessons a job should be told, scoped and ranked by specificity then weight of evidence. Capped by the caller, because a chat turn and an overnight research job can afford different amounts.';


--
-- Name: let_job_go(uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.let_job_go(p_job uuid, p_why text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_was text;
begin
  if p_job is null then return; end if;
  select state::text into v_was from public.jobs where job_id = p_job;
  if v_was is null then return; end if;
  /*
    A resolved blocker whose job is still parked in waiting_user is a job
    nothing will ever pick up. But waiting_user -> queued is not an edge, and
    0290 says why it should not be: queued means nobody has looked at this yet.
    So: park it, then queue it. Both transitions are written to
    job_state_transitions by the trigger, and the ledger reads as what
    happened.
  */
  if v_was in ('waiting_user', 'waiting_external') then
    update public.jobs
       set state = 'paused', state_reason = p_why, updated_at = app.now_utc()
     where job_id = p_job;
    v_was := 'paused';
  end if;
  if v_was = 'paused' then
    update public.jobs
       set state = 'queued', state_reason = p_why, updated_at = app.now_utc()
     where job_id = p_job;
  end if;
end;
$$;


--
-- Name: FUNCTION let_job_go(p_job uuid, p_why text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.let_job_go(p_job uuid, p_why text) IS 'The one definition of "this job may run again", so the blocker answer path and the personal-task path cannot come to disagree (#259, 0472s rule).';


--
-- Name: link(uuid, text, uuid, text, text, uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.link(p_project uuid, p_from_kind text, p_from_id uuid, p_verb text, p_to_kind text, p_to_id uuid, p_made_by text DEFAULT 'grant'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_id uuid;
  v_ok boolean;
begin
  -- Both ends must exist. The edge table cannot enforce this, so it is enforced
  -- here — a dangling edge is invisible until someone reads the graph and finds
  -- a relationship to nothing.
  foreach v_ok in array array[true] loop end loop;  -- no-op, keeps plpgsql happy

  execute format(
    'select exists (select 1 from public.%I where %I = $1)',
    case p_from_kind
      when 'document' then 'documents' when 'task' then 'tasks'
      when 'agent' then 'staff' when 'job' then 'jobs'
      when 'collection' then 'collections' else 'projects' end,
    case p_from_kind
      when 'document' then 'document_id' when 'task' then 'task_id'
      when 'agent' then 'staff_id' when 'job' then 'job_id'
      when 'collection' then 'collection_id' else 'project_id' end)
  into v_ok using p_from_id;
  if not v_ok then
    raise exception 'no % with id %', p_from_kind, p_from_id;
  end if;

  execute format(
    'select exists (select 1 from public.%I where %I = $1)',
    case p_to_kind
      when 'document' then 'documents' when 'task' then 'tasks'
      when 'agent' then 'staff' when 'job' then 'jobs'
      when 'collection' then 'collections' else 'projects' end,
    case p_to_kind
      when 'document' then 'document_id' when 'task' then 'task_id'
      when 'agent' then 'staff_id' when 'job' then 'job_id'
      when 'collection' then 'collection_id' else 'project_id' end)
  into v_ok using p_to_id;
  if not v_ok then
    raise exception 'no % with id %', p_to_kind, p_to_id;
  end if;

  insert into public.relations
    (project_id, from_kind, from_id, verb, to_kind, to_id, made_by)
  values (p_project, p_from_kind, p_from_id, p_verb, p_to_kind, p_to_id, p_made_by)
  on conflict (from_kind, from_id, verb, to_kind, to_id) do update
    set made_by = excluded.made_by
  returning relation_id into v_id;

  return v_id;
end $_$;


--
-- Name: log_job_creation(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.log_job_creation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  insert into public.job_state_transitions (job_id, from_state, to_state, reason, attempt)
  values (new.job_id, null, new.state, new.state_reason, new.attempt);
  return null;
end
$$;


--
-- Name: mail_awaiting(uuid, integer, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.mail_awaiting(p_project uuid, p_days integer DEFAULT 7, p_limit integer DEFAULT 10) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  with claimed as (
    -- The messages this project can see, by ADR-0037's derivation, unchanged.
    select (x->>'thread_id') as thread_id,
           (x->>'why') as why
      from jsonb_array_elements(app.mail_for_project(p_project, 200)) as x
  ),
  /*
    One reason per thread, and `contact` wins.

    A thread can contain a contact match and an alias match; the tier reported
    has to be the strongest one in it, for the same reason the message-level
    reader picks the stronger of two tiers rather than merging them.
  */
  threads as (
    select thread_id,
           case when bool_or(why = 'contact') then 'contact' else 'named' end as why
      from claimed
     where thread_id is not null
     group by thread_id
  ),
  /*
    Every message in those threads, including the ones Grant sent.

    This is the step 0467 was missing. It widens nothing about WHICH threads
    the project can see -- that is still ADR-0037's derivation, above -- only
    which messages of an already-claimed thread are considered when deciding
    who spoke last.
  */
  msgs as (
    select m.*, t.why
      from threads t
      join public.mail_messages m on m.thread_id = t.thread_id
     where m.vanished_at is null
       and not ('CATEGORY_PROMOTIONS' = any (coalesce(m.labels, '{}')))
       and not ('CATEGORY_UPDATES' = any (coalesce(m.labels, '{}')))
  ),
  last_in_thread as (
    select distinct on (thread_id)
           thread_id, message_id, subject, from_name, from_address, sent_at, why,
           ('SENT' = any (coalesce(labels, '{}'))) as from_grant
      from msgs
     order by thread_id, sent_at desc nulls last
  ),
  /*
    Who the thread is WITH, which is never Grant.

    The last message decides the direction; it is the wrong place to get the
    other person's name from, because on a thread he spoke last on it would
    read "waiting on Grant Rogers". The counterpart is the most recent sender
    in the thread who is not him.
  */
  counterpart as (
    select distinct on (thread_id) thread_id,
           coalesce(nullif(btrim(coalesce(from_name, '')), ''), from_address, 'unknown') as who
      from msgs
     where not ('SENT' = any (coalesce(labels, '{}')))
     order by thread_id, sent_at desc nulls last
  )
  select coalesce(jsonb_agg(v order by ord), '[]'::jsonb)
    from (
      select jsonb_build_object(
               'thread_id', t.thread_id,
               'subject', coalesce(nullif(btrim(coalesce(t.subject, '')), ''), '(no subject)'),
               'with', coalesce(c.who, 'unknown'),
               'last_at', t.sent_at,
               'days', floor(extract(epoch from (app.now_utc() - t.sent_at)) / 86400)::int,
               -- Which way round, never one "outstanding" flag: the two need
               -- completely different things from him (0304's asymmetry).
               'waiting', case when t.from_grant then 'no reply to you'
                               else 'you have not replied' end,
               'why', t.why) as v,
             t.sent_at as ord
        from last_in_thread t
        left join counterpart c using (thread_id)
       where t.sent_at is not null
         and t.sent_at < app.now_utc() - make_interval(days => greatest(1, coalesce(p_days, 7)))
       order by t.sent_at asc
       limit greatest(1, least(50, coalesce(p_limit, 10)))
    ) q;
$$;


--
-- Name: FUNCTION mail_awaiting(p_project uuid, p_days integer, p_limit integer); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.mail_awaiting(p_project uuid, p_days integer, p_limit integer) IS 'Threads on one project where nobody has spoken for a while, and which way round (#172). Derived from ADR-0037''s project association and from thread shape alone: there are no message bodies in this system, so this reports what is CHECKABLE and never guesses at a commitment.';


--
-- Name: mail_bodies_held(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.mail_bodies_held() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select jsonb_build_object(
           'messages', count(*),
           'with_body', count(*) filter (where body is not null),
           'withheld_as_bulk', count(*) filter (where body_withheld = 'bulk'),
           'no_text_part', count(*) filter (where body_withheld = 'no text part'),
           'never_looked', count(*) filter (where body is null and body_withheld is null))
    from public.mail_messages
   where vanished_at is null;
$$;


--
-- Name: mail_coverage(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.mail_coverage(p_project uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    /* How much mail the office holds at all, across every project. */
    'cached', (select count(*)::int from public.mail_messages),
    /* The newest thing it holds, so a stale cache is visible as staleness. */
    'newest', (select max(sent_at) from public.mail_messages),
    /*
      The two ways a message can reach a project, counted. Zero contacts is
      the fact that matters: it means the strongest tier cannot fire at all,
      which is a completely different sentence from "nothing matched".
    */
    'contacts', (
      select count(*)::int from public.contacts c
       where p_project is not null and c.project_id = p_project
    ),
    'aliases', (
      select count(*)::int from public.project_aliases a
       where p_project is not null and a.project_id = p_project
    ),
    'associated', (
      select jsonb_array_length(app.mail_for_project(p_project, 200))
       where p_project is not null
    )
  );
$$;


--
-- Name: FUNCTION mail_coverage(p_project uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.mail_coverage(p_project uuid) IS 'What the office can and cannot see in the inbox for this project, so an empty answer can say which kind of empty it is (#172, #257).';


--
-- Name: mail_for_project(uuid, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.mail_for_project(p_project uuid, p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  with live as (
    select p.project_id
      from public.projects p
     where p.project_id = p_project
       and p.status = 'active'
       and not p.is_fixture
  ),
  by_contact as (
    select m.message_id,
           'contact'::text as tier,
           coalesce(nullif(btrim(c.name), ''), c.email) as matched
      from public.mail_messages m
      join public.contacts c
        on lower(btrim(c.email)) = lower(btrim(coalesce(m.from_address, '')))
      join live on live.project_id = c.project_id
     where m.vanished_at is null
       and coalesce(btrim(c.email), '') <> ''
  ),
  by_alias as (
    select m.message_id,
           'named'::text as tier,
           a.alias as matched
      from public.mail_messages m
      join public.project_aliases a on true
      join live on live.project_id = a.project_id
     where m.vanished_at is null
       and length(a.normalised) >= 4
       and strpos(
             ' ' || regexp_replace(lower(coalesce(m.subject, '')), '[^a-z0-9]+', ' ', 'g') || ' ',
             ' ' || btrim(regexp_replace(lower(a.normalised), '[^a-z0-9]+', ' ', 'g')) || ' '
           ) > 0
  ),
  best as (
    select message_id, tier, matched,
           row_number() over (
             partition by message_id
             order by case tier when 'contact' then 0 else 1 end, matched) as rank
      from (select * from by_contact union all select * from by_alias) both_tiers
  )
  select coalesce(jsonb_agg(v order by ord), '[]'::jsonb)
    from (
      select jsonb_build_object(
               'message_id', m.message_id,
               'thread_id', m.thread_id,
               'subject', coalesce(nullif(btrim(coalesce(m.subject, '')), ''), '(no subject)'),
               'from', coalesce(nullif(btrim(coalesce(m.from_name, '')), ''), m.from_address, 'unknown'),
               'from_address', m.from_address,
               'sent_at', m.sent_at,
               'excerpt', m.excerpt,
               /*
                 Bounded here rather than at the caller. The reader returns up
                 to 100 rows and a prompt has a character budget; a caller that
                 has to remember to truncate is a caller that will forget once.
               */
               'body', left(m.body, 1500),
               'body_truncated', coalesce(length(m.body), 0) > 1500,
               'body_withheld', m.body_withheld,
               'has_attachments', m.has_attachments,
               'why', b.tier,
               'matched', b.matched) as v,
             m.sent_at as ord
        from best b
        join public.mail_messages m using (message_id)
       where b.rank = 1
       order by m.sent_at desc nulls last
       limit greatest(1, least(100, coalesce(p_limit, 20)))
    ) q;
$$;


--
-- Name: FUNCTION mail_for_project(p_project uuid, p_limit integer); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.mail_for_project(p_project uuid, p_limit integer) IS 'The correspondence that belongs to a dashboard project (#172, ADR-0037). Derived from a contact on the project or an alias phrase in the SUBJECT -- never stored, never matched on the excerpt. `why` names which tier, and the two are deliberately not merged.';


--
-- Name: mail_recent(integer, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.mail_recent(p_hours integer DEFAULT 24, p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  select coalesce(jsonb_agg(m order by m.sent_at desc), '[]'::jsonb)
    from (
      select jsonb_build_object(
               'subject', coalesce(subject, '(no subject)'),
               'from', coalesce(nullif(from_name, ''), from_address, 'unknown'),
               'from_address', from_address,
               'sent_at', sent_at,
               'excerpt', excerpt,
               'unread', unread,
               'has_attachments', has_attachments
             ) as m, sent_at
        from public.mail_messages
       where vanished_at is null
         and sent_at > app.now_utc() - make_interval(hours => greatest(1, least(720, p_hours)))
       order by sent_at desc
       limit greatest(1, least(100, p_limit))
    ) m
$$;


--
-- Name: mail_search(text, uuid, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.mail_search(p_query text, p_project uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  with words as (
    select distinct w
      from unnest(
             regexp_split_to_array(lower(coalesce(p_query, '')), '[^a-z0-9]+')
           ) as w
     where length(w) >= 4
       and w not in (
         'have', 'has', 'been', 'that', 'this', 'with', 'from', 'what', 'when',
         'where', 'which', 'about', 'there', 'their', 'they', 'them', 'were',
         'will', 'would', 'could', 'should', 'your', 'yours', 'ours', 'into',
         'over', 'under', 'then', 'than', 'also', 'just', 'some', 'any', 'all',
         'more', 'most', 'much', 'very', 'said', 'says', 'tell', 'told', 'know',
         'anything', 'something', 'already', 'please', 'thanks', 'regarding',
         'message', 'messages', 'email', 'emails', 'mail', 'inbox',
         'discussed', 'discuss', 'talked', 'talking'
       )
  ),
  scope as (
    select jsonb_array_elements(app.mail_for_project(p_project, 100)) ->> 'message_id' as message_id
     where p_project is not null
  ),
  /*
    The body scores 1, the same as the snippet and half the subject.

    Not more, deliberately. A body is thirty times longer than a snippet, so a
    word that appears in it once is much weaker evidence than the same word in
    a subject line -- and scoring by presence rather than by count is what
    stops the longest thread in the inbox winning every search.
  */
  scored as (
    select m.message_id,
           sum(case when strpos(lower(coalesce(m.subject, '')), words.w) > 0 then 2 else 0 end
             + case when strpos(lower(coalesce(m.excerpt, '')), words.w) > 0 then 1 else 0 end
             + case when strpos(lower(coalesce(m.body, '')), words.w) > 0 then 1 else 0 end
           )::int as score
      from public.mail_messages m
     cross join words
     where m.vanished_at is null
       and (p_project is null or m.message_id in (select message_id from scope))
     group by m.message_id
    having sum(case when strpos(lower(coalesce(m.subject, '')), words.w) > 0 then 2 else 0 end
             + case when strpos(lower(coalesce(m.excerpt, '')), words.w) > 0 then 1 else 0 end
             + case when strpos(lower(coalesce(m.body, '')), words.w) > 0 then 1 else 0 end) > 0
  )
  select coalesce(jsonb_agg(v order by score desc, ord desc nulls last), '[]'::jsonb)
    from (
      select jsonb_build_object(
               'message_id', m.message_id,
               'thread_id', m.thread_id,
               'subject', coalesce(nullif(btrim(coalesce(m.subject, '')), ''), '(no subject)'),
               'from', coalesce(nullif(btrim(coalesce(m.from_name, '')), ''), m.from_address, 'unknown'),
               'from_address', m.from_address,
               'sent_at', m.sent_at,
               'excerpt', m.excerpt,
               'body', left(m.body, 1500),
               'body_truncated', coalesce(length(m.body), 0) > 1500,
               'body_withheld', m.body_withheld,
               'has_attachments', m.has_attachments,
               'score', s.score) as v,
             s.score, m.sent_at as ord
        from scored s
        join public.mail_messages m using (message_id)
       order by s.score desc, m.sent_at desc nulls last
       limit greatest(1, least(100, coalesce(p_limit, 20)))
    ) r;
$$;


--
-- Name: FUNCTION mail_search(p_query text, p_project uuid, p_limit integer); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.mail_search(p_query text, p_project uuid, p_limit integer) IS 'Search the cached mail with a question (#172). Any word of four characters or more, subject matches worth double, ranked rather than filtered. With a project, only that project''s correspondence as `mail_for_project` derives it -- the isolation rule of ADR-0037.';


--
-- Name: mark_telegram_undeliverable(text, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.mark_telegram_undeliverable(p_chat_id text, p_reason text, p_bot_id text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  update public.telegram_chats
     set deliverable = false,
         undeliverable_reason = p_reason,
         undeliverable_at = app.now_utc()
   where chat_id = p_chat_id
     and deliverable
     and (p_bot_id is null or bot_id = p_bot_id);
  return found;
end;
$$;


--
-- Name: may_act(uuid, text, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.may_act(p_project uuid, p_tool text, p_job uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_tool      record;
  v_autonomy  public.autonomy_level;
  v_verdict   public.policy_verdict;
  v_note      text;
  v_standing  record;
  v_asked_for boolean := false;
  v_by        text;
begin
  select tool, level, enabled, disabled_reason into v_tool
    from public.tool_permissions where tool = p_tool;
  if not found then
    return jsonb_build_object('verdict', 'refuse', 'tool', p_tool,
      'because', format('There is no such capability as %s.', p_tool));
  end if;

  -- A disabled tool is refused before the dial is consulted. The registry is
  -- the authority on what exists; autonomy is only about what may be done
  -- without asking, and it may never re-enable something switched off.
  if not v_tool.enabled then
    return jsonb_build_object('verdict', 'refuse', 'tool', p_tool,
      'action_level', v_tool.level,
      'because', coalesce(nullif(btrim(v_tool.disabled_reason), ''),
                          format('%s is switched off for everyone.', p_tool)));
  end if;

  /*
    Did a PERSON ask for this, or did the office decide to do it?

    The distinction the first draft of this function did not make, and without
    it wiring the policy into the handlers that write outward would have made
    the office noisier -- which is the opposite of #15. If Grant says "put the
    module outline in Notion", asking him whether he would like it in Notion is
    the interruption he wants removed. The asking IS the approval.

    `jobs.requested_by` is `<origin_channel>:<actor>` for anything a person
    started and `duty:<name>` for anything the office started on a schedule, so
    this is a PROPERTY rather than a list of kinds nobody will maintain -- the
    same correction #185's citation check needed.

    No job means unprompted, which is the conservative reading: a caller that
    cannot name the job it is running cannot claim somebody asked for it.
  */
  if p_job is not null then
    select requested_by into v_by from public.jobs where job_id = p_job;
    v_asked_for := v_by is not null and v_by not like 'duty:%';
  end if;

  v_autonomy := app.autonomy_for(p_project);

  select verdict, note into v_verdict, v_note
    from public.autonomy_policy
   where autonomy = v_autonomy and action_level = v_tool.level;
  if v_verdict is null then
    -- A gap in the matrix is a fault, and a missing configuration must not
    -- read as permission (the same argument `autonomy_for` makes).
    return jsonb_build_object('verdict', 'ask', 'tool', p_tool,
      'action_level', v_tool.level, 'autonomy', v_autonomy::text,
      'because', 'The policy has nothing to say about this, so it asks.');
  end if;

  /*
    A standing authorization upgrades ask to proceed and nothing else.

    Not refuse: `observe` means observe, and a level-3 tool cannot hold one at
    all (the trigger above). The project's own row wins over the global one,
    the same precedence `autonomy_for` uses.
  */
  /*
    Prompted work below level 3 does not stop to ask.

    Level 3 is untouched, here as everywhere: a person asking for something
    consequential is not the same as a person having seen what it will do, and
    `autonomy_policy`'s CHECK means no route through this function can return
    `proceed` for one.

    `refuse` is untouched too. A project set to `observe` and then asked to
    write is a contradiction, and the honest answer is the refusal with its
    reason, so Grant can change the dial rather than have the office quietly
    decide which of his two instructions it preferred.
  */
  if v_verdict = 'ask' and v_asked_for and v_tool.level < 3 then
    return jsonb_build_object(
      'verdict', 'proceed', 'tool', p_tool, 'action_level', v_tool.level,
      'autonomy', v_autonomy::text, 'standing', null, 'asked_for', true,
      'because', 'You asked for this, so it does not stop to ask you again.');
  end if;

  if v_verdict = 'ask' then
    select authorization_id, project_id, reason, granted_at, expires_at
      into v_standing
      from public.standing_authorizations
     where tool = p_tool
       and revoked_at is null
       and (expires_at is null or expires_at > app.now_utc())
       and (project_id is null or project_id = p_project)
     order by (project_id is not null) desc
     limit 1;
    if found then
      return jsonb_build_object(
        'verdict', 'proceed', 'tool', p_tool, 'action_level', v_tool.level,
        'autonomy', v_autonomy::text,
        'standing', jsonb_build_object(
          'id', v_standing.authorization_id,
          'scope', case when v_standing.project_id is null then 'everywhere' else 'this project' end,
          'reason', v_standing.reason,
          'since', v_standing.granted_at,
          'until', v_standing.expires_at),
        'because', format('You said not to ask again about %s: %s', p_tool, v_standing.reason));
    end if;
  end if;

  return jsonb_build_object('verdict', v_verdict::text, 'tool', p_tool,
    'action_level', v_tool.level, 'autonomy', v_autonomy::text,
    'standing', null, 'asked_for', v_asked_for, 'because', v_note);
end;
$$;


--
-- Name: mcp_add_document(text, text, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.mcp_add_document(p_client_id text, p_project text, p_title text, p_content text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_project uuid;
  v_id uuid;
  v_fingerprint text;
  v_existing uuid;
begin
  select project_id into v_project
    from public.projects where slug = p_project and status = 'active';
  if v_project is null then
    return jsonb_build_object('error', format('no active project with slug %L', p_project));
  end if;
  if coalesce(trim(p_content), '') = '' then
    return jsonb_build_object('error', 'content is empty; refusing to store an empty document');
  end if;
  if coalesce(trim(p_title), '') = '' then
    return jsonb_build_object('error', 'title is required');
  end if;

  v_fingerprint := encode(sha256(convert_to(p_content, 'UTF8')), 'hex');

  select document_id into v_existing
    from public.documents
   where project_id = v_project and content_fingerprint = v_fingerprint;
  if v_existing is not null then
    return jsonb_build_object(
      'document_id', v_existing, 'title', p_title, 'duplicate', true,
      'note', 'identical content already in this project; nothing was added'
    );
  end if;

  insert into public.documents
    (project_id, connector, external_parent_ref, external_ref, title, doc_type,
     content, content_fingerprint, content_chars, fetched_at, added_by)
  values (v_project, 'mcp', null, null, p_title, 'note',
          p_content, v_fingerprint, length(p_content), app.now_utc(), p_client_id)
  returning document_id into v_id;

  return jsonb_build_object(
    'document_id', v_id, 'title', p_title, 'chars', length(p_content), 'duplicate', false
  );
end;
$$;


--
-- Name: mcp_client_for(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.mcp_client_for(p_token_sha256 text) RETURNS TABLE(client_id text, display_name text, scopes text[])
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select c.client_id, c.display_name, c.scopes
    from public.mcp_clients c
   where c.token_sha256 = p_token_sha256
     and c.enabled
$$;


--
-- Name: FUNCTION mcp_client_for(p_token_sha256 text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.mcp_client_for(p_token_sha256 text) IS 'Recognise a token by its hash. No row is the only failure mode - a disabled client and an unknown one are deliberately indistinguishable to the caller.';


--
-- Name: mcp_client_name(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.mcp_client_name(p_client_id text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select client_name from public.mcp_oauth_clients where client_id = p_client_id
$$;


--
-- Name: FUNCTION mcp_client_name(p_client_id text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.mcp_client_name(p_client_id text) IS 'The name a client registered under, for the consent page. Never the one it passes in a query parameter: that is a string the caller controls, on the one page whose job is to let Grant recognise what is asking.';


--
-- Name: mcp_code_challenge(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.mcp_code_challenge(p_code_sha256 text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select code_challenge from public.mcp_auth_codes
   where code_sha256 = p_code_sha256
     and redeemed_at is null
     and expires_at > app.now_utc()
$$;


--
-- Name: mcp_document(uuid, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.mcp_document(p_document_id uuid, p_max_chars integer DEFAULT 20000) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select coalesce(
    (select jsonb_build_object(
              'document_id', d.document_id,
              'title', d.title,
              'connector', d.connector,
              'project', (select p.slug from public.projects p where p.project_id = d.project_id),
              'chars', d.content_chars,
              'truncated', d.content_chars > greatest(1000, least(coalesce(p_max_chars, 20000), 60000)),
              'fetched_at', d.fetched_at,
              'content', left(coalesce(d.content, ''),
                              greatest(1000, least(coalesce(p_max_chars, 20000), 60000)))
            )
       from public.documents d where d.document_id = p_document_id),
    jsonb_build_object('error', 'no such document'))
$$;


--
-- Name: mcp_enqueue(text, text, text, jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.mcp_enqueue(p_client_id text, p_project text, p_kind text, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_project uuid;
  v_job uuid;
begin
  -- The list is fixed for the same reason the tool list is: a client naming a
  -- job kind is a client choosing what the worker does.
  if p_kind not in ('notebook.generate', 'notebook.push_document', 'notebook.ask') then
    return jsonb_build_object('error', format('%L is not a kind a client may enqueue', p_kind));
  end if;

  select project_id into v_project
    from public.projects where slug = p_project and status = 'active';
  if v_project is null then
    return jsonb_build_object('error', format('no active project with slug %L', p_project));
  end if;

  insert into public.jobs
    (correlation_id, project_id, idempotency_key, kind, requested_by, priority, pinned_config)
  values (gen_random_uuid(), v_project,
          format('mcp-%s-%s', p_client_id, gen_random_uuid()),
          p_kind, format('mcp:%s', p_client_id), 200, p_payload)
  returning job_id into v_job;

  return jsonb_build_object(
    'job_id', v_job, 'kind', p_kind, 'state', 'queued',
    'note', 'the worker picks this up; call check_job with the id'
  );
end;
$$;


--
-- Name: FUNCTION mcp_enqueue(p_client_id text, p_project text, p_kind text, p_payload jsonb); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.mcp_enqueue(p_client_id text, p_project text, p_kind text, p_payload jsonb) IS 'A client asks; the worker does. The Edge Function cannot spawn the Python the notebook adapter needs, and an audio overview takes minutes - a tool call that blocks for minutes times out in every client, so the constraint and the right design agree.';


--
-- Name: mcp_expire_codes(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.mcp_expire_codes() RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  with gone as (
    delete from public.mcp_auth_codes
     where expires_at < app.now_utc() - interval '1 hour'
    returning 1
  )
  select count(*)::integer from gone
$$;


--
-- Name: mcp_inventory(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.mcp_inventory() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select coalesce(jsonb_agg(v order by name), '[]'::jsonb)
    from (
      select p.name,
             jsonb_build_object(
               'id', p.provider_id, 'name', p.name, 'display_name', p.display_name, 'endpoint', p.endpoint,
               'auth', p.auth_kind, 'enabled', p.enabled, 'revoked_at', p.revoked_at,
               'server', p.server_name, 'protocol', p.protocol_version,
               'last_probe_at', p.last_probe_at, 'last_probe_ok', p.last_probe_ok,
               'last_probe_detail', p.last_probe_detail,
               'discovered', (select count(*) from public.mcp_discovered_tools d
                               where d.provider_id = p.provider_id and d.vanished_at is null),
               'vanished', (select count(*) from public.mcp_discovered_tools d
                             where d.provider_id = p.provider_id and d.vanished_at is not null),
               'offered', (select count(*) from public.mcp_discovered_tools d
                            where d.provider_id = p.provider_id and d.offered_as is not null),
               /*
                 The number that matters, and the reason it is separate from
                 `offered`: a provider can advertise forty tools, the office
                 can offer six, and NONE of them be usable until Grant
                 approves. Showing only "offered" would read as reach.
               */
               'usable', (select count(*) from public.tool_permissions t
                           where t.delivered_by = format('mcp:%s', p.name) and t.enabled),
               'tools', (select coalesce(jsonb_agg(jsonb_build_object(
                                  'id', d.discovered_id, 'name', d.external_name, 'reach', d.reach,
                                  'certainty', d.reach_certainty, 'why', d.why_that_reach,
                                  'offered_as', d.offered_as,
                                  'usable', exists (select 1 from public.tool_permissions t
                                                     where t.tool = d.offered_as and t.enabled),
                                  'gone', d.vanished_at is not null)
                                order by d.external_name), '[]'::jsonb)
                           from public.mcp_discovered_tools d
                          where d.provider_id = p.provider_id)) as v
        from public.mcp_providers p
    ) q;
$$;


--
-- Name: FUNCTION mcp_inventory(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.mcp_inventory() IS 'Every outside provider, what it advertises, what the office offered and what Grant can actually use (#265) — with the ids a press needs (0478). No credential, ever: the token is not selected here.';


--
-- Name: mcp_issue_code(text, text, text, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.mcp_issue_code(p_client_id text, p_redirect_uri text, p_code_sha256 text, p_code_challenge text, p_resource text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_uris text[];
begin
  select redirect_uris into v_uris
    from public.mcp_oauth_clients where client_id = p_client_id;
  if v_uris is null then
    return jsonb_build_object('error', 'invalid_client');
  end if;
  -- Exact membership. A prefix match here is how an open redirector becomes a
  -- token thief.
  if not (p_redirect_uri = any(v_uris)) then
    return jsonb_build_object('error', 'invalid_redirect_uri');
  end if;

  insert into public.mcp_auth_codes
    (code_sha256, client_id, redirect_uri, code_challenge, resource)
  values (p_code_sha256, p_client_id, p_redirect_uri, p_code_challenge, p_resource);

  update public.mcp_oauth_clients set last_used_at = app.now_utc()
   where client_id = p_client_id;

  return jsonb_build_object('ok', true);
end;
$$;


--
-- Name: mcp_job_status(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.mcp_job_status(p_job_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select coalesce(
    (select jsonb_build_object(
              'job_id', j.job_id, 'kind', j.kind, 'state', j.state,
              'reason', j.state_reason, 'created_at', j.created_at,
              'finished_at', j.finished_at,
              'output', (select left(o.body, 4000) from public.outputs o
                          where o.job_id = j.job_id order by o.created_at desc limit 1)
            )
       from public.jobs j where j.job_id = p_job_id),
    jsonb_build_object('error', 'no such job'))
$$;


--
-- Name: mcp_projects(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.mcp_projects() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select coalesce(jsonb_agg(x order by x->>'name'), '[]'::jsonb) from (
    select jsonb_build_object(
             'project_id', p.project_id,
             'slug', p.slug,
             'name', p.name,
             'status', p.status,
             'documents', (select count(*) from public.documents d where d.project_id = p.project_id),
             'live_jobs', (select count(*) from public.jobs j
                            where j.project_id = p.project_id
                              and j.state not in ('complete', 'cancelled', 'failed')),
             'updated_at', p.updated_at
           ) as x
      from public.projects p
     where p.status = 'active'
  ) s
$$;


--
-- Name: mcp_recent_work(integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.mcp_recent_work(p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select coalesce(jsonb_agg(x order by x->>'created_at' desc), '[]'::jsonb) from (
    select jsonb_build_object(
             'output_id', o.output_id,
             'project', (select p.slug from public.projects p where p.project_id = j.project_id),
             'kind', j.kind,
             'staff', (select st.slug from public.staff st where st.staff_id = o.staff_id),
             'confidence', o.confidence,
             'evidence', o.evidence,
             'reviewed', o.reviewer_status,
             'sources', o.sources,
             'model', o.model,
             'created_at', o.created_at,
             'body', left(o.body, 4000)
           ) as x
      from public.outputs o
      join public.jobs j on j.job_id = o.job_id
     order by o.created_at desc
     limit greatest(1, least(coalesce(p_limit, 20), 50))
  ) s
$$;


--
-- Name: FUNCTION mcp_recent_work(p_limit integer); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.mcp_recent_work(p_limit integer) IS 'Outputs and their provenance. Deliberately not inbound_commands: the team''s decisions are visible to a client, Grant''s messages are not.';


--
-- Name: mcp_record_call(text, text, jsonb, text, integer, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.mcp_record_call(p_client_id text, p_tool text, p_arguments jsonb, p_outcome text, p_rows integer DEFAULT 0, p_duration_ms integer DEFAULT NULL::integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
begin
  insert into public.mcp_calls (client_id, tool, arguments, outcome, rows_returned, duration_ms)
  values (p_client_id, p_tool, coalesce(p_arguments, '{}'::jsonb), p_outcome,
          coalesce(p_rows, 0), p_duration_ms);

  update public.mcp_clients
     set last_seen_at = app.now_utc(), calls = calls + 1
   where client_id = p_client_id;
end;
$$;


--
-- Name: mcp_redeem_code(text, text, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.mcp_redeem_code(p_code_sha256 text, p_client_id text, p_redirect_uri text, p_token_sha256 text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  c public.mcp_auth_codes;
  v_name text;
begin
  update public.mcp_auth_codes
     set redeemed_at = app.now_utc()
   where code_sha256 = p_code_sha256
     and redeemed_at is null
     and expires_at > app.now_utc()
     and client_id = p_client_id
     and redirect_uri = p_redirect_uri
  returning * into c;

  if not found then
    return jsonb_build_object('error', 'invalid_grant');
  end if;

  select client_name into v_name
    from public.mcp_oauth_clients where client_id = p_client_id;

  -- One row per OAuth client in `mcp_clients`, reusing the table the endpoint
  -- already authenticates against. A second authentication path would be a
  -- second thing to get wrong, and this one is already tested.
  insert into public.mcp_clients (client_id, display_name, token_sha256, scopes)
  values (p_client_id, coalesce(v_name, 'OAuth client'), p_token_sha256,
          string_to_array(c.scope, ' '))
  on conflict (client_id) do update
    set token_sha256 = excluded.token_sha256,
        display_name = excluded.display_name,
        scopes = excluded.scopes,
        enabled = true,
        disabled_reason = null;

  return jsonb_build_object('ok', true, 'scope', c.scope);
end;
$$;


--
-- Name: mcp_redirects_are_safe(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.mcp_redirects_are_safe() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
begin
  if exists (
    select 1 from unnest(new.redirect_uris) u
     where u !~ '^https://' and u !~ '^http://localhost(:[0-9]+)?(/|$)'
  ) then
    raise exception 'every redirect_uri must be https, or http://localhost for a loopback client'
      using errcode = '23514';
  end if;
  return new;
end;
$_$;


--
-- Name: mcp_register_client(text, text[]); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.mcp_register_client(p_client_name text, p_redirect_uris text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_id text;
  v_name text;
begin
  if coalesce(array_length(p_redirect_uris, 1), 0) = 0 then
    return jsonb_build_object('error', 'invalid_redirect_uri');
  end if;
  if exists (select 1 from unnest(p_redirect_uris) u
              where u !~ '^https://' and u !~ '^http://localhost') then
    return jsonb_build_object('error', 'invalid_redirect_uri');
  end if;

  v_name := coalesce(nullif(trim(p_client_name), ''), 'unnamed client');
  -- Core Postgres, not pgcrypto. See the header.
  v_id := 'mcpc_' || replace(gen_random_uuid()::text, '-', '');

  insert into public.mcp_oauth_clients (client_id, client_name, redirect_uris)
  values (v_id, v_name, p_redirect_uris);

  return jsonb_build_object(
    'client_id', v_id,
    'client_name', v_name,
    'redirect_uris', to_jsonb(p_redirect_uris),
    'token_endpoint_auth_method', 'none',
    'grant_types', jsonb_build_array('authorization_code'),
    'response_types', jsonb_build_array('code')
  );
end;
$$;


--
-- Name: mcp_search(text, text, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.mcp_search(p_query text, p_project text DEFAULT NULL::text, p_limit integer DEFAULT 8) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'document_id', s.document_id,
           'title', s.title,
           'connector', s.connector,
           'project', (select p.slug from public.projects p where p.project_id = s.project_id),
           'rank', s.rank,
           'snippet', s.snippet
         ) order by s.rank desc), '[]'::jsonb)
    from app.search_documents(
           p_query,
           (select p.project_id from public.projects p where p.slug = p_project),
           greatest(1, least(coalesce(p_limit, 8), 25)),
           'any'
         ) s
$$;


--
-- Name: FUNCTION mcp_search(p_query text, p_project text, p_limit integer); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.mcp_search(p_query text, p_project text, p_limit integer) IS 'The same search the office uses, with the same ''any'' matching, so a model asking a question of the corpus gets what a director would get.';


--
-- Name: mcp_staff(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.mcp_staff() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'slug', s.slug, 'name', s.name, 'title', s.title,
           'responsibilities', s.responsibilities, 'expertise', s.expertise
         ) order by s.slug), '[]'::jsonb)
    from public.staff s where s.active
$$;


--
-- Name: model_order(text, integer, integer, numeric, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.model_order(p_kind text, p_window_days integer DEFAULT 30, p_min_tried integer DEFAULT 20, p_floor numeric DEFAULT 0.50, p_explore_hours integer DEFAULT 24) RETURNS TABLE(provider text, model_id text, pricing_prompt text, pricing_completion text, base_url text, secret_ref uuid, is_free boolean, tried bigint, good bigint, rate numeric, standing text, why text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  with seen as (
    select r.provider, r.model_id, r.tried, r.good, r.rate, r.last_tried_at
      from public.model_record r
     where r.kind = p_kind
       and r.last_tried_at >= app.now_utc() - make_interval(days => greatest(p_window_days, 1))
  ),
  judged as (
    select m.provider,
           m.model_id,
           m.pricing_prompt,
           m.pricing_completion,
           m.base_url,
           m.secret_ref,
           m.priority       as provider_priority,
           m.model_priority,
           (m.pricing_prompt = '0' and m.pricing_completion = '0') as is_free,
           coalesce(s.tried, 0) as tried,
           coalesce(s.good, 0)  as good,
           s.rate,
           case
             when coalesce(s.tried, 0) < greatest(p_min_tried, 1) then 'unproven'
             when s.rate >= p_floor then 'good'
             when s.last_tried_at < app.now_utc() - make_interval(hours => greatest(p_explore_hours, 1))
               then 'exploring'
             else 'poor'
           end as standing
      from public.usable_models m
      left join seen s
        on s.provider = m.provider and s.model_id = m.model_id
  )
  select j.provider,
         j.model_id,
         j.pricing_prompt,
         j.pricing_completion,
         j.base_url,
         j.secret_ref,
         j.is_free,
         j.tried,
         j.good,
         j.rate,
         j.standing,
         case j.standing
           when 'unproven' then
             format('no record yet for %s (%s of %s calls needed)',
                    p_kind, j.tried, greatest(p_min_tried, 1))
           when 'good' then
             format('%s%% good on %s over %s calls',
                    round(j.rate * 100), p_kind, j.tried)
           when 'exploring' then
             format('%s%% good on %s over %s calls, but untried for %s hours - taking a turn to see if it has improved',
                    round(j.rate * 100), p_kind, j.tried, greatest(p_explore_hours, 1))
           else
             format('%s%% good on %s over %s calls, below the %s%% floor - moved to the back',
                    round(j.rate * 100), p_kind, j.tried, round(p_floor * 100))
         end as why
    from judged j
   /*
     The registry's order, with exactly one thing inserted: a poor record sends
     a model to the back. Nothing is ever moved FORWARD, so no model is tried
     earlier than the registry would have tried it and a demotion can never
     cause a paid call that would not have happened anyway.

     `provider_priority` stays outermost and `model_priority` keeps its place
     below the quality term, so the certified chain survives intact among every
     model that is not demoted.
   */
   order by j.provider_priority,
            (case when j.standing = 'poor' then 1 else 0 end),
            j.model_priority,
            j.model_id;
$$;


--
-- Name: FUNCTION model_order(p_kind text, p_window_days integer, p_min_tried integer, p_floor numeric, p_explore_hours integer); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.model_order(p_kind text, p_window_days integer, p_min_tried integer, p_floor numeric, p_explore_hours integer) IS 'Which models to try for one kind of work, in order, each with the reason (#127, 0394; corrected 0396). Quality may only DEMOTE - a poor record for this kind goes to the back and nothing is ever moved forward, so no model is tried earlier than the registry would have tried it and no demotion can cause a paid call that would not have happened. The certified chain in model_priority is otherwise untouched. A poor model returns to its place once untried for the explore window, so a bad afternoon cannot retire it.';


--
-- Name: now_utc(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.now_utc() RETURNS timestamp with time zone
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
  select now()
$$;


--
-- Name: FUNCTION now_utc(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.now_utc() IS 'Transaction timestamp. Every row written by one transaction shares it, so a single logical event does not disagree with itself about when it occurred.';


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: model_prices; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.model_prices (
    model_id text NOT NULL,
    effective_from timestamp with time zone DEFAULT app.now_utc() NOT NULL,
    input_usd_per_mtok numeric(12,4) NOT NULL,
    output_usd_per_mtok numeric(12,4) NOT NULL,
    source_url text NOT NULL,
    note text,
    CONSTRAINT model_prices_input_usd_per_mtok_check CHECK ((input_usd_per_mtok >= (0)::numeric)),
    CONSTRAINT model_prices_output_usd_per_mtok_check CHECK ((output_usd_per_mtok >= (0)::numeric))
);

ALTER TABLE ONLY public.model_prices FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE model_prices; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.model_prices IS 'Published prices per million tokens, used ONLY to produce the modelled cost column. Never used to produce a measured one: what was actually charged is in inference_usage.cost_usd and comes from the provider (§11).';


--
-- Name: model_price_at(text, timestamp with time zone); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.model_price_at(p_model text, p_when timestamp with time zone) RETURNS public.model_prices
    LANGUAGE sql STABLE
    AS $$
  select p.* from public.model_prices p
   where p.model_id in (p_model, '')
     and p.effective_from <= p_when
   -- Exact model beats fallback; newer price beats older.
   order by (p.model_id = '')::int, p.effective_from desc
   limit 1
$$;


--
-- Name: model_speed(integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.model_speed(p_days integer DEFAULT 7) RETURNS TABLE(model_id text, attempts integer, median_ms integer, worst_ms integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select u.model_id,
         count(*)::int as attempts,
         (percentile_cont(0.5) within group (order by u.latency_ms))::int as median_ms,
         max(u.latency_ms)::int as worst_ms
    from public.inference_usage u
   where u.latency_ms is not null
     and u.outcome = 'ok'
     and u.occurred_at > app.now_utc() - make_interval(days => greatest(1, p_days))
   group by u.model_id
   order by 3
$$;


--
-- Name: FUNCTION model_speed(p_days integer); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.model_speed(p_days integer) IS 'Median and worst latency per model over recent successful calls. The measurement behind any future decision about which model answers Grant.';


--
-- Name: morning_briefing_facts(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.morning_briefing_facts() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with
  z as (select app.grant_timezone() as tz),
  -- The local day this briefing is FOR, which is not necessarily today in UTC.
  d as (select (app.now_utc() at time zone (select tz from z))::date as today),

  /*
    What needs him. First, because it is the only category he can unblock —
    the `needs_me` view's own comment says so, and it is not capped there
    deliberately: "a view that silently returned 7 of 40 would hide the thing
    worth knowing."
  */
  waiting as (
    select coalesce(jsonb_agg(jsonb_build_object(
             'what', n.requested_action,
             'why', n.why_needed,
             'project', p.name,
             'overdue', n.overdue,
             'deadline', n.real_deadline,
             'if_delayed', n.consequences_of_delay,
             'work_continues', n.work_can_continue
           ) order by n.overdue desc, n.real_deadline nulls last, n.created_at), '[]'::jsonb) as v
      from public.needs_me n
      left join public.projects p on p.project_id = n.project_id
  ),

  -- What the office did while he slept. Fixtures excluded — 264 harness
  -- failures were once reported to him as the office falling over.
  overnight as (
    select jsonb_build_object(
             'finished', count(*) filter (where j.state = 'complete'),
             'failed',   count(*) filter (where j.state = 'failed'),
             'still_going', count(*) filter (where j.state in ('queued', 'running'))
           ) as v
      from public.jobs j
     where not j.is_fixture
       and j.updated_at >= app.now_utc() - interval '18 hours'
  ),

  -- What is stuck, and for how long. A blocked job with no stated reason is
  -- the failure Active Jobs was built to fix, so the reason comes with it.
  stuck as (
    select coalesce(jsonb_agg(jsonb_build_object(
             'kind', j.kind,
             'project', p.name,
             'since_hours', round(extract(epoch from (app.now_utc() - j.updated_at)) / 3600),
             'why', coalesce(nullif(btrim(j.state_reason), ''), 'no reason recorded')
           ) order by j.updated_at), '[]'::jsonb) as v
      from public.jobs j
      left join public.projects p on p.project_id = j.project_id
     where not j.is_fixture
       and j.state in ('waiting_external', 'waiting_user', 'retrying', 'paused')
       and j.updated_at < app.now_utc() - interval '2 hours'
  ),

  -- His day. The calendar is already refreshed hourly by its own duty.
  diary as (
    select coalesce(jsonb_agg(jsonb_build_object(
             'what', c.summary,
             'at', c.starts_at
           ) order by c.starts_at), '[]'::jsonb) as v
      from public.calendar_events c, z, d
     where (c.starts_at at time zone z.tz)::date = d.today
  ),

  /*
    What the office has asked to be able to reach (#53).

    Its own section rather than a recommendation, because it is a different
    kind of sentence: a recommendation is something he might act on, and this
    is a question waiting on an answer only he can give. The needs_me argument
    applies — burying a request under a status summary is how it gets missed.
  */
  wanted as (
    select coalesce(jsonb_agg(jsonb_build_object(
             'tool', w.tool,
             'asked_by', w.asked_by,
             'what_for', w.what_for,
             'exists_yet', w.exists_yet,
             'days', round(extract(epoch from (app.now_utc() - w.raised_at)) / 86400)
           ) order by w.raised_at), '[]'::jsonb) as v
      from app.reach_wanted() w
  ),

  /*
    Recommendations, from the one place that computes them (#52), already
    ranked and already stripped of anything he has dismissed.
  */
  noticed as (
    select coalesce(jsonb_agg(jsonb_build_object(
             'kind', n.kind,
             'body', n.body,
             'because', n.because,
             'weight', n.weight
           ) order by n.weight desc), '[]'::jsonb) as v
      from app.notice(6) n
  )

  select jsonb_build_object(
    'for_date', (select today from d),
    'timezone', (select tz from z),
    'generated_at', app.now_utc(),
    'waiting_on_you', (select v from waiting),
    'overnight', (select v from overnight),
    'stuck', (select v from stuck),
    'diary', (select v from diary),
    'noticed', (select v from noticed),
    'wanted', (select v from wanted),
    /*
      How much is being held back, and how old the oldest is (#272).

      `app.needs_me_pressure` has existed with no caller at all. The briefing
      names up to four things waiting and says how many are past a deadline --
      and `needs_me` is CAPPED, so anything beyond the cap is silently absent,
      and a request with no formal deadline ages invisibly however long it
      sits. Both are things a person needs to be told and neither was said.
    */
    'pressure', (select jsonb_build_object(
                          'open_items', p.open_items,
                          'cap', p.cap,
                          'suppressed', p.suppressed,
                          'oldest_days', p.oldest_days)
                   from app.needs_me_pressure() p)
  )
$$;


--
-- Name: FUNCTION morning_briefing_facts(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.morning_briefing_facts() IS 'Everything the morning briefing is allowed to say, counted rather than inferred (#56). Recommendations come from app.notice() (#52) and open requests for reach from app.reach_wanted() (#53).';


--
-- Name: my_task_add(text, text, date, timestamp with time zone, integer, text, text[], text, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.my_task_add(p_title text, p_detail text DEFAULT ''::text, p_due_on date DEFAULT NULL::date, p_remind_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_priority integer DEFAULT 100, p_project text DEFAULT NULL::text, p_labels text[] DEFAULT NULL::text[], p_parent text DEFAULT NULL::text, p_job uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_title text := btrim(coalesce(p_title, ''));
  v_project uuid;
  v_id uuid;
  v_parent uuid;
  v_why text;
begin
  if v_title = '' then
    return jsonb_build_object('ok', false, 'error', 'a task needs a title');
  end if;

  if coalesce(p_parent, '') <> '' then
    begin
      v_parent := p_parent::uuid;
    exception when others then
      return jsonb_build_object('ok', false, 'error', 'that is not a task id to put this under');
    end;
    v_why := app.task_parent_ok(v_parent);
    if v_why is not null then
      return jsonb_build_object('ok', false, 'error', v_why);
    end if;
  end if;

  if coalesce(p_project, '') <> '' then
    select project_id into v_project from public.projects
     where slug = p_project and status <> 'archived';
    if v_project is null then
      -- Named, rather than silently filed with no project: a task that quietly
      -- lands in the inbox when Grant said which project it belongs to is a
      -- task he will look for in the wrong place.
      return jsonb_build_object('ok', false,
        'error', format('no active project called %s', p_project));
    end if;
  elsif v_parent is not null then
    /*
      A subtask inherits its parent's project unless told otherwise. Without
      this a subtask of a project task lands in the Inbox, away from the
      parent it belongs to, which is how a relationship becomes a filing
      error.
    */
    select t.project_id into v_project from public.tasks t where t.task_id = v_parent;
  end if;

  insert into public.tasks
    (project_id, title, detail, state, priority, due_on, remind_at,
     assigned_to_human, added_by, labels, parent_task_id, job_id)
  values (v_project, v_title, coalesce(p_detail, ''), 'todo',
          greatest(coalesce(p_priority, 100), 1), p_due_on, p_remind_at,
          true, 'grant',
          coalesce((select array(select distinct lower(btrim(x))
                                   from unnest(p_labels) x
                                  where btrim(x) <> '' order by 1)), '{}'::text[]),
          v_parent, p_job)
  returning task_id into v_id;

  return jsonb_build_object('ok', true, 'id', v_id, 'title', v_title,
    'project', coalesce(p_project, ''), 'parent', v_parent);
end;
$$;


--
-- Name: my_task_delete(text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.my_task_delete(p_task_id text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_id       uuid;
  v_title    text;
  v_children int;
begin
  begin
    v_id := p_task_id::uuid;
  exception when others then
    return jsonb_build_object('ok', false, 'error', 'that is not a task id');
  end;

  select t.title into v_title
    from public.tasks t
   where t.task_id = v_id and t.assigned_to_human;

  /*
    0517. Which of the two it is, rather than both at once. Said about a
    task that is already gone, the combined sentence implied the row might
    be the office's.
  */
  if v_title is null
     and not exists (select 1 from public.tasks t where t.task_id = v_id) then
    return jsonb_build_object('ok', false, 'gone', true,
      'error', 'that task is already gone');
  end if;
  if v_title is null then
    /*
      Named rather than silent, and scoped to MINE. The office's own project
      tasks are not Grant's to delete from this door — #259's second invariant
      is that the two are separate, and a delete that reached across it would
      be the one place the separation stopped mattering.
    */
    return jsonb_build_object('ok', false,
      'error', 'no personal task by that id — the team''s own work is not deleted from here');
  end if;

  select count(*)::int into v_children
    from public.tasks c where c.parent_task_id = v_id;

  delete from public.tasks where task_id = v_id;

  return jsonb_build_object(
    'ok', true, 'deleted', v_title,
    -- Said out loud, because the foreign key takes them and a subtask that
    -- disappears without being mentioned is data loss that looks like a bug.
    'children_deleted', v_children,
    'reason', p_reason);
end
$$;


--
-- Name: my_task_recent(interval); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.my_task_recent(p_within interval DEFAULT '00:30:00'::interval) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case when t.task_id is null then null else jsonb_build_object(
           'id', t.task_id,
           'title', t.title,
           'due_on', t.due_on,
           'priority', t.priority,
           'created_at', t.created_at) end
    from (
      select *
        from public.tasks
       where assigned_to_human
         and state not in ('done', 'cancelled')
         and not app.harness_task(is_fixture, job_id)
         and created_at >= app.now_utc() - p_within
       /*
         `seq`, then the clock. The sequence is assigned at INSERT so it is
         correct even inside one statement; `created_at` is kept as the second
         key only so a row that predates the column still sorts sensibly.
       */
       order by seq desc nulls last, created_at desc
       limit 1
    ) t
$$;


--
-- Name: FUNCTION my_task_recent(p_within interval); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.my_task_recent(p_within interval) IS 'The task a follow-up means by "that" (#259): the most recently created open personal task inside a short window, or null. Deliberately not a title match — a fuzzy match is one bad guess away from editing the wrong row.';


--
-- Name: my_task_reparent(text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.my_task_reparent(p_task_id text, p_parent text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_id uuid;
  v_parent uuid;
  v_why text;
begin
  begin
    v_id := p_task_id::uuid;
  exception when others then
    return jsonb_build_object('ok', false, 'error', 'that is not a task id');
  end;
  if not exists (select 1 from public.tasks t
                  where t.task_id = v_id and t.assigned_to_human) then
    return jsonb_build_object('ok', false, 'error', 'no personal task by that id');
  end if;

  if coalesce(p_parent, '') <> '' then
    begin
      v_parent := p_parent::uuid;
    exception when others then
      return jsonb_build_object('ok', false, 'error', 'that is not a task id to put this under');
    end;
    v_why := app.task_parent_ok(v_parent, v_id);
    if v_why is not null then
      return jsonb_build_object('ok', false, 'error', v_why);
    end if;
  end if;

  update public.tasks set parent_task_id = v_parent where task_id = v_id;
  return jsonb_build_object('ok', true, 'id', v_id, 'parent', v_parent);
end
$$;


--
-- Name: my_task_set(text, text[], timestamp with time zone, interval, text, text[], text, text, integer, date, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.my_task_set(p_task_id text, p_labels text[] DEFAULT NULL::text[], p_remind_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_repeat_every interval DEFAULT NULL::interval, p_repeat_from text DEFAULT NULL::text, p_clear text[] DEFAULT '{}'::text[], p_title text DEFAULT NULL::text, p_detail text DEFAULT NULL::text, p_priority integer DEFAULT NULL::integer, p_due_on date DEFAULT NULL::date, p_project text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_id uuid;
  v_clear text[] := coalesce(p_clear, '{}'::text[]);
  v_project uuid;
  v_title text := nullif(btrim(coalesce(p_title, '')), '');
begin
  begin
    v_id := p_task_id::uuid;
  exception when others then
    return jsonb_build_object('ok', false, 'error', 'that is not a task id');
  end;
  if not exists (select 1 from public.tasks where task_id = v_id) then
    return jsonb_build_object('ok', false, 'error', 'no task by that id');
  end if;
  if p_repeat_from is not null and p_repeat_from not in ('due', 'done') then
    return jsonb_build_object('ok', false,
      'error', 'a repeat runs from its due date or from when it was last done');
  end if;
  /*
    A title may be CHANGED and may not be emptied.

    `tasks.title` is not null, and an update that silently kept the old title
    when the box was cleared would look like the save failing. Said instead.
  */
  if p_title is not null and v_title is null then
    return jsonb_build_object('ok', false, 'error', 'a task needs a title');
  end if;
  /*
    The vocabulary `my_task_add` already uses, read rather than invented.

    `tasks.priority` is an integer where LOWER is more important and 100 is the
    default; the rows in the table today are 20 and 100. A first draft of this
    validated 1..5, which is a different scale with the same name -- 0311 spent
    a migration undoing two words for one thing, and this would have been two
    meanings for one column. `my_task_add` floors at 1 and so does this.
  */
  if p_priority is not null and p_priority < 1 then
    return jsonb_build_object('ok', false,
      'error', 'priority is a number from 1 upwards, where 1 is the most important');
  end if;

  /*
    The project is named by SLUG, the way `my_task_add` takes it and the way
    Grant's vocabulary works -- a uuid is not something anybody types. An
    unknown slug is refused by name rather than silently leaving the task where
    it was, which is 0350's delete that matched nothing and reported success.
  */
  if p_project is not null and btrim(p_project) <> '' then
    select project_id into v_project from public.projects
     where slug = lower(btrim(p_project)) and status = 'active';
    if v_project is null then
      return jsonb_build_object('ok', false,
        'error', format('there is no active project called %s', btrim(p_project)));
    end if;
  end if;

  update public.tasks set
    title = coalesce(v_title, title),
    /*
      `tasks.detail` is NOT NULL with a default of '', so clearing it is '' and
      not null. CLAUDE.md records the cost of the same column's shape once
      already: a sentinel satisfies the constraint and makes every `coalesce`
      against it dead code.
    */
    detail = case when 'detail' = any (v_clear) then ''
                  else coalesce(nullif(btrim(coalesce(p_detail, '')), ''), detail) end,
    priority = coalesce(p_priority, priority),
    due_on = case when 'due_on' = any (v_clear) then null
                  else coalesce(p_due_on, due_on) end,
    project_id = case when 'project' = any (v_clear) then null
                      else coalesce(v_project, project_id) end,
    labels = case
               when 'labels' = any (v_clear) then '{}'::text[]
               when p_labels is null then labels
               else (select array(select distinct lower(btrim(x)) from unnest(p_labels) x
                                   where btrim(x) <> '' order by 1))
             end,
    reminded_at = case when 'remind_at' = any (v_clear) or p_remind_at is not null then null else reminded_at end,
    remind_at = case when 'remind_at' = any (v_clear) then null
                     else coalesce(p_remind_at, remind_at) end,
    repeat_every = case when 'repeat' = any (v_clear) then null
                        else coalesce(p_repeat_every, repeat_every) end,
    repeat_from = case when 'repeat' = any (v_clear) then null
                       when p_repeat_every is not null then coalesce(p_repeat_from, 'due')
                       else coalesce(p_repeat_from, repeat_from) end,
    updated_at = app.now_utc()
   where task_id = v_id;

  return (select jsonb_build_object('ok', true, 'id', v_id,
            'title', t.title,
            'detail', t.detail,
            'priority', t.priority,
            'due_on', t.due_on,
            'project', (select slug from public.projects where project_id = t.project_id),
            'labels', to_jsonb(t.labels),
            'remind_at', t.remind_at,
            'repeats', case when t.repeat_every is null then null
                       else jsonb_build_object('every', t.repeat_every::text,
                                               'from', t.repeat_from) end)
            from public.tasks t where t.task_id = v_id);
end;
$$;


--
-- Name: my_tasks(text, integer, text, text, boolean); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.my_tasks(p_bucket text DEFAULT 'today'::text, p_limit integer DEFAULT 200, p_query text DEFAULT NULL::text, p_sort text DEFAULT 'smart'::text, p_include_harness boolean DEFAULT false) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with mine as (
    select t.*,
           p.name as project_name,
           p.slug as project_slug
      from public.tasks t
      left join public.projects p on p.project_id = t.project_id
     /*
       THE BOUNDARY, in one place.

       ADR-0041: one table means one filter to get wrong, and the failure is
       asymmetric -- the office's own work appearing in Grant's personal list
       is what stops him trusting the list. Every bucket below filters this
       CTE, so there is exactly one place this can be forgotten.
     */
     where t.assigned_to_human
       and (p_include_harness or not app.harness_task(t.is_fixture, t.job_id))
  ), matched as (
    /*
      The search NARROWS a bucket rather than replacing it.

      A task app where typing in the box throws away "overdue" is one where you
      cannot answer "what am I late on about the pricing". It reads the title,
      the notes and the labels -- the three places a person would look -- and
      an empty box changes nothing, so the behaviour with no search is exactly
      what it was before this migration.
    */
    select * from mine m
     where coalesce(btrim(p_query), '') = ''
        or position(lower(btrim(p_query)) in lower(coalesce(m.title, ''))) > 0
        or position(lower(btrim(p_query)) in lower(coalesce(m.detail, ''))) > 0
        or exists (select 1 from unnest(coalesce(m.labels, '{}'::text[])) l
                    where position(lower(btrim(p_query)) in lower(l)) > 0)
  ), picked as (
    select * from matched m
     where case lower(coalesce(p_bucket, 'today'))
       -- Nothing scheduled and no project: the pile you have not sorted yet.
       when 'inbox' then m.state <> 'done' and m.due_on is null and m.project_id is null
       when 'today' then m.state <> 'done'
            and (m.due_on <= (app.now_utc() at time zone 'UTC')::date
                 or m.remind_at <= app.now_utc())
       when 'upcoming' then m.state <> 'done'
            and m.due_on > (app.now_utc() at time zone 'UTC')::date
       when 'overdue' then m.state <> 'done'
            and m.due_on < (app.now_utc() at time zone 'UTC')::date
       when 'unscheduled' then m.state <> 'done' and m.due_on is null
       when 'done' then m.state = 'done'
       when 'all' then true
       else m.state <> 'done'
     end
     order by
       /*
         `smart` is the default and is what this reader has always done:
         overdue first, then by date, then by priority. A list ordered by
         priority alone buries a thing due today under an important thing due
         next month, which is the complaint every task app eventually gets --
         so priority-first is OFFERED and is not the default.

         An unrecognised sort falls to `smart` rather than erroring. A list
         that refuses to render because a query string was wrong is worse than
         one that renders in the order it always did.
       */
       case when lower(coalesce(p_sort, 'smart')) = 'priority' then m.priority end nulls last,
       case when lower(coalesce(p_sort, 'smart')) = 'title' then lower(m.title) end nulls last,
       case when lower(coalesce(p_sort, 'smart')) = 'created' then m.created_at end desc nulls last,
       (m.due_on is null),
       m.due_on,
       m.priority,
       m.created_at
     limit greatest(coalesce(p_limit, 200), 1)
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', k.task_id,
           'title', k.title,
           'detail', k.detail,
           'state', k.state,
           'priority', k.priority,
           'due_on', k.due_on,
           'starts_on', k.starts_on,
           'remind_at', k.remind_at,
           'labels', to_jsonb(k.labels),
           'repeats', case when k.repeat_every is null then null
                      else jsonb_build_object('every', k.repeat_every::text,
                                              'from', k.repeat_from) end,
           'project', case when k.project_id is null then null
                      else jsonb_build_object('slug', k.project_slug, 'name', k.project_name) end,
           -- What the office is waiting on, if this exists because a job is
           -- blocked (#259's human-action bridge).
           'for_job', k.job_id,
           'parent', k.parent_task_id,
           -- How many open children this task has, so a parent can say so
           -- rather than a subtask being a relationship nothing renders.
           'children', (select count(*) from public.tasks c
                         where c.parent_task_id = k.task_id and c.state <> 'done'),
           'overdue', k.state <> 'done' and k.due_on is not null
                      and k.due_on < (app.now_utc() at time zone 'UTC')::date,
           /*
             0515. The children themselves, not only how many. One level,
             because 0514 refuses to nest further, and capped so a parent
             with fifty is a project rather than a payload.
           */
           'subtasks', (select coalesce(jsonb_agg(jsonb_build_object(
                             'id', c.task_id, 'title', c.title,
                             'state', c.state,
                             'done', c.state = 'done',
                             'due_on', c.due_on)
                             order by (c.state = 'done'), c.due_on nulls last,
                                      c.priority, c.created_at), '[]'::jsonb)
                         from public.tasks c
                        where c.parent_task_id = k.task_id
                        limit 20),
           'done_at', k.done_at
         )), '[]'::jsonb)
    from picked k
$$;


--
-- Name: FUNCTION my_tasks(p_bucket text, p_limit integer, p_query text, p_sort text, p_include_harness boolean); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.my_tasks(p_bucket text, p_limit integer, p_query text, p_sort text, p_include_harness boolean) IS 'Grant''s personal list. p_include_harness is for the harness only and is not exposed publicly (0533).';


--
-- Name: my_tasks_counts(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.my_tasks_counts() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with mine as (
    select t.* from public.tasks t
     where t.assigned_to_human and not app.harness_task(t.is_fixture, t.job_id)
  ), today as (select (app.now_utc() at time zone 'UTC')::date as d)
  select jsonb_build_object(
    'inbox', (select count(*) from mine m where m.state <> 'done'
               and m.due_on is null and m.project_id is null),
    'today', (select count(*) from mine m, today
               where m.state <> 'done'
                 and (m.due_on <= today.d or m.remind_at <= app.now_utc())),
    'upcoming', (select count(*) from mine m, today
                  where m.state <> 'done' and m.due_on > today.d),
    'overdue', (select count(*) from mine m, today
                 where m.state <> 'done' and m.due_on < today.d),
    'unscheduled', (select count(*) from mine m where m.state <> 'done' and m.due_on is null),
    'done', (select count(*) from mine m where m.state = 'done'),
    'all', (select count(*) from mine m)
  )
$$;


--
-- Name: needs_me_cap(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.needs_me_cap() RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(
    (select (value #>> '{}')::integer from public.system_config
      where key = 'ui.needs_me_cap'),
    7);
$$;


--
-- Name: needs_me_pressure(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.needs_me_pressure() RETURNS TABLE(open_items integer, cap integer, suppressed integer, oldest_days numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    count(*)::int,
    app.needs_me_cap(),
    greatest(count(*)::int - app.needs_me_cap(), 0),
    coalesce(round(extract(epoch from (app.now_utc() - min(created_at))) / 86400, 1), 0)
  from public.blockers where state = 'open';
$$;


--
-- Name: normalise_name(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.normalise_name(p_text text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
  select nullif(
    regexp_replace(
      regexp_replace(
        regexp_replace(
          trim(lower(coalesce(p_text, ''))),
          '^the\s+', ''
        ),
        '\s+(project|app|application)$', ''
      ),
      '[^a-z0-9]+', ' ', 'g'
    ),
    ''
  )
$_$;


--
-- Name: FUNCTION normalise_name(p_text text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.normalise_name(p_text text) IS 'Lowercase, de-punctuate, and drop the words people add and drop without meaning anything by them. Immutable, so a generated column can use it.';


--
-- Name: normalise_reference_url(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.normalise_reference_url(p_url text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
  select regexp_replace(
           regexp_replace(
             regexp_replace(lower(btrim(coalesce(p_url, ''))), '^https?://', ''),
             '^www\.', ''),
           '/+$', '')
$_$;


--
-- Name: notebook_allowance(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.notebook_allowance(p_operation text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_hours    integer := coalesce((select value::text::integer from public.system_config where key = 'notebook.window_hours'), 5);
  v_window   integer := coalesce((select value::text::integer from public.system_config where key = 'notebook.window_units'), 40);
  v_week     integer := coalesce((select value::text::integer from public.system_config where key = 'notebook.week_units'), 300);
  v_measured boolean := coalesce((select value::text::boolean from public.system_config where key = 'notebook.ceiling_is_measured'), false);
  v_spent_w  integer;
  v_spent_7  integer;
  v_cost     integer;
  v_blocked  timestamptz;
  v_resets   timestamptz;
begin
  select coalesce(sum(units), 0) into v_spent_w
    from public.notebook_spend
   where succeeded and occurred_at > now() - make_interval(hours => v_hours);

  select coalesce(sum(units), 0) into v_spent_7
    from public.notebook_spend
   where succeeded and occurred_at > now() - interval '7 days';

  select units into v_cost
    from public.notebook_operation_cost where operation = p_operation;

  -- A refusal Google dated is authoritative until that moment, whatever our
  -- own arithmetic says. Their no beats our estimate.
  select resets_at into v_blocked
    from public.notebook_refusals
   where resets_at is not null and resets_at > now()
   order by resets_at desc limit 1;

  -- When the window turns over, on our own reckoning: the oldest spend inside
  -- the window ages out first, so that is the soonest anything frees up.
  select occurred_at + make_interval(hours => v_hours) into v_resets
    from public.notebook_spend
   where succeeded and occurred_at > now() - make_interval(hours => v_hours)
   order by occurred_at asc limit 1;

  return jsonb_build_object(
    'window_hours', v_hours,
    'window_spent', v_spent_w,
    'window_ceiling', v_window,
    'window_left', greatest(v_window - v_spent_w, 0),
    'week_spent', v_spent_7,
    'week_ceiling', v_week,
    'week_left', greatest(v_week - v_spent_7, 0),
    'ceiling_is_measured', v_measured,
    'operation', p_operation,
    'operation_cost', v_cost,
    'blocked_until', v_blocked,
    'window_resets_at', v_resets,
    'allowed', (
      v_blocked is null
      and (v_cost is null or v_spent_w + v_cost <= v_window)
      and (v_cost is null or v_spent_7 + v_cost <= v_week)
    ),
    -- Everything above is OUR arithmetic. Said here so no caller can present
    -- it as Google's without going out of its way.
    'source', 'our own ledger — Google exposes no usage API'
  );
end;
$$;


--
-- Name: notebook_chat_allowed(boolean); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.notebook_chat_allowed(p_urgent boolean DEFAULT false) RETURNS boolean
    LANGUAGE plpgsql STABLE
    AS $$
declare
  v_budget record;
  v_spent integer;
begin
  select * into v_budget from public.notebook_budget;

  -- No measured budget means no basis for spending. Refusing is the §11-safe
  -- answer: inventing a default here would be the hard-coding the whole table
  -- exists to prevent.
  if v_budget is null then
    return false;
  end if;

  select count(*)::integer into v_spent
  from public.notebook_chat_usage
  where occurred_at >= date_trunc('day', app.now_utc());

  -- Urgent work may draw on the reserve; ordinary work may not. That is what
  -- makes the reserve a reserve rather than a smaller budget.
  if p_urgent then
    return v_spent < v_budget.daily_chat_budget;
  end if;
  return v_spent < (v_budget.daily_chat_budget - v_budget.chat_reserve);
end;
$$;


--
-- Name: FUNCTION notebook_chat_allowed(p_urgent boolean); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.notebook_chat_allowed(p_urgent boolean) IS 'Budget check against the DERIVED daily allowance. Urgent work may draw on the reserve; ordinary work may not, which is what makes it a reserve.';


--
-- Name: notebook_record_refusal(text, text, timestamp with time zone); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.notebook_record_refusal(p_operation text, p_detail text, p_resets_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_hours integer := coalesce((select value::text::integer from public.system_config where key = 'notebook.window_hours'), 5);
  v_spent integer;
  v_ceiling integer := coalesce((select value::text::integer from public.system_config where key = 'notebook.window_units'), 40);
  v_lowered boolean := false;
begin
  select coalesce(sum(units), 0) into v_spent
    from public.notebook_spend
   where succeeded and occurred_at > now() - make_interval(hours => v_hours);

  insert into public.notebook_refusals (operation, detail, window_spend, resets_at)
  values (p_operation, left(p_detail, 500), v_spent, p_resets_at);

  -- The measurement. We were refused having spent this much, so the real
  -- ceiling is at most this much — and a configured ceiling above it is a
  -- ceiling that will let us be refused again tomorrow.
  --
  -- Only ever downward, and only from evidence. Raising it would require a
  -- successful operation ABOVE the ceiling, which cannot happen because the
  -- ceiling prevents it: the loop is one-way by construction, and a human
  -- raises it in the front end when they think we are being too careful.
  if v_spent > 0 and v_spent < v_ceiling then
    update public.system_config set value = to_jsonb(v_spent) where key = 'notebook.window_units';
    update public.system_config set value = to_jsonb(true) where key = 'notebook.ceiling_is_measured';
    v_lowered := true;
  end if;

  return jsonb_build_object(
    'window_spend', v_spent, 'ceiling_lowered_to', case when v_lowered then v_spent end,
    'resets_at', p_resets_at
  );
end;
$$;


--
-- Name: notebook_record_spend(text, text, uuid, uuid, boolean); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.notebook_record_spend(p_operation text, p_notebook text DEFAULT NULL::text, p_project uuid DEFAULT NULL::uuid, p_job uuid DEFAULT NULL::uuid, p_succeeded boolean DEFAULT true) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_units integer;
begin
  select units into v_units from public.notebook_operation_cost where operation = p_operation;
  if v_units is null then
    -- An operation with no price is still an operation. Charged at the median
    -- rather than free: a free unknown is how a meter stops meaning anything.
    v_units := 5;
  end if;

  insert into public.notebook_spend (operation, units, notebook_ref, project_id, job_id, succeeded)
  values (p_operation, v_units, p_notebook, p_project, p_job, p_succeeded);

  return v_units;
end;
$$;


--
-- Name: notice(integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.notice(p_limit integer DEFAULT 12) RETURNS TABLE(kind text, project_id uuid, subject_ref text, body text, because jsonb, weight integer, offer_kind text, offer_args jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with live as (
    select p.project_id, p.name, p.updated_at
      from public.projects p
     where p.status = 'active' and not p.is_fixture
  ),

  /*
    Everything settled recently enough to still count as answered.

    Keyed on the identity, never on the wording — that is the whole point of
    the shape 0210 chose. `state = 'open'` is in here too: an observation
    already sitting unanswered on the dashboard should not be raised a second
    time as though it were new.
  */
  answered as (
    select s.kind, coalesce(s.project_id::text, '') as pid, s.subject_ref
      from public.suggestions s
     where s.state = 'open'
        or (s.state = 'dismissed'
            and s.settled_at > app.now_utc()
                               - (greatest(s.dismissals, 1) * interval '14 days'))
        or (s.state = 'acted'
            and s.settled_at > app.now_utc() - interval '7 days')
  ),

  quiet as (
    select 'project_quiet'::text as kind, l.project_id, ''::text as subject_ref,
           format('%s has not moved in %s days, with %s open %s.',
                  l.name,
                  round(extract(epoch from (app.now_utc() - l.updated_at)) / 86400),
                  t.open_count,
                  case when t.open_count = 1 then 'task' else 'tasks' end) as body,
           jsonb_build_object('days',
             round(extract(epoch from (app.now_utc() - l.updated_at)) / 86400),
             'open_tasks', t.open_count) as because,
           55 as weight,
           null::text as offer_kind, null::jsonb as offer_args
      from live l
      join lateral (
        select count(*) filter (where tk.state in ('todo', 'doing', 'blocked')) as open_count
          from public.tasks tk
         where tk.project_id = l.project_id and not tk.is_fixture
      ) t on true
     where l.updated_at < app.now_utc() - interval '14 days'
       and t.open_count > 0
  ),

  looming as (
    select 'deadline_unowned'::text, tk.project_id, tk.task_id::text,
           format('“%s” is due %s and nobody is on it.',
                  left(tk.title, 90), to_char(tk.due_on, 'FMDay DD Mon')),
           jsonb_build_object('due_on', tk.due_on),
           80,
           null::text, null::jsonb
      from public.tasks tk
      join live l on l.project_id = tk.project_id
     where not tk.is_fixture
       and tk.state in ('todo', 'doing')
       and tk.due_on is not null
       and tk.due_on <= (app.now_utc() at time zone app.grant_timezone())::date + 7
       and tk.assignee_staff is null
       and not tk.assigned_to_human
  ),

  idle_source as (
    select 'source_unused'::text, a.project_id, a.attachment_id::text,
           format('%s has been attached to %s since %s and has produced nothing.',
                  coalesce(nullif(a.display_name, ''), a.connector),
                  l.name, to_char(a.created_at, 'FMDD Mon')),
           jsonb_build_object('connector', a.connector,
                              'attached_days',
                              round(extract(epoch from (app.now_utc() - a.created_at)) / 86400)),
           45,
           null::text, null::jsonb
      from public.project_attachments a
      join live l on l.project_id = a.project_id
     where a.enabled
       and a.created_at < app.now_utc() - interval '7 days'
       and not exists (
         select 1 from public.documents d
          where d.project_id = a.project_id
            and coalesce(d.connector, '') = a.connector
       )
  ),

  /*
    A failure the office has seen before (#132, migration 0274).

    #132: *"this has failed the same way eleven times in three days is a
    recommendation, and it is exactly the kind of thing app.notice() was built
    to surface."* Until this branch existed, `failure_signatures` was a table
    nobody read -- the mechanism built and the mouth forgotten, which is #72's
    shape and which this repository keeps producing.

    Weighted at 75: below a deadline nobody owns, above a quiet project. A
    thing that keeps breaking is more urgent than a thing that is merely still,
    and less urgent than a date that is about to pass.

    Only three or more, and only within a fortnight. Two is a coincidence and
    a month-old signature is history rather than news.
  */
  repeated_failure as (
    select 'failure_repeats'::text, null::uuid,
           -- Kind and class, never the message. The signature IS the identity,
           -- so the suggestion is answered per signature rather than per job.
           format('%s:%s%s', f.job_kind, f.error_class,
                  case when f.subject = '' then '' else ':' || f.subject end),
           format('%s has failed the same way (%s) %s times since %s. Nothing about '
                  || 'the next attempt will be different.',
                  f.job_kind, replace(f.error_class, '_', ' '), f.seen,
                  to_char(f.first_seen, 'FMDD Mon')),
           jsonb_build_object('times', f.seen, 'class', f.error_class,
                              'since', f.first_seen, 'last_job', f.last_job_id),
           75,
           null::text, null::jsonb
      from app.recurring_failures(3, 14) f
  ),

  blocked_capability as (
    select 'capability_missing'::text, null::uuid, i.needed,
           format('We have been unable to %s %s times in the last fortnight.',
                  replace(i.needed, '-', ' '), i.times),
           jsonb_build_object('times', i.times, 'who', i.staff_slug),
           70,
           null::text, null::jsonb
      from public.impediments_tally(14, 3) i
  )

  select k.kind, k.project_id, k.subject_ref, k.body, k.because,
         k.weight, k.offer_kind, k.offer_args
    from (
      select * from looming
      union all select * from repeated_failure
      union all select * from blocked_capability
      union all select * from quiet
      union all select * from idle_source
    ) as k (kind, project_id, subject_ref, body, because, weight, offer_kind, offer_args)
   where not exists (
     select 1 from answered a
      where a.kind = k.kind
        and a.pid = coalesce(k.project_id::text, '')
        and a.subject_ref = k.subject_ref
   )
   order by k.weight desc
   limit greatest(coalesce(p_limit, 12), 1)
$$;


--
-- Name: FUNCTION notice(p_limit integer); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.notice(p_limit integer) IS 'What is worth saying without being asked, minus what he has already answered. Every row is a COUNT of something real. A dismissal buys a fortnight of silence per dismissal; acting on one buys a week (#52).';


--
-- Name: notice_new_document(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.notice_new_document() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_enabled boolean;
  v_cap integer;
  v_min integer;
  v_had integer;
  v_recent integer;
begin
  select coalesce((select value::text::boolean from public.system_config
                    where key = 'knowledge.read_new_sources'), true)
    into v_enabled;
  if not v_enabled then return new; end if;

  if new.project_id is null then return new; end if;

  select coalesce((select value::text::integer from public.system_config
                    where key = 'knowledge.new_source_min_chars'), 600)
    into v_min;
  if coalesce(new.content_chars, 0) < v_min then return new; end if;

  if exists (
    select 1 from public.projects p
     where p.project_id = new.project_id
       and (p.slug like 'fixture-%' or p.slug like 'verify-%' or p.status <> 'active')
  ) then
    return new;
  end if;

  select count(*)::integer into v_had
    from public.documents d
   where d.project_id = new.project_id and d.document_id <> new.document_id;
  if v_had = 0 then return new; end if;

  select coalesce((select value::text::integer from public.system_config
                    where key = 'knowledge.new_source_jobs_per_hour'), 6)
    into v_cap;
  -- Real work only. A job on an archived or fixture project does not count
  -- against a ceiling that exists to protect Grant from a stampede.
  select count(*)::integer into v_recent
    from public.jobs j
    join public.projects p on p.project_id = j.project_id
   where j.kind = 'knowledge.read_source'
     and j.created_at > app.now_utc() - interval '1 hour'
     and p.status = 'active'
     and p.slug not like 'fixture-%'
     and p.slug not like 'verify-%'
     and p.slug not like 'newsroom-%';
  if v_recent >= v_cap then
    return new;
  end if;

  insert into public.jobs
    (correlation_id, project_id, idempotency_key, kind, requested_by, priority,
     announce, pinned_config)
  values (gen_random_uuid(), new.project_id,
          format('read:%s', new.document_id),
          'knowledge.read_source',
          format('%s:%s', new.connector, coalesce(new.external_ref, 'source')),
          200,
          true,
          jsonb_build_object(
            'document_id', new.document_id,
            'title', new.title,
            'connector', new.connector));

  return new;
exception
  when unique_violation then
    return new;
  when others then
    raise warning 'notice_new_document failed for %: %', new.document_id, sqlerrm;
    return new;
end;
$$;


--
-- Name: FUNCTION notice_new_document(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.notice_new_document() IS 'Starts a research job for a source arriving into an established project. A trigger rather than a call in each sync script, because two connectors write documents and the missing call in both is exactly how this arc went un-traversed for 586 documents.';


--
-- Name: notification_allowed(text, text, public.notify_severity, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.notification_allowed(p_subject text, p_channel text, p_severity public.notify_severity, p_project_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE
    AS $$
declare
  v_pref record;
begin
  -- The more specific scope wins, which is why the project row is ordered
  -- first rather than merged: layering two partial preferences would need a
  -- precedence rule per column, and there is no sensible rule for min_severity.
  select * into v_pref
  from public.notification_preferences
  where subject = p_subject
    and (project_id = p_project_id or project_id is null)
  order by (project_id is not null) desc
  limit 1;

  -- No preference is not the same as a restrictive one.
  if v_pref is null then
    return true;
  end if;

  -- The escape hatch, checked before every restriction. §12 gives Grant
  -- blockers because he is the only one who can clear them, so a preference
  -- must not be able to hide them by accident — only by saying so.
  if p_severity = 'blocker' and v_pref.blockers_always then
    return true;
  end if;

  if v_pref.quiet_until is not null and v_pref.quiet_until > app.now_utc() then
    return false;
  end if;

  if p_channel = any (v_pref.muted_channels) then
    return false;
  end if;

  if v_pref.min_severity is not null and p_severity < v_pref.min_severity then
    return false;
  end if;

  return true;
end;
$$;


--
-- Name: FUNCTION notification_allowed(p_subject text, p_channel text, p_severity public.notify_severity, p_project_id uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.notification_allowed(p_subject text, p_channel text, p_severity public.notify_severity, p_project_id uuid) IS 'The single definition of "may this be delivered". In SQL because both the Edge Function runtime and the worker loop need it, and a second implementation would drift (§11 on guards in one of two call paths).';


--
-- Name: notification_patterns(integer, numeric); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.notification_patterns(p_min_sample integer DEFAULT 10, p_ignored_ratio numeric DEFAULT 0.8) RETURNS TABLE(channel text, severity public.notify_severity, project_id uuid, sent integer, ignored integer, ignored_ratio numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    n.channel, n.severity, n.project_id,
    count(*)::int,
    count(*) filter (where n.outcome = 'delivered' and n.resolved_at is null)::int,
    round(
      count(*) filter (where n.outcome = 'delivered' and n.resolved_at is null)::numeric
      / nullif(count(*), 0), 2)
  from public.notification_events n
  where n.sent_at >= app.now_utc() - interval '30 days'
    -- Never propose away a blocker. `blockers_always` defaults true for a
    -- reason, and a learned rule must not be able to argue with it.
    and n.severity <> 'blocker'
  group by n.channel, n.severity, n.project_id
  having count(*) >= p_min_sample
     and count(*) filter (where n.outcome = 'delivered' and n.resolved_at is null)::numeric
         / nullif(count(*), 0) >= p_ignored_ratio;
$$;


--
-- Name: FUNCTION notification_patterns(p_min_sample integer, p_ignored_ratio numeric); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.notification_patterns(p_min_sample integer, p_ignored_ratio numeric) IS 'Candidate patterns only - writes nothing. Never returns `blocker` severity: a learned rule that stops blockers reaching Grant is the one outcome with no recovery.';


--
-- Name: offer_mcp_tool(uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.offer_mcp_tool(p_discovered uuid, p_as text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare d public.mcp_discovered_tools%rowtype; v_provider public.mcp_providers%rowtype;
        v_tool text; v_level integer;
begin
  select * into d from public.mcp_discovered_tools where discovered_id = p_discovered;
  if not found then
    return jsonb_build_object('error', 'no such discovered tool');
  end if;
  if d.vanished_at is not null then
    return jsonb_build_object('error',
      'that tool is no longer offered by the provider; rediscover before offering it');
  end if;
  if d.offered_as is not null then
    return jsonb_build_object('ok', true, 'already', true, 'tool', d.offered_as);
  end if;
  select * into v_provider from public.mcp_providers where provider_id = d.provider_id;
  if not v_provider.enabled or v_provider.revoked_at is not null then
    return jsonb_build_object('error', 'that provider is disconnected');
  end if;

  v_tool := coalesce(nullif(btrim(coalesce(p_as, '')), ''),
                     format('%s.%s', v_provider.name,
                            lower(regexp_replace(d.external_name, '[^a-zA-Z0-9]+', '_', 'g'))));
  /*
    The level follows the REACH, and `unknown` is treated as a write.

    Not as a read: a tool nobody can classify is a tool nobody has read the
    documentation for, and the cheap direction is an approval nobody needed.
  */
  v_level := case d.reach
               when 'read' then 0
               when 'write' then 2
               when 'destructive' then 3
               else 2
             end;

  insert into public.tool_permissions
    (tool, level, description, enabled, disabled_reason, delivered_by)
  values (v_tool, v_level,
          left(format('%s, offered by %s. %s', d.external_name, v_provider.name,
                      coalesce(nullif(d.description, ''), 'no description given')), 900),
          false,
          format('discovered from %s and not yet approved. Reach %L (%s).',
                 v_provider.name, d.reach, d.reach_certainty),
          format('mcp:%s', v_provider.name))
  on conflict (tool) do nothing;

  update public.mcp_discovered_tools set offered_as = v_tool where discovered_id = p_discovered;

  return jsonb_build_object('ok', true, 'tool', v_tool, 'level', v_level,
    'enabled', false,
    'note', 'offered and DISABLED. Approving it is the ordinary approval path.');
end;
$$;


--
-- Name: office_health(integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.office_health(p_hours integer DEFAULT 24) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'window_hours', p_hours,
    'finished', count(*) filter (where state = 'complete'),
    'failed', count(*) filter (where state = 'failed'),
    'in_flight', count(*) filter (where state not in ('complete', 'failed', 'cancelled')),
    'failing_kinds', (
      select coalesce(jsonb_agg(jsonb_build_object('kind', k.kind, 'n', k.n)
             order by k.n desc), '[]'::jsonb)
        from (select kind, count(*) n
                from public.jobs
               where not app.harness_job(job_id) and state = 'failed'
                 and created_at > app.now_utc() - make_interval(hours => p_hours)
               group by kind order by count(*) desc limit 5) k
    ),
    'stalled', (select coalesce(sum(s.n), 0) from app.jobs_stuck_queued() s),
    'stalled_kinds', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'kind', s.kind, 'n', s.n, 'oldest_minutes', s.oldest_minutes,
               'period_minutes', s.period_minutes) order by s.n desc), '[]'::jsonb)
        from app.jobs_stuck_queued() s
    ),
    /*
      The reading the fifteen-hour outage had no word for (#236).

      `oldest_minutes` is the one to read: eleven messages waiting two minutes
      is a busy queue and one message waiting nine hours is an office that has
      stopped. A count alone cannot tell those apart, which is part of why
      nothing noticed.
    */
    'waiting', (
      select jsonb_build_object(
        'jobs', coalesce(sum(w.n), 0),
        'oldest_minutes', coalesce(max(w.oldest_minutes), 0),
        'threshold_minutes', 15,
        'kinds', coalesce(jsonb_agg(jsonb_build_object('kind', w.kind, 'n', w.n)
                 order by w.n desc) filter (where w.kind is not null), '[]'::jsonb))
        from app.jobs_waiting(15) w
    ),
    -- Why a morning of failures happened, when the answer is "it could not
    -- think". Empty when every provider is reachable, which is the common case
    -- and the one that should add nothing to the reading.
    'cannot_think', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'provider', h.provider,
               'since', h.opened_at,
               'next_probe_at', h.next_probe_at,
               'said', left(coalesce(h.last_error, ''), 200)) order by h.opened_at), '[]'::jsonb)
        from public.provider_health h
       where h.state = 'open'
         and h.provider not like 'probe_%'
    ),
    'held_for_budget', app.held_for_budget(), 'excluded_fixtures', (
      select count(*) from public.jobs
       where app.harness_job(job_id)
         and created_at > app.now_utc() - make_interval(hours => p_hours)
    )
  )
    from public.jobs
   where not app.harness_job(job_id)
     and created_at > app.now_utc() - make_interval(hours => p_hours)
$$;


--
-- Name: FUNCTION office_health(p_hours integer); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.office_health(p_hours integer) IS 'Health as a fact, not a verdict. cannot_think names any provider whose breaker is open (0372).';


--
-- Name: open_approval_for_job(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.open_approval_for_job(p_job uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select blocker_id from public.blockers
   where job_id = p_job and state = 'open'
   order by created_at desc limit 1
$$;


--
-- Name: origin_follows_connector(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.origin_follows_connector() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  -- Only fill in what the caller did not say. `origin` defaults to 'yours', so
  -- "did not say" and "said yours" are indistinguishable here — and that is
  -- acceptable, because a row with a connector is a source either way.
  if new.connector is not null and btrim(new.connector) <> '' and new.origin = 'yours' then
    new.origin := 'source';
  end if;

  -- The mirror of it: an origin of 'yours' cannot carry a connector, so an
  -- empty string is normalised to null rather than tripping the check. Since
  -- 0283 a 'made' document MAY name a connector — provenance is who made it,
  -- the connector is where it lives — so only a blank one is cleared.
  if new.connector is not null and btrim(new.connector) = '' then
    new.connector := null;
  end if;

  -- 0284. Nobody is called empty string.
  if new.produced_by is not null and btrim(new.produced_by) = '' then
    new.produced_by := null;
  end if;

  return new;
end $$;


--
-- Name: output_author_follows_the_job(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.output_author_follows_the_job() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
begin
  if new.staff_id is null then
    select s.staff_id into new.staff_id
      from public.jobs j
      join public.staff s on s.slug = j.recipient_agent
     where j.job_id = new.job_id;
  end if;
  return new;
end $$;


--
-- Name: FUNCTION output_author_follows_the_job(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.output_author_follows_the_job() IS '#65. An output with no author takes the one the job was addressed to. Historic rows are deliberately NOT backfilled: nothing recorded who wrote an output before `recipient_agent` was written, and inventing a name Grant would read as fact is worse than admitting the gap.';


--
-- Name: output_shape_problem(text, jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.output_shape_problem(p_shape text, p_facts jsonb) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  v_spec public.output_shapes;
  v_missing text[];
  v_wrong text[];
begin
  if p_shape is null and p_facts is null then return null; end if;
  if p_shape is null then
    return 'facts were given with no shape to interpret them';
  end if;
  -- The other half of the pair, said in its own words rather than falling
  -- through to a complaint about the type of nothing.
  if p_facts is null then
    return format('a %s output was claimed with no facts behind it', p_shape);
  end if;

  select * into v_spec from public.output_shapes where shape = p_shape;
  if not found then
    return format('%L is not a declared output shape', p_shape);
  end if;

  if coalesce(jsonb_typeof(p_facts), 'missing') <> 'object' then
    return 'facts must be an object';
  end if;

  -- `coalesce(jsonb_typeof(...), 'missing')` throughout: `p_facts -> key` is
  -- SQL NULL when the key is ABSENT, and a NULL comparison is dropped rather
  -- than failing. Migration 0251 lost a day to exactly that on the dashboard
  -- layout, and 0267 to the same thing on plan steps.
  select array_agg(k.key order by k.key) into v_missing
    from jsonb_each_text(v_spec.required) k
   where coalesce(jsonb_typeof(p_facts -> k.key), 'missing') = 'missing';

  select array_agg(format('%s should be %s', k.key, k.value) order by k.key)
    into v_wrong
    from jsonb_each_text(v_spec.required) k
   where coalesce(jsonb_typeof(p_facts -> k.key), 'missing') <> 'missing'
     and not app.output_value_is(p_facts -> k.key, k.value);

  if v_wrong is null then
    select array_agg(format('%s should be %s', k.key, k.value) order by k.key)
      into v_wrong
      from jsonb_each_text(v_spec.optional) k
     where coalesce(jsonb_typeof(p_facts -> k.key), 'missing') <> 'missing'
       and not app.output_value_is(p_facts -> k.key, k.value);
  end if;

  if v_missing is not null then
    return format('a %s output is missing %s', p_shape, array_to_string(v_missing, ', '));
  end if;
  if v_wrong is not null then
    return format('a %s output has %s', p_shape, array_to_string(v_wrong, ', '));
  end if;
  return null;
end;
$$;


--
-- Name: FUNCTION output_shape_problem(p_shape text, p_facts jsonb); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.output_shape_problem(p_shape text, p_facts jsonb) IS '#130. Null when the facts match the declared shape, otherwise a sentence naming the key and what it should have been.';


--
-- Name: output_value_is(jsonb, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.output_value_is(p_value jsonb, p_type text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case p_type
    when 'string'        then jsonb_typeof(p_value) = 'string'
    when 'number'        then jsonb_typeof(p_value) = 'number'
    when 'boolean'       then jsonb_typeof(p_value) = 'boolean'
    when 'object'        then jsonb_typeof(p_value) = 'object'
    when 'array'         then jsonb_typeof(p_value) = 'array'
    when 'array<string>' then jsonb_typeof(p_value) = 'array'
      and not exists (select 1 from jsonb_array_elements(p_value) e
                       where jsonb_typeof(e) <> 'string')
    when 'array<object>' then jsonb_typeof(p_value) = 'array'
      and not exists (select 1 from jsonb_array_elements(p_value) e
                       where jsonb_typeof(e) <> 'object')
    else false
  end
$$;


--
-- Name: outputs_match_their_shape(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.outputs_match_their_shape() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare v_problem text;
begin
  v_problem := app.output_shape_problem(new.shape, new.facts);
  if v_problem is not null then
    raise exception '%', v_problem using errcode = 'check_violation';
  end if;
  return new;
end;
$$;


--
-- Name: over_budget(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.over_budget(p_agent text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  with lim as (
    select coalesce((select (value #>> '{}')::numeric from public.system_config
                      where key = 'budget.pence_per_agent_per_day'), 60) as per_agent,
           coalesce((select (value #>> '{}')::numeric from public.system_config
                      where key = 'budget.pence_for_the_office_per_day'), 200) as office
  )
  select case
    -- The office ceiling binds above the per-agent ones, and is checked first
    -- so its sentence is the one Grant sees when both are reached.
    when app.spent_today(null) >= lim.office then
      format('the office has spent %sp today, which is its daily limit of %sp',
             round(app.spent_today(null)), round(lim.office))
    when p_agent is not null and app.spent_today(p_agent) >= lim.per_agent then
      format('%s has spent %sp today, which is their daily limit of %sp',
             p_agent, round(app.spent_today(p_agent)), round(lim.per_agent))
    else null
  end
  from lim
$$;


--
-- Name: pause_job(uuid, text, text, text, boolean, timestamp with time zone, timestamp with time zone, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.pause_job(p_job uuid, p_reason text, p_detail text, p_resume_when text, p_resumable boolean DEFAULT true, p_until timestamp with time zone DEFAULT NULL::timestamp with time zone, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_binds_to text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_state text;
begin
  /*
    0436's body, unchanged, with one guard and one column added.

    Rewritten from memory the first time and four behaviours went missing:
    `waiting_on` took the reason instead of the sentence a person reads,
    `state_reason` lost its prefix, the already-paused early return went, and
    the job kept its LEASE — which would have left a paused job looking
    claimed until the lease expired. Taken from the live definition this time,
    which is the rule CLAUDE.md states and which I did not follow.
  */
  select state::text into v_state from public.jobs where job_id = p_job;
  if v_state is null then
    return jsonb_build_object('error', 'no such job');
  end if;
  if v_state = 'paused' then
    return jsonb_build_object('ok', true, 'already', true);
  end if;

  if p_reason = 'awaiting_approval' and coalesce(p_binds_to, '') !~ '^[0-9a-f]{64}$' then
    return jsonb_build_object('error',
      'an approval has to bind to the exact action it approves — pass the '
      'fingerprint of what the job is promising to do');
  end if;

  insert into public.job_pauses
    (job_id, reason, detail, resume_when, resumable, expires_at, binds_to)
  values (p_job, p_reason, p_detail, p_resume_when, coalesce(p_resumable, true),
          p_expires_at, p_binds_to);

  update public.jobs
     set state = 'paused',
         state_reason = left(p_reason || ': ' || p_detail, 500),
         waiting_on = left(p_resume_when, 500),
         not_before = coalesce(p_until, not_before),
         leased_by = null,
         leased_until = null
   where job_id = p_job;

  return jsonb_build_object('ok', true, 'was', v_state);
end;
$_$;


--
-- Name: pause_worker(integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.pause_worker(p_seconds integer DEFAULT 120) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare v_until timestamptz;
begin
  v_until := app.now_utc() + make_interval(secs => greatest(1, least(900, p_seconds)));
  update public.system_config
     set value = to_jsonb(to_char(v_until, 'YYYY-MM-DD"T"HH24:MI:SSOF'))
   where key = 'worker.paused_until';
  return v_until;
end;
$$;


--
-- Name: project_artifacts(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.project_artifacts(p_project uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  -- No kinds: a page shows everything, and the filter is the question's
  -- business rather than the page's.
  select app.artifacts_in(p_project, null, 50);
$$;


--
-- Name: project_attention(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.project_attention() RETURNS TABLE(project_id uuid, slug text, name text, open_blockers integer, overdue_blockers integer, live_jobs integer, failed_jobs_24h integer, stalled_jobs integer, hours_since_sync numeric, has_brief boolean, brief_is_stale boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    p.project_id, p.slug, p.name,
    (select count(*)::int from public.blockers b
      where b.project_id = p.project_id and b.state = 'open'),
    (select count(*)::int from public.blockers b
      where b.project_id = p.project_id and b.state = 'open'
        and b.real_deadline is not null and b.real_deadline <= app.now_utc()),
    (select count(*)::int from public.jobs j
      where j.project_id = p.project_id
        and j.state not in ('complete', 'cancelled', 'failed')),
    (select count(*)::int from public.jobs j
      where j.project_id = p.project_id and j.state = 'failed'
        and j.finished_at >= app.now_utc() - interval '24 hours'),
    (select count(*)::int from public.jobs j
      where j.project_id = p.project_id
        and j.state not in ('complete', 'cancelled', 'failed')
        and j.updated_at <= app.now_utc() - interval '1 hour'),
    (select round(extract(epoch from (app.now_utc() - max(d.fetched_at))) / 3600, 1)
      from public.documents d where d.project_id = p.project_id),
    exists (select 1 from public.project_briefs b where b.project_id = p.project_id),
    exists (
      select 1 from public.documents d
      where d.project_id = p.project_id
        and d.fetched_at > coalesce(
          (select max(b.generated_at) from public.project_briefs b
            where b.project_id = p.project_id),
          '-infinity'::timestamptz)
    )
  from public.projects p
  where p.status = 'active'
  order by p.name;
$$;


--
-- Name: FUNCTION project_attention(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.project_attention() IS 'Facts per active project, not a score. A single number would need a threshold, and a threshold always gets tuned toward fewer alerts.';


--
-- Name: project_automations(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.project_automations(p_project_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(x.v order by x.at desc), '[]'::jsonb)
    from (
      select r.created_at as at, jsonb_build_object(
               'slug', r.slug,
               'what', r.description,
               -- The instruction as written, when there is one. A duty that
               -- pre-dates automations has none, and says so by being null
               -- rather than by an empty string that reads as a blank field.
               'instruction', nullif(r.pinned_config ->> 'instruction', ''),
               'who', s.name,
               'who_slug', s.slug,
               'addressed_to', r.recipient_agent,
               'when', app.say_schedule(r.period_minutes, r.at_time, r.timezone),
               'every_minutes', r.period_minutes,
               'at_time', to_char(r.at_time, 'HH24:MI'),
               'on', r.enabled,
               'last_run', r.last_run_at,
               'made_by', r.created_by,
               -- Whether Grant can edit it here. The twelve that run the
               -- office are not his to change from a project page, and a
               -- control that refuses on press is worse than one that is not
               -- drawn. See `remove_automation`.
               'mine', r.created_by <> 'migration' and r.job_kind = 'office.instruction'
             ) as v
        from public.responsibilities r
        left join public.staff s on s.staff_id = r.staff_id
       where r.project_id = p_project_id
    ) x
$$;


--
-- Name: project_connections(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.project_connections(p_project_id uuid) RETURNS TABLE(connector text, name text, state text, detail text, external_ref text, external_url text, role text, last_synced_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    k.connector,
    k.name,
    case
      -- Connected, but the service behind it is not answering. Distinct from
      -- missing, and needing something completely different from Grant.
      when a.attachment_id is not null and h.state in ('dead', 'missing')
        then 'broken'
      when a.attachment_id is not null then 'connected'
      when c.choice = 'declined' then 'declined'
      when c.choice = 'wanted'   then 'wanted'
      else 'missing'
    end as state,
    case
      when a.attachment_id is not null and h.state in ('dead', 'missing')
        then coalesce(k.name || ' is not answering: ' || coalesce(h.detail, h.state), 'not answering')
      when a.attachment_id is not null then a.display_name
      when c.choice is not null then c.reason
      else null
    end as detail,
    a.external_ref,
    a.external_url,
    a.role,
    a.last_synced_at
  from public.knowledge_connectors k
  left join public.project_attachments a
    on a.project_id = p_project_id and a.connector = k.connector and a.enabled
  left join public.project_connector_choices c
    on c.project_id = p_project_id and c.connector = k.connector
  -- The worst state recorded for the service, so one dead credential is not
  -- hidden by a healthy row beside it. `connection_health` holds several rows
  -- per service (Google has four).
  left join lateral (
    select ch.state, ch.detail
      from public.connection_health ch
     where ch.service = k.health_service
     order by case ch.state
                when 'dead' then 0 when 'missing' then 1 when 'unknown' then 2
                when 'ok' then 3 else 4 end
     limit 1
  ) h on true
  where k.enabled
    and k.connector not in ('upload', 'mcp')
  order by
    -- What needs attention first, then alphabetical. A list ordered by name
    -- buries the one broken row in the middle.
    case
      when a.attachment_id is not null and h.state in ('dead', 'missing') then 0
      when c.choice = 'wanted' then 1
      when a.attachment_id is null and c.choice is null then 2
      when a.attachment_id is not null then 3
      else 4
    end,
    k.connector
$$;


--
-- Name: FUNCTION project_connections(p_project_id uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.project_connections(p_project_id uuid) IS 'Every first-class connector and this project''s standing with it: connected, broken, wanted, declined, or missing. Ordered by what needs attention (0158).';


--
-- Name: project_debris(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.project_debris() RETURNS TABLE(slug text, status text, docs integer, jobs integer, decisions integer, removable boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p.slug, p.status,
         (select count(*) from public.documents d where d.project_id = p.project_id)::int,
         (select count(*) from public.jobs j where j.project_id = p.project_id)::int,
         (select count(*) from public.decisions x where x.project_id = p.project_id)::int,
         not exists (select 1 from public.documents d where d.project_id = p.project_id)
           and not exists (select 1 from public.jobs j where j.project_id = p.project_id)
           /*
             0510. A decision pins a project the way a job does: the reference
             can only be cleared by an UPDATE, and `public.decisions` refuses
             one.
           */
           and not exists (select 1 from public.decisions x where x.project_id = p.project_id)
           /*
             0511. And an event, for the same reason with a different mechanism:
             `events_project_id_fkey` is NO ACTION, so the delete is refused
             outright rather than attempting a cascade the ledger will reject.
           */
           and not exists (select 1 from public.events e where e.project_id = p.project_id)
    from public.projects p
   where not p.is_fixture
     and p.status = 'archived'
     /*
       The shapes a harness leaves. Deliberately a list rather than "anything
       archived": `ai-learning-two` and `ai-learning-superseded-2026-09-07` are
       real history and must never be swept.
     */
     and (p.slug like 'newsroom-%' or p.slug like 'gate4-probe-%'
          or p.slug like 'clash-%' or p.slug like 'untitled-notebook-%'
          or p.slug like 'dbg-%' or p.slug like 'probe-%')
   order by p.slug
$$;


--
-- Name: project_delete(text, boolean); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.project_delete(p_slug text, p_force boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_id       uuid;
  v_docs     int;
  v_jobs     int;
  v_decs     int;
  v_reserved text;
begin
  select project_id, reserved_reason into v_id, v_reserved
    from public.projects where slug = p_slug;
  if v_id is null then
    return jsonb_build_object('error', format('no project %L', p_slug));
  end if;

  -- ADR-0024. Not force-able: p_force exists to override a judgement about
  -- debris, and this is not a judgement.
  if v_reserved is not null then
    return jsonb_build_object('error', format(
      '%s is reserved and cannot be deleted. %s', p_slug, v_reserved));
  end if;

  select count(*) into v_docs from public.documents where project_id = v_id;
  select count(*) into v_jobs from public.jobs where project_id = v_id;
  select count(*) into v_decs from public.decisions where project_id = v_id;

  /*
    Documents are the thing that took work. ADR-0013 is explicit that closing a
    route never loses the corpus, and a project holding one is not debris.
  */
  if v_docs > 0 then
    return jsonb_build_object('error', format(
      '%s holds %s document(s). Archive it instead — a project with a corpus is not debris, '
      || 'and ADR-0013 says a route may be closed and the corpus is kept.', p_slug, v_docs));
  end if;

  /*
    And jobs cannot be removed at all: `job_state_transitions` is append-only by
    §6 and has a foreign key to `jobs`, so a job can only ever be cancelled. A
    project that was worked on is history, and history is archived rather than
    deleted.
  */
  if v_jobs > 0 then
    return jsonb_build_object('error', format(
      '%s has %s job(s) against it and a job can never be deleted — '
      || 'job_state_transitions is append-only. Archive it; the row stays out of your '
      || 'project list and its history stays readable.', p_slug, v_jobs));
  end if;

  /*
    0509. A decision is history the same way a job is, and the foreign key that
    was supposed to let go of it cannot.

    `decisions.project_id` is ON DELETE SET NULL, and `public.decisions` is
    append-only by master spec section 6 -- three triggers refusing UPDATE,
    DELETE and TRUNCATE. So the cascade's own UPDATE is refused, by the
    ledger, with 42501, four frames inside `delete from public.projects`. Not a
    foreign key violation, so 0360's handler below never saw it, and the caller
    got a raw Postgres stack rather than a sentence.

    Seventeen projects hold a decision. Every one of them has been permanently
    undeletable since the ledger triggers existed, and would have taken a sweep
    down with it the way the Slack mapping did before 0360.

    Refused rather than repaired, deliberately. The fix is not to let the
    cascade through: a recorded decision about a project is exactly the kind of
    history ADR-0022 says is archived and never deleted, which is the same
    argument the job branch above makes in the same words.
  */
  if v_decs > 0 then
    return jsonb_build_object('error', format(
      '%s has %s recorded decision(s) against it, and public.decisions is append-only '
      || '(master spec section 6) -- the foreign key would clear the reference with an UPDATE '
      || 'and the ledger refuses one. Archive it; the row stays out of your project list and '
      || 'the reasoning stays readable.', p_slug, v_decs));
  end if;

  -- Archive first. ADR-0014's trigger fires on the attachment delete and
  -- refuses an active project with no enabled attachment.
  update public.projects set status = 'archived' where project_id = v_id;
  delete from public.project_attachments where project_id = v_id;

  /*
    0292. The switch log, which is debris once its subject is gone. Not a breach
    of append-only: that trigger guards UPDATE, so the log cannot be REWRITTEN.
  */
  delete from public.project_switches where project_id = v_id;

  /*
    0360. The channel mapping, for the same reason as the switch log: it is a
    pointer to this project and means nothing without it. Deleting the row does
    not touch the Slack channel — slack:tidy archives those, and it must, because
    Slack refuses to rename or delete an archived channel.
  */
  delete from public.slack_channel_map where project_id = v_id;

  /*
    Aliases are NOT deleted here, and that is the original behaviour preserved
    deliberately: `project_aliases` cascades on the project's foreign key, and
    0282's trigger scopes its uniqueness to ACTIVE projects so a departing
    project releases its phrases anyway. Adding a delete here would have been
    an unverified behaviour change smuggled in by a function replacement.
  */

  /*
    0360. Anything still pointing at this project is history somebody kept on
    purpose, and the caller gets a sentence rather than a stack trace. Naming
    the constraint is enough to find the table without guessing, and returning
    instead of raising is what lets a sweep of eleven projects finish the other
    ten.
  */
  begin
    delete from public.projects where project_id = v_id;
  /*
    0509. `insufficient_privilege` as well, because an append-only ledger
    refuses a cascade with 42501 and not with 23503.

    The pre-check above names `decisions` specifically and gives a sentence
    worth reading. This is the net under it: the next table that gains a
    section 6 trigger and a SET NULL foreign key to projects will fail here
    the same way, and 0360's whole argument -- a sweep of eleven finishes the
    other ten, and the caller gets words rather than a stack -- applies to
    either error class.
  */
  exception when foreign_key_violation or insufficient_privilege then
    return jsonb_build_object('error', format(
      '%s cannot be deleted: %s. It has been archived, '
      || 'which keeps it out of the project list. If that reference is history, archiving '
      || 'is the right end state; if it is configuration, project_delete should clear it.',
      p_slug, sqlerrm));
  end;

  return jsonb_build_object('ok', true, 'deleted', p_slug);
end;
$$;


--
-- Name: FUNCTION project_delete(p_slug text, p_force boolean); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.project_delete(p_slug text, p_force boolean) IS 'Delete a project, refusing when that would lose work. Order is forced by ADR-0014: archive, then attachments, then the project. Refuses a project carrying reserved_reason outright (ADR-0024) — not force-able, because p_force overrides a judgement about debris and that is not a judgement.';


--
-- Name: project_export(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.project_export(p_project_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_strip_nulls(jsonb_build_object(
    'format', 'ai-team-hq/project-package',
    'format_version', 1,
    'exported_at', app.now_utc(),
    'project', (
      select jsonb_build_object(
               'slug', p.slug, 'name', p.name, 'status', p.status,
               'created_at', p.created_at,
               'brief', (select b.body from public.project_briefs b
                          where b.project_id = p.project_id
                          order by b.generated_at desc limit 1),
               'also_known_as', (select coalesce(jsonb_agg(a.alias order by a.alias), '[]'::jsonb)
                                   from public.project_aliases a
                                  where a.project_id = p.project_id))
        from public.projects p where p.project_id = p_project_id),

    'documents', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'path', app.export_path(d.title, d.document_id),
               'title', d.title,
               'kind', d.doc_type,
               'text', d.content,
               'came_from', d.connector,
               'external_ref', d.external_ref,
               'tags', d.tags,
               -- Named, not identified. `produced_by` is a person's name and
               -- 0284 made it nullable so that a blank one reads as unknown
               -- rather than as the empty string a coalesce could not catch.
               'made_by', nullif(d.produced_by, ''),
               'origin', d.origin,
               'in_collections', (select coalesce(jsonb_agg(c.name order by c.name), '[]'::jsonb)
                                    from public.document_collections dc
                                    join public.collections c using (collection_id)
                                   where dc.document_id = d.document_id),
               'created_at', d.created_at) order by d.created_at), '[]'::jsonb)
        from public.documents d
       where d.project_id = p_project_id and d.state = 'approved'),

    'collections', (
      select coalesce(jsonb_agg(jsonb_build_object('name', c.name, 'position', c.position)
                                order by c.position, c.name), '[]'::jsonb)
        from public.collections c where c.project_id = p_project_id),

    'tasks', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'title', t.title, 'state', t.state, 'due', t.due_on,
               'detail', nullif(t.detail, ''),
               -- `assigned_to_human` is a BOOLEAN saying whether this is
               -- Grant's rather than the office's; the person, when it is one
               -- of the team, is `assignee_staff`. Named here, never the uuid.
               'for_grant', t.assigned_to_human,
               'assigned_to', ts.name,
               'blocked_on', nullif(t.blocked_on, ''),
               'milestone', t.is_milestone) order by t.created_at), '[]'::jsonb)
        -- Harness tasks excluded, the same rule the whole product reads by:
        -- an export that carries fixtures is an export of the test suite.
        from public.tasks t
       left join public.staff ts on ts.staff_id = t.assignee_staff
       where t.project_id = p_project_id and not t.is_fixture),

    'contacts', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'name', ct.name, 'role', nullif(ct.role, ''),
               'org', nullif(ct.org, ''), 'email', nullif(ct.email, ''),
               'phone', nullif(ct.phone, ''), 'website', nullif(ct.website, ''),
               'notes', nullif(ct.note, ''),
               'labels', (select coalesce(jsonb_agg(l.name order by l.name), '[]'::jsonb)
                            from public.contact_label_links ll
                            join public.contact_labels l using (label_id)
                           where ll.contact_id = ct.contact_id))
               order by ct.name), '[]'::jsonb)
        from public.contacts ct where ct.project_id = p_project_id and not ct.is_fixture),

    -- Our own row ids dropped, and only ours. See the header: the uuids that
    -- survive elsewhere in this package are either inside Grant's own document
    -- text or are the external system's reference, and both belong here.
    -- `studio_sources` keeps emitting the id because the Sources section needs
    -- it to remove a row; a reader's shape should not be bent by an unrelated
    -- writer's needs, so the export drops it rather than the function.
    'sources', coalesce(
      (select jsonb_agg(s - 'id')
         from jsonb_array_elements(app.studio_sources(p_project_id)) s),
      '[]'::jsonb),

    'team', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'name', s.name, 'role', s.title,
               'on_this_project', (s.slug = 'chief-of-staff' or coalesce(ps.active, true)),
               'brief_here', nullif(coalesce(ps.instruction, ''), ''))
               order by s.name), '[]'::jsonb)
        from public.staff s
        left join public.project_staff ps
          on ps.staff_id = s.staff_id and ps.project_id = p_project_id
       where s.active),

    'automations', app.project_automations(p_project_id),

    'answers', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'by', coalesce(st.name, 'The team'),
               'text', o.body,
               'how_sure', o.confidence,
               'on_what', o.evidence,
               'at', o.created_at) order by o.created_at), '[]'::jsonb)
        from public.outputs o
        join public.jobs j on j.job_id = o.job_id
        left join public.staff st on st.staff_id = o.staff_id
       where j.project_id = p_project_id and not j.is_fixture)
  ))
$$;


--
-- Name: FUNCTION project_export(p_project_id uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.project_export(p_project_id uuid) IS '#36, §13. One dashboard project as a neutral JSON document. Our own row ids are removed; the uuids that remain are inside Grant material or are the external system''s own reference, and both belong in the package. 0326.';


--
-- Name: project_for_slack_channel(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.project_for_slack_channel(p_channel_id text) RETURNS uuid
    LANGUAGE sql STABLE
    AS $$
  select project_id
  from public.slack_channel_map
  where channel_id = p_channel_id and active
  limit 1;
$$;


--
-- Name: project_has_an_attachment(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.project_has_an_attachment() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_project uuid;
  v_status text;
  v_count integer;
begin
  v_project := coalesce(new.project_id, old.project_id);

  select status into v_status from public.projects where project_id = v_project;
  -- An archived project keeps its history and needs no live attachment. Only
  -- an active one has to be attached to something.
  if v_status is distinct from 'active' then
    return null;
  end if;

  select count(*) into v_count
    from public.project_attachments a
   where a.project_id = v_project and a.enabled;

  if v_count = 0 then
    raise exception
      'project % is active with no enabled attachment. A project reads from and '
      'writes to somewhere real - attach a notebook, a Notion database or an '
      'upload before activating it (ADR-0014).', v_project
      using errcode = 'check_violation';
  end if;
  return null;
end;
$$;


--
-- Name: FUNCTION project_has_an_attachment(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.project_has_an_attachment() IS 'Deferred, so a project and its first attachment are one transaction - which is how the front end will create them. Archived projects are exempt: they keep their history and need nowhere to write.';


--
-- Name: project_history(uuid, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.project_history(p_project uuid, p_limit integer DEFAULT 200) RETURNS TABLE(at timestamp with time zone, kind text, what text, detail text, who text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  with story as (
    -- It began.
    select p.created_at as at, 'created'::text as kind,
           format('%s started', p.name) as what,
           nullif(btrim(coalesce(p.purpose, p.description, '')), '') as detail,
           null::text as who
      from public.projects p
     where p.project_id = p_project

    union all

    -- Something was attached to work from.
    select a.created_at, 'attached',
           format('%s attached', coalesce(nullif(a.display_name, ''), a.connector)),
           format('%s · %s', a.connector, coalesce(nullif(a.artifact_kind, ''), a.role)),
           null
      from public.project_attachments a
     where a.project_id = p_project

    union all

    /*
      And something stopped being used. `updated_at` is when the row last
      changed, which for a disabled attachment is when it was disabled - the
      one case where a touch timestamp genuinely dates the event, because
      disabling is the only thing that sets `enabled = false`.
    */
    select a.updated_at, 'detached',
           format('%s detached', coalesce(nullif(a.display_name, ''), a.connector)),
           nullif(btrim(coalesce(a.disabled_reason, '')), ''),
           null
      from public.project_attachments a
     where a.project_id = p_project and not a.enabled

    union all

    -- Material arrived, and it matters whether the office wrote it.
    select d.created_at,
           case when d.origin = 'made' then 'made' else 'source' end,
           d.title,
           case when d.origin = 'made' then 'written by the team'
                else format('%s%s', coalesce(nullif(d.connector, ''), 'upload'),
                            case when d.content_chars > 0
                                 then format(' · %s words', (d.content_chars / 6)) else '' end)
           end,
           nullif(d.produced_by, '')
      from public.documents d
     where d.project_id = p_project
       and coalesce(d.state, '') <> 'archived'
       -- Harness material is not part of how the project got here.
       and coalesce(d.added_by, '') !~ '^(verify|probe|fixture|gate|ledger-proof)[:-]'

    union all

    -- Work finished. Not work STARTED: a task appearing is an intention and a
    -- task finishing is the project having moved.
    select t.done_at, 'finished', t.title,
           case when t.is_milestone then 'a milestone' else null end,
           (select s.name from public.staff s where s.staff_id = t.assignee_staff)
      from public.tasks t
     where t.project_id = p_project and t.state = 'done' and t.done_at is not null
       and not t.is_fixture

    union all

    -- A milestone being SET is itself a shaping decision, dated by the task.
    select t.created_at, 'milestone', t.title, 'set as a milestone', null
      from public.tasks t
     where t.project_id = p_project and t.is_milestone and not t.is_fixture

    union all

    /*
      And where it stands, for a project that is no longer active.

      Dated `updated_at` and worded so the date is not read as the moment the
      status changed - there is no status history and this view will not
      pretend there is.
    */
    select p.updated_at, 'standing',
           format('%s is %s', p.name, p.status),
           'the office keeps no history of status changes, so this is dated by the last change to the project row',
           null
      from public.projects p
     where p.project_id = p_project and coalesce(p.status, 'active') <> 'active'
  )
  select s.at, s.kind, s.what, s.detail, s.who
    from story s
   where s.at is not null
   order by s.at asc
   limit greatest(coalesce(p_limit, 200), 1)
$$;


--
-- Name: FUNCTION project_history(p_project uuid, p_limit integer); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.project_history(p_project uuid, p_limit integer) IS 'How a project got here, oldest first (#156; harness documents excluded in 0402). The events that CHANGED it, not everything that happened in it. Derived from the timestamps the rows already carry, because public.events holds agent actions and no project lifecycle. Status changes are NOT in it: projects.status has no history and inventing one would be the office remembering what nobody wrote down.';


--
-- Name: project_instruction_for(uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.project_instruction_for(p_project_id uuid, p_staff_slug text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(
    (select ps.instruction
       from public.project_staff ps
       join public.staff s on s.staff_id = ps.staff_id
      where ps.project_id = p_project_id and s.slug = p_staff_slug),
    '')
$$;


--
-- Name: project_knowledge(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.project_knowledge(p_project uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  with attached as (
    select a.connector,
           count(*)::int as attachments,
           max(a.last_synced_at) as last_synced
      from public.project_attachments a
     where a.project_id = p_project
       and a.enabled
     group by a.connector
  ),
  indexed as (
    select d.connector,
           count(*)::int as documents,
           max(coalesce(d.fetched_at, d.updated_at)) as newest
      from public.documents d
     where d.project_id = p_project
       and coalesce(btrim(d.connector), '') <> ''
     group by d.connector
  ),
  /*
    Every connector that is attached OR has fed something in.

    Named `covered` rather than `both`, which is a reserved word — `trim(both
    ...)` — and produced a syntax error pointing at the CTE name.

    A full outer join rather than a left one: a connector whose attachment was
    removed can still have documents (§17 turns off a route, not what it
    brought in), and a reader that hid those would be understating what the
    office holds -- the opposite failure to the one this exists for, and just
    as dishonest.
  */
  covered as (
    select coalesce(a.connector, i.connector) as connector,
           coalesce(a.attachments, 0) as attachments,
           a.last_synced,
           coalesce(i.documents, 0) as documents,
           i.newest
      from attached a
      full outer join indexed i on i.connector = a.connector
  ),
  /*
    Mail as a domain the office can be blind to (#172, ADR-0037).

    Narrowed to a project that has at least one CONTACT with an address, and
    deliberately not to one that merely has an alias: almost every project has
    a name of four characters or more, so the wider rule would put a caveat on
    every answer the office gives whenever Gmail is down -- and CLAUDE.md
    already records what a caveat on every turn costs. A contact is Grant
    saying this project has correspondents, which is what makes the gap worth
    reporting.

    Stale rather than empty. An inbox with nothing new in it is normal; a cache
    that has not been refreshed in a day means the reader is broken, which is
    the case today -- Google is refusing the stored refresh token and the mail
    has been 40 hours old without anything saying so.
  */
  mail as (
    select exists (
             select 1 from public.contacts c
              where c.project_id = p_project
                and coalesce(btrim(c.email), '') <> ''
           )
           and coalesce(
                 (select max(m.last_seen_at) from public.mail_messages m),
                 'epoch'::timestamptz
               ) < app.now_utc() - interval '24 hours' as blind
  )
  select jsonb_build_object(
    'as_of', app.now_utc(),
    'documents', (select coalesce(sum(documents), 0)::int from covered),
    'sources', coalesce((
      select jsonb_agg(jsonb_build_object(
               'connector', b.connector,
               'attached', b.attachments > 0,
               'documents', b.documents,
               'newest', b.newest,
               'last_synced', b.last_synced,
               -- Attached, and nothing of it is in the index. The case this
               -- function exists for.
               'blank', b.attachments > 0 and b.documents = 0)
             order by b.documents desc, b.connector)
        from covered b), '[]'::jsonb),
    /*
      The connectors a search CANNOT speak for.

      Named rather than counted, because the sentence the office has to be able
      to say is "nothing in what I have indexed, and Drive is not indexed" --
      and a count cannot name Drive.
    */
    'blank', coalesce((
      select jsonb_agg(x order by x) from (
        select b.connector as x from covered b where b.attachments > 0 and b.documents = 0
        union all
        select 'mail' from mail where mail.blind
      ) named), '[]'::jsonb),
    -- True only when every attached connector has fed something in. A search
    -- that finds nothing may be reported as an absence ONLY when this is true.
    'complete', not exists (
      select 1 from covered b where b.attachments > 0 and b.documents = 0)
      and not (select mail.blind from mail)
  );
$$;


--
-- Name: FUNCTION project_knowledge(p_project uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.project_knowledge(p_project uuid) IS 'What the project index covers, and what it does not (#257). `blank` names every connector attached with nothing indexed; `complete` is false whenever one exists, and a search finding nothing may only be reported as an absence when it is true.';


--
-- Name: project_team(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.project_team(p_project_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(t.v order by t.ord, t.name), '[]'::jsonb)
    from (
      select case when s.slug = 'chief-of-staff' then 0 else 1 end as ord,
             s.name,
             jsonb_build_object(
               'slug', s.slug,
               'name', s.name,
               'title', s.title,
               'avatar', s.avatar_ref,
               'on', (s.slug = 'chief-of-staff' or coalesce(ps.active, true)),
               -- Said plainly, because a switch that cannot move needs to
               -- explain itself rather than merely refuse.
               'fixed', s.slug = 'chief-of-staff',
               'why_fixed', case when s.slug = 'chief-of-staff'
                                 then 'She is the only person who messages you.' end,
               'instruction', coalesce(ps.instruction, ''),
               -- Whether a DECISION exists, which is not the same as being on.
               -- The page draws a default differently from a choice.
               'decided', ps.staff_id is not null,
               'decided_by', ps.decided_by,
               'decided_at', ps.decided_at
             ) as v
        from public.staff s
        left join public.project_staff ps
          on ps.staff_id = s.staff_id and ps.project_id = p_project_id
       where s.active
    ) t
$$;


--
-- Name: proposals_sent(uuid[], uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.proposals_sent(p_ids uuid[], p_job uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_n int;
begin
  update public.proposals
     set delivered_at = app.now_utc(),
         delivered_by_job = p_job
   where proposal_id = any(p_ids)
     and delivered_at is null;
  get diagnostics v_n = row_count;
  return v_n;
end
$$;


--
-- Name: FUNCTION proposals_sent(p_ids uuid[], p_job uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.proposals_sent(p_ids uuid[], p_job uuid) IS '#49/#272. Marks a batch told-to-Grant. The job is recorded because the claim is checkable: app.proposals_undeliver puts back anything whose job never actually delivered.';


--
-- Name: proposals_to_send(integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.proposals_to_send(p_limit integer DEFAULT 5) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(p order by p.times_seen desc, p.last_seen desc), '[]'::jsonb)
    from (
      select proposal_id as id, staff_slug as who, kind::text, needed, title, remedy,
             argument, cost_note, times_seen, last_seen
        from public.proposals
       where state = 'open' and delivered_at is null
         -- No escape hatch here, unlike the raise path: this is the batch
         -- the chief of staff actually sends, and a suite must never be
         -- able to make the office tell Grant about a gap it invented.
         and not app.harness_proposal(staff_slug, needed)
       order by times_seen desc, last_seen desc
       limit greatest(coalesce(p_limit, 5), 1)
    ) p
$$;


--
-- Name: proposals_undeliver(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.proposals_undeliver() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_n int;
begin
  /*
    Only a FINISHED job is judged.

    A job still running, retrying or waiting has not failed to deliver — it
    has not finished trying. Sweeping those would put a proposal back in front
    of Grant while the message announcing it is still in flight, which is the
    duplicate half of the defect this function exists to prevent.

    A job with NO delivery row at all counts as not delivered, and that is
    deliberate: `notify` writes the row, so its absence means nothing was
    sent. 0304's asymmetry decides the direction — this can only ever restore
    a proposal, never hide one, so being wrong costs a repeated message rather
    than a lost one.
  */
  update public.proposals p
     set delivered_at = null,
         delivered_by_job = null
   where p.delivered_at is not null
     and p.state = 'open'
     and p.delivered_by_job is not null
     and exists (
       select 1 from public.jobs j
        where j.job_id = p.delivered_by_job
          and j.state in ('complete', 'failed', 'cancelled')
     )
     and not exists (
       select 1 from public.deliveries d
        where d.job_id = p.delivered_by_job
          and d.state = 'sent'
     );
  get diagnostics v_n = row_count;
  return v_n;
end
$$;


--
-- Name: FUNCTION proposals_undeliver(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.proposals_undeliver() IS 'Puts back any open proposal whose announcing job finished without a sent delivery. Marking something delivered before the delivery is confirmed is how the one message saying the office is stuck gets lost for ever.';


--
-- Name: propose_standing_rule(text, text, text, uuid, uuid, jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.propose_standing_rule(p_body text, p_scope text DEFAULT 'global'::text, p_staff text DEFAULT NULL::text, p_project_id uuid DEFAULT NULL::uuid, p_from_job uuid DEFAULT NULL::uuid, p_because jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_body    text := btrim(coalesce(p_body, ''));
  v_staff   text := nullif(btrim(coalesce(p_staff, '')), '');
  v_ref     text;
  v_id      uuid;
  v_target  jsonb;
begin
  if length(v_body) < 12 then
    return jsonb_build_object('error', 'a standing rule needs to say something');
  end if;
  /*
    The scopes the PRESS can perform, which is a shorter list than the enum.

    'kind' is a real member of `lesson_scope` and is refused here for a reason
    about this function rather than about the enum: a kind-scoped lesson needs
    a `job_kind` and an offer carries no way to say one. Offer only what the
    press can perform.
  */
  if p_scope not in ('global', 'project', 'staff') then
    return jsonb_build_object('error',
      format('%L is not a scope a standing rule can be offered at', p_scope));
  end if;

  /*
    Exactly one target, chosen by the scope, and the others dropped.

    `lessons_scope_matches_target` permits precisely one non-null per scope, so
    this is not tidying - it is the difference between an offer that can be
    accepted and one that raises 23514 on the press.
  */
  v_target := case p_scope
    when 'project' then jsonb_build_object('project_id', p_project_id, 'staff', null)
    when 'staff'   then jsonb_build_object('project_id', null, 'staff', v_staff)
    else                jsonb_build_object('project_id', null, 'staff', null)
  end;
  if p_scope = 'project' and p_project_id is null then
    return jsonb_build_object('error', 'a project rule needs a project');
  end if;
  if p_scope = 'staff' and v_staff is null then
    return jsonb_build_object('error', 'a rule for one person needs to say who');
  end if;

  /*
    The class, not the sentence.

    Two corrections about the same thing, worded differently, must not produce
    two offers - "offer at most once per correction" is only meaningful if
    similar corrections collapse. The subject is the normalised rule text, so
    punctuation and case do not make a second class.
  */
  v_ref := left(regexp_replace(lower(v_body), '[^a-z0-9]+', '-', 'g'), 120);

  -- Any row, not only an open one. A dismissed offer must not come back.
  if exists (select 1 from public.suggestions s
              where s.kind = 'standing_rule' and s.subject_ref = v_ref) then
    return jsonb_build_object('offered', false, 'why', 'already offered once');
  end if;

  insert into public.suggestions
    (project_id, kind, subject_ref, body, because, weight, offer_kind, offer_args)
  values (p_project_id, 'standing_rule', v_ref, v_body,
          coalesce(p_because, '{}'::jsonb), 3, 'learn',
          v_target || jsonb_build_object('scope', p_scope, 'from_job', p_from_job))
  returning suggestion_id into v_id;

  return jsonb_build_object('offered', true, 'suggestion_id', v_id,
                            'rule', v_body, 'scope', p_scope);
end;
$$;


--
-- Name: FUNCTION propose_standing_rule(p_body text, p_scope text, p_staff text, p_project_id uuid, p_from_job uuid, p_because jsonb); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.propose_standing_rule(p_body text, p_scope text, p_staff text, p_project_id uuid, p_from_job uuid, p_because jsonb) IS 'Offer a drafted rule on the Governance page, once (#147, 0393). The body IS the rule - Grant approves text he can read, never a summary. Global, project and staff only, and the offer carries exactly the one target its scope names, because lessons_scope_matches_target permits exactly one.';


--
-- Name: protect_briefing_body(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.protect_briefing_body() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.body is distinct from old.body
     or new.kind is distinct from old.kind
     or new.for_date is distinct from old.for_date
     or new.inputs is distinct from old.inputs then
    raise exception
      'a briefing''s content cannot be changed after it is generated. Delivery '
      'fields may be updated; what it said may not - it is a record of what '
      'Grant was told.'
      using errcode = 'check_violation';
  end if;
  return new;
end;
$$;


--
-- Name: provider_available(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.provider_available(p_provider text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  h record;
begin
  select * into h from public.provider_health where provider = p_provider;

  -- Unknown provider: no failures recorded, so nothing to distrust. Refusing
  -- here would make adding a provider require a database row first.
  if not found then
    return true;
  end if;

  if h.state = 'closed' then
    return true;
  end if;

  if h.state = 'half_open' then
    -- A probe is already in flight. Exactly one caller gets through per
    -- cooldown, and it is the one that flipped open -> half_open below.
    return false;
  end if;

  if h.next_probe_at is not null and now() >= h.next_probe_at then
    -- Cooldown elapsed: let precisely one request through to test the water.
    update public.provider_health
    set state = 'half_open'
    where provider = p_provider and state = 'open';
    return true;
  end if;

  return false;
end
$$;


--
-- Name: provision_missing_channels(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.provision_missing_channels() RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  with want as (
    select p.project_id, p.name
      from public.projects p
     where p.status = 'active'
       and not p.is_fixture
       -- Fifteen minutes. A suite's subject is gone long before this; a
       -- project Grant made is still here.
       and p.created_at < app.now_utc() - interval '15 minutes'
       -- ADR-0014: an active project reads from and writes to somewhere real.
       -- One with nothing attached is half-made and does not need a room yet.
       and exists (
         select 1 from public.project_attachments a
          where a.project_id = p.project_id and a.enabled)
       and not exists (
         select 1 from public.slack_channel_map m
          where m.project_id = p.project_id and m.active)
       /*
         Once a day, whatever the reason (0477).

         Without this the sweep re-asks on every tick, and a project whose
         desired name is taken by somebody else's channel can never succeed —
         740 jobs in twelve hours, each one an API call and each one announcing
         a failure.
       */
       and not exists (
         select 1 from public.jobs j
          where j.project_id = p.project_id
            and j.kind = 'office.provision_channels'
            and j.created_at > app.now_utc() - interval '24 hours')
       /*
         And not at all while Grant is being asked about it. A blocker is the
         office saying "somebody has to choose"; asking again tomorrow while
         the question is still open is asking twice.
       */
       and not exists (
         select 1 from public.blockers b
          where b.project_id = p.project_id
            and b.state = 'open'
            and b.requested_action like '%Slack channel%')
  ),
  queued as (
    insert into public.jobs
      (correlation_id, project_id, idempotency_key, kind, requested_by, priority)
    select gen_random_uuid(), w.project_id, format('provision-%s', w.project_id),
           'office.provision_channels', 'hq', 300
      from want w
    on conflict (idempotency_key) where state in ('queued','running','retrying') do nothing
    returning project_id
  )
  select jsonb_build_object(
    'wanted', (select count(*)::int from want),
    'queued', (select count(*)::int from queued),
    'projects', coalesce((select jsonb_agg(w.name order by w.name) from want w), '[]'::jsonb)
  )
$$;


--
-- Name: FUNCTION provision_missing_channels(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.provision_missing_channels() IS 'Enqueue a channel for every active, attached, non-fixture dashboard project older than fifteen minutes that has none (#187, 0419) — at most once a day each, and never while a blocker is asking Grant about it (0477).';


--
-- Name: purge_fixture_staff(boolean); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.purge_fixture_staff(p_go boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_row record;
  v_removed int := 0;
  v_held jsonb := '[]'::jsonb;
  v_holder text;
begin
  for v_row in
    select staff_id, slug, name from public.staff
     where is_fixture and not active and not permanent
     order by slug
  loop
    -- The three keys that do not refuse - two CASCADE and one SET NULL - so a
    -- row they hold is excluded BEFORE the delete is attempted, because by the
    -- time you could look the cascade has happened. assignee_staff is a uuid
    -- however its name reads (0404).
    v_holder := null;
    if exists (select 1 from public.proposals p where p.staff_slug = v_row.slug) then
      v_holder := 'proposals';
    elsif exists (select 1 from public.staff_tools t where t.staff_slug = v_row.slug) then
      v_holder := 'staff_tools';
    elsif exists (select 1 from public.tasks t where t.assignee_staff = v_row.staff_id) then
      v_holder := 'tasks';
    end if;

    if v_holder is not null then
      v_held := v_held || jsonb_build_object('slug', v_row.slug, 'held_by', v_holder);
      continue;
    end if;

    if not p_go then
      v_removed := v_removed + 1;
      continue;
    end if;

    begin
      -- The prompt written for this specialist, which is derived data and the
      -- only thing that held the last 55. Scoped to this row, inside the same
      -- attempt, so a specialist that some OTHER table still names keeps its
      -- prompt along with everything else.
      delete from public.staff_prompts where staff_id = v_row.staff_id;
      delete from public.staff where staff_id = v_row.staff_id;
      v_removed := v_removed + 1;
    exception when foreign_key_violation then
      /*
        The prompt delete is rolled back with the staff delete by this block,
        so a specialist that something else names keeps both. That is what
        makes deleting the prompt first safe rather than a widening: it is
        undone unless the whole removal succeeds.
      */
      v_held := v_held || jsonb_build_object(
        'slug', v_row.slug,
        'held_by', coalesce(nullif(split_part(SQLERRM, '"', 4), ''), 'a table that names it')
      );
    end;
  end loop;

  return jsonb_build_object(
    'ok', true,
    'went', p_go,
    'removed', v_removed,
    'could_not_remove', jsonb_array_length(v_held),
    'held', v_held,
    'still_fixture', (select count(*) from public.staff where is_fixture)
  );
end;
$$;


--
-- Name: FUNCTION purge_fixture_staff(p_go boolean); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.purge_fixture_staff(p_go boolean) IS 'Remove harness specialists nobody ever worked through. Reports what it could not remove and why. #269';


--
-- Name: put_in_collection(uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.put_in_collection(p_document uuid, p_collection_name text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_project uuid;
  v_col uuid;
begin
  select project_id into v_project from public.documents where document_id = p_document;
  if v_project is null then
    raise exception 'no document with id %', p_document;
  end if;

  -- Created on first use. Grant should never have to make a collection before
  -- he can put something in one — that is the manual step §31A calls a design
  -- failure, in miniature.
  insert into public.collections (project_id, name)
  values (v_project, btrim(p_collection_name))
  on conflict (project_id, name) do update set name = excluded.name
  returning collection_id into v_col;

  insert into public.document_collections (document_id, collection_id)
  values (p_document, v_col)
  on conflict do nothing;

  return v_col;
end $$;


--
-- Name: raise_proposals(integer, integer, boolean); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.raise_proposals(p_days integer DEFAULT 30, p_min integer DEFAULT 3, p_include_fixtures boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  t          record;
  v_new      int := 0;
  v_bumped   int := 0;
  v_silent   int := 0;
  v_title    text;
  v_remedy   text;
  v_arg      text;
  v_existed  boolean;
begin
  for t in
    select * from app.impediments_tally(p_days, p_min, coalesce(p_include_fixtures, false))
     where staff_slug is not null and kind <> 'not_capable' and (coalesce(p_include_fixtures, false)
          -- The switch that has meant "count the harness traffic too"
          -- since 0297. 0490 tightened the filter and forgot it.
          or not app.harness_proposal(staff_slug, needed))
  loop
    /*
      A declined proposal is left completely alone — not reopened, not
      re-counted, not re-delivered. Declining costs Grant one press and buys
      permanent silence on that subject, which is the whole point of the row.
    */
    if exists (
      select 1 from public.proposals
       where staff_slug = t.staff_slug and kind = t.kind and needed = t.needed
         and state = 'declined'
    ) then
      v_silent := v_silent + 1;
      continue;
    end if;

    /*
      Asked BEFORE the upsert. The first version asked afterwards, by looking
      for a row created in the last two seconds — which is a clock reading
      standing in for a fact the statement already knew, and would have
      miscounted a slow pass.
    */
    v_existed := exists (
      select 1 from public.proposals
       where staff_slug = t.staff_slug and kind = t.kind and needed = t.needed
    );

    v_title := format('%s could not: %s', initcap(replace(t.staff_slug, '-', ' ')), t.needed);
    v_remedy := case t.kind
      when 'missing_tool'     then format('Give this agent a tool that can %s.', t.needed)
      when 'missing_skill'    then format('The office has no way to %s at all — it needs building.', t.needed)
      when 'missing_data'     then format('Connect or supply the material needed to %s.', t.needed)
      when 'needs_permission' then format('Grant permission to %s.', t.needed)
      when 'ambiguous'        then format('Say which reading of "%s" is meant.', t.needed)
      else format('Decide whether the office should be able to %s.', t.needed)
    end;
    v_arg := format(
      '%s time(s) in the last %s day(s), across %s project(s). Most recently: %s',
      t.times, p_days, t.projects,
      coalesce(nullif(btrim(t.for_instance), ''), 'no detail recorded'));

    insert into public.proposals
      (staff_slug, kind, needed, title, remedy, argument,
       times_seen, first_seen, last_seen, for_instance)
    values (t.staff_slug, t.kind, t.needed, v_title, v_remedy, v_arg,
            t.times, t.first_seen, t.last_seen, coalesce(t.for_instance, ''))
    on conflict (staff_slug, kind, needed) do update
      set times_seen = excluded.times_seen,
          last_seen  = excluded.last_seen,
          argument   = excluded.argument,
          for_instance = excluded.for_instance
      -- Only while it is still open and unanswered. An approved or done
      -- proposal is history and must not be rewritten under Grant.
      where public.proposals.state = 'open';

    if v_existed then v_bumped := v_bumped + 1; else v_new := v_new + 1; end if;
  end loop;

  return jsonb_build_object('raised', v_new, 'updated', v_bumped, 'left_declined', v_silent);
end;
$$;


--
-- Name: FUNCTION raise_proposals(p_days integer, p_min integer, p_include_fixtures boolean); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.raise_proposals(p_days integer, p_min integer, p_include_fixtures boolean) IS 'Turn recurring impediments into proposals Grant can answer (#49). Skips not_capable: an agent that could not write a coherent answer is an engineering signal, not a request (0474).';


--
-- Name: raise_suggestions(integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.raise_suggestions(p_limit integer DEFAULT 6) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  n integer;
  raised uuid[];
begin
  with put as (
    insert into public.suggestions
      (project_id, kind, subject_ref, body, because, weight, offer_kind, offer_args)
    select s.project_id, s.kind, s.subject_ref, s.body, s.because,
           s.weight, s.offer_kind, s.offer_args
      from app.notice(p_limit) s
    on conflict (kind, coalesce(project_id::text, ''), subject_ref)
      where state = 'open'
      do nothing
    returning suggestion_id
  )
  select count(*)::integer, coalesce(array_agg(suggestion_id), '{}')
    into n, raised
    from put;

  /*
    One event for the pass, not one per suggestion.

    A noticing pass that found four things is one act of noticing, and four
    ledger rows would make the daily volume of "the office thought about itself"
    four times what it is. The ids are in the row, so the detail is not lost.
  */
  if n > 0 then
    perform public.append_event(
      extensions.gen_random_uuid(), 'agent', 'chief-of-staff', 'noticing',
      'office.noticed', true, null, null,
      jsonb_build_object('raised', n, 'suggestion_ids', raised),
      format('Raised %s observation%s nobody asked for.', n,
             case when n = 1 then '' else 's' end),
      '[]'::jsonb, null, null,
      'update public.suggestions set state = ''dismissed'' — or the dashboard',
      null);
  end if;

  return n;
end;
$$;


--
-- Name: FUNCTION raise_suggestions(p_limit integer); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.raise_suggestions(p_limit integer) IS 'Write what was noticed into public.suggestions so it can be dismissed. notice() has no memory; this table is the memory (#52). One ledger event per pass, because a pass is one act of noticing (#53).';


--
-- Name: reach_wanted(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.reach_wanted() RETURNS TABLE(request_id uuid, tool text, asked_by text, what_for text, because jsonb, exists_yet boolean, raised_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select r.request_id, r.tool, r.asked_by, r.what_for, r.because,
         exists (select 1 from public.tool_permissions t where t.tool = r.tool),
         r.raised_at
    from public.tool_requests r
   where r.state = 'open'
   order by r.raised_at
$$;


--
-- Name: FUNCTION reach_wanted(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.reach_wanted() IS 'The open asks, for the briefing and the dashboard. `exists_yet` is false when approving means deciding to build rather than switching on (ADR-0018).';


--
-- Name: readings(integer, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.readings(p_days integer DEFAULT 7, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(r order by r.at desc), '[]'::jsonb)
    from (
      select j.job_id as id,
             j.kind,
             j.recipient_agent as who,
             left(coalesce(c.transcript, c.instruction, ''), 300) as asked,
             j.understood_as as understood,
             j.created_at as at
        from public.jobs j
        left join public.inbound_commands c
          on c.command_id = (j.pinned_config ->> 'command_id')::uuid
       where not j.is_fixture
         and j.created_at >= app.now_utc() - make_interval(days => greatest(coalesce(p_days, 7), 1))
         and coalesce(btrim(coalesce(c.transcript, c.instruction, '')), '') <> ''
       order by j.created_at desc
       limit greatest(coalesce(p_limit, 50), 1)
    ) r
$$;


--
-- Name: recall_conversation(uuid, text, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.recall_conversation(p_command_id uuid, p_query text, p_limit integer DEFAULT 3) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  with self as (
    select origin_channel, split_part(origin_ref, ':', 1) as chat,
           coalesce(subject, actor) as who, received_at
      from public.inbound_commands where command_id = p_command_id
  ),
  /*
    The edge of the working window.

    Everything at or after this is ALREADY in the prompt, so returning it would
    spend tokens repeating what the model can see. Recall is for what the window
    cannot reach -- which is the only reason this function exists.
  */
  edge as (
    select self.received_at - make_interval(mins => coalesce(
             (select value::text::integer from public.system_config
               where key = 'conversation.window_minutes'), 30)) as older_than
      from self
  ),
  older as (
    select c.received_at,
           coalesce(c.transcript, c.instruction) as said,
           (select left(o.body, 600) from public.outputs o
             where o.job_id = c.job_id order by o.created_at desc limit 1) as answered
      from public.inbound_commands c, self, edge
     where c.origin_channel = self.origin_channel
       and split_part(c.origin_ref, ':', 1) = self.chat
       and coalesce(c.subject, c.actor) = self.who
       and c.callback_action is null
       and c.command_id <> p_command_id
       and c.received_at < edge.older_than
  ),
  matched as (
    select o.received_at, o.said, o.answered,
           ts_rank(
             to_tsvector('english', coalesce(o.said, '') || ' ' || coalesce(o.answered, '')),
             plainto_tsquery('english', coalesce(nullif(btrim(p_query), ''), 'x'))
           ) as rank
      from older o
     where to_tsvector('english', coalesce(o.said, '') || ' ' || coalesce(o.answered, ''))
           @@ plainto_tsquery('english', coalesce(nullif(btrim(p_query), ''), 'x'))
     order by rank desc, o.received_at desc
     limit greatest(coalesce(p_limit, 3), 1)
  )
  select coalesce(
    jsonb_agg(jsonb_build_object(
      'at', received_at,
      'minutes_ago', round(extract(epoch from (app.now_utc() - received_at)) / 60)::int,
      'said', said,
      'answered', answered
    ) order by received_at asc),
    '[]'::jsonb)
    from matched
$$;


--
-- Name: FUNCTION recall_conversation(p_command_id uuid, p_query text, p_limit integer); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.recall_conversation(p_command_id uuid, p_query text, p_limit integer) IS 'Older turns of THIS chat that match a query - what the working window cannot reach. Scoped to (channel, chat, subject) like app.conversation_before (#238).';


--
-- Name: recent_exchange(uuid, integer, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.recent_exchange(p_command_id uuid, p_minutes integer DEFAULT 90, p_limit integer DEFAULT 12) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with self as (
    select * from public.inbound_commands where command_id = p_command_id
  ),
  -- What he said. Excludes button presses: a callback is an answer to a
  -- question, already recorded against it, and reading "useful" back as a
  -- conversational turn is noise.
  said as (
    select c.received_at as at,
           'grant'::text  as who,
           coalesce(c.transcript, c.instruction) as text
      from public.inbound_commands c, self
     where c.command_id <> self.command_id
       and c.origin_channel = self.origin_channel
       and split_part(c.origin_ref, ':', 1) = split_part(self.origin_ref, ':', 1)
       and coalesce(c.addressed_to, '') = coalesce(self.addressed_to, '')
       and coalesce(c.subject, c.actor) = coalesce(self.subject, self.actor)
       and c.callback_action is null
       and c.received_at < self.received_at
       and c.received_at >= self.received_at
             - make_interval(mins => greatest(coalesce(p_minutes, 90), 1))
       and coalesce(btrim(coalesce(c.transcript, c.instruction)), '') <> ''
  ),
  /*
    What went back to him.

    Joined through the job that answered each command rather than through the
    delivery, because a delivery row says a message was sent and not what was
    in it. `outputs.body` is the text, and it has no project_id — it joins
    through `jobs`, which is a trap already recorded in CLAUDE.md.
  */
  replied as (
    select o.created_at as at,
           coalesce(st.slug, 'the office') as who,
           o.body as text
      from self
      join public.inbound_commands c
        on c.origin_channel = self.origin_channel
       and split_part(c.origin_ref, ':', 1) = split_part(self.origin_ref, ':', 1)
       and coalesce(c.addressed_to, '') = coalesce(self.addressed_to, '')
      join public.jobs j
        on j.pinned_config ->> 'command_id' = c.command_id::text
      join public.outputs o
        on o.job_id = j.job_id
      left join public.staff st on st.staff_id = o.staff_id
     where o.created_at < self.received_at
       and o.created_at >= self.received_at
             - make_interval(mins => greatest(coalesce(p_minutes, 90), 1))
       and coalesce(btrim(o.body), '') <> ''
  ),
  turns as (
    select * from said
    union all
    select * from replied
  )
  select coalesce(jsonb_agg(t order by t.at), '[]'::jsonb)
    from (
      select at, who,
             -- Capped per turn. A 4,000-character answer three turns ago is
             -- not what "make it longer" refers to, and carrying it whole is
             -- how a context window becomes the cost of the feature.
             left(text, 600) as text
        from turns
       order by at desc
       limit greatest(coalesce(p_limit, 12), 1)
    ) t
$$;


--
-- Name: FUNCTION recent_exchange(p_command_id uuid, p_minutes integer, p_limit integer); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.recent_exchange(p_command_id uuid, p_minutes integer, p_limit integer) IS 'The last few turns in this chat, both sides, so a pronoun has an antecedent (#63). Scoped by channel, chat, addressed-to and subject — all four, because seven director bots share one chat id (0097).';


--
-- Name: reconcile_vanished(text, text, text[], numeric); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.reconcile_vanished(p_connector text, p_parent_ref text, p_seen text[], p_limit_fraction numeric DEFAULT 0.5) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_held int;
  v_absent int;
  v_marked int := 0;
  v_archived int := 0;
  v_returned int := 0;
  v_restored int := 0;
begin
  if coalesce(btrim(p_connector), '') = '' or coalesce(btrim(p_parent_ref), '') = '' then
    return jsonb_build_object('ok', false, 'error', 'a connector and a parent are required');
  end if;

  select count(*) into v_held from public.documents
   where connector = p_connector and external_parent_ref = p_parent_ref;

  select count(*) into v_absent from public.documents
   where connector = p_connector and external_parent_ref = p_parent_ref
     and external_ref is not null
     and not (external_ref = any (coalesce(p_seen, '{}'::text[])));

  -- The blast radius, checked BEFORE anything is written, so a refusal cannot
  -- leave half the marks behind for the next pass to act on.
  if v_held > 0 and v_absent::numeric / v_held::numeric > p_limit_fraction then
    return jsonb_build_object(
      'ok', false, 'refused', true, 'held', v_held, 'absent', v_absent,
      'error', format(
        '%s of %s sources are missing from this listing, which is more than the %s%% this may act on. '
        'That is likelier to be a failed listing than a deletion, so nothing was changed.',
        v_absent, v_held, round(p_limit_fraction * 100)));
  end if;

  /*
    Back from the dead: seen again, and archived by THIS mechanism.

    Counted separately from an ordinary return, because "a file came back" and
    "a file we had hidden came back and is answerable again" are different
    events and the second is the one worth a sentence.
  */
  update public.documents
     set state = 'approved', missing_since = null
   where connector = p_connector and external_parent_ref = p_parent_ref
     and external_ref = any (coalesce(p_seen, '{}'::text[]))
     and missing_since is not null
     and coalesce(state, '') = 'archived';
  get diagnostics v_restored = row_count;

  -- Anything else that came back simply stops being missing.
  update public.documents
     set missing_since = null
   where connector = p_connector and external_parent_ref = p_parent_ref
     and missing_since is not null
     and external_ref = any (coalesce(p_seen, '{}'::text[]));
  get diagnostics v_returned = row_count;

  -- Strike two: already missing at an earlier pass, and still missing.
  update public.documents
     set state = 'archived'
   where connector = p_connector and external_parent_ref = p_parent_ref
     and external_ref is not null
     and not (external_ref = any (coalesce(p_seen, '{}'::text[])))
     and missing_since is not null
     and coalesce(state, '') <> 'archived';
  get diagnostics v_archived = row_count;

  -- Strike one: absent for the first time. Marked, never hidden.
  update public.documents
     set missing_since = app.now_utc()
   where connector = p_connector and external_parent_ref = p_parent_ref
     and external_ref is not null
     and not (external_ref = any (coalesce(p_seen, '{}'::text[])))
     and missing_since is null;
  get diagnostics v_marked = row_count;

  return jsonb_build_object(
    'ok', true, 'held', v_held, 'absent', v_absent,
    'marked', v_marked, 'archived', v_archived,
    'returned', v_returned, 'restored', v_restored);
end;
$$;


--
-- Name: FUNCTION reconcile_vanished(p_connector text, p_parent_ref text, p_seen text[], p_limit_fraction numeric); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.reconcile_vanished(p_connector text, p_parent_ref text, p_seen text[], p_limit_fraction numeric) IS 'Converge an upstream listing into the index (#257, ADR-0040): mark on the first absence, archive on the second, un-mark on return, and refuse a pass that would archive more than a fraction of what the parent holds.';


--
-- Name: record_browser_page(uuid, text, text, text, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.record_browser_page(p_project uuid, p_url text, p_title text, p_text text, p_job uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_id uuid;
  v_text text := left(coalesce(p_text, ''), 400000);
  v_title text := nullif(trim(coalesce(p_title, '')), '');
begin
  if not exists (select 1 from public.projects where project_id = p_project) then
    return jsonb_build_object('error', 'there is no dashboard project by that id');
  end if;
  if length(trim(v_text)) = 0 then
    return jsonb_build_object('error', 'the page had no words on it');
  end if;
  if v_title is null then
    return jsonb_build_object('error', 'a kept page needs a title');
  end if;

  insert into public.documents
    (project_id, title, origin, connector, external_ref, state,
     content, content_fingerprint, content_chars, fetched_at,
     produced_by_job)
  values
    (p_project, v_title, 'source', 'browser', p_url, 'approved',
     v_text, encode(extensions.digest(v_text, 'sha256'), 'hex'), length(v_text), app.now_utc(),
     p_job)
  on conflict (project_id, external_ref) where connector = 'browser' and external_ref is not null
  do update set
     title = excluded.title,
     content = excluded.content,
     content_fingerprint = excluded.content_fingerprint,
     content_chars = excluded.content_chars,
     fetched_at = excluded.fetched_at,
     produced_by_job = excluded.produced_by_job,
     updated_at = app.now_utc()
  returning document_id into v_id;

  return jsonb_build_object('ok', true, 'document_id', v_id);
end;
$$;


--
-- Name: FUNCTION record_browser_page(p_project uuid, p_url text, p_title text, p_text text, p_job uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.record_browser_page(p_project uuid, p_url text, p_title text, p_text text, p_job uuid) IS 'What a browser read, kept as a source document. Never ''made'': the office did not write it, it went and looked at it, and provenance depends on the difference.';


--
-- Name: record_connection_health(jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.record_connection_health(p_rows jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_count integer;
begin
  insert into public.connection_health (service, credential, state, detail, owner, action, checked_at)
  select r->>'service', r->>'credential', r->>'state',
         left(coalesce(r->>'detail', ''), 200), coalesce(r->>'owner', ''),
         left(coalesce(r->>'action', ''), 200), app.now_utc()
    from jsonb_array_elements(p_rows) as r
  on conflict (service, credential) do update
    set state = excluded.state,
        detail = excluded.detail,
        owner = excluded.owner,
        action = excluded.action,
        checked_at = excluded.checked_at;

  get diagnostics v_count = row_count;

  -- A service that stops being probed stops being shown, rather than lingering
  -- green for ever. Removed only when this run wrote a full set, so one
  -- partial run cannot empty the page.
  if v_count >= 5 then
    delete from public.connection_health
     where checked_at < app.now_utc() - interval '1 minute';
  end if;

  return v_count;
end;
$$;


--
-- Name: FUNCTION record_connection_health(p_rows jsonb); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.record_connection_health(p_rows jsonb) IS 'Upsert a whole probe run. Prunes rows this run did not write - a service that stopped being probed must stop being shown, not linger green - but only when the run was large enough to be a full set.';


--
-- Name: record_consultation(uuid, text, text, text, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.record_consultation(p_job_id uuid, p_consulted text, p_requested_by text DEFAULT 'chief-of-staff'::text, p_reason text DEFAULT ''::text, p_requests integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_consulted uuid;
  v_by        uuid;
  v_id        uuid;
begin
  if not exists (select 1 from public.jobs where job_id = p_job_id) then
    return jsonb_build_object('error', 'no such job');
  end if;

  select staff_id into v_consulted from public.staff where slug = btrim(coalesce(p_consulted, ''));
  if v_consulted is null then
    return jsonb_build_object('error', format('nobody here is called %L', p_consulted));
  end if;

  select staff_id into v_by from public.staff where slug = btrim(coalesce(p_requested_by, ''));

  /*
    Consulting yourself is not a consultation.

    Refused rather than silently written: the chief of staff handling something
    herself is the ordinary case, and counting it would make the delegation
    rate look healthy while nothing was being delegated at all — which is
    exactly the illusion #65 is about.
  */
  if v_consulted = v_by then
    return jsonb_build_object('error', 'that is the same person — not a consultation');
  end if;

  insert into public.consultations
    (job_id, consulted_staff, requested_by, reason, provider_requests)
  values (p_job_id, v_consulted, v_by,
          coalesce(nullif(btrim(p_reason), ''), 'no reason recorded'),
          greatest(coalesce(p_requests, 0), 0))
  returning consultation_id into v_id;

  return jsonb_build_object('ok', true, 'consultation', v_id, 'consulted', p_consulted);
end;
$$;


--
-- Name: record_decision_made(text, text, text[], text, text, uuid, uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.record_decision_made(p_question text, p_chose text, p_ruled_out text[], p_because text, p_decided_by text, p_project uuid DEFAULT NULL::uuid, p_job uuid DEFAULT NULL::uuid, p_supersedes uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare v_id uuid;
begin
  if coalesce(btrim(p_question), '') = '' or coalesce(btrim(p_chose), '') = ''
     or coalesce(btrim(p_because), '') = '' then
    return jsonb_build_object('ok', false,
      'error', 'a decision needs the question, what was chosen, and why');
  end if;

  insert into public.decisions
    (question, chose, ruled_out, because, decided_by, project_id, from_job, supersedes)
  values (btrim(p_question), btrim(p_chose),
          coalesce(p_ruled_out, array[]::text[]), btrim(p_because),
          p_decided_by, p_project, p_job, p_supersedes)
  returning decision_id into v_id;

  return jsonb_build_object('ok', true, 'decision', v_id);
end;
$$;


--
-- Name: record_delivery_failure(uuid, text, boolean); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.record_delivery_failure(p_delivery_id uuid, p_error_code text, p_retryable boolean) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_row public.deliveries;
  v_max int;
  v_base int;
  v_ceiling int;
  v_wait int;
begin
  select * into v_row from public.deliveries
    where delivery_id = p_delivery_id for update;
  if not found then
    raise exception 'no delivery %', p_delivery_id using errcode = 'no_data_found';
  end if;

  if v_row.state = 'sent' then
    -- Two attempts disagree about reality. The sent record wins: it has a
    -- message reference, which is evidence; the failure has only a code.
    return 'already_sent';
  end if;

  if not p_retryable then
    update public.deliveries
       set state = 'failed', error_code = p_error_code
     where delivery_id = p_delivery_id and state = 'claimed';
    return 'failed';
  end if;

  select coalesce((select value::int from public.system_config
                    where key = 'delivery.max_attempts'), 5),
         coalesce((select value::int from public.system_config
                    where key = 'delivery.backoff_seconds'), 30),
         coalesce((select value::int from public.system_config
                    where key = 'delivery.backoff_ceiling_seconds'), 900)
    into v_max, v_base, v_ceiling;

  /*
    Out of road. The last error code is kept rather than replaced with
    something generic — "chat_not_found five times" and "timeout five times"
    are different problems and only the code says which.
  */
  if v_row.attempt >= v_max then
    update public.deliveries
       set state = 'failed', error_code = p_error_code
     where delivery_id = p_delivery_id and state = 'claimed';
    return 'gave_up';
  end if;

  /*
    Exponential, with a ceiling, computed from the attempt already made.

    `least` before the multiply would overflow on a large attempt count;
    `power` returns double precision, so the cast is explicit rather than
    implicit. Both are the kind of detail that only shows up at attempt 30.
  */
  v_wait := least(v_ceiling, (v_base * power(2, greatest(0, v_row.attempt - 1)))::int);

  update public.deliveries
     set lease_expires_at = app.now_utc() + make_interval(secs => v_wait),
         error_code = p_error_code
   where delivery_id = p_delivery_id and state = 'claimed';

  return 'retry_in_' || v_wait::text;
end;
$$;


--
-- Name: FUNCTION record_delivery_failure(p_delivery_id uuid, p_error_code text, p_retryable boolean); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.record_delivery_failure(p_delivery_id uuid, p_error_code text, p_retryable boolean) IS 'Issue #202. Bounded retry: up to delivery.max_attempts, with exponential backoff to a ceiling. Returns already_sent, failed, gave_up, or retry_in_<n>.';


--
-- Name: record_delivery_sent(uuid, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.record_delivery_sent(p_delivery_id uuid, p_message_ref text, p_link text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_row public.deliveries;
begin
  select * into v_row from public.deliveries
    where delivery_id = p_delivery_id for update;
  if not found then
    raise exception 'no delivery %', p_delivery_id using errcode = 'no_data_found';
  end if;

  if v_row.state = 'sent' then
    -- A retry of the RECORDING step, not of the send. Keeping the first
    -- message_ref keeps the one that exists.
    return 'already_sent';
  end if;

  if v_row.state = 'failed' then
    -- Use app.resolve_indeterminate_delivery, which asks whether you looked.
    return 'failed';
  end if;

  if v_row.state = 'suppressed' then
    -- The suppression lost the race. The message EXISTS and must be deleted,
    -- not forgotten, so the reference is recorded even though the state stays
    -- suppressed — that reference is the only handle on it.
    update public.deliveries
       set message_ref = p_message_ref, link = p_link
     where delivery_id = p_delivery_id;
    return 'suppressed_too_late';
  end if;

  update public.deliveries
     set state = 'sent', message_ref = p_message_ref, link = p_link,
         sent_at = app.now_utc()
   where delivery_id = p_delivery_id;

  return 'sent';
end;
$$;


--
-- Name: record_drive_document(uuid, text, text, text, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.record_drive_document(p_project_id uuid, p_folder_id text, p_file_id text, p_title text, p_content text DEFAULT NULL::text, p_added_by text DEFAULT 'chief-of-staff'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_id          uuid;
  v_was         text;
  v_content     text := nullif(btrim(coalesce(p_content, '')), '');
  v_fingerprint text;
  v_outcome     text;
begin
  if p_project_id is null or coalesce(btrim(p_file_id), '') = ''
     or coalesce(btrim(p_folder_id), '') = '' then
    return jsonb_build_object(
      'ok', false, 'error', 'a project, a folder and a file id are all needed');
  end if;
  if not exists (select 1 from public.projects where project_id = p_project_id) then
    return jsonb_build_object('ok', false, 'error', 'no such project');
  end if;

  if v_content is not null then
    v_fingerprint := encode(extensions.digest(v_content, 'sha256'), 'hex');
  end if;

  select document_id, content_fingerprint into v_id, v_was
    from public.documents
   where connector = 'drive'
     and external_parent_ref = p_folder_id
     and external_ref = p_file_id;

  if v_id is null then
    insert into public.documents
      (project_id, connector, external_parent_ref, external_ref, title, doc_type,
       content, content_fingerprint, content_chars, fetched_at, origin, added_by)
    values
      (p_project_id, 'drive', p_folder_id, p_file_id,
       coalesce(nullif(btrim(p_title), ''), 'Untitled'), 'file',
       v_content, v_fingerprint,
       case when v_content is null then null else length(v_content) end,
       case when v_content is null then null else app.now_utc() end,
       'source', p_added_by)
    returning document_id into v_id;
    v_outcome := 'added';
  else
    /*
      An unchanged file is left alone rather than re-stamped.

      `upsertSource` makes the same distinction and for the same reason: a
      re-read that reports "changed" makes everything downstream re-brief, and
      a folder polled every ten minutes would re-brief on every pass. The
      fingerprint is over the text we actually store, so it only moves when the
      text does.
    */
    if v_content is not null and v_fingerprint is distinct from v_was then
      update public.documents
         set title = coalesce(nullif(btrim(p_title), ''), title),
             content = v_content,
             content_fingerprint = v_fingerprint,
             content_chars = length(v_content),
             fetched_at = app.now_utc()
       where document_id = v_id;
      v_outcome := 'changed';
    else
      update public.documents
         set title = coalesce(nullif(btrim(p_title), ''), title)
       where document_id = v_id;
      v_outcome := 'unchanged';
    end if;
  end if;

  return jsonb_build_object(
    'ok', true, 'document', v_id, 'outcome', v_outcome,
    'has_text', v_content is not null);
end;
$$;


--
-- Name: FUNCTION record_drive_document(p_project_id uuid, p_folder_id text, p_file_id text, p_title text, p_content text, p_added_by text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.record_drive_document(p_project_id uuid, p_folder_id text, p_file_id text, p_title text, p_content text, p_added_by text) IS '#96. Create or refresh the document for one Drive file. Parented on the FOLDER id so documents_one_per_external_ref actually bites — a null parent makes two nulls distinct and lets one file become two documents, which is what #28 spent five migrations learning. Text only; bytes are attached by app.attach_file_to_document. 0332.';


--
-- Name: record_file_document(uuid, text, text, text, bigint, text, text, integer, text, uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.record_file_document(p_project_id uuid, p_title text, p_storage_path text, p_mime_type text, p_byte_size bigint, p_parent_ref text DEFAULT NULL::text, p_external_ref text DEFAULT NULL::text, p_duration_s integer DEFAULT NULL::integer, p_added_by text DEFAULT 'chief-of-staff'::text, p_job_id uuid DEFAULT NULL::uuid, p_origin text DEFAULT 'made'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  made public.documents%rowtype;
  v_renamed boolean := false;
  v_kept boolean := false;
begin
  if not exists (select 1 from public.projects where project_id = p_project_id) then
    return jsonb_build_object('error', 'no such dashboard project');
  end if;
  if coalesce(p_byte_size, 0) <= 0 then
    return jsonb_build_object('error', 'a file with no bytes is not a file');
  end if;
  if p_parent_ref is not null and coalesce(btrim(p_external_ref), '') = '' then
    return jsonb_build_object('error', 'a parent reference needs the artifact reference too');
  end if;
  if p_origin is null or p_origin not in ('made', 'yours') then
    return jsonb_build_object(
      'error', format('a stored file is either yours or made here, not %L', p_origin));
  end if;

  select * into made from public.documents
   where project_id = p_project_id and storage_path = p_storage_path;
  if found then
    /*
      Already here — and possibly renamed upstream since.

      The comparison is against `source_title`, never against `title`: the
      question is not "does the office call it something else" but "has the
      SOURCE started calling it something else", and those differ exactly when
      Grant has renamed it himself.
    */
    if coalesce(made.source_title, '') is distinct from coalesce(p_title, '') then
      v_renamed := true;
      -- Grant's own rename is anything that no longer matches what the source
      -- last said. His wins; the source's new name is still written down.
      v_kept := coalesce(made.title, '') is distinct from coalesce(made.source_title, '');

      update public.documents
         set source_title = p_title,
             title = case when v_kept then title else p_title end,
             updated_at = app.now_utc()
       where document_id = made.document_id;
    end if;

    return jsonb_build_object(
      'document_id', made.document_id, 'already_there', true,
      'renamed_at_source', v_renamed,
      'kept_your_name', v_kept,
      'title', case when v_renamed and not v_kept then p_title else made.title end);
  end if;

  insert into public.documents
    (project_id, title, source_title, doc_type, connector, external_parent_ref, external_ref,
     storage_path, mime_type, byte_size, duration_s,
     content, content_fingerprint, content_chars,
     fetched_at,
     added_by, produced_by, produced_by_job, origin, state)
  values
    (p_project_id, p_title,
     case when p_origin = 'yours' then p_title else null end,
     'file', null,  -- a desktop is the absence of a connector (0414)
     p_parent_ref, p_external_ref,
     p_storage_path, p_mime_type, p_byte_size, p_duration_s,
     null, null, null,
     null,
     p_added_by,
     case when p_origin = 'made' then p_added_by else null end,
     p_job_id, p_origin, 'draft')
  returning * into made;

  return jsonb_build_object('document_id', made.document_id, 'already_there', false);
end;
$$;


--
-- Name: record_mcp_tools(uuid, jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.record_mcp_tools(p_provider uuid, p_tools jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_tool jsonb; v_guess jsonb; v_seen text[] := array[]::text[];
  v_new integer := 0; v_gone integer := 0;
begin
  if not exists (select 1 from public.mcp_providers where provider_id = p_provider) then
    return jsonb_build_object('error', 'no such provider');
  end if;

  for v_tool in select * from jsonb_array_elements(coalesce(p_tools, '[]'::jsonb)) loop
    if coalesce(btrim(v_tool ->> 'name'), '') = '' then continue; end if;
    v_seen := v_seen || (v_tool ->> 'name');
    v_guess := app.guess_reach(v_tool ->> 'name', v_tool ->> 'description');

    insert into public.mcp_discovered_tools
      (provider_id, external_name, description, input_schema, reach, why_that_reach)
    values (p_provider, v_tool ->> 'name',
            left(coalesce(v_tool ->> 'description', ''), 2000),
            coalesce(v_tool -> 'inputSchema', '{}'::jsonb),
            v_guess ->> 'reach', v_guess ->> 'why')
    on conflict (provider_id, external_name) do update
      set description = excluded.description,
          input_schema = excluded.input_schema,
          last_seen_at = app.now_utc(),
          vanished_at = null,
          /*
            A CONFIRMED reach is a person's judgement and survives a
            rediscovery. Overwriting it would make the confirmation worthless
            the next time the provider rewords a description.
          */
          reach = case when public.mcp_discovered_tools.reach_certainty = 'confirmed'
                       then public.mcp_discovered_tools.reach else excluded.reach end,
          why_that_reach = case when public.mcp_discovered_tools.reach_certainty = 'confirmed'
                                then public.mcp_discovered_tools.why_that_reach
                                else excluded.why_that_reach end;
    if found then v_new := v_new + 1; end if;
  end loop;

  update public.mcp_discovered_tools
     set vanished_at = app.now_utc()
   where provider_id = p_provider and vanished_at is null
     and not (external_name = any (v_seen));
  get diagnostics v_gone = row_count;

  update public.mcp_providers
     set last_probe_at = app.now_utc(), last_probe_ok = true,
         last_probe_detail = format('%s tool(s)', coalesce(array_length(v_seen, 1), 0)),
         updated_at = app.now_utc()
   where provider_id = p_provider;

  return jsonb_build_object('ok', true,
    'seen', coalesce(array_length(v_seen, 1), 0), 'vanished', v_gone);
end;
$$;


--
-- Name: record_notebook_artifact(uuid, text, text, text, text, text, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.record_notebook_artifact(p_project uuid, p_notebook_ref text, p_external_ref text, p_kind text, p_title text, p_url text DEFAULT NULL::text, p_state text DEFAULT 'generating'::text, p_detail text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_id uuid;
  v_state text := coalesce(nullif(btrim(p_state), ''), 'generating');
  v_was text;
begin
  if coalesce(btrim(p_notebook_ref), '') = '' or coalesce(btrim(p_external_ref), '') = '' then
    return jsonb_build_object('ok', false,
      'error', 'an artifact needs the notebook it belongs to and its own id');
  end if;

  /*
    `ready` needs a link, and the constraint says so.

    Rather than let the INSERT raise, the state is DEMOTED when no URL came
    back: the artifact genuinely is finished in the notebook and the office
    genuinely cannot open it, and saying "ready, here is nothing" would be the
    fabricated link #260 forbids. `detail` carries the reason so the page and
    the answer can both say it.
  */
  if v_state = 'ready' and coalesce(btrim(p_url), '') = '' then
    v_state := 'generating';
    p_detail := coalesce(nullif(btrim(p_detail), ''),
      'Finished in the notebook, but it gave no link the office can open.');
  end if;

  select artifact_id, state into v_id, v_was
    from public.artifacts
   where notebook_ref = btrim(p_notebook_ref) and external_ref = btrim(p_external_ref);

  if v_id is null then
    insert into public.artifacts
      (project_id, notebook_ref, external_ref, kind, title, url, state, detail, ready_at)
    values (p_project, btrim(p_notebook_ref), btrim(p_external_ref),
            coalesce(nullif(btrim(p_kind), ''), 'unknown'),
            nullif(btrim(coalesce(p_title, '')), ''),
            nullif(btrim(coalesce(p_url, '')), ''),
            v_state, nullif(btrim(coalesce(p_detail, '')), ''),
            case when v_state = 'ready' then app.now_utc() else null end)
    returning artifact_id into v_id;
    return jsonb_build_object('ok', true, 'artifact', v_id, 'outcome', 'adopted');
  end if;

  /*
    An update never moves a terminal state backwards.

    A notebook listing that briefly reports an old artifact as pending must not
    un-finish something the office already has a link for -- the same argument
    `record_drive_document` makes about not re-stamping an unchanged file, with
    a worse failure mode: a `ready` row demoted loses its URL to the CHECK.
  */
  update public.artifacts
     set title = coalesce(nullif(btrim(coalesce(p_title, '')), ''), title),
         kind = coalesce(nullif(btrim(p_kind), ''), kind),
         url = coalesce(nullif(btrim(coalesce(p_url, '')), ''), url),
         state = case
                   when state in ('ready', 'failed', 'abandoned') then state
                   else v_state
                 end,
         detail = coalesce(nullif(btrim(coalesce(p_detail, '')), ''), detail),
         ready_at = case
                      when ready_at is not null then ready_at
                      when v_state = 'ready' then app.now_utc()
                      else null
                    end,
         updated_at = app.now_utc()
   where artifact_id = v_id;

  return jsonb_build_object('ok', true, 'artifact', v_id,
    'outcome', case when v_was = 'ready' then 'unchanged' else 'updated' end);
end;
$$;


--
-- Name: record_provider_failure(text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.record_provider_failure(p_provider text, p_error text) RETURNS public.breaker_state
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_threshold integer;
  v_max_cooldown integer;
  v_failures integer;
  v_was public.breaker_state;
  v_cooldown integer;
  v_state public.breaker_state;
begin
  select coalesce((value ->> 'failure_threshold')::integer, 5),
         coalesce((value ->> 'max_cooldown_seconds')::integer, 3600)
    into v_threshold, v_max_cooldown
  from public.system_config where key = 'providers.breaker';

  v_threshold := coalesce(v_threshold, 5);
  v_max_cooldown := coalesce(v_max_cooldown, 3600);

  insert into public.provider_health (provider, consecutive_failures, last_failure_at, last_error)
  values (p_provider, 1, now(), left(p_error, 500))
  on conflict (provider) do update
    set consecutive_failures = public.provider_health.consecutive_failures + 1,
        last_failure_at      = now(),
        last_error           = left(p_error, 500)
  returning consecutive_failures, state into v_failures, v_was;

  -- A failed probe re-opens immediately and backs off. Waiting for the
  -- threshold again would hammer a provider that just told us it is still down.
  if v_was = 'half_open' then
    select least(cooldown_seconds * 2, v_max_cooldown) into v_cooldown
    from public.provider_health where provider = p_provider;
    v_state := 'open';
  elsif v_failures >= v_threshold then
    v_cooldown := 60;
    v_state := 'open';
  else
    return v_was;
  end if;

  update public.provider_health
  set state            = v_state,
      opened_at        = coalesce(opened_at, now()),
      cooldown_seconds = v_cooldown,
      next_probe_at    = now() + make_interval(secs => v_cooldown)
  where provider = p_provider;

  return v_state;
end
$$;


--
-- Name: record_provider_success(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.record_provider_success(p_provider text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  insert into public.provider_health (provider, state, consecutive_failures, last_success_at)
  values (p_provider, 'closed', 0, now())
  on conflict (provider) do update
    set state                = 'closed',
        consecutive_failures = 0,
        opened_at            = null,
        next_probe_at        = null,
        cooldown_seconds     = 60,
        last_success_at      = now()
$$;


--
-- Name: record_signal(text, text, text, uuid, text, jsonb, uuid, timestamp with time zone); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.record_signal(p_source text, p_event_type text, p_external_ref text, p_project uuid DEFAULT NULL::uuid, p_summary text DEFAULT ''::text, p_detail jsonb DEFAULT '{}'::jsonb, p_caused_by_job uuid DEFAULT NULL::uuid, p_happened_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare v_id uuid; v_was uuid;
begin
  select signal_id into v_was from public.signals
   where source = p_source and external_ref = p_external_ref;
  if v_was is not null then
    return jsonb_build_object('ok', true, 'signal', v_was, 'duplicate', true);
  end if;
  insert into public.signals
    (source, event_type, external_ref, project_id, summary, detail, caused_by_job, happened_at)
  values (p_source, p_event_type, p_external_ref, p_project,
          left(coalesce(p_summary, ''), 500), coalesce(p_detail, '{}'::jsonb),
          p_caused_by_job, coalesce(p_happened_at, app.now_utc()))
  returning signal_id into v_id;
  return jsonb_build_object('ok', true, 'signal', v_id, 'duplicate', false);
end;
$$;


--
-- Name: record_slack_channel_rename(text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.record_slack_channel_rename(p_channel_id text, p_new_name text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_old text;
begin
  select channel_name into v_old
    from public.slack_channel_map where channel_id = p_channel_id;
  if not found then
    return false;
  end if;

  update public.slack_channel_map
     set channel_name = p_new_name,
         name_observed_at = app.now_utc()
   where channel_id = p_channel_id;

  return v_old is distinct from p_new_name;
end;
$$;


--
-- Name: FUNCTION record_slack_channel_rename(p_channel_id text, p_new_name text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.record_slack_channel_rename(p_channel_id text, p_new_name text) IS 'Corrects the cached label for a channel. Returns true when the name actually changed. Cannot move a mapping: the id is the identity.';


--
-- Name: record_slack_history(text, text, text, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.record_slack_history(p_channel_id text, p_ts text, p_user text, p_text text, p_thread_ts text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_project uuid;
  v_said    text := nullif(btrim(coalesce(p_text, '')), '');
  v_key     text;
  v_id      uuid;
begin
  if coalesce(btrim(p_channel_id), '') = '' or coalesce(btrim(p_ts), '') = '' then
    return jsonb_build_object('ok', false, 'error', 'a channel and a ts are both needed');
  end if;
  if v_said is null then
    -- A join notice or a file share with no comment. Not a message; skipped
    -- rather than refused, because a backfill hits plenty of them.
    return jsonb_build_object('ok', true, 'outcome', 'skipped', 'why', 'no text');
  end if;

  select m.project_id into v_project
    from public.slack_channel_map m
   where m.channel_id = p_channel_id and m.project_id is not null;

  if v_project is null then
    return jsonb_build_object(
      'ok', false, 'error', format('channel %s maps to no project', p_channel_id));
  end if;

  v_key := 'slack:message:' || p_channel_id || ':' || p_ts;

  insert into public.inbound_commands
    (origin_channel, origin_ref, actor, instruction, dedupe_key, project_id,
     processed_at, context)
  values ('slack', p_channel_id || ':' || p_ts, coalesce(nullif(btrim(p_user), ''), 'unknown'),
          v_said, v_key, v_project, app.now_utc(),
          jsonb_build_object('backfilled', true, 'thread_ts', p_thread_ts,
                             'project_id', v_project))
  on conflict (dedupe_key) do nothing
  returning command_id into v_id;

  return jsonb_build_object(
    'ok', true,
    'outcome', case when v_id is null then 'already there' else 'added' end,
    'command', v_id,
    'project', v_project);
end;
$$;


--
-- Name: FUNCTION record_slack_history(p_channel_id text, p_ts text, p_user text, p_text text, p_thread_ts text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.record_slack_history(p_channel_id text, p_ts text, p_user text, p_text text, p_thread_ts text) IS 'Import one historical Slack message into a project''s conversation (#193). NEVER enqueues: every message in a channel''s history is an instruction to the router, and importing six months of it would have the office act on every request Grant made since March. Idempotent through the dedupe_key that already makes a redelivered webhook safe. 0340.';


--
-- Name: record_slack_membership(text, boolean); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.record_slack_membership(p_channel_id text, p_present boolean) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_before boolean;
begin
  select bot_present into v_before
    from public.slack_channel_map where channel_id = p_channel_id;
  if not found then
    return false;
  end if;

  update public.slack_channel_map
     set bot_present = p_present,
         bot_left_at = case when p_present then null else app.now_utc() end
   where channel_id = p_channel_id;

  return v_before is distinct from p_present;
end;
$$;


--
-- Name: record_telegram_chat(text, text, text, text, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.record_telegram_chat(p_chat_id text, p_chat_type text, p_bot_id text, p_subject text DEFAULT NULL::text, p_title text DEFAULT NULL::text, p_username text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_existed boolean;
begin
  select true into v_existed from public.telegram_chats
   where chat_id = p_chat_id and bot_id = p_bot_id;

  insert into public.telegram_chats
    (chat_id, chat_type, bot_id, subject, title, username)
  values
    (p_chat_id, p_chat_type, p_bot_id, p_subject, p_title, p_username)
  on conflict (bot_id, chat_id) do update
    set last_seen_at = app.now_utc(),
        chat_type = excluded.chat_type,
        title = coalesce(excluded.title, public.telegram_chats.title),
        username = coalesce(excluded.username, public.telegram_chats.username),
        subject = coalesce(excluded.subject, public.telegram_chats.subject),
        deliverable = true,
        undeliverable_reason = null,
        undeliverable_at = null;

  return case when coalesce(v_existed, false) then 'updated' else 'registered' end;
end;
$$;


--
-- Name: record_tts_failure(uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.record_tts_failure(p_usage_id uuid, p_error_code text) RETURNS boolean
