--
-- Name: recover_stalled_jobs(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.recover_stalled_jobs() RETURNS TABLE(job_id uuid, from_state public.job_state, to_state public.job_state, reason text)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'app', 'public'
    AS $$
declare
  r record;
  v_to public.job_state;
  v_reason text;
  v_has_output boolean;
begin
  for r in
    select j.job_id, j.state, j.attempt, j.max_attempts, j.leased_by
    from public.jobs j
    where j.state in (
      'running', 'output_created', 'quality_review', 'committing', 'committed', 'notifying'
    )
      and (j.leased_until is null or j.leased_until < now())
    order by j.created_at
    for update
  loop
    select exists (select 1 from public.outputs o where o.job_id = r.job_id)
      into v_has_output;

    if v_has_output or r.state in ('committed', 'notifying') then
      -- §18's case. Two conditions, neither redundant: an output row means the
      -- work is durable wherever it stalled and retrying would redo it; and
      -- `committed`/`notifying` cannot legally go to `retrying` at all, so the
      -- machine decides those regardless of what the evidence says.
      v_to := 'notifying';
      v_reason := case
        when v_has_output then 'recovery: committed work with delivery outstanding'
        else 'recovery: past the commit point with no output to deliver'
      end;

    elsif r.attempt >= r.max_attempts then
      v_to := 'failed';
      v_reason := format(
        'recovery: %s attempts exhausted while in %s', r.max_attempts, r.state
      );

    else
      v_to := 'retrying';
      v_reason := format(
        'recovery: worker %s died holding this in %s',
        coalesce(r.leased_by, '(unleased)'), r.state
      );
    end if;

    update public.jobs j
    set state        = v_to,
        state_reason = v_reason,
        leased_by    = null,
        leased_until = null
    where j.job_id = r.job_id;

    return query select r.job_id, r.state, v_to, v_reason;
  end loop;
end;
$$;


--
-- Name: FUNCTION recover_stalled_jobs(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.recover_stalled_jobs() IS 'Reconciles jobs a dead worker left in flight. Only touches expired leases, so it is safe to run while workers are active. Resumes delivery rather than retrying when an output row exists (the work is durable) OR when the state is committed/notifying (the machine forbids retrying from there) - §18.';


--
-- Name: recover_stalled_syncs(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.recover_stalled_syncs() RETURNS integer
    LANGUAGE sql
    AS $$
  with recovered as (
    update public.sync_runs
    set state = 'abandoned',
        finished_at = app.now_utc(),
        leased_by = null,
        leased_until = null,
        detail = coalesce(detail, '') ||
          case when detail is null then '' else '; ' end ||
          'lease expired at ' || leased_until::text || ' - the worker died mid-sync'
    where state = 'running'
      and leased_until is not null
      and leased_until < app.now_utc()
    returning 1
  )
  select coalesce(count(*), 0)::integer from recovered;
$$;


--
-- Name: FUNCTION recover_stalled_syncs(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.recover_stalled_syncs() IS 'Marks runs whose lease expired as abandoned. A crash is not a verdict, so it is not recorded as a failure.';


--
-- Name: recoverable_projects(integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.recoverable_projects(p_limit integer DEFAULT 12) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'slug', x.slug,
           'name', x.name,
           'purpose', x.purpose,
           'archived_at', x.updated_at,
           'held', x.held
         ) order by x.updated_at desc), '[]'::jsonb)
    from (
      select p.slug, p.name, p.purpose, p.updated_at,
             (select count(*) from public.documents d where d.project_id = p.project_id)
             + (select count(*) from public.tasks t where t.project_id = p.project_id)
             + (select count(*) from public.contacts c where c.project_id = p.project_id)
               as held
        from public.projects p
       where p.status = 'archived'
         and not p.is_fixture
         and not app.harness_label(p.slug)
       order by p.updated_at desc
    ) x
   where x.held > 0
   limit greatest(coalesce(p_limit, 12), 1)
$$;


--
-- Name: recurring_failures(integer, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.recurring_failures(p_least integer DEFAULT 3, p_days integer DEFAULT 14) RETURNS TABLE(job_kind text, error_class text, subject text, seen integer, first_seen timestamp with time zone, last_seen timestamp with time zone, last_job_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select f.job_kind, f.error_class, f.subject, f.seen, f.first_seen, f.last_seen, f.last_job_id
    from public.failure_signatures f
   -- Belt and braces with the writer (0491): a signature whose last job is
   -- a suite's never reaches Grant, however it got into the table.
   where (f.last_job_id is null or not app.harness_job(f.last_job_id))
     and f.seen >= greatest(coalesce(p_least, 3), 2)
     and f.last_seen > app.now_utc() - make_interval(days => coalesce(p_days, 14))
   order by f.seen desc, f.last_seen desc
$$;


--
-- Name: references_in(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.references_in(p_text text) RETURNS TABLE(project_id uuid, slug text, name text, connector text, external_ref text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
  with found as (
    select lower(m[1]) as ref
      from regexp_matches(
             coalesce(p_text, ''),
             '([0-9a-fA-F]{8}-?[0-9a-fA-F]{4}-?[0-9a-fA-F]{4}-?[0-9a-fA-F]{4}-?[0-9a-fA-F]{12})',
             'g'
           ) as m
    union
    select lower(m[1] || '/' || m[2])
      from regexp_matches(
             coalesce(p_text, ''),
             '(?:github\.com[/:])?([A-Za-z0-9][\w-]{0,38})/([\w.-]{1,100}?)(?:\.git)?(?=[\s,)\]]|$)',
             'g'
           ) as m
  ),
  candidates as (
    select ref from found
    union
    select replace(ref, '-', '') from found
  )
  select distinct p.project_id, p.slug, p.name, a.connector, a.external_ref
    from public.project_attachments a
    join public.projects p on p.project_id = a.project_id
   where p.status = 'active'
     and not p.is_fixture
     and a.enabled
     and (
       lower(a.external_ref) in (select ref from candidates)
       or replace(lower(a.external_ref), '-', '') in (select ref from candidates)
     )
$_$;


--
-- Name: FUNCTION references_in(p_text text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.references_in(p_text text) IS 'Projects named by an external identifier appearing in a piece of text — a notebook UUID, a Notion id, an owner/repo. Only references already attached: this looks things up, it never invents or creates (0162).';


--
-- Name: register_mcp_provider(text, text, text, text, uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.register_mcp_provider(p_name text, p_endpoint text, p_display_name text DEFAULT ''::text, p_auth_kind text DEFAULT 'none'::text, p_credential_ref uuid DEFAULT NULL::uuid, p_notes text DEFAULT ''::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
declare v_id uuid;
begin
  if p_name !~ '^[a-z][a-z0-9_-]{1,30}$' then
    return jsonb_build_object('error',
      'a provider name is lower case letters, digits, dashes and underscores');
  end if;
  if p_endpoint !~ '^https://' then
    -- Plain HTTP would put a bearer token on the wire. Refused rather than
    -- warned about.
    return jsonb_build_object('error', 'an endpoint must be https');
  end if;
  if exists (select 1 from public.mcp_providers where name = p_name) then
    return jsonb_build_object('error', format('%L is already registered', p_name));
  end if;

  insert into public.mcp_providers
    (name, endpoint, display_name, auth_kind, credential_ref, notes)
  values (p_name, p_endpoint, coalesce(nullif(btrim(p_display_name), ''), p_name),
          p_auth_kind, p_credential_ref, coalesce(p_notes, ''))
  returning provider_id into v_id;

  -- Ask it what it offers. The note below has promised this
  -- since the function was written and nothing performed it.
  insert into public.jobs
    (correlation_id, project_id, idempotency_key, kind, requested_by,
     priority, pinned_config, announce)
  values (gen_random_uuid(), null,
          format('mcp-discover-%s-%s', p_name, gen_random_uuid()),
          'mcp.discover', 'connector:register', 150,
          jsonb_build_object('provider', p_name), true);

  return jsonb_build_object('ok', true, 'provider', v_id,
    'note', 'registered, and I am asking it what it offers. Nothing is granted by that survey.');
end;
$_$;


--
-- Name: reject_address_text_on(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.reject_address_text_on(p_text text) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
begin
  if p_text ~* '(https?|ftps?|wss?)://' then
    raise exception
      'A skill may not contain a URL. Name the tool that reaches it instead '
      '(ADR-0017).'
      using errcode = 'check_violation';
  end if;

  if p_text ~* '(^|[^a-z0-9._-])www\.[a-z0-9-]' then
    raise exception
      'A skill may not contain a web address. Name the tool that reaches it '
      'instead (ADR-0017).'
      using errcode = 'check_violation';
  end if;

  if p_text ~* '[a-z0-9._%+-]+@[a-z0-9-]+\.[a-z]{2,}' then
    raise exception
      'A skill may not contain an email address. Name the tool that reaches '
      'it instead (ADR-0017).'
      using errcode = 'check_violation';
  end if;

  if p_text ~ '(^|[^0-9.])[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}([^0-9.]|$)' then
    raise exception
      'A skill may not contain an IP address. Name the tool that reaches it '
      'instead (ADR-0017).'
      using errcode = 'check_violation';
  end if;

  if p_text ~* ('(^|[^a-z0-9._/-])[a-z0-9][a-z0-9-]*\.'
                || '(com|net|org|io|ai|co|dev|app|cloud|xyz|info|biz|tech|'
                || 'uk|de|fr|eu|us|gg|sh|me|to|so|online|site|live|link|store)'
                || '([^a-z0-9]|$)') then
    raise exception
      'A skill may not contain a hostname. Name the tool that reaches it '
      'instead (ADR-0017).'
      using errcode = 'check_violation';
  end if;
end;
$_$;


--
-- Name: FUNCTION reject_address_text_on(p_text text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.reject_address_text_on(p_text text) IS 'The ADR-0017 boundary. A skill names tools, never addresses: a procedure that can carry an endpoint is a procedure that can grant itself reach.';


--
-- Name: reject_credential_text(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.reject_credential_text() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform app.reject_credential_text_on(new.body);
  return new;
end;
$$;


--
-- Name: FUNCTION reject_credential_text(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.reject_credential_text() IS 'Lessons trigger. Delegates to app.reject_credential_text_on() so the pattern lives in exactly one place (0185).';


--
-- Name: reject_credential_text_on(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.reject_credential_text_on(p_text text) RETURNS void
    LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_text ~ '(sk-[A-Za-z0-9]{16,}|ghp_[A-Za-z0-9]{20,}|github_pat_[A-Za-z0-9_]{20,}|xox[baprs]-[A-Za-z0-9-]{10,}|-----BEGIN [A-Z ]*PRIVATE KEY-----|eyJ[A-Za-z0-9_-]{20,}\.[A-Za-z0-9_-]{20,}\.)'
  then
    raise exception 'that text looks like a credential and will not be stored'
      using errcode = '42501',
            hint = 'Secrets live in the Supabase Vault. Reference one by name; '
                   'never copy its value into a row.';
  end if;
end;
$$;


--
-- Name: FUNCTION reject_credential_text_on(p_text text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.reject_credential_text_on(p_text text) IS 'The one credential-shape check. 0181 and 0184 both call it so the two cannot drift apart and leave one table protected and the other not.';


--
-- Name: reject_impediment_credential(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.reject_impediment_credential() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  probe public.lessons%rowtype;
begin
  -- Reuse the one implementation rather than keeping two patterns in step.
  probe.body := coalesce(new.detail, '') || ' ' || coalesce(new.understood_as, '');
  perform app.reject_credential_text_on(probe.body);
  return new;
end;
$$;


--
-- Name: reject_ledger_mutation(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.reject_ledger_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
begin
  raise exception
    '%.% is append-only: % is never permitted (master spec §6)',
    tg_table_schema, tg_table_name, tg_op
    using errcode = '42501',
          hint = 'To reverse an action, INSERT a compensating row referencing '
                 'the original — never UPDATE or DELETE the history.';
end
$$;


--
-- Name: FUNCTION reject_ledger_mutation(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.reject_ledger_mutation() IS 'Blocks UPDATE, DELETE and TRUNCATE on append-only tables for every role, owner included — REVOKE cannot restrain the owner, and migrations run as the owner. Names the table it actually guarded, so the error is actionable.';


--
-- Name: relations_of(text, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.relations_of(p_kind text, p_id uuid) RETURNS TABLE(direction text, verb text, other_kind text, other_id uuid, other_title text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with edges as (
    select 'out'::text as direction, r.verb, r.to_kind as other_kind, r.to_id as other_id
      from public.relations r
     where r.from_kind = p_kind and r.from_id = p_id
    union all
    select 'in'::text, r.verb, r.from_kind, r.from_id
      from public.relations r
     where r.to_kind = p_kind and r.to_id = p_id

    -- Derived edges — the same fact read from both ends, so traversal is
    -- symmetric without anything being written twice (0310), speaking the
    -- stored verb vocabulary so a filter returns both halves (0311).

    union all
    select 'out', 'produced', 'document', d.document_id
      from public.documents d
     where p_kind = 'job' and d.produced_by_job = p_id
    union all
    select 'in', 'produced', 'job', d.produced_by_job
      from public.documents d
     where p_kind = 'document' and d.document_id = p_id and d.produced_by_job is not null

    union all
    select 'out', 'mirrors', 'document', d.mirrors_document_id
      from public.documents d
     where p_kind = 'document' and d.document_id = p_id and d.mirrors_document_id is not null
    union all
    select 'in', 'mirrors', 'document', d.document_id
      from public.documents d
     where p_kind = 'document' and d.mirrors_document_id = p_id

    union all
    select 'out', 'produced', 'document', d.document_id
      from public.documents d
      join public.staff s on s.slug = d.produced_by
     where p_kind = 'agent' and s.staff_id = p_id and coalesce(d.produced_by, '') <> ''
    union all
    select 'in', 'produced', 'agent', s.staff_id
      from public.documents d
      join public.staff s on s.slug = d.produced_by
     where p_kind = 'document' and d.document_id = p_id and coalesce(d.produced_by, '') <> ''

    union all
    select 'out', 'attached_to', 'collection', dc.collection_id
      from public.document_collections dc
     where p_kind = 'document' and dc.document_id = p_id
    union all
    select 'in', 'attached_to', 'document', dc.document_id
      from public.document_collections dc
     where p_kind = 'collection' and dc.collection_id = p_id

    union all
    select 'out', 'about', 'task', c.for_task_id
      from public.collections c
     where p_kind = 'collection' and c.collection_id = p_id and c.for_task_id is not null
    union all
    select 'in', 'about', 'collection', c.collection_id
      from public.collections c
     where p_kind = 'task' and c.for_task_id = p_id

    union all
    select 'out', 'assigned_to', 'agent', t.assignee_staff
      from public.tasks t
     where p_kind = 'task' and t.task_id = p_id and t.assignee_staff is not null
    union all
    select 'in', 'assigned_to', 'task', t.task_id
      from public.tasks t
     where p_kind = 'agent' and t.assignee_staff = p_id

    union all
    select 'out', 'output_of', 'job', t.job_id
      from public.tasks t
     where p_kind = 'task' and t.task_id = p_id and t.job_id is not null
    union all
    select 'in', 'output_of', 'task', t.task_id
      from public.tasks t
     where p_kind = 'job' and t.job_id = p_id

    union all
    select 'out', 'under', 'task', t.parent_task_id
      from public.tasks t
     where p_kind = 'task' and t.task_id = p_id and t.parent_task_id is not null
    union all
    select 'in', 'under', 'task', t.task_id
      from public.tasks t
     where p_kind = 'task' and t.parent_task_id = p_id
  )
  select e.direction, e.verb, e.other_kind, e.other_id,
         -- Resolved here so six callers cannot disagree about how to do it.
         -- A dangling edge yields null rather than dropping the row, so the
         -- graph reports its own damage instead of hiding it.
         coalesce(d.title, t.title, s.name, c.name, j.kind, src.name) as other_title
    from edges e
    left join public.documents   d on e.other_kind = 'document'   and d.document_id = e.other_id
    left join public.tasks       t on e.other_kind = 'task'       and t.task_id = e.other_id
    left join public.staff       s on e.other_kind = 'agent'      and s.staff_id = e.other_id
    left join public.collections c on e.other_kind = 'collection' and c.collection_id = e.other_id
    left join public.jobs        j on e.other_kind = 'job'        and j.job_id = e.other_id
    /*
      A source is two tables (0316). An authenticated attachment has a
      `display_name`; a plain reference (#35) has a `title`. Either can be the
      other end of a `derived_from`, so both are folded into one name here
      rather than making every caller know there are two kinds.
    */
    left join lateral (
      select coalesce(
               (select a.display_name from public.project_attachments a
                 where a.attachment_id = e.other_id),
               (select r.title from public.project_references r
                 where r.reference_id = e.other_id)) as name
    ) src on e.other_kind = 'source'
   order by e.direction, e.verb
$$;


--
-- Name: FUNCTION relations_of(p_kind text, p_id uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.relations_of(p_kind text, p_id uuid) IS '#29. Every relation an object has, both directions. Edges a COLUMN already holds are derived rather than copied into public.relations: storing them twice makes two witnesses that can disagree, and the copy is the one that rots. Derived and stored edges use ONE verb vocabulary (0311). A source resolves against attachments AND references, because it is both (0316).';


--
-- Name: reminders_due(interval); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.reminders_due(p_grace interval DEFAULT '14 days'::interval) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  /*
    `p_grace` is the floor, not the ceiling: a reminder whose time passed
    while the office was down should still arrive, and one from a fortnight
    ago should not — by then the due date has done the work and a stale
    midnight ping is noise. Fourteen days is long enough to survive any
    outage this office has had and short enough that a backlog cannot
    announce itself as a wall of text.
  */
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', t.task_id,
           'title', t.title,
           'remind_at', t.remind_at,
           'due_on', t.due_on,
           'project', p.name,
           'overdue', t.due_on is not null
                      and t.due_on < (app.now_utc() at time zone 'UTC')::date
         ) order by t.remind_at), '[]'::jsonb)
    from public.tasks t
    left join public.projects p on p.project_id = t.project_id
   where t.assigned_to_human
     and t.state <> 'done'
     and t.state <> 'cancelled'
     and not coalesce(t.is_fixture, false)
     and t.remind_at is not null
     and t.reminded_at is null
     and t.remind_at <= app.now_utc()
     and t.remind_at >= app.now_utc() - p_grace
$$;


--
-- Name: FUNCTION reminders_due(p_grace interval); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.reminders_due(p_grace interval) IS 'Personal-task reminders whose time has come and which have not been said yet. Reads only: app.reminders_sent does the marking, so a handler that dies before it has a body re-reminds rather than losing one (0512).';


--
-- Name: reminders_sent(uuid[]); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.reminders_sent(p_ids uuid[]) RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with marked as (
    update public.tasks
       set reminded_at = app.now_utc()
     where task_id = any(coalesce(p_ids, array[]::uuid[]))
       and reminded_at is null
    returning task_id
  )
  select count(*)::int from marked
$$;


--
-- Name: remove_automation(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.remove_automation(p_automation text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare v_by text; v_kind text; v_what text;
begin
  select created_by, job_kind, description into v_by, v_kind, v_what
    from public.responsibilities where slug = p_automation;
  if v_by is null then
    return jsonb_build_object('ok', false, 'error', format('no automation called %s', p_automation));
  end if;
  if v_by = 'migration' then
    return jsonb_build_object(
      'ok', false, 'refused', true,
      'error', 'That one runs the office rather than this project. Switch it off in Settings if you need it quiet.');
  end if;

  delete from public.responsibilities where slug = p_automation;
  return jsonb_build_object('ok', true, 'removed', p_automation, 'what', v_what);
end;
$$;


--
-- Name: remove_project_reference(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.remove_project_reference(p_reference_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare v_title text;
begin
  delete from public.project_references
   where reference_id = p_reference_id
  returning title into v_title;
  if v_title is null then
    return jsonb_build_object('ok', false, 'error', 'no such reference');
  end if;
  return jsonb_build_object('ok', true, 'removed', v_title);
end;
$$;


--
-- Name: rename_document(uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.rename_document(p_document uuid, p_title text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_was  text;
  v_new  text := btrim(coalesce(p_title, ''));
  v_undo uuid;
begin
  if v_new = '' then
    return jsonb_build_object('ok', false, 'error', 'a document needs a name');
  end if;
  select title into v_was from public.documents where document_id = p_document;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'no such document');
  end if;
  if v_was = v_new then
    return jsonb_build_object('ok', true, 'was', v_was, 'now', v_new, 'unchanged', true);
  end if;
  update public.documents set title = v_new, updated_at = app.now_utc()
   where document_id = p_document;

  -- The reversal is this same function with the old name, which is what
  -- "exactly invertible" means and why no separate undo path is needed.
  v_undo := app.undo_offer(
    'document.rename',
    format('Renamed %s', left(v_was, 60)),
    jsonb_build_object('action', 'document_rename',
                       'args', jsonb_build_object('p_document', p_document,
                                                  'p_title', v_was)));

  return jsonb_build_object('ok', true, 'was', v_was, 'now', v_new, 'undo', v_undo);
end;
$$;


--
-- Name: replays_never_announce(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.replays_never_announce() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if coalesce(new.requested_by, '') like 'verify:replay-%' then
    new.announce := false;
  end if;
  return new;
end;
$$;


--
-- Name: FUNCTION replays_never_announce(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.replays_never_announce() IS 'A replayed job and its descendants may not be delivered (#133), on insert AND on the update the worker uses to write the handler''s own announce decision. Scoped to the verify:replay- namespace: harness traffic in general MAY announce, because the suites that test delivery need to.';


--
-- Name: request_approval(uuid, text, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.request_approval(p_job uuid, p_action text, p_why text, p_next text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_project uuid;
  v_agent text;
  v_id uuid;
begin
  if p_next not in ('notebook.generate', 'office.execute_plan') then
    -- The list is fixed for the same reason the MCP kinds are: an approval
    -- that can start any job kind is a button that can start any job kind.
    raise exception '% is not a kind an approval may start', p_next
      using errcode = '22023';
  end if;

  select project_id into v_project from public.jobs where job_id = p_job;

  -- Up the parent chain: a follow-up job is the same person continuing the
  -- same work, and the routing decision lives on the job that took the
  -- message. Third place this has been needed, hence the note in
  -- new-environment.md rather than a fourth fix in a fourth file.
  with recursive lineage as (
    select job_id, parent_job_id, 0 as depth
      from public.jobs where job_id = p_job
    union all
    select j.job_id, j.parent_job_id, l.depth + 1
      from public.jobs j join lineage l on j.job_id = l.parent_job_id
     where l.depth < 8
  )
  select s.name into v_agent
    from lineage l
    join public.routing_decisions r on r.job_id = l.job_id
    join public.staff s on s.slug = r.roster[1]
   order by l.depth asc, r.decided_at desc
   limit 1;

  select blocker_id into v_id
    from public.blockers where job_id = p_job and state = 'open' limit 1;
  if v_id is not null then
    return v_id;
  end if;

  insert into public.blockers
    (project_id, job_id, requested_action, why_needed, consequences_of_delay,
     approval_options, originating_agent, work_can_continue)
  values (
    v_project, p_job, p_action,
    -- The plan, appended (#131). Empty when the job has none, so a job that
    -- only reads gains nothing and no blank heading.
    p_why || app.job_plan_text(p_job),
    'Nothing happens until you answer. The request stays here.',
    array['Go ahead', 'Not now'],
    coalesce(v_agent, (select name from public.staff where slug = 'chief-of-staff')),
    true
  )
  returning blocker_id into v_id;

  -- What the yes should start. On the job, because `pinned_config` is already
  -- §6's record of the configuration a job ran under, and a plan is exactly
  -- that.
  update public.jobs
     set pinned_config = pinned_config || jsonb_build_object('approval_next', p_next)
   where job_id = p_job;

  return v_id;
end;
$$;


--
-- Name: request_carries_no_credential(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.request_carries_no_credential() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform app.reject_credential_text_on(new.what_for);
  perform app.reject_credential_text_on(coalesce(new.decline_reason, ''));
  return new;
end;
$$;


--
-- Name: request_generation_approval(uuid, text, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.request_generation_approval(p_job uuid, p_kind text, p_what text, p_cost text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_project uuid;
  v_agent text;
  v_id uuid;
begin
  select project_id into v_project from public.jobs where job_id = p_job;

  -- Up the parent chain. A generation job is the child of the instruction that
  -- asked for it, and the routing decision — who is speaking — lives on the
  -- parent. Bounded at eight because a chain deeper than that is a bug, and an
  -- unbounded recursive CTE over a table with a self-reference is how a bug
  -- becomes an outage.
  with recursive lineage as (
    select job_id, parent_job_id, 0 as depth
      from public.jobs where job_id = p_job
    union all
    select j.job_id, j.parent_job_id, l.depth + 1
      from public.jobs j join lineage l on j.job_id = l.parent_job_id
     where l.depth < 8
  )
  select s.name into v_agent
    from lineage l
    join public.routing_decisions r on r.job_id = l.job_id
    join public.staff s on s.slug = r.roster[1]
   order by l.depth asc, r.decided_at desc
   limit 1;

  select blocker_id into v_id
    from public.blockers
   where job_id = p_job and state = 'open'
   limit 1;
  if v_id is not null then
    return v_id;
  end if;

  insert into public.blockers
    (project_id, job_id, requested_action, why_needed, consequences_of_delay,
     approval_options, originating_agent, work_can_continue)
  values (
    v_project, p_job,
    format('Generate %s in the notebook', p_what),
    p_cost,
    'Nothing is generated until you say so. The request stays here until you answer it.',
    array['Go ahead', 'Not now'],
    -- The Chief of Staff, not "the team", when the chain says nothing. She is
    -- who asks when nobody else was convened, and a request signed by a
    -- collective noun is a request from the software.
    coalesce(v_agent, (select name from public.staff where slug = 'chief-of-staff')),
    true
  )
  returning blocker_id into v_id;

  return v_id;
end;
$$;


--
-- Name: FUNCTION request_generation_approval(p_job uuid, p_kind text, p_what text, p_cost text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.request_generation_approval(p_job uuid, p_kind text, p_what text, p_cost text) IS 'Ask before generating. A blocker rather than a new table, because `blockers` is already "a thing waiting on Grant, with options, surfaced in Needs Me" and a second one of those would be a second Needs Me.';


--
-- Name: request_stop(uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.request_stop(p_job uuid, p_who text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_state text;
begin
  select state::text into v_state from public.jobs where job_id = p_job;
  if v_state is null then
    return jsonb_build_object('error', 'there is no job by that id');
  end if;
  if v_state in ('complete', 'failed', 'cancelled') then
    return jsonb_build_object('ok', false, 'note',
      'that job already finished, so there is nothing to stop');
  end if;
  update public.jobs
     set stop_requested_at = coalesce(stop_requested_at, app.now_utc()),
         stop_requested_by = coalesce(stop_requested_by, nullif(trim(coalesce(p_who, '')), '')),
         updated_at = app.now_utc()
   where job_id = p_job;
  return jsonb_build_object('ok', true, 'state', v_state);
end;
$$;


--
-- Name: request_tool(text, text, text, jsonb, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.request_tool(p_tool text, p_asked_by text, p_what_for text, p_because jsonb DEFAULT '{}'::jsonb, p_from_job uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  refused public.tool_requests%rowtype;
  made    public.tool_requests%rowtype;
begin
  -- Nothing to ask for. Answering "you already have it" beats an open request
  -- sitting in front of Grant for a decision he already made.
  if app.staff_may_use(p_asked_by, p_tool) then
    return jsonb_build_object('already_held', true, 'tool', p_tool);
  end if;

  /*
    A decline that is still in force, keyed on the exact tool and person.

    Ninety days per decline. The `order by` matters: the most recent refusal is
    the one whose clock is running, and taking any other row would let an old
    settled decline expire the silence a new one just bought.
  */
  select * into refused
    from public.tool_requests
   where tool = p_tool and asked_by = p_asked_by and state = 'declined'
   order by settled_at desc nulls last
   limit 1;

  if found and refused.settled_at
       > app.now_utc() - (greatest(refused.declines, 1) * interval '90 days') then
    return jsonb_build_object(
      'declined', true,
      'tool', p_tool,
      'reason', refused.decline_reason,
      'may_ask_again_after',
        refused.settled_at + (greatest(refused.declines, 1) * interval '90 days'));
  end if;

  insert into public.tool_requests (tool, asked_by, what_for, because, from_job)
  values (p_tool, p_asked_by, p_what_for, coalesce(p_because, '{}'::jsonb), p_from_job)
  on conflict (tool, asked_by) where state = 'open' do nothing
  returning * into made;

  if made.request_id is null then
    -- Already asked and still waiting. Not an error: the honest answer is that
    -- the ask exists, and repeating it would only make the queue longer.
    select * into made from public.tool_requests
     where tool = p_tool and asked_by = p_asked_by and state = 'open';
    return jsonb_build_object('request_id', made.request_id, 'already_asked', true);
  end if;

  perform public.append_event(
    coalesce((select correlation_id from public.jobs where job_id = p_from_job),
             extensions.gen_random_uuid()),
    'agent', p_asked_by, 'capability_gap', 'tool.requested',
    true, null, null,
    jsonb_build_object('tool', p_tool, 'request_id', made.request_id),
    left(p_what_for, 1000), '[]'::jsonb, null, null,
    -- §6: if the author cannot say how to undo it, it is not reversible.
    'app.withdraw_tool_request(request_id)',
    p_from_job);

  return jsonb_build_object('request_id', made.request_id, 'tool', p_tool);
end;
$$;


--
-- Name: FUNCTION request_tool(p_tool text, p_asked_by text, p_what_for text, p_because jsonb, p_from_job uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.request_tool(p_tool text, p_asked_by text, p_what_for text, p_because jsonb, p_from_job uuid) IS 'An agent asking to be able to reach something. Writes one row and grants nothing — app.staff_may_use() answers identically before and after (ADR-0018). Refuses while a decline is still in force.';


--
-- Name: request_undo(uuid, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.request_undo(p_action_id uuid, p_requested_by text, p_source text DEFAULT NULL::text) RETURNS public.undo_status
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$ select outcome from app.claim_undo(p_action_id, p_requested_by, p_source) $$;


--
-- Name: FUNCTION request_undo(p_action_id uuid, p_requested_by text, p_source text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.request_undo(p_action_id uuid, p_requested_by text, p_source text) IS 'Idempotent under concurrent duplicate delivery. A thin wrapper over app.claim_undo; a caller that PERFORMS a reversal must use claim_undo and honour `won`, because this answers what became of the action and not who got to act on it.';


--
-- Name: requeue_retrying(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.requeue_retrying() RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_count integer;
begin
  with moved as (
    update public.jobs j
    set state = 'queued', state_reason = 'requeued after retry'
    where j.state = 'retrying'
      and j.attempt < j.max_attempts
    returning 1
  )
  select count(*) into v_count from moved;
  return v_count;
end
$$;


--
-- Name: reserve_tts_characters(text, integer, integer, uuid, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.reserve_tts_characters(p_provider text, p_characters integer, p_ceiling integer, p_correlation_id uuid DEFAULT NULL::uuid, p_purpose text DEFAULT 'voice_note'::text, p_voice text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_used integer;
  v_id uuid;
begin
  if p_characters <= 0 then
    return null;
  end if;

  -- Serialise reservations for this provider and month, so two concurrent
  -- callers cannot both see room for the last thousand characters. An advisory
  -- lock rather than a row lock because the thing being protected is a SUM,
  -- and there is no row to lock until after the decision.
  perform pg_advisory_xact_lock(hashtext('tts:' || p_provider));

  v_used := app.tts_characters_this_month(p_provider);
  if v_used + p_characters > p_ceiling then
    return null;
  end if;

  insert into public.tts_usage
    (provider, voice, characters, correlation_id, purpose)
  values
    (p_provider, p_voice, p_characters, p_correlation_id, p_purpose)
  returning usage_id into v_id;

  return v_id;
end;
$$;


--
-- Name: resolve_inbound_subject(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.resolve_inbound_subject() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
begin
  if new.subject is null then
    new.subject := app.subject_for(new.origin_channel, new.actor);
  end if;
  return new;
end;
$$;


--
-- Name: FUNCTION resolve_inbound_subject(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.resolve_inbound_subject() IS 'Fills inbound_commands.subject from the identity table (§31). A trigger rather than a rule each writer follows, because a column that depends on every writer remembering is right until the third writer.';


--
-- Name: resolve_indeterminate_delivery(uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.resolve_indeterminate_delivery(p_delivery_id uuid, p_message_ref text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_row public.deliveries;
begin
  select * into v_row from public.deliveries
    where delivery_id = p_delivery_id for update;
  if not found then
    raise exception 'no delivery %', p_delivery_id using errcode = 'no_data_found';
  end if;

  if v_row.state = 'sent' then return 'already_sent'; end if;

  if v_row.state <> 'failed' or coalesce(v_row.error_code, '') not like 'indeterminate:%' then
    -- Not an exception: a sweep meets rows that resolved themselves between the
    -- read and the write, and that is normal.
    return 'not_indeterminate';
  end if;

  if p_message_ref is not null then
    update public.deliveries
       set state = 'sent', message_ref = p_message_ref, sent_at = app.now_utc()
     where delivery_id = p_delivery_id;
    return 'sent';
  end if;

  update public.deliveries
     set state = 'claimed', error_code = null,
         lease_expires_at = app.now_utc() - interval '1 second'
   where delivery_id = p_delivery_id;
  return 'retryable';
end;
$$;


--
-- Name: resolve_project(public.project_scope_kind, text, uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.resolve_project(p_scope_kind public.project_scope_kind, p_scope_ref text, p_explicit uuid DEFAULT NULL::uuid, p_said text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_mapped uuid;
  v_named  uuid;
  v_count  integer;
begin
  -- 1. What the caller already resolved.
  if p_explicit is not null then
    return p_explicit;
  end if;

  -- 2. An identifier for something we are attached to, appearing in the words
  --    themselves. Above the channel map on purpose: a notebook id pasted into
  --    a project's own channel is somebody talking about that notebook, and
  --    the channel is the weaker signal because it is ambient. The id was
  --    typed. Declines when two projects match, like every other step here.
  if p_said is not null then
    select count(*), (array_agg(r.project_id))[1]
      into v_count, v_named
      from (select distinct project_id from app.references_in(p_said)) r;
    if v_count = 1 then
      return v_named;
    end if;
  end if;

  -- 3. A permanent channel mapping. Outranks a switch made IN that channel:
  --    the map is deliberate configuration, and a passing "let's look at X"
  --    must not silently repoint the team's project channel.
  if p_scope_kind = 'slack_channel' then
    v_mapped := app.project_for_slack_channel(p_scope_ref);
    if v_mapped is not null then
      return v_mapped;
    end if;
  end if;

  -- 4. The scope's current switch.
  v_mapped := app.current_project(p_scope_kind, p_scope_ref);
  if v_mapped is not null then
    return v_mapped;
  end if;

  -- 5. A NAME in what was said, and only when it is unambiguous. Below the
  --    switch, unlike an identifier above it: a name is a phrase and a phrase
  --    can be in passing.
  if p_said is not null then
    select count(*), (array_agg(r.project_id))[1]
      into v_count, v_named
      from app.resolve_project_by_name(p_said) r
     where r.confidence >= 0.90;
    if v_count = 1 then
      return v_named;
    end if;
  end if;

  -- 6. Null, meaning ASK. Deliberately not "the most recently touched
  --    project", which is how work lands in the wrong place while looking
  --    entirely reasonable.
  return null;
end;
$$;


--
-- Name: resolve_project_by_name(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.resolve_project_by_name(p_text text) RETURNS TABLE(project_id uuid, slug text, name text, confidence numeric, how text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
  with asked as (
    select app.normalise_name(p_text) as n
  ),
  live as (
    -- One place the fixture rule is applied, rather than four.
    select p.* from public.projects p
     where p.status = 'active' and not p.is_fixture
  ),
  scored as (
    select p.project_id, p.slug, p.name, 1.00::numeric as confidence, 'slug'::text as how
      from live p
     cross join asked a
     where a.n is not null and app.normalise_name(p.slug) = a.n

    union all

    select p.project_id, p.slug, p.name,
           least(0.99, 0.90 + (al.confidence * 0.09))::numeric,
           case al.source when 'grant' then 'you call it that'
                          when 'name' then 'its name'
                          when 'slug' then 'its slug'
                          else 'a name we picked up' end
      from public.project_aliases al
      join live p on p.project_id = al.project_id
     cross join asked a
     where a.n is not null and al.normalised = a.n

    union all

    -- The name inside a sentence (0156).
    select p.project_id, p.slug, p.name,
           least(0.95, 0.86 + (al.confidence * 0.09))::numeric,
           case al.source when 'grant' then 'you called it that, in what you said'
                          when 'name' then 'its name, in what you said'
                          else 'a name we know, in what you said' end
      from public.project_aliases al
      join live p on p.project_id = al.project_id
     cross join asked a
     where a.n is not null
       and length(al.normalised) >= 4
       and al.normalised <> a.n
       and a.n ~ ('\m' || regexp_replace(al.normalised, '([.^$*+?()\[\]{}|\\])', '\\\1', 'g') || '\M')

    union all

    select p.project_id, p.slug, p.name,
           (0.40 + (0.45 * greatest(
              extensions.similarity(app.normalise_name(p.name), a.n),
              coalesce((select max(extensions.similarity(al2.normalised, a.n))
                          from public.project_aliases al2
                         where al2.project_id = p.project_id), 0),
              coalesce(extensions.similarity(app.normalise_name(coalesce(p.description, '')), a.n), 0) * 0.6,
              coalesce(extensions.similarity(app.normalise_name(coalesce(p.purpose, '')), a.n), 0) * 0.6
           )))::numeric,
           'a close match on the name'::text
      from live p
     cross join asked a
     where a.n is not null
       and greatest(
             extensions.similarity(app.normalise_name(p.name), a.n),
             coalesce((select max(extensions.similarity(al3.normalised, a.n))
                         from public.project_aliases al3
                        where al3.project_id = p.project_id), 0),
             coalesce(extensions.similarity(app.normalise_name(coalesce(p.description, '')), a.n), 0) * 0.6,
             coalesce(extensions.similarity(app.normalise_name(coalesce(p.purpose, '')), a.n), 0) * 0.6
           ) >= 0.34
  )
  select distinct on (s.project_id)
         s.project_id, s.slug, s.name, round(s.confidence, 3), s.how
    from scored s
   order by s.project_id, s.confidence desc
$_$;


--
-- Name: FUNCTION resolve_project_by_name(p_text text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.resolve_project_by_name(p_text text) IS 'Scored candidates for a phrase, best route per project. Never picks — the caller applies its own threshold and says which route it took (0153).';


--
-- Name: resolve_secret(app.vault_secret_ref); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.resolve_secret(p_ref app.vault_secret_ref) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'vault', 'public'
    AS $$
declare
  v_secret text;
begin
  if p_ref is null then
    return null;
  end if;

  select decrypted_secret into v_secret
  from vault.decrypted_secrets
  where id = p_ref::uuid;

  if not found then
    raise exception 'vault secret % does not exist', p_ref
      using errcode = '23503';
  end if;

  return v_secret;
end
$$;


--
-- Name: FUNCTION resolve_secret(p_ref app.vault_secret_ref); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.resolve_secret(p_ref app.vault_secret_ref) IS 'The ONLY path from a reference to a plaintext credential (§15). Takes a reference, never a name, so a caller cannot enumerate the vault — it can only resolve what a row already handed it. Its return value must never reach a log, an error trace, or the event ledger.';


--
-- Name: resumable_now(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.resumable_now() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'job_id', j.job_id, 'kind', j.kind, 'reason', p.reason,
           'since', p.at) order by p.at), '[]'::jsonb)
    from public.jobs j
    join public.job_pauses p on p.job_id = j.job_id and p.resumed_at is null
   where j.state = 'paused'
     and p.resumable
     and p.reason in ('scheduled_wait', 'rate_limited', 'provider_unavailable',
                      'dependency_wait')
     and (p.expires_at is null or p.expires_at > app.now_utc())
     and (j.not_before is null or j.not_before <= app.now_utc());
$$;


--
-- Name: resume_job(uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.resume_job(p_job uuid, p_why text DEFAULT 'the condition was met'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare v_state text; v_resumable boolean;
begin
  select state::text into v_state from public.jobs where job_id = p_job;
  if v_state is null then
    return jsonb_build_object('error', 'no such job');
  end if;
  if v_state <> 'paused' then
    return jsonb_build_object('error', format('that job is %s, not paused', v_state));
  end if;
  select resumable into v_resumable from public.job_pauses
   where job_id = p_job and resumed_at is null order by at desc limit 1;
  if v_resumable is false then
    return jsonb_build_object('error',
      'that pause was recorded as not automatically resumable; it needs a person');
  end if;

  update public.job_pauses
     set resumed_at = app.now_utc(), resumed_why = left(coalesce(p_why, ''), 400)
   where job_id = p_job and resumed_at is null;

  update public.jobs
     set state = 'queued', state_reason = left(coalesce(p_why, 'resumed'), 500),
         waiting_on = null, not_before = null
   where job_id = p_job;

  return jsonb_build_object('ok', true);
end;
$$;


--
-- Name: resume_paused(text[]); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.resume_paused(p_kinds text[] DEFAULT NULL::text[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app', 'public'
    AS $$
declare
  v_count integer := 0;
  r record;
begin
  for r in
    select j.job_id, j.kind from public.jobs j
     where j.state = 'paused'
       and (p_kinds is null or j.kind = any(p_kinds))
       -- Only the ones parked for the reason this fixes. A job paused for any
       -- other reason was paused deliberately, and un-pausing it would be
       -- overriding a decision rather than repairing an accident.
       and coalesce(j.state_reason, '') like 'no handler for kind%'
     for update skip locked
  loop
    update public.jobs
       set state = 'queued',
           state_reason = 'resumed: a worker that knows this kind is running now',
           leased_by = null,
           leased_until = null
     where job_id = r.job_id;
    v_count := v_count + 1;
  end loop;
  return v_count;
end
$$;


--
-- Name: FUNCTION resume_paused(p_kinds text[]); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.resume_paused(p_kinds text[]) IS 'Requeue jobs parked because the worker that claimed them had no handler. Called by the drain before it claims anything. Only that reason: a job paused deliberately stays paused.';


--
-- Name: resume_worker(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.resume_worker() RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  update public.system_config set value = to_jsonb(''::text)
   where key = 'worker.paused_until'
$$;


--
-- Name: retire_skill(uuid, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.retire_skill(p_skill_id uuid, p_by text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  prior public.skills%rowtype;
begin
  select * into prior from public.skills where skill_id = p_skill_id;
  if not found then
    return jsonb_build_object('error', 'no such skill: ' || p_skill_id::text);
  end if;
  if exists (select 1 from public.skills where supersedes = p_skill_id) then
    return jsonb_build_object('error', 'that skill has already been revised or retired');
  end if;
  if length(btrim(coalesce(p_reason, ''))) < 8 then
    return jsonb_build_object('error', 'a retirement needs a reason');
  end if;

  insert into public.skills
    (row_kind, scope, project_id, staff_slug, job_kind, name, when_to_use,
     procedure, authored_by, version, supersedes)
  values
    ('retirement', prior.scope, prior.project_id, prior.staff_slug, prior.job_kind,
     prior.name,
     'Retired. ' || btrim(p_reason),
     'This skill was withdrawn and is no longer used. Reason given: '
       || btrim(p_reason),
     p_by, prior.version + 1, p_skill_id);

  return jsonb_build_object('retired', p_skill_id, 'by', p_by);
end;
$$;


--
-- Name: FUNCTION retire_skill(p_skill_id uuid, p_by text, p_reason text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.retire_skill(p_skill_id uuid, p_by text, p_reason text) IS 'Withdraw a skill, with a reason and an author. A row rather than a flag: the table refuses UPDATE, and who withdrew it is worth keeping (#54).';


--
-- Name: retract_lesson(uuid, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.retract_lesson(p_lesson_id uuid, p_why text DEFAULT NULL::text, p_by text DEFAULT 'grant'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  l    public.lessons%rowtype;
  v_id uuid;
begin
  select * into l from public.lessons where lesson_id = p_lesson_id;
  if not found then
    return jsonb_build_object('error', 'there is no such lesson');
  end if;
  if l.row_kind <> 'lesson' then
    return jsonb_build_object('error', 'that is a retraction, not a lesson');
  end if;
  if exists (select 1 from public.lessons where supersedes = p_lesson_id) then
    -- Not an error. Two open tabs produce this, and the honest answer is that
    -- it is already gone rather than a failure.
    return jsonb_build_object('ok', false, 'already', true);
  end if;

  insert into public.lessons
    (row_kind, scope, project_id, staff_slug, job_kind, body, learned_by,
     confidence, supersedes)
  values ('retraction', l.scope, l.project_id, l.staff_slug, l.job_kind,
          coalesce(nullif(btrim(coalesce(p_why, '')), ''),
                   format('Retracted by %s.', p_by)),
          p_by, l.confidence, p_lesson_id)
  returning lesson_id into v_id;

  return jsonb_build_object('ok', true, 'retraction', v_id, 'retracted', p_lesson_id);
end;
$$;


--
-- Name: retry_delivery(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.retry_delivery(p_delivery_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_row public.deliveries;
begin
  select * into v_row from public.deliveries
    where delivery_id = p_delivery_id for update;
  if not found then
    raise exception 'no delivery %', p_delivery_id using errcode = 'no_data_found';
  end if;

  if v_row.state = 'sent' then
    return 'already_sent';
  end if;
  if v_row.state = 'suppressed' then
    -- Suppression is a decision somebody made about whether this SHOULD be
    -- sent. Undoing it here would let a retry button override a policy.
    return 'suppressed';
  end if;

  update public.deliveries
     set state = 'claimed',
         attempt = 1,
         lease_expires_at = app.now_utc()
   where delivery_id = p_delivery_id;

  return 'queued';
end;
$$;


--
-- Name: retry_job_deliveries(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.retry_job_deliveries(p_job_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_id uuid;
  v_queued int := 0;
  v_skipped int := 0;
  v_result text;
begin
  if p_job_id is null then
    raise exception 'a job is required' using errcode = 'invalid_parameter_value';
  end if;

  /*
    Only the failed ones. A job whose Telegram delivery succeeded and whose
    Slack delivery did not must not have the Telegram message sent twice —
    which is #195's guarantee, and the cheapest way to keep it is not to ask.
  */
  for v_id in
    select d.delivery_id from public.deliveries d
     where d.job_id = p_job_id and d.state = 'failed'
     order by d.updated_at
  loop
    v_result := app.retry_delivery(v_id);
    if v_result = 'queued' then
      v_queued := v_queued + 1;
    else
      v_skipped := v_skipped + 1;
    end if;
  end loop;

  return jsonb_build_object(
    'job', p_job_id,
    'queued', v_queued,
    'skipped', v_skipped,
    -- Said in words, because the studio shows this to a person and a pair of
    -- integers is not an answer.
    'says', case
      when v_queued = 0 and v_skipped = 0 then 'There was nothing waiting to be sent.'
      when v_queued = 0 then 'Nothing could be queued again.'
      when v_queued = 1 then 'Queued again. It will go out within a minute.'
      else 'Queued ' || v_queued::text || ' again. They will go out within a minute.'
    end
  );
end;
$$;


--
-- Name: FUNCTION retry_job_deliveries(p_job_id uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.retry_job_deliveries(p_job_id uuid) IS 'Issue #202. Queue every FAILED delivery of one job again. Deliveries that succeeded are left alone, so a retry cannot send twice.';


--
-- Name: revoke_mcp_provider(uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.revoke_mcp_provider(p_provider uuid, p_why text DEFAULT ''::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare v_name text; v_off integer;
begin
  select name into v_name from public.mcp_providers where provider_id = p_provider;
  if v_name is null then
    return jsonb_build_object('error', 'no such provider');
  end if;

  update public.tool_permissions
     set enabled = false,
         disabled_reason = left(format('%s was disconnected. %s', v_name, coalesce(p_why, '')), 900)
   where delivered_by = format('mcp:%s', v_name) and enabled;
  get diagnostics v_off = row_count;

  update public.mcp_providers
     set enabled = false, revoked_at = app.now_utc(), updated_at = app.now_utc(),
         notes = left(coalesce(notes, '') || format(E'\ndisconnected: %s', coalesce(p_why, '')), 2000)
   where provider_id = p_provider;

  return jsonb_build_object('ok', true, 'provider', v_name, 'tools_disabled', v_off);
end;
$$;


--
-- Name: revoke_standing(uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.revoke_standing(p_authorization uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare v_n integer;
begin
  update public.standing_authorizations
     set revoked_at = app.now_utc(),
         revoked_reason = coalesce(nullif(btrim(p_reason), ''), 'you took it back')
   where authorization_id = p_authorization and revoked_at is null;
  get diagnostics v_n = row_count;
  -- 0350's lesson: a delete keyed on something nobody checked reports success
  -- having matched nothing. Say which happened.
  if v_n = 0 then
    return jsonb_build_object('ok', false,
      'error', 'there is no live standing authorization with that id');
  end if;
  return jsonb_build_object('ok', true, 'revoked', p_authorization);
end;
$$;


--
-- Name: revoke_tool(text, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.revoke_tool(p_slug text, p_tool text, p_by text DEFAULT 'grant'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_out jsonb;
begin
  v_out := app.hq_staff_tool_set(p_slug, p_tool, false, p_by);
  if v_out ? 'error' then
    return v_out;
  end if;
  if not coalesce((v_out->>'changed')::boolean, false) then
    return jsonb_build_object('error', format('%s does not hold %s', p_slug, p_tool));
  end if;
  return jsonb_build_object('revoked', p_tool, 'from', p_slug);
end;
$$;


--
-- Name: FUNCTION revoke_tool(p_slug text, p_tool text, p_by text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.revoke_tool(p_slug text, p_tool text, p_by text) IS 'The other half of a grant. Named in the ledger as the reversal method for tool.granted, so §6''s rule that a reversal method must be real holds.';


--
-- Name: say_in_project(uuid, text, text, text[]); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.say_in_project(p_project_id uuid, p_text text, p_addressed_to text DEFAULT NULL::text, p_addressed_also text[] DEFAULT '{}'::text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_said     text := nullif(btrim(coalesce(p_text, '')), '');
  v_to       text := nullif(btrim(coalesce(p_addressed_to, '')), '');
  v_also     text[];
  v_asked    text[] := coalesce(p_addressed_also, '{}');
  v_dropped  text[] := '{}';
  v_key      text;
  v_command  uuid;
  v_queued   jsonb;
begin
  if p_project_id is null
     or not exists (select 1 from public.projects where project_id = p_project_id) then
    return jsonb_build_object('ok', false, 'error', 'no such project');
  end if;

  if v_said is null then
    return jsonb_build_object('ok', false, 'error', 'there is nothing to say');
  end if;

  /*
    Who was asked and could not be found, gathered BEFORE anything is dropped.

    The old version returned a single `addressee_dropped`. A composer that
    quietly ignores who you picked is worse than one that says it could not
    find them, and with a selection there can be more than one - so it is a
    list now, and it names every one.
  */
  select coalesce(array_agg(t.slug order by t.slug), '{}')
    into v_dropped
    from unnest(array_remove(array_append(v_asked, v_to), null)) as t(slug)
   where not exists (select 1 from public.staff s where s.slug = t.slug and s.active);

  if v_to is not null
     and not exists (select 1 from public.staff where slug = v_to and active) then
    v_to := null;
  end if;

  /*
    Everybody real that Grant picked, minus whoever is answering.

    If he picked three and named no answerer, the FIRST becomes the answerer
    and the rest are convened - because somebody has to speak, and choosing
    for him here is better than a reply attributed to nobody.
  */
  select coalesce(array_agg(distinct s.slug order by s.slug), '{}')
    into v_also
    from unnest(v_asked) as t(slug)
    join public.staff s on s.slug = t.slug and s.active;

  if v_to is null and cardinality(v_also) > 0 then
    v_to := v_also[1];
  end if;
  v_also := array_remove(v_also, v_to);

  v_key := 'teamhq:message:' || replace(gen_random_uuid()::text, '-', '');

  insert into public.inbound_commands
    (origin_channel, origin_ref, actor, instruction, addressed_to, addressed_also,
     dedupe_key, project_id, context)
  values ('teamhq', v_key, 'grant', v_said, v_to, v_also, v_key, p_project_id,
          jsonb_build_object('project_id', p_project_id))
  returning command_id into v_command;

  v_queued := app.enqueue_inbound(v_command);

  return jsonb_build_object(
    'ok', true,
    'command', v_command,
    'job', v_queued->>'job_id',
    'project', p_project_id,
    'addressed_to', v_to,
    'addressed_also', to_jsonb(v_also),
    -- Named rather than silent, and all of them rather than the first.
    'addressee_dropped', to_jsonb(v_dropped));
end;
$$;


--
-- Name: say_schedule(integer, time without time zone, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.say_schedule(p_minutes integer, p_at time without time zone, p_zone text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    when p_at is not null and p_minutes >= 10080 then 'weekly at ' || to_char(p_at, 'HH24:MI')
    when p_at is not null then 'every day at ' || to_char(p_at, 'HH24:MI')
    when p_minutes % 10080 = 0 and p_minutes >= 10080 then
      case when p_minutes = 10080 then 'once a week'
           else 'every ' || (p_minutes / 10080)::text || ' weeks' end
    when p_minutes % 1440 = 0 then
      case when p_minutes = 1440 then 'once a day'
           else 'every ' || (p_minutes / 1440)::text || ' days' end
    when p_minutes % 60 = 0 then
      case when p_minutes = 60 then 'every hour'
           else 'every ' || (p_minutes / 60)::text || ' hours' end
    else 'every ' || p_minutes::text || ' minutes'
  end
$$;


--
-- Name: search_documents(text, uuid, integer, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.search_documents(p_query text, p_project uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 10, p_match text DEFAULT 'all'::text) RETURNS TABLE(document_id uuid, project_id uuid, connector text, title text, rank real, snippet text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  with q as (
    select case
             when p_match = 'any' then
               nullif(
                 array_to_string(
                   tsvector_to_array(to_tsvector('english', coalesce(p_query, ''))), ' | '
                 ), ''
               )::tsquery
             else websearch_to_tsquery('english', coalesce(p_query, ''))
           end as tsq
  )
  select d.document_id,
         d.project_id,
         d.connector,
         d.title,
         ts_rank(d.search, q.tsq) as rank,
         ts_headline('english', coalesce(d.content, ''), q.tsq,
                     'MaxWords=40, MinWords=20, ShortWord=3, MaxFragments=2') as snippet
    from public.documents d, q
   -- A query with no lexemes at all - "the and of" - is null here, and the
   -- match operator against null is null, so it matches nothing. That is the
   -- correct answer and not an error: there was nothing to search for.
   where q.tsq is not null
     and d.search @@ q.tsq
     and (p_project is null or d.project_id = p_project)
     -- A route being closed does not hide what it already brought in. Section
     -- 17 turns off a connector, not the documents it fed.
     --
     -- ADR-0040: archived material keeps its row, its content and its
     -- relations, and leaves ordinary retrieval.
     and coalesce(d.state, '') <> 'archived'
     -- One document, one hit. A mirror steps aside only when the thing it
     -- mirrors is visible here too.
     and not exists (
       select 1 from public.documents o
        where o.document_id = d.mirrors_document_id
          and coalesce(o.state, '') <> 'archived'
          and (p_project is null or o.project_id = p_project)
     )
   order by rank desc, d.updated_at desc
   limit greatest(1, least(p_limit, 100));
$$;


--
-- Name: FUNCTION search_documents(p_query text, p_project uuid, p_limit integer, p_match text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.search_documents(p_query text, p_project uuid, p_limit integer, p_match text) IS 'Project knowledge retrieval (#257). One hit per document -- a mirror the office wrote into a connector steps aside for its original (0169) -- and archived material is out of ordinary search (ADR-0040) while keeping its row, its content and its relations.';


--
-- Name: seed_project_aliases(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.seed_project_aliases() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  -- Its name, as written. `source = 'name'` and high confidence, because a
  -- project's own name is not an inference.
  -- `normalised` is a GENERATED column — the database derives it from `alias`,
  -- so writing it is refused. That is the right design: it means two callers
  -- cannot disagree about how a name normalises.
  /*
    `normalised` is a GENERATED column and there are TWO unique constraints on
    this table: one per project, and one GLOBAL — an alias points at exactly one
    project, which is how "a name that already exists asks first" is supposed to
    work. So a name already claimed by another project is left alone rather than
    stolen, and the ambiguity surfaces where it should: as a question.
  */
  insert into public.project_aliases (project_id, alias, source, confidence)
  select new.project_id, new.name, 'name', 1.0
   where app.normalise_name(new.name) is not null
     and not exists (
       select 1 from public.project_aliases a
        where a.normalised = app.normalise_name(new.name)
     );

  -- Its slug, which is how it is written in a URL or a command.
  insert into public.project_aliases (project_id, alias, source, confidence)
  select new.project_id, new.slug, 'slug', 1.0
   where app.normalise_name(new.slug) is not null
     and not exists (
       select 1 from public.project_aliases a
        where a.normalised = app.normalise_name(new.slug)
     );

  /*
    A rename leaves the old name behind on purpose.

    Grant will keep calling it what he called it last week, and the point of
    this table is to answer to the names people actually use. Old aliases are
    only removed when he says so.
  */
  return new;
end $$;


--
-- Name: self_changes(integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.self_changes(p_days integer DEFAULT 14) RETURNS TABLE(occurred_at timestamp with time zone, actor_kind text, actor text, what text, detail text, reversible boolean, undo_with text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select e.occurred_at, e.actor_kind, e.actor, e.action_type,
         e.rationale_summary, e.reversible, e.reversal_method
    from public.events e
   where e.action_type in ('office.learned', 'office.skill_written',
                           'office.noticed', 'tool.requested', 'tool.granted',
                           'tool.declined', 'tool.revoked', 'tool.wanted')
     and e.occurred_at > app.now_utc()
                         - (greatest(coalesce(p_days, 14), 1) || ' days')::interval
   order by e.occurred_at desc
$$;


--
-- Name: FUNCTION self_changes(p_days integer); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.self_changes(p_days integer) IS 'Everything the office has changed about itself, with who did it and how to undo it (#53). The one question an office that extends itself must be able to answer about its own past.';


--
-- Name: self_improvement_budget(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.self_improvement_budget() RETURNS bigint
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(
    (select (value #>> '{}')::bigint from public.system_config
      where key = 'jobs.self_improvement_tokens_per_day'),
    -- Roughly a dozen substantial passes a day. Chosen to be generous enough
    -- that ordinary reflection never notices it and small enough that a loop
    -- talking to itself hits it within an hour.
    200000)
$$;


--
-- Name: self_improvement_headroom(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.self_improvement_headroom() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'spent_tokens', app.self_improvement_spent(24),
    'budget_tokens', app.self_improvement_budget(),
    'left_tokens', greatest(app.self_improvement_budget() - app.self_improvement_spent(24), 0),
    'within_budget', app.self_improvement_within_budget(),
    'governed_kinds', (select coalesce(array_agg(kind order by kind), '{}')
                         from public.self_improvement_kinds),
    -- Named so a page can say WHEN it comes back rather than only that it is
    -- stopped. A ceiling with no stated end reads like a fault.
    'window', '24 hours, rolling'
  )
$$;


--
-- Name: self_improvement_spent(integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.self_improvement_spent(p_hours integer DEFAULT 24) RETURNS bigint
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(sum(u.prompt_tokens + u.completion_tokens), 0)::bigint
    from public.inference_usage u
    join public.jobs j on j.job_id = u.job_id
   where j.kind in (select kind from public.self_improvement_kinds)
     and not j.is_fixture
     and u.occurred_at > app.now_utc()
                         - (greatest(coalesce(p_hours, 24), 1) || ' hours')::interval
$$;


--
-- Name: self_improvement_within_budget(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.self_improvement_within_budget() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select app.self_improvement_spent(24) < app.self_improvement_budget()
$$;


--
-- Name: FUNCTION self_improvement_within_budget(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.self_improvement_within_budget() IS 'Whether the office may keep working on itself today. Read by app.dequeue_job, which is the only place it needs to be read (#53).';


--
-- Name: send_to_agent(text, uuid, text, text, uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.send_to_agent(p_kind text, p_id uuid, p_action text, p_to text DEFAULT NULL::text, p_with uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  a          record;
  v_title    text;
  v_project  uuid;
  v_command  uuid;
  v_said     text;
  v_queued   jsonb;
  v_key      text;
begin
  select * into a from public.asset_actions where action = lower(btrim(coalesce(p_action, '')));
  if not found then
    return jsonb_build_object('ok', false, 'error',
      format('no such action: %s', coalesce(p_action, '(none)')));
  end if;

  /*
    The asset's own name and project, from whichever table it lives in.

    Four branches rather than a lookup table: the id columns and the title
    columns genuinely differ, and a generic resolver would need the same four
    branches with a layer of indirection over them.
  */
  if p_kind = 'document' then
    select d.title, d.project_id into v_title, v_project
      from public.documents d where d.document_id = p_id;
  elsif p_kind = 'task' then
    select t.title, t.project_id into v_title, v_project
      from public.tasks t where t.task_id = p_id;
  elsif p_kind = 'contact' then
    select c.name, c.project_id into v_title, v_project
      from public.contacts c where c.contact_id = p_id;
  elsif p_kind = 'collection' then
    select c.name, c.project_id into v_title, v_project
      from public.collections c where c.collection_id = p_id;
  else
    return jsonb_build_object('ok', false, 'error',
      format('cannot send a %s', coalesce(p_kind, '(nothing)')));
  end if;

  if v_project is null then
    return jsonb_build_object('ok', false, 'error', format('no such %s', p_kind));
  end if;
  if a.needs_two and p_with is null then
    return jsonb_build_object('ok', false, 'error',
      format('%s needs a second thing to compare against', a.label));
  end if;

  v_said := format(a.says, coalesce(nullif(v_title, ''), 'this'));
  if coalesce(btrim(p_note), '') <> '' then
    v_said := v_said || ' ' || btrim(p_note);
  end if;

  v_key := format('asset:%s:%s:%s:%s', p_kind, p_id, a.action,
                  to_char(app.now_utc(), 'YYYYMMDDHH24MISSMS'));

  insert into public.inbound_commands
    (origin_channel, origin_ref, actor, instruction, addressed_to, dedupe_key, context)
  values ('teamhq', v_key, 'grant', v_said,
          nullif(btrim(coalesce(p_to, '')), ''),
          v_key,
          jsonb_build_object(
            'asset_kind', p_kind,
            'asset_id', p_id,
            'asset_title', v_title,
            'action', a.action,
            'compare_with', p_with,
            'project_id', v_project))
  returning command_id into v_command;

  v_queued := app.enqueue_inbound(v_command);
  if v_queued->>'job_id' is null then
    return jsonb_build_object('ok', false, 'error',
      coalesce(v_queued->>'error', 'the queue refused it'));
  end if;

  insert into public.relations (project_id, from_kind, from_id, verb, to_kind, to_id, made_by)
  values (v_project, p_kind, p_id, 'input_to', 'job', (v_queued->>'job_id')::uuid, 'teamhq')
  on conflict do nothing;

  if p_with is not null then
    insert into public.relations (project_id, from_kind, from_id, verb, to_kind, to_id, made_by)
    values (v_project, p_kind, p_with, 'input_to', 'job', (v_queued->>'job_id')::uuid, 'teamhq')
    on conflict do nothing;
  end if;

  return jsonb_build_object(
    'ok', true, 'job', v_queued->>'job_id', 'action', a.label,
    'about', v_title, 'said', v_said);
end;
$$;


--
-- Name: set_automation(text, boolean); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.set_automation(p_automation text, p_on boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare v_kind text; v_by text;
begin
  select job_kind, created_by into v_kind, v_by
    from public.responsibilities where slug = p_automation;
  if v_kind is null then
    return jsonb_build_object('ok', false, 'error', format('no automation called %s', p_automation));
  end if;

  update public.responsibilities
     set enabled = p_on, updated_at = app.now_utc()
   where slug = p_automation;

  return jsonb_build_object('ok', true, 'automation', p_automation, 'on', p_on);
end;
$$;


--
-- Name: set_project_instruction(text, text, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.set_project_instruction(p_slug text, p_staff_slug text, p_instruction text DEFAULT ''::text, p_by text DEFAULT 'grant'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_project uuid;
  v_staff   uuid;
  v_text    text := btrim(coalesce(p_instruction, ''));
begin
  select project_id into v_project
    from public.projects where slug = p_slug and status <> 'archived';
  if v_project is null then
    return jsonb_build_object('ok', false, 'error', format('no active project called %s', p_slug));
  end if;

  select staff_id into v_staff from public.staff where slug = p_staff_slug and active;
  if v_staff is null then
    return jsonb_build_object('ok', false, 'error', format('nobody here is called %s', p_staff_slug));
  end if;

  -- A brief long enough to be a brief. Two words is a note to self, and it
  -- would be pasted into a prompt where it can only confuse. Empty is not
  -- short — it is the clear.
  if v_text <> '' and length(v_text) < 12 then
    return jsonb_build_object(
      'ok', false,
      'error', 'A brief needs to be a sentence — that is going into what they are told.');
  end if;

  insert into public.project_staff (project_id, staff_id, instruction, decided_by)
  values (v_project, v_staff, v_text, p_by)
  on conflict (project_id, staff_id)
  do update set instruction = excluded.instruction,
                decided_by = excluded.decided_by,
                decided_at = app.now_utc();

  return jsonb_build_object('ok', true, 'staff', p_staff_slug,
                            'cleared', v_text = '', 'instruction', v_text);
end;
$$;


--
-- Name: set_project_staff(text, text, boolean, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.set_project_staff(p_slug text, p_staff_slug text, p_on boolean, p_by text DEFAULT 'grant'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_project uuid;
  v_staff   uuid;
  v_name    text;
begin
  select project_id into v_project
    from public.projects where slug = p_slug and status <> 'archived';
  if v_project is null then
    return jsonb_build_object('ok', false, 'error', format('no active project called %s', p_slug));
  end if;

  select staff_id, name into v_staff, v_name
    from public.staff where slug = p_staff_slug and active;
  if v_staff is null then
    return jsonb_build_object('ok', false, 'error', format('nobody here is called %s', p_staff_slug));
  end if;

  if p_staff_slug = 'chief-of-staff' and not p_on then
    return jsonb_build_object(
      'ok', false, 'refused', true,
      'error', 'The Chief of Staff is on every project — she is the only person who messages you.');
  end if;

  insert into public.project_staff (project_id, staff_id, active, decided_by)
  values (v_project, v_staff, p_on, p_by)
  on conflict (project_id, staff_id)
  do update set active = excluded.active,
                decided_by = excluded.decided_by,
                decided_at = app.now_utc();

  return jsonb_build_object('ok', true, 'staff', p_staff_slug, 'name', v_name, 'on', p_on);
end;
$$;


--
-- Name: signals; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.signals (
    signal_id uuid DEFAULT gen_random_uuid() NOT NULL,
    source text NOT NULL,
    event_type text NOT NULL,
    external_ref text NOT NULL,
    project_id uuid,
    summary text DEFAULT ''::text NOT NULL,
    detail jsonb DEFAULT '{}'::jsonb NOT NULL,
    caused_by_job uuid,
    happened_at timestamp with time zone DEFAULT app.now_utc() NOT NULL,
    received_at timestamp with time zone DEFAULT app.now_utc() NOT NULL,
    CONSTRAINT signals_event_type_check CHECK ((btrim(event_type) <> ''::text)),
    CONSTRAINT signals_external_ref_check CHECK ((btrim(external_ref) <> ''::text)),
    CONSTRAINT signals_source_check CHECK ((btrim(source) <> ''::text))
);


--
-- Name: TABLE signals; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.signals IS 'What the office NOTICED: something that happened, normalised and deduplicated (#264). Deliberately not `public.events`, which is the ledger of what the office DID -- 2,641 rows of actor, action and before/after. Two different nouns, and one table for both would make "who did this" unanswerable.';


--
-- Name: signal_matches(public.signals, jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.signal_matches(p_signal public.signals, p_filters jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    AS $$
declare k text; v text; got text; path text;
begin
  for k, v in select key, value #>> '{}' from jsonb_each(coalesce(p_filters, '{}'::jsonb)) loop
    path := rtrim(k, '~');
    got := case
      when path = 'summary' then p_signal.summary
      when path = 'event_type' then p_signal.event_type
      when path = 'source' then p_signal.source
      when path like 'detail.%' then p_signal.detail #>> string_to_array(substr(path, 8), '.')
      else null
    end;
    if got is null then return false; end if;
    if k like '%~' then
      if position(lower(v) in lower(got)) = 0 then return false; end if;
    else
      if got <> v then return false; end if;
    end if;
  end loop;
  return true;
end;
$$;


--
-- Name: skill_carries_no_reach(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.skill_carries_no_reach() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  /*
    Both checks, on both long fields.

    `reject_credential_text_on` (0185) is the lesson boundary and applies here
    unchanged — a table is exactly where a secret hides from `check:secrets`,
    which scans files. The address check is this ADR's addition. Neither is
    sufficient alone: a credential with no address is still a credential, and
    an address with no credential is still reach.
  */
  perform app.reject_credential_text_on(new.procedure);
  perform app.reject_credential_text_on(new.when_to_use);
  perform app.reject_address_text_on(new.procedure);
  perform app.reject_address_text_on(new.when_to_use);
  return new;
end;
$$;


--
-- Name: skill_effect(integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.skill_effect(p_days integer DEFAULT 60) RETURNS TABLE(skill_id uuid, name text, uses integer, completed integer, failed integer, their_rate numeric, office_rate numeric, difference numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with window_jobs as (
    select j.job_id, j.state
      from public.jobs j
     where not j.is_fixture
       and j.updated_at > app.now_utc() - (greatest(coalesce(p_days, 60), 1) || ' days')::interval
       and j.state in ('complete', 'failed')
  ),
  baseline as (
    select case when count(*) = 0 then null
                else round(count(*) filter (where state = 'complete')::numeric
                           / count(*), 3) end as rate
      from window_jobs
  )
  select s.skill_id, s.name,
         count(*)::integer as uses,
         count(*) filter (where w.state = 'complete')::integer as completed,
         count(*) filter (where w.state = 'failed')::integer as failed,
         round(count(*) filter (where w.state = 'complete')::numeric / count(*), 3) as their_rate,
         (select rate from baseline) as office_rate,
         round(count(*) filter (where w.state = 'complete')::numeric / count(*), 3)
           - coalesce((select rate from baseline), 0) as difference
    from public.skill_uses su
    join window_jobs w on w.job_id = su.job_id
    join public.skills s on s.skill_id = su.skill_id
   group by s.skill_id, s.name
   order by count(*) desc
$$;


--
-- Name: FUNCTION skill_effect(p_days integer); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.skill_effect(p_days integer) IS 'Whether a skill improved outcomes, against the office''s own rate over the same window (#50). A library of procedures nobody has checked is worse than none: expensive to read, and it looks like competence.';


--
-- Name: skill_used(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.skill_used(p_skill_id uuid, p_job_id uuid) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  insert into public.skill_uses (skill_id, job_id)
  values (p_skill_id, p_job_id)
  on conflict do nothing
$$;


--
-- Name: skills_for(text, text, uuid, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.skills_for(p_staff_slug text DEFAULT NULL::text, p_job_kind text DEFAULT NULL::text, p_project_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 4) RETURNS TABLE(skill_id uuid, name text, scope public.lesson_scope, when_to_use text, procedure text, tools text[], missing text[], authored_by text, version integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select s.skill_id, s.name, s.scope, s.when_to_use, s.procedure,
         coalesce(t.all_tools, '{}') as tools,
         coalesce(t.not_held, '{}') as missing,
         s.authored_by, s.version
    from public.skills_live s
    left join lateral (
      select array_agg(st.tool order by st.tool) as all_tools,
             array_remove(array_agg(
               -- The one column that turns a procedure into a request. Computed
               -- by asking the authorisation path; the authorisation path is
               -- never asked to look the other way (ADR-0017).
               case when app.staff_may_use(coalesce(p_staff_slug, ''), st.tool)
                    then null else st.tool end
               order by st.tool), null) as not_held
        from public.skill_tools st
       where st.skill_id = s.skill_id
    ) t on true
   where (s.scope = 'global')
      or (s.scope = 'staff'   and s.staff_slug = p_staff_slug)
      or (s.scope = 'kind'    and s.job_kind   = p_job_kind)
      or (s.scope = 'project' and s.project_id = p_project_id)
   order by
     -- Same ranking rule as lessons: the specific one is what nobody knew, the
     -- general one is usually already reflected in how the office is built.
     case s.scope when 'staff' then 0 when 'kind' then 1 when 'project' then 2 else 3 end,
     s.created_at desc
   limit greatest(coalesce(p_limit, 4), 0)
$$;


--
-- Name: FUNCTION skills_for(p_staff_slug text, p_job_kind text, p_project_id uuid, p_limit integer); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.skills_for(p_staff_slug text, p_job_kind text, p_project_id uuid, p_limit integer) IS 'The procedures a job should be shown, with the tools each names and which of those the person does not hold. `missing` is the start of the route to new capability: it becomes an impediment, then a briefing line (#50).';


--
-- Name: spent_today(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.spent_today(p_agent text DEFAULT NULL::text) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select coalesce(sum(j.trace_pence), 0)::numeric
    from public.jobs j
   where j.finished_at >= date_trunc('day', app.now_utc())
     and coalesce(j.trace_pence, 0) > 0
     and (p_agent is null or j.recipient_agent = p_agent)
     and not coalesce(app.harness_job(j.job_id), false)
$$;


--
-- Name: FUNCTION spent_today(p_agent text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.spent_today(p_agent text) IS 'Pence actually spent today, by one agent or by the whole office (#134). Only rows with a real cost: free-model work is most of what this office does and must not throttle it. Harness traffic is excluded - a suite spending money is not the office spending money.';


--
-- Name: spoken_about_whom(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.spoken_about_whom(p_said text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  with gist as (select app.spoken_gist(p_said) as g)
  select s.slug
    from public.staff s, gist
   where s.active
     and s.slug not like 'fixture-%'
     and (
       gist.g ~ ('\m' || lower(s.name) || '\M')
       -- The discipline from the slug: 'research-director' matches "research".
       or gist.g ~ ('\m' || lower(split_part(s.slug, '-', 1)) || '\M')
     )
   -- A named person beats a discipline, so "what did Emma in research say"
   -- resolves to Emma once rather than ambiguously.
   order by case when gist.g ~ ('\m' || lower(s.name) || '\M') then 0 else 1 end
   limit 1
$$;


--
-- Name: spoken_gist(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.spoken_gist(p_said text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select regexp_replace(
           regexp_replace(lower(coalesce(p_said, '')), '[^a-z0-9 ]+', ' ', 'g'),
           '\s+', ' ', 'g')
$$;


--
-- Name: spoken_is_a_request(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.spoken_is_a_request(p_said text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select case
    -- A wh-question about a named colleague's work. See the header: three
    -- conditions, all of them, or this does not apply.
    when app.spoken_gist(p_said) ~ '^(what|who|how|when|where|why)\M'
     and app.spoken_about_whom(p_said) is not null
     and app.spoken_gist(p_said) ~
         '\m(said|say|find|found|going on|about|doing|been up to|conclude|concluded|reported|report)\M'
    then false
    else app.spoken_gist(p_said) ~
      ('\m('
       -- Asking for work outright.
       || 'have a look|take a look|look into|look at|dig into|find out|work out|'
       || 'figure out|work up|put together|draft|write|draw up|make me|build|'
       || 'research|investigate|check whether|see whether|see if|'
       -- Asking a person or the team.
       || 'ask |get \w+ to|bring \w+ in|tell \w+ to|have \w+ look|'
       -- Delegating judgement, which §22 names explicitly: "do what you think
       -- is best and let me know".
       || 'do what you think|your call|use your judgement|use your judgment|'
       || 'go ahead and|carry on and|sort out|deal with|handle'
       || ')\M')
  end
$$;


--
-- Name: FUNCTION spoken_is_a_request(p_said text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.spoken_is_a_request(p_said text) IS 'Whether an utterance asks for work rather than for a fact. Checked before the state matchers, and deliberately eager: work mistaken for a question is never done at all, while a question sent to the team comes back answered. The one exemption is a wh-question naming a colleague and asking what they did — §22 A names that sentence, and the phrase list was catching it on the word "research" in the Research Director''s title (0139).';


--
-- Name: staff_behind_job(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.staff_behind_job(p_job_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  with recursive lineage as (
    select job_id, parent_job_id, 0 as depth
      from public.jobs where job_id = p_job_id
    union all
    select j.job_id, j.parent_job_id, l.depth + 1
      from public.jobs j join lineage l on j.job_id = l.parent_job_id
     where l.depth < 8
  ),
  routed as (
    select st.slug, l.depth, r.decided_at
      from lineage l
      join public.routing_decisions r on r.job_id = l.job_id
      join public.staff st on st.slug = r.roster[1]
  ),
  -- The duty's owner, for a job the dispatcher created (0098). Matched on
  -- `requested_by`, which it writes as `duty:<slug>` and which no client can
  -- set.
  owned as (
    select st.slug
      from public.jobs j
      join public.responsibilities resp
        on 'duty:' || resp.slug = j.requested_by
      join public.staff st on st.staff_id = resp.staff_id
     where j.job_id = p_job_id and st.active
  )
  -- `coalesce` of two scalar subqueries, not a UNION with a LIMIT: a LIMIT
  -- inside a UNION branch needs parentheses, and the version that did not have
  -- them was a syntax error rather than a subtle bug — but the coalesce also
  -- says the precedence out loud, which the UNION did not.
  select coalesce(
    (select slug from routed order by depth asc, decided_at desc limit 1),
    (select slug from owned limit 1)
  )
$$;


--
-- Name: FUNCTION staff_behind_job(p_job_id uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.staff_behind_job(p_job_id uuid) IS 'Who a job belongs to: the routing decision that convened them, walked up the parent chain, or - for a recurring duty, which nothing routes - the staff member who owns the responsibility. NOT outputs.staff_id, which has never been written.';


--
-- Name: staff_for_bot(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.staff_for_bot(p_bot_id text) RETURNS TABLE(staff_slug text, staff_name text, username text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select b.staff_slug, s.name, b.username
    from public.telegram_bots b
    left join public.staff s on s.slug = b.staff_slug
   where b.bot_id = p_bot_id
     and b.enabled
     and b.token_ref is not null
$$;


--
-- Name: FUNCTION staff_for_bot(p_bot_id text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.staff_for_bot(p_bot_id text) IS 'The person behind a bot id. No row means the id is unknown or the bot is turned off — both of which must refuse the update, because the bot id arrives in a query string and a lookup is the only thing making it a fact.';


--
-- Name: staff_may_use(text, text, boolean); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.staff_may_use(p_slug text, p_tool text, p_approved boolean DEFAULT false) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  select app.tool_allowed(p_tool, p_approved)
     and exists (
       select 1 from public.staff_tools st
        where st.staff_slug = p_slug and st.tool = p_tool
     )
$$;


--
-- Name: staff_on_project(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.staff_on_project(p_project_id uuid) RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(array_agg(s.slug order by s.slug), array[]::text[])
    from public.staff s
    left join public.project_staff ps
      on ps.staff_id = s.staff_id and ps.project_id = p_project_id
   where s.active
     and (s.slug = 'chief-of-staff' or coalesce(ps.active, true))
$$;


--
-- Name: FUNCTION staff_on_project(p_project_id uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.staff_on_project(p_project_id uuid) IS '#36. Who may be convened for this project. A staff member with no row is included — see the table comment. The Chief of Staff cannot be excluded: she is the only person Grant hears from. 0323.';


--
-- Name: standing_never_covers_level_three(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.standing_never_covers_level_three() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare v_level smallint;
begin
  select level into v_level from public.tool_permissions where tool = new.tool;
  if v_level is null then
    raise exception 'no such tool: %', new.tool;
  end if;
  if v_level >= 3 then
    raise exception
      'a standing authorization may not cover %, which is a level-3 action — those always ask',
      new.tool;
  end if;
  return new;
end;
$$;


--
-- Name: standing_now(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.standing_now(p_project uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select coalesce(jsonb_agg(q.v order by q.ord, q.at desc), '[]'::jsonb)
    from (
      select case when s.revoked_at is null then 0 else 1 end as ord,
             s.granted_at as at,
             jsonb_build_object(
               'id', s.authorization_id,
               'tool', s.tool,
               'level', t.level,
               'what', t.description,
               'scope', case when s.project_id is null then 'everywhere' else coalesce(p.name, 'a project') end,
               'project', s.project_id,
               'reason', s.reason,
               'by', s.granted_by,
               'since', s.granted_at,
               'until', s.expires_at,
               'revoked', s.revoked_at,
               'revoked_reason', s.revoked_reason,
               'live', s.revoked_at is null
                       and (s.expires_at is null or s.expires_at > app.now_utc())) as v
        from public.standing_authorizations s
        join public.tool_permissions t on t.tool = s.tool
        left join public.projects p on p.project_id = s.project_id
       where (p_project is null or s.project_id is not distinct from p_project
              or s.project_id is null)
         and (s.revoked_at is null or s.revoked_at > app.now_utc() - interval '30 days')
       order by 1, 2 desc
       limit 60
    ) q;
$$;


--
-- Name: step_begin(uuid, text, integer, text, integer, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.step_begin(p_job uuid, p_step text, p_ordinal integer, p_effect_kind text, p_schema integer, p_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare v public.job_steps%rowtype;
begin
  if coalesce(btrim(p_step), '') = '' then
    return jsonb_build_object('error', 'a step needs a name');
  end if;
  if p_effect_kind not in ('none', 'local', 'external') then
    return jsonb_build_object('error', format('%L is not a kind of effect', p_effect_kind));
  end if;

  select * into v from public.job_steps where job_id = p_job and step = p_step;

  if not found then
    insert into public.job_steps
      (job_id, step, ordinal, effect_kind, schema_version, code_version)
    values (p_job, p_step, p_ordinal, p_effect_kind, p_schema, p_code);
    return jsonb_build_object('do', true, 'first', true);
  end if;

  -- A checkpoint from different code is not a checkpoint this run may reason
  -- about, finished or not.
  if v.schema_version <> p_schema then
    return jsonb_build_object('stale', true,
      'was', v.schema_version, 'now', p_schema,
      'why', format('step %L was recorded by schema %s and this is %s',
                    p_step, v.schema_version, p_schema));
  end if;

  -- And the CODE version, which this function stored and never read
  -- until 0527. The comment above has always said "finished or not",
  -- and it means it: an outcome recorded by code that is no longer
  -- running is one this run may not reason about, however complete.
  if coalesce(v.code_version, '') is distinct from coalesce(p_code, '') then
    return jsonb_build_object('stale', true,
      'was', v.code_version, 'now', p_code,
      'why', format('step %L was recorded by %s and this is %s',
                    p_step, coalesce(v.code_version, 'nothing'),
                    coalesce(p_code, 'nothing')));
  end if;

  if v.finished_at is not null then
    return jsonb_build_object('skip', true, 'outcome', coalesce(v.outcome, '{}'::jsonb),
                              'effect_ref', v.effect_ref, 'at', v.finished_at);
  end if;

  if v.effect_kind = 'external' then
    return jsonb_build_object('park', true,
      'why', format('step %L started at %s and never finished, and it acts outside the '
                    'office -- whether it committed cannot be known from here',
                    p_step, v.began_at));
  end if;

  -- Safe to run again: nothing outside the office happened.
  update public.job_steps set began_at = app.now_utc()
   where step_id = v.step_id;
  return jsonb_build_object('do', true, 'again', true);
end;
$$;


--
-- Name: step_done(uuid, text, jsonb, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.step_done(p_job uuid, p_step text, p_outcome jsonb DEFAULT '{}'::jsonb, p_effect_ref text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare v public.job_steps%rowtype;
begin
  select * into v from public.job_steps where job_id = p_job and step = p_step;
  if not found then
    return jsonb_build_object('error', format('step %L was never begun on this job', p_step));
  end if;
  if v.finished_at is not null then
    -- Idempotent on purpose: finishing twice is a retry, not an error.
    return jsonb_build_object('ok', true, 'already', true);
  end if;
  update public.job_steps
     set finished_at = app.now_utc(),
         outcome = coalesce(p_outcome, '{}'::jsonb),
         effect_ref = nullif(btrim(coalesce(p_effect_ref, '')), '')
   where step_id = v.step_id;
  return jsonb_build_object('ok', true);
end;
$$;


--
-- Name: stop_requested(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.stop_requested(p_job uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1 from public.jobs where job_id = p_job and stop_requested_at is not null
  );
$$;


--
-- Name: store_secret(text, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.store_secret(p_name text, p_value text, p_description text) RETURNS app.vault_secret_ref
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'vault', 'public'
    AS $$
declare
  v_id uuid;
begin
  if p_value is null or length(p_value) = 0 then
    raise exception 'refusing to store an empty secret as %', p_name
      using errcode = '22023';
  end if;

  select id into v_id from vault.secrets where name = p_name;

  if v_id is null then
    v_id := vault.create_secret(p_value, p_name, p_description);
  else
    -- Rotation: same reference, new value. Every row pointing at this
    -- reference picks up the new credential with no write of its own, which is
    -- what makes a 12-hourly rotation survivable.
    perform vault.update_secret(v_id, p_value, p_name, p_description);
  end if;

  return v_id::app.vault_secret_ref;
end
$$;


--
-- Name: FUNCTION store_secret(p_name text, p_value text, p_description text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.store_secret(p_name text, p_value text, p_description text) IS 'Create or rotate a vault secret and return its reference. Rotation reuses the reference, so every row pointing at it picks up the new value without a write — which is what makes a twice-daily rotation survivable.';


--
-- Name: stuck_fixture_projects(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.stuck_fixture_projects() RETURNS TABLE(slug text, name text, jobs integer, age interval)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p.slug, p.name,
         (select count(*)::int from public.jobs j where j.project_id = p.project_id),
         app.now_utc() - p.created_at
    from public.projects p
   where p.status = 'active'
     and p.is_fixture
     -- Holding a job is what makes it undeletable, which is what makes it
     -- accumulate. A fixture project with no jobs is swept by purge:fixtures
     -- and is nobody's problem.
     and exists (select 1 from public.jobs j where j.project_id = p.project_id)
   order by p.created_at
$$;


--
-- Name: FUNCTION stuck_fixture_projects(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.stuck_fixture_projects() IS '0494. Active fixture projects that hold a job and therefore can never be deleted. Ten of these reached Grant''s switcher before anybody looked. check:leaks sweeps what it CAN remove; this names what it cannot.';


--
-- Name: studio_activity(uuid, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.studio_activity(p_project_id uuid, p_limit integer DEFAULT 12) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'who', e.actor,
           'verb', app.action_in_words(e.action_type) ->> 'verb',
           'what', app.action_in_words(e.action_type) ->> 'what',
           'when', to_char(e.occurred_at, 'FMDD Mon HH24:MI'),
           -- #153. The instant, so the words can be re-made in the browser and
           -- the exact date is available on hover. `when` stays as the
           -- fallback for a page that cannot parse this.
           'at', e.occurred_at,
           'detail', e.rationale_summary
         ) order by e.occurred_at desc), '[]'::jsonb)
    from (select * from public.events ee
           where ee.project_id = p_project_id
           order by ee.occurred_at desc
           limit greatest(coalesce(p_limit, 12), 1)) e
$$;


--
-- Name: studio_contacts(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.studio_contacts(p_project_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
           'id', c.contact_id,
           'name', c.name,
           'kind', c.kind,
           'role', nullif(c.role, ''),
           'org', nullif(c.org, ''),
           'stage', c.stage,
           'email', nullif(c.email, ''),
           'phone', nullif(c.phone, ''),
           'instagram', nullif(c.instagram, ''),
           'website', nullif(c.website, ''),
           'where', nullif(c."where", ''),
           'note', nullif(c.note, ''),
           'next', nullif(c.next, ''),
           'nextDue', nullif(c.next_due, ''),
           -- The card shows "3 days ago". Absent is absent rather than
           -- "never", because a contact nobody has spoken to yet has no last.
           'last', case when c.last_at is null then null else app.ago(c.last_at) end,
           -- #153. And the instant it was rendered from.
           'lastAt', c.last_at,
           -- #110. The ids only: the page already holds the label set, and
           -- repeating a name and a hue on every contact is the same string
           -- twenty times in one payload.
           'labels', coalesce((select jsonb_agg(k.label_id)
                                 from public.contact_label_links k
                                where k.contact_id = c.contact_id), '[]'::jsonb),
           'labelsSet', c.labels_set,
           'fields', c.fields
         )) order by c.name), '[]'::jsonb)
    from public.contacts c
   where c.project_id = p_project_id and not c.is_fixture
$$;


--
-- Name: studio_document(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.studio_document(p_document_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case
    when p_document_id is null
      then jsonb_build_object('error', 'no document asked for')
    else coalesce(
      (select jsonb_build_object(
                'id',        d.document_id,
                'title',     d.title,
                'content',   d.content,
                'mime_type', d.mime_type,
                'path',      d.storage_path,
                'bytes',     d.byte_size,
                'seconds',   d.duration_s,
                'state',     d.state,
                'origin',    case d.origin
                               when 'yours' then 'Yours'
                               when 'made'  then coalesce(d.produced_by, 'The team')
                               else app.connector_label(d.connector) end,
                -- A boolean, not the id it mirrors: the reader needs to say
                -- "we wrote this" and does not need to enumerate documents.
                'mirrored',  d.mirrors_document_id is not null,
                'created',   to_char(d.created_at, 'FMDD Mon YYYY')
              )
         from public.documents d
        where d.document_id = p_document_id),
      jsonb_build_object('error', 'no such document'))
  end
$$;


--
-- Name: studio_documents(uuid, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.studio_documents(p_project_id uuid, p_limit integer DEFAULT 24) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', d.document_id,
           'title', d.title,
           'kind', case
             when coalesce(d.mime_type, '') like 'audio/%' then 'audio'
             when d.origin = 'made' then 'made'
             when coalesce(d.mime_type, '') = 'application/pdf'
               or d.title ilike '%.pdf' then 'pdf'
             else 'doc' end,
           'origin', case d.origin
             when 'yours' then 'Yours'
             when 'made' then coalesce(d.produced_by, 'The team')
             else app.connector_label(d.connector) end,
           -- A size only when it says something. Below a hundred words "4 words"
           -- reads as broken metadata even when it is exactly right, and several
           -- of these are Notion database containers (#19).
           'size', case
             when d.duration_s is not null
               then format('%s min', greatest(round(d.duration_s / 60.0), 1))
             when coalesce(d.content_chars, 0) >= 550
               then format('%s words', to_char(round(d.content_chars / 5.5), 'FM999G999'))
             when d.byte_size is not null and d.byte_size >= 1024
               then format('%s KB', round(d.byte_size / 1024.0))
             else '' end,
           'state', d.state,
           -- What the two new controls toggle. Sorted, so a press that adds a
           -- tag does not reorder the ones already there.
           'tags', to_jsonb(coalesce((select array(select distinct unnest(d.tags) order by 1)), '{}'::text[])),
           'collections', coalesce((
             select jsonb_agg(c.name order by c.name)
               from public.document_collections dc
               join public.collections c on c.collection_id = dc.collection_id
              where dc.document_id = d.document_id), '[]'::jsonb)
         ) order by d.created_at desc), '[]'::jsonb)
    from (select * from public.documents dd
           where dd.project_id = p_project_id
             /*
               #28: an output that has not been approved is not in the project.

               This function emitted `state` and never filtered on it, so a
               draft sat in the gallery beside eighty-six approved documents and
               looked exactly like them. The import gate is only a gate if the
               thing behind it is actually behind it.

               Here rather than in the page: an agent asking what this project
               holds must get the same answer as the gallery, and a rule
               enforced in one renderer is a rule the API does not have.
             */
             and dd.state = 'approved'
           order by dd.created_at desc
           limit greatest(coalesce(p_limit, 24), 1)) d
$$;


--
-- Name: studio_modules(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.studio_modules(p_project_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', m.task_id,
           'n', m.n,
           'name', m.title,
           /*
             A module's state is its own, not its children's average.

             Deliberately: Grant ticks a milestone when the module is done, and
             deriving it from the children would mean a module with four tasks
             and one still open can never read Done however finished it is. The
             children are counted beside it, which is the honest way to show
             the same information.
           */
           'state', case m.state when 'done' then 'done'
                                 when 'doing' then 'doing'
                                 when 'blocked' then 'doing'
                                 else 'todo' end,
           'docs', m.docs,
           'tasks', m.tasks
         ) order by m.n), '[]'::jsonb)
    from (
      select tk.task_id, tk.title, tk.state,
             row_number() over (order by tk.priority desc nulls last,
                                         tk.due_on nulls last, tk.created_at) as n,
             (select count(*)::int
                from public.collections c
                join public.document_collections dc on dc.collection_id = c.collection_id
               where c.for_task_id = tk.task_id) as docs,
             (select count(*)::int from public.tasks ch
               where ch.parent_task_id = tk.task_id and not ch.is_fixture) as tasks
        from public.tasks tk
       where tk.project_id = p_project_id
         and tk.is_milestone
         and not tk.is_fixture
    ) m
$$;


--
-- Name: FUNCTION studio_modules(p_project_id uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.studio_modules(p_project_id uuid) IS '#71. A module is a milestone task that gathers documents — see 0286 for why this is derived and not a table. The counts are computed here so they cannot drift from what they count.';


--
-- Name: studio_plane(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.studio_plane(p_project_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
with
-- Which staff have actually touched this project. Not the whole roster: a map
-- of eight people where three have ever done anything is a map of the org
-- chart, and Grant asked for a map of the project.
touched as (
  select distinct s.staff_id, s.slug, s.name, s.title
    from public.staff s
   where exists (select 1 from public.jobs j
                  where j.project_id = p_project_id and j.recipient_agent = s.slug
                    and not coalesce(app.harness_job(j.job_id), false))
      or exists (select 1 from public.tasks t
                  where t.project_id = p_project_id and t.assignee_staff = s.staff_id
                    and not coalesce(t.is_fixture, false))
      or exists (select 1 from public.documents d
                  join public.jobs j2 on j2.job_id = d.produced_by_job
                 where d.project_id = p_project_id and j2.recipient_agent = s.slug)
),
agent_state as (
  select t.*,
         (select count(*) from public.jobs j
           where j.project_id = p_project_id and j.recipient_agent = t.slug
             and j.state not in ('complete','cancelled','failed')) as live,
         (select count(*) from public.job_impediments i
           where i.project_id = p_project_id and i.staff_slug = t.slug
             and not coalesce(i.is_fixture, false)) as walls,
         (select count(*) from public.documents d
           join public.jobs j3 on j3.job_id = d.produced_by_job
          where d.project_id = p_project_id and j3.recipient_agent = t.slug) as made,
         (select count(*) from public.jobs j4
           where j4.project_id = p_project_id and j4.recipient_agent = t.slug
             and j4.state = 'complete'
             and not coalesce(app.harness_job(j4.job_id), false)) as answered
    from touched t
),
agents as (
  select jsonb_build_object(
           'id',    'agent:' || a.slug,
           'kind',  'agent',
           'ref',   a.slug,
           'name',  a.name,
           'sub',   a.title,
           'state', case when a.live  > 0 then 'working'
                         when a.walls > 0 then 'needs attention'
                         when a.made  > 0 or a.answered > 0 then 'done'
                         else 'idle' end,
           'says',  case when a.live  > 0 then a.live::text  || ' in hand'
                         when a.walls > 0 then a.walls::text || ' could not be done'
                         when a.made  > 0 then a.made::text  || ' made'
                         when a.answered > 0 then a.answered::text || ' answered'
                         else 'nothing yet' end
         ) as n, a.slug
    from agent_state a
),
-- The project's own attachments. `ref_kind` separates a live connector from a
-- reference (0306, #35): a bookmark never fails and nothing syncs it, so it
-- must not be drawn as a connection that could be healthy.
attach as (
  select pa.attachment_id, pa.connector, pa.external_ref, pa.display_name,
         pa.external_url, pa.enabled, pa.last_synced_at,
         coalesce(pa.ref_kind, 'connector') as ref_kind,
         (select ch.state from public.connection_health ch
           where lower(ch.service) = case pa.connector
                                       when 'drive'      then 'google'
                                       when 'notion'     then 'notion'
                                       when 'github'     then 'github'
                                       when 'notebooklm' then 'google'
                                       else null end
           limit 1) as health
    from public.project_attachments pa
   where pa.project_id = p_project_id
),
services as (
  select jsonb_build_object(
           'id',    'service:' || a.attachment_id::text,
           'kind',  case when a.ref_kind = 'connector' then 'service' else 'reference' end,
           'ref',   a.attachment_id::text,
           'name',  coalesce(nullif(a.display_name, ''), a.connector),
           'sub',   a.connector,
           'url',   a.external_url,
           'state', case when a.ref_kind <> 'connector'  then 'a pointer'
                         when a.enabled is not true      then 'not connected'
                         when a.health = 'failing'       then 'needs attention'
                         else 'connected' end,
           -- The page already turns a timestamp into "6 minutes ago" everywhere
           -- else (`when.words`), so this hands over the instant and not a
           -- sentence. Two places that phrase the same fact is how a product
           -- ends up with two vocabularies for one thing (0311).
           'says',  case when a.ref_kind <> 'connector' then 'nothing reads this'
                         when a.last_synced_at is null  then 'never read'
                         else null end,
           'at',    a.last_synced_at
         ) as n, a.attachment_id, a.connector, a.external_ref
    from attach a
),
open_tasks as (
  select t.task_id, t.title, t.state, t.assignee_staff, t.due_on,
         jsonb_build_object(
           'id',    'task:' || t.task_id::text,
           'kind',  'task',
           'ref',   t.task_id::text,
           'name',  t.title,
           'sub',   case when t.due_on is null then null else 'due ' || to_char(t.due_on, 'FMDD Mon') end,
           'state', case when t.state = 'done' then 'done'
                         when t.blocked_on is not null then 'blocked'
                         else 'open' end,
           'says',  t.state
         ) as n
    from public.tasks t
   where t.project_id = p_project_id
     and not coalesce(t.is_fixture, false)
     and t.state <> 'done'
   order by t.due_on nulls last, t.created_at desc
   limit 12
),
recent_docs as (
  select d.document_id, d.title, d.connector, d.external_parent_ref,
         d.produced_by_job, d.produced_by,
         jsonb_build_object(
           'id',    'doc:' || d.document_id::text,
           'kind',  'document',
           'ref',   d.document_id::text,
           'name',  d.title,
           'sub',   nullif(d.produced_by, ''),
           'state', 'ready',
           'says',  coalesce(d.doc_type, 'document')
         ) as n
    from public.documents d
   where d.project_id = p_project_id
     and coalesce(d.state, 'approved') <> 'archived'
   order by d.updated_at desc nulls last
   limit 12
),
-- --- the edges, each read from the column that already holds it -------------
e_made as (
  select jsonb_build_object('from', 'agent:' || j.recipient_agent,
                            'to',   'doc:' || d.document_id::text,
                            'verb', 'produced', 'derived', false) as e,
         j.recipient_agent as slug, d.document_id
    from recent_docs d
    join public.jobs j on j.job_id = d.produced_by_job
   where j.recipient_agent is not null
     and exists (select 1 from agents a where a.slug = j.recipient_agent)
),
e_task as (
  select jsonb_build_object('from', 'agent:' || s.slug,
                            'to',   'task:' || t.task_id::text,
                            'verb', 'assigned_to', 'derived', false) as e
    from open_tasks t
    join public.staff s on s.staff_id = t.assignee_staff
   where exists (select 1 from agents a where a.slug = s.slug)
),
e_from as (
  select jsonb_build_object('from', 'service:' || sv.attachment_id::text,
                            'to',   'doc:' || d.document_id::text,
                            'verb', 'came_from', 'derived', false) as e,
         sv.attachment_id, d.document_id
    from recent_docs d
    join services sv
      on sv.connector = d.connector
     and (d.external_parent_ref is null or d.external_parent_ref = sv.external_ref)
),
-- The one Grant asked for, and the only one no column holds. Derived from two
-- real edges and labelled as such, so the interface can say WHY the line is
-- there rather than implying a credential.
e_uses as (
  select distinct jsonb_build_object(
           'from', 'agent:' || m.slug,
           'to',   'service:' || f.attachment_id::text,
           'verb', 'uses', 'derived', true,
           'because', 'wrote something that came from here') as e
    from e_made m
    join e_from f on f.document_id = m.document_id
)
select jsonb_build_object(
  'nodes', coalesce((select jsonb_agg(x.n) from (
             select n from agents
             union all select n from services
             union all select n from open_tasks
             union all select n from recent_docs) x), '[]'::jsonb),
  'edges', coalesce((select jsonb_agg(y.e) from (
             select e from e_made
             union all select e from e_task
             union all select e from e_from
             union all select e from e_uses) y), '[]'::jsonb)
)
$$;


--
-- Name: FUNCTION studio_plane(p_project_id uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.studio_plane(p_project_id uuid) IS 'The project as a graph the dashboard can draw (#25): agents who have actually worked here, the project''s own attachments, its open tasks and recent documents, and the edges between them. Every edge is DERIVED from the column that already holds the fact (0310''s rule); the one edge that no column holds - which agent uses which service - is computed from two real edges and carries derived=true plus the sentence that explains it, because a line that implies a credential nobody granted is the failure Grant named.';


--
-- Name: studio_requests(uuid, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.studio_requests(p_project_id uuid, p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
           'id', j.job_id,
           'state', case
             when j.state in ('queued', 'running', 'waiting_external',
                              'waiting_user', 'retrying', 'paused') then 'working'
             when j.state = 'complete' and o.output_id is not null
              and coalesce(o.reviewer_status, 'pending') = 'pending' then 'review'
             when j.state = 'complete' then 'approved'
             else 'discarded' end,
           'who', coalesce(j.recipient_agent, 'chief-of-staff'),
           'ask', j.kind,
           'asked', to_char(j.created_at, 'FMDD Mon'),
           'delivered', case when o.created_at is null then ''
                             else to_char(o.created_at, 'FMDD Mon') end,
           -- #153. The instants behind both, so a request made this morning
           -- does not still read as this morning tomorrow.
           'askedAt', j.created_at,
           'deliveredAt', o.created_at,
           /*
             Blocked means blocked (0230), and absent means absent (0232).

             The three states that mean something is being waited on, with the
             reason from `blockers.requested_action` — the same column
             `needs_me` reads. Null here is stripped by the wrapper above, so
             the key is simply not there when nothing is wrong.
           */
           'blocked', case
             when j.state in ('waiting_external', 'waiting_user', 'paused')
               then coalesce(
                 (select bl.requested_action from public.blockers bl
                   where bl.job_id = j.job_id and bl.resolved_at is null
                   order by bl.created_at desc limit 1),
                 nullif(btrim(coalesce(j.state_reason, '')), ''),
                 'waiting')
             else null end,
           'output', case when o.output_id is null then null else jsonb_build_object(
             -- The output's own id, so IMPORT TO PROJECT has something to call
             -- `import_output` with (#28, 0317). The row's `id` is the JOB's,
             -- which is the wrong key for a thing that becomes one document.
             'id', o.output_id,
             'imported', exists (
               select 1 from public.documents d
                where d.project_id = j.project_id
                  and d.connector = 'upload'
                  and d.external_ref = format('output:%s', o.output_id)
                  and d.state = 'approved'),
             'title', left(coalesce(
               nullif(btrim(split_part(o.body, E'\n', 1)), ''), j.kind), 80),
             'kind', 'made',
             'size', case
               when length(coalesce(o.body, '')) >= 550
                 then format('%s words', to_char(round(length(o.body) / 5.5), 'FM999G999'))
               else '' end,
             'body', o.body) end
         )) order by j.created_at desc), '[]'::jsonb)
    from (select * from public.jobs jj
           where jj.project_id = p_project_id and not jj.is_fixture
           order by jj.created_at desc
           limit greatest(coalesce(p_limit, 20), 1)) j
    left join lateral (
      select * from public.outputs oo
       where oo.job_id = j.job_id
       order by oo.created_at desc limit 1
    ) o on true
$$;


--
-- Name: FUNCTION studio_requests(p_project_id uuid, p_limit integer); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.studio_requests(p_project_id uuid, p_limit integer) IS 'The work asked of the team on one project, with what came back (#68). Four states, not the engine''s fourteen. Blocked is the three waiting states and a joined blocker, never the presence of a state_reason (0230).';


--
-- Name: studio_search(text, uuid, integer, jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.studio_search(p_query text, p_project uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 12, p_filters jsonb DEFAULT '{}'::jsonb) RETURNS TABLE(kind text, ref uuid, title text, snippet text, place text, rank real, at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with asked as (
    -- `websearch_to_tsquery`, not `to_tsquery`: quoting a phrase or typing
    -- "or" then does what a person expects rather than raising a syntax error
    -- the caller has to report as "no results".
    select websearch_to_tsquery('english', btrim(coalesce(p_query, ''))) as q
  ),
  f as (
    select coalesce(p_filters, '{}'::jsonb) as j
  ),
  want as (
    select
      case when (select j -> 'kinds' from f) is null then null
           else (select array(select jsonb_array_elements_text(j -> 'kinds') from f)) end as kinds,
      nullif(btrim(coalesce((select j ->> 'tag' from f), '')), '')      as tag,
      (select nullif(btrim(coalesce(j ->> 'since', '')), '')::timestamptz from f) as since,
      (select nullif(btrim(coalesce(j ->> 'until', '')), '')::timestamptz from f) as until,
      nullif(btrim(coalesce((select j #>> '{related_to,kind}' from f), '')), '') as rel_kind,
      (select nullif(btrim(coalesce(j #>> '{related_to,id}', '')), '')::uuid from f) as rel_id
  ),
  /*
    Everything the named thing is connected to, from the one definition of
    what "connected" means. Empty when no relation filter was asked for, and
    the predicates below only consult it when `rel_kind` is present - so an
    unrelated search does not pay for a traversal it does not need.
  */
  related as (
    select r.other_kind, r.other_id
      from want w
      cross join lateral app.relations_of(w.rel_kind, w.rel_id) r
     where w.rel_kind is not null and w.rel_id is not null
  ),
  hits as (
    select 'document'::text as kind,
           d.document_id as ref,
           coalesce(nullif(d.title, ''), '(untitled)') as title,
           ts_headline('english', coalesce(d.content, ''), a.q,
                       'MaxWords=22, MinWords=8, ShortWord=3, MaxFragments=1') as snippet,
           coalesce(p.name, 'No project') as place,
           -- `d.search`: generated, indexed, and WEIGHTED, so a title match
           -- outranks a passing mention instead of tying with it.
           ts_rank(d.search, a.q) as rank,
           d.created_at as at
      from public.documents d
      cross join asked a
      cross join want w
      left join public.projects p on p.project_id = d.project_id
     where a.q is not null
       and (p_project is null or d.project_id = p_project)
       and d.search @@ a.q
       and (w.kinds is null or 'document' = any(w.kinds))
       and (w.tag is null or w.tag = any(coalesce(d.tags, array[]::text[])))
       and (w.since is null or d.created_at >= w.since)
       and (w.until is null or d.created_at <= w.until)
       and (w.rel_kind is null
            or exists (select 1 from related r
                        where r.other_kind = 'document' and r.other_id = d.document_id))

    union all

    /*
      An output is reached through its JOB, which is what carries the project
      and the person - `outputs` has no `project_id` of its own, which is a
      column name this repository has guessed wrong before.

      Fixtures excluded: harness answers are not things Grant is looking for.
    */
    select 'answer'::text as kind,
           o.job_id as ref,
           coalesce(nullif(s.name, ''), 'The team')
             || ' on ' || coalesce(nullif(j.kind, ''), 'a job') as title,
           ts_headline('english', coalesce(o.body, ''), a.q,
                       'MaxWords=22, MinWords=8, ShortWord=3, MaxFragments=1') as snippet,
           coalesce(p.name, 'No project') as place,
           ts_rank(to_tsvector('english', coalesce(o.body, '')), a.q) as rank,
           o.created_at as at
      from public.outputs o
      cross join asked a
      cross join want w
      join public.jobs j on j.job_id = o.job_id
      left join public.projects p on p.project_id = j.project_id
      left join public.staff s on s.staff_id = o.staff_id
     where a.q is not null
       and not j.is_fixture
       and (p_project is null or j.project_id = p_project)
       and to_tsvector('english', coalesce(o.body, '')) @@ a.q
       and (w.kinds is null or 'answer' = any(w.kinds))
       and (w.since is null or o.created_at >= w.since)
       and (w.until is null or o.created_at <= w.until)
       /*
         An answer carries no tags, so a tag filter excludes every answer
         rather than ignoring itself. Asking for "documents tagged pricing"
         and being shown untagged answers would be the filter not applying.
       */
       and (w.tag is null)
       and (w.rel_kind is null
            or exists (select 1 from related r
                        where r.other_kind = 'job' and r.other_id = o.job_id))
  )
  select h.kind, h.ref, h.title, h.snippet, h.place, h.rank, h.at
    from hits h
   order by h.rank desc, h.at desc
   limit greatest(coalesce(p_limit, 12), 1)
$$;


--
-- Name: FUNCTION studio_search(p_query text, p_project uuid, p_limit integer, p_filters jsonb); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.studio_search(p_query text, p_project uuid, p_limit integer, p_filters jsonb) IS 'Search the words inside things, narrowed by the graph (#37, 0397). p_filters takes kinds, tag, since, until and related_to {kind, id}. related_to asks app.relations_of, which is the ONE definition of what connected means - so by producing agent, by related contact, by source, by collection and by job are all the same filter, and an edge added to the traversal tomorrow works here the same day. An unknown key is ignored, because a filter that refuses a typo reads as "there is nothing there".';


--
-- Name: studio_sources(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.studio_sources(p_project_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(both_kinds.v order by both_kinds.ord, both_kinds.at), '[]'::jsonb)
    from (
      select 0 as ord, a.created_at as at, jsonb_build_object(
               'kind', 'connector',
               'id', a.attachment_id,
               'connector', a.connector,
               'ref', a.external_ref,
               'url', a.external_url,
               -- The individual thing here, because that is what a Sources row
               -- is for: which notebook, which database, which folder. The
               -- card above says the kind.
               'name', coalesce(nullif(a.display_name, ''), app.connector_label(a.connector)),
               'via', app.connector_label(a.connector),
               'what', a.role,
               'health', case when a.enabled then 'ok' else 'blocked' end,
               'problem', a.disabled_reason,
               'last', case when a.last_synced_at is null then 'never'
                            else to_char(a.last_synced_at, 'FMDD Mon') end,
               'gave', (select count(*)::int from public.documents d
                         where d.project_id = p_project_id
                           and coalesce(d.connector, '') = a.connector)
             ) as v
        from public.project_attachments a
       where a.project_id = p_project_id

      union all

      /*
        A reference carries no `health`, no `last` and no `gave`, and that is
        the point rather than an omission: it is a pointer, it never fails, and
        nothing has read it. A null health is what tells the page to draw it as
        the other kind of thing.
      */
      select 1 as ord, r.created_at as at, jsonb_build_object(
               'kind', 'reference',
               'id', r.reference_id,
               'ref', r.kind,
               'url', r.url,
               'name', r.title,
               'via', case r.kind
                        when 'api' then 'An API'
                        when 'folder' then 'A folder'
                        when 'document' then 'A document'
                        when 'application' then 'An application'
                        when 'website' then 'A website'
                        else 'A reference'
                      end,
               'what', nullif(r.note, ''),
               'health', null,
               'problem', null,
               'last', null,
               'gave', null
             ) as v
        from public.project_references r
       where r.project_id = p_project_id
    ) both_kinds
$$;


--
-- Name: studio_tasks(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.studio_tasks(p_project_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', tk.task_id,
           'title', tk.title,
           'note', tk.detail,
           'who', st.slug,
           'state', case
             when tk.state = 'done' then 'done'
             when tk.state = 'doing' then 'doing'
             when tk.due_on is not null
              and tk.due_on <= (app.now_utc() at time zone app.grant_timezone())::date + 7
               then 'due' else null end,
           'due', case when tk.due_on is null then null
                       else format('Due %s', to_char(tk.due_on, 'FMDD FMMonth')) end,
           'blocked', tk.blocked_on,

           -- The raw half, for the editor. Named so it cannot be mistaken for
           -- the rendered half sitting next to it.
           'state_raw', tk.state,
           'due_on', tk.due_on,
           'starts_on', tk.starts_on,
           'priority', tk.priority,
           'milestone', tk.is_milestone,
           'parent', tk.parent_task_id,
           -- Grant's own, on the project it belongs to (#259). Marked
           -- rather than hidden: the project is where he decides, and a
           -- list that mixes his errands with the team's work without
           -- saying which is which is the same defect as showing them twice.
           'mine', tk.assigned_to_human,
           'labels', to_jsonb(tk.labels)
         ) order by
           case tk.state when 'doing' then 0 when 'blocked' then 1
                         when 'todo' then 2 else 3 end,
           tk.due_on nulls last), '[]'::jsonb)
    from public.tasks tk
    left join public.staff st on st.staff_id = tk.assignee_staff
   where tk.project_id = p_project_id and not app.harness_task(tk.is_fixture, tk.job_id)
$$;


--
-- Name: studio_team_work(integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.studio_team_work(p_days integer DEFAULT 14) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
with since as (select app.now_utc() - make_interval(days => greatest(1, coalesce(p_days, 14))) as t),
real_jobs as (
  select j.job_id, j.recipient_agent, j.state, j.created_at, j.project_id
    from public.jobs j, since s
   where j.recipient_agent is not null
     and j.created_at > s.t
     and not coalesce(app.harness_job(j.job_id), false)
),
per as (
  select st.slug, st.name, st.title,
         (select count(*) from real_jobs r where r.recipient_agent = st.slug) as asked,
         (select count(*) from real_jobs r
           where r.recipient_agent = st.slug and r.state = 'complete') as answered,
         (select count(*) from real_jobs r
           where r.recipient_agent = st.slug and r.state = 'failed') as failed,
         (select count(*) from public.job_impediments i, since s
           where i.staff_slug = st.slug and i.created_at > s.t
             and not coalesce(i.is_fixture, false)) as could_not,
         (select count(*) from real_jobs r
           where r.recipient_agent = st.slug
             and r.state not in ('complete', 'failed', 'cancelled')) as in_hand
    from public.staff st
   where st.active
),
made as (
  select r.recipient_agent as slug,
         jsonb_agg(jsonb_build_object(
           'title', d.title,
           'at', d.created_at,
           'project', (select p.name from public.projects p where p.project_id = d.project_id))
           order by d.created_at desc) as items
    from public.documents d
    join real_jobs r on r.job_id = d.produced_by_job
   group by r.recipient_agent
),
/*
  What they could not do, in their own words.

  The impediment's `needed` is the sentence the agent wrote about what stopped
  it, which is more useful than a count and is the whole point of showing
  failures at all - "3 could not" tells him to look, and this is what he finds.
*/
walls as (
  select i.staff_slug as slug,
         jsonb_agg(jsonb_build_object('needed', i.needed, 'at', i.created_at)
                   order by i.created_at desc) as items
    from public.job_impediments i, since s
   where i.created_at > s.t and not coalesce(i.is_fixture, false)
   group by i.staff_slug
)
select coalesce(jsonb_object_agg(per.slug, jsonb_build_object(
         'name', per.name, 'title', per.title,
         'asked', per.asked, 'answered', per.answered,
         'failed', per.failed, 'could_not', per.could_not, 'in_hand', per.in_hand,
         -- Three is a card, not a list. The rest is one press away on the
         -- agent's own screen.
         'made', coalesce((select jsonb_agg(x) from jsonb_array_elements(
                    (select m.items from made m where m.slug = per.slug)) with ordinality t(x, i)
                    where i <= 3), '[]'::jsonb),
         'walls', coalesce((select jsonb_agg(x) from jsonb_array_elements(
                    (select w.items from walls w where w.slug = per.slug)) with ordinality t(x, i)
                    where i <= 2), '[]'::jsonb))), '{}'::jsonb)
  from per
$$;


--
-- Name: FUNCTION studio_team_work(p_days integer); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.studio_team_work(p_days integer) IS 'What each agent has actually done lately (#155): asked, answered, in hand, and COULD NOT - which is on the card rather than behind it, because a team page that only shows wins is decoration. Harness traffic is excluded through app.harness_job, because a fixture job is not something Emma did.';


--
-- Name: studio_unseen(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.studio_unseen() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
with mine as (
  select p.project_id, p.slug,
         greatest(
           coalesce((select s.at from public.project_seen s
                      where s.owner = 'grant' and s.project_id = p.project_id),
                    p.created_at),
           app.now_utc() - interval '7 days') as since
    from public.projects p
   where p.status = 'active' and not p.is_fixture
),
counted as (
  select m.slug,
         (select count(*) from public.documents d
           where d.project_id = m.project_id and d.created_at > m.since
             and coalesce(d.state, 'live') <> 'superseded') as docs,
         (select count(*) from public.tasks t
           where t.project_id = m.project_id and t.created_at > m.since
             and not coalesce(t.is_fixture, false)) as tasks,
         /*
           Outputs, through the job, because `outputs` has no project of its
           own - CLAUDE.md's own note about this join. An output exists only
           when a job produced one, which is the "finished" the first rule asks
           for: there is no such thing as an output from a job that is still
           thinking.
         */
         (select count(*) from public.outputs o
            join public.jobs j on j.job_id = o.job_id
           where j.project_id = m.project_id and o.created_at > m.since
             and not coalesce(app.harness_job(j.job_id), false)) as answers,
         (select count(*) from public.job_impediments i
           where i.project_id = m.project_id and i.created_at > m.since
             and not coalesce(i.is_fixture, false)) as walls
    from mine m
)
select coalesce(jsonb_object_agg(c.slug, jsonb_build_object(
         'n', c.docs + c.tasks + c.answers + c.walls,
         'docs', c.docs, 'tasks', c.tasks, 'answers', c.answers, 'walls', c.walls)),
       '{}'::jsonb)
  from counted c
 where c.docs + c.tasks + c.answers + c.walls > 0
$$;


--
-- Name: FUNCTION studio_unseen(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.studio_unseen() IS 'How much has arrived on each project since Grant last opened it (#122). Counts things that have ARRIVED - outputs, documents, tasks, impediments - and never a job that has merely started, because a mark that is always on is a mark nobody reads.';


--
-- Name: studio_waiting(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.studio_waiting(p_project_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
           'id', n.blocker_id,
           'what', n.requested_action,
           'why', nullif(btrim(n.why_needed), ''),
           'who', coalesce(n.originating_agent, 'The team'),
           'when', to_char(n.created_at, 'FMDD Mon'),
           -- #153: the instant travels, so "2 days ago" stays true on a page
           -- that has been open all afternoon.
           'at', n.created_at,
           'overdue', n.overdue,
           'due', n.real_deadline,
           -- The answers this one will accept, when it names them. Empty means
           -- it wants words rather than a button, and the page draws a field.
           'options', to_jsonb(coalesce(n.approval_options, array[]::text[])),
           'blocks', not n.work_can_continue,
           'cost', nullif(btrim(n.consequences_of_delay), ''),
           'job', n.job_id
         )) order by n.overdue desc, n.real_deadline nulls last, n.created_at), '[]'::jsonb)
    from public.needs_me n
   where n.project_id = p_project_id
$$;


--
-- Name: subject_for(text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.subject_for(p_origin_channel text, p_actor text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select subject from public.subject_identities
   where origin_channel = p_origin_channel and actor = p_actor
$$;


--
-- Name: FUNCTION subject_for(p_origin_channel text, p_actor text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.subject_for(p_origin_channel text, p_actor text) IS 'The person behind a channel-native actor, or null. Null is the correct answer for a stranger: mapping an unknown actor to the only person on file would let them inherit his preferences and his authority.';


--
-- Name: suppress_delivery(text, text, text, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.suppress_delivery(p_dedupe_key text, p_reason text, p_channel text DEFAULT NULL::text, p_account_ref text DEFAULT NULL::text, p_target_ref text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_row public.deliveries;
begin
  select * into v_row from public.deliveries
    where dedupe_key = p_dedupe_key for update;

  if not found then
    if p_channel is null or p_account_ref is null or p_target_ref is null then
      -- A tombstone must satisfy the table's own constraints, so the caller has
      -- to say where the message would have gone. Refusing beats inventing a
      -- target that no audit will ever match.
      return 'unknown_key';
    end if;
    insert into public.deliveries
      (channel, dedupe_key, account_ref, target_ref, purpose, state,
       suppressed_reason, lease_expires_at)
    values
      (p_channel, p_dedupe_key, p_account_ref, p_target_ref, 'notice',
       'suppressed', p_reason, app.now_utc())
    on conflict (dedupe_key) do nothing;
    return 'tombstoned';
  end if;

  if v_row.state = 'sent' then return 'too_late'; end if;
  if v_row.state = 'suppressed' then return 'already_suppressed'; end if;

  update public.deliveries
     set state = 'suppressed', suppressed_reason = p_reason
   where delivery_id = v_row.delivery_id;
  return 'suppressed';
end;
$$;


--
-- Name: tag_document(uuid, text, boolean); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.tag_document(p_document uuid, p_tag text, p_on boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare v_tag text := lower(btrim(coalesce(p_tag, ''))); v_tags text[];
begin
  if v_tag = '' then
    return jsonb_build_object('ok', false, 'error', 'a tag needs a word');
  end if;
  if not exists (select 1 from public.documents where document_id = p_document) then
    return jsonb_build_object('ok', false, 'error', 'no such document');
  end if;

  update public.documents
     set tags = case
                  when coalesce(p_on, true)
                    -- `array_append` would add a second copy. This is the
                    -- idempotent form: pressing the tag button twice is one tag.
                    then (select array(select distinct unnest(coalesce(tags, '{}') || v_tag) order by 1))
                  else (select array(select unnest(coalesce(tags, '{}')) except select v_tag order by 1))
                end
   where document_id = p_document
  returning tags into v_tags;

  return jsonb_build_object('ok', true, 'tags', to_jsonb(coalesce(v_tags, '{}')));
end;
$$;


--
-- Name: take_out_of_collection(uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.take_out_of_collection(p_document uuid, p_collection_name text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare v_collection uuid; v_project uuid;
begin
  select project_id into v_project from public.documents where document_id = p_document;
  if v_project is null then
    return jsonb_build_object('ok', false, 'error', 'no such document');
  end if;
  select collection_id into v_collection
    from public.collections
   where project_id = v_project and lower(name) = lower(btrim(coalesce(p_collection_name, '')));
  if v_collection is null then
    return jsonb_build_object('ok', false, 'error', 'no such collection in this project');
  end if;
  delete from public.document_collections
   where document_id = p_document and collection_id = v_collection;
  if not found then
    -- Not an error. "It is not in that collection" is the state the caller
    -- wanted, and reporting it as a failure makes an idempotent action
    -- look broken on the second press.
    return jsonb_build_object('ok', true, 'already', true);
  end if;
  return jsonb_build_object('ok', true, 'removed_from', p_collection_name);
end;
$$;


--
-- Name: task_add(uuid, text, text, date, text, boolean, text, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.task_add(p_project uuid, p_title text, p_detail text DEFAULT NULL::text, p_due_on date DEFAULT NULL::date, p_assignee text DEFAULT NULL::text, p_milestone boolean DEFAULT false, p_added_by text DEFAULT 'grant'::text, p_job uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_staff uuid;
  v_title text := btrim(coalesce(p_title, ''));
  v_by    text := coalesce(nullif(btrim(p_added_by), ''), 'grant');
  v       jsonb;
begin
  if v_title = '' then
    return jsonb_build_object('error', 'a task needs a title');
  end if;

  if p_project is not null
     and not exists (select 1 from public.projects
                      where project_id = p_project
                        and coalesce(status, '') <> 'archived') then
    return jsonb_build_object('error', 'that project does not exist or is archived');
  end if;

  if coalesce(p_milestone, false) and p_project is null then
    return jsonb_build_object('error',
      'a module belongs to a dashboard project - say which one');
  end if;

  if coalesce(btrim(p_assignee), '') <> '' then
    select staff_id into v_staff from public.staff where slug = btrim(p_assignee);
    if v_staff is null then
      return jsonb_build_object('error', format('nobody here is called %L', btrim(p_assignee)));
    end if;
  end if;

  /*
    Harness traffic names itself, here, once.

    `is_fixture` is GENERATED from `added_by`, so the prefix is the only way to
    set it -- and the job is the only thing that knows. A caller that had to
    remember this would forget, which is the whole history of this defect.
  */
  if p_job is not null and app.harness_job(p_job) then
    v_by := 'verify:' || v_by;
  end if;

  insert into public.tasks
    (project_id, title, detail, due_on, assignee_staff, added_by, is_milestone, job_id)
  values (p_project, v_title, coalesce(btrim(p_detail), ''), p_due_on, v_staff,
          v_by, coalesce(p_milestone, false), p_job)
  returning jsonb_build_object(
    'id', task_id, 'title', title, 'state', state, 'due_on', due_on,
    'milestone', is_milestone, 'fixture', is_fixture,
    'project', (select p.slug from public.projects p where p.project_id = p_project)
  ) into v;

  return v;
end;
$$;


--
-- Name: FUNCTION task_add(p_project uuid, p_title text, p_detail text, p_due_on date, p_assignee text, p_milestone boolean, p_added_by text, p_job uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.task_add(p_project uuid, p_title text, p_detail text, p_due_on date, p_assignee text, p_milestone boolean, p_added_by text, p_job uuid) IS 'Create a task against a project already resolved to an id. The door a JOB uses; app.hq_task_add is the door a person types into and resolves a slug onto this.';


--
-- Name: task_answers_blocker(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.task_answers_blocker() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  b public.blockers%rowtype;
begin
  if new.satisfies_blocker is null then return new; end if;
  if new.state <> 'done' or coalesce(old.state, '') = 'done' then return new; end if;

  select * into b from public.blockers where blocker_id = new.satisfies_blocker;
  if b.blocker_id is null then return new; end if;
  /*
    Idempotent. He may tick a task whose blocker somebody already answered --
    from Telegram, from the Governance page, or through a standing
    authorization -- and that is not an error, it is two people agreeing.
  */
  if b.state <> 'open' then return new; end if;

  update public.blockers
     set state = 'resolved',
         resolved_at = app.now_utc(),
         resolution = coalesce(new.satisfies_answer, 'done') ||
                      ' — the linked personal task was completed'
   where blocker_id = b.blocker_id;

  perform app.let_job_go(b.job_id, 'the personal task for this was done');
  return new;
end;
$$;


--
-- Name: task_delete_pushed(uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.task_delete_pushed(p_task_id uuid, p_provider text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_left jsonb;
begin
  select jsonb_agg(e) into v_left
    from public.task_tombstones d,
         lateral jsonb_array_elements(d.links) e
   where d.task_id = p_task_id and e ->> 'provider' <> p_provider;

  update public.task_tombstones
     set links = coalesce(v_left, '[]'::jsonb),
         cleared_at = case when coalesce(v_left, '[]'::jsonb) = '[]'::jsonb
                           then app.now_utc() else null end
   where task_id = p_task_id;
  return jsonb_build_object('ok', true, 'owed_to', coalesce(v_left, '[]'::jsonb));
end
$$;


--
-- Name: task_leaves_a_tombstone(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.task_leaves_a_tombstone() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_links jsonb;
begin
  select coalesce(jsonb_agg(jsonb_build_object(
           'provider', l.provider,
           'external_id', l.external_id,
           'external_project_id', l.external_project_id)), '[]'::jsonb)
    into v_links
    from public.task_links l
   where l.task_id = old.task_id;

  /*
    Nothing outside knew about it, so there is nothing to tell and no row to
    keep. This is what stops the table filling with every fixture task a
    verification run ever made — by construction rather than by a filter,
    which is the difference between a rule and a hope.
  */
  if v_links = '[]'::jsonb then
    return old;
  end if;

  insert into public.task_tombstones (task_id, title, links, deleted_by)
  values (old.task_id, old.title, v_links, coalesce(old.added_by, 'grant'))
  on conflict (task_id) do nothing;
  return old;
end $$;


--
-- Name: task_parent_ok(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.task_parent_ok(p_parent uuid, p_child uuid DEFAULT NULL::uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  /*
    Returns null when the parent is usable, and the sentence to refuse with
    otherwise. One function because `my_task_add` and `my_task_set` both need
    it, and CLAUDE.md records what two writers checking the same field
    separately costs — 0282/0293, and then a third instance with nothing
    loosened at all.
  */
  select case
    when p_parent is null then null
    when not exists (select 1 from public.tasks t where t.task_id = p_parent)
      then 'no task by that id to put this under'
    when not exists (select 1 from public.tasks t
                      where t.task_id = p_parent and t.assigned_to_human)
      then 'that is the team''s own work, not one of your tasks'
    when p_child is not null and p_parent = p_child
      then 'a task cannot be its own subtask'
    when exists (select 1 from public.tasks t
                  where t.task_id = p_parent and t.parent_task_id is not null)
      then 'that is already a subtask, and subtasks do not nest'
    when p_child is not null and exists (select 1 from public.tasks c
                                          where c.parent_task_id = p_child)
      then 'that task has subtasks of its own, so it cannot become one'
    else null
  end
$$;


--
-- Name: task_provider_forget(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.task_provider_forget(p_provider text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_links int;
  v_tasks int;
begin
  select count(*)::int into v_links from public.task_links where provider = p_provider;
  delete from public.task_links where provider = p_provider;
  update public.task_tombstones
     set links = coalesce((select jsonb_agg(e) from jsonb_array_elements(links) e
                            where e ->> 'provider' <> p_provider), '[]'::jsonb);
  update public.task_tombstones set cleared_at = app.now_utc()
   where cleared_at is null and links = '[]'::jsonb;
  select count(*)::int into v_tasks from public.tasks where assigned_to_human;
  return jsonb_build_object('ok', true, 'links_removed', v_links, 'tasks_kept', v_tasks);
end
$$;


--
-- Name: task_pulled(text, text, jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.task_pulled(p_provider text, p_external_id text, p_fields jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_provider text := btrim(coalesce(p_provider, ''));
  v_ext      text := btrim(coalesce(p_external_id, ''));
  v_link     public.task_links%rowtype;
  v_task     public.tasks%rowtype;
  v_title    text := nullif(btrim(coalesce(p_fields ->> 'title', '')), '');
  v_rev      text := nullif(btrim(coalesce(p_fields ->> 'external_revision', '')), '');
  v_id       uuid;
  v_conflict boolean := false;
  v_changed  text[] := '{}';
begin
  if v_provider = '' or v_ext = '' then
    return jsonb_build_object('error', 'a pulled task needs a provider and an external id');
  end if;

  /*
    THE TOMBSTONE IS CHECKED FIRST, and against the EXTERNAL id.

    A task Grant deleted here can still be sitting in the provider, and the
    provider will offer it back on every pull for ever. Checking the canonical
    id would not help: by the time a pull arrives the link may already be gone.
  */
  if exists (
    select 1 from public.task_tombstones d
     where d.cleared_at is null
       and d.links @> jsonb_build_array(
             jsonb_build_object('provider', v_provider, 'external_id', v_ext))
  ) then
    return jsonb_build_object(
      'ok', false, 'deleted', true,
      'note', 'that task was deleted here - remove it at the provider rather than recreating it');
  end if;

  select * into v_link from public.task_links
   where provider = v_provider and external_id = v_ext;

  -- ------------------------------------------------------------------ new --
  if not found then
    if v_title is null then
      return jsonb_build_object('error', 'a new task needs a title');
    end if;
    v_id := (app.my_task_add(
      p_title   => left(v_title, 500),
      p_detail  => coalesce(p_fields ->> 'detail', ''),
      p_due_on  => nullif(p_fields ->> 'due_on', '')::date,
      p_priority => nullif(p_fields ->> 'priority', '')::int
    ) ->> 'id')::uuid;
    if v_id is null then
      return jsonb_build_object('error', 'the task could not be created here');
    end if;
    if coalesce((p_fields ->> 'done')::boolean, false) then
      update public.tasks set state = 'done', done_at = app.now_utc() where task_id = v_id;
    end if;
    select * into v_task from public.tasks where task_id = v_id;
    insert into public.task_links
      (task_id, provider, external_id, external_project_id, external_revision,
       synced_revision, pulled_at, sync_state)
    values (v_id, v_provider, v_ext, nullif(p_fields ->> 'external_project_id', ''),
            v_rev, v_task.revision, app.now_utc(), 'ok');
    return jsonb_build_object('ok', true, 'created', true, 'id', v_id,
                              'title', v_task.title, 'revision', v_task.revision);
  end if;

  -- ------------------------------------------------------------- existing --
  select * into v_task from public.tasks where task_id = v_link.task_id;
  if not found then
    -- The link outlived its task. Nothing to update and nothing to resurrect.
    delete from public.task_links where task_id = v_link.task_id and provider = v_provider;
    return jsonb_build_object('ok', false, 'deleted', true,
      'note', 'that task no longer exists here');
  end if;

  /*
    BOTH SIDES MOVED. Canonical is kept and the disagreement is recorded.

    `synced_revision` is the canonical revision as of the last successful
    sync in EITHER direction, so "greater than" means somebody changed the
    task here since the provider was last in step with it.
  */
  if v_task.revision > coalesce(v_link.synced_revision, 0) then
    v_conflict := true;
  end if;

  if not v_conflict then
    /*
      `is distinct from` on every column, so applying the same payload twice
      does not move `revision` — the trigger fires on any UPDATE, including
      one that changes nothing.
    */
    if v_title is not null and v_title is distinct from v_task.title then
      update public.tasks set title = left(v_title, 500) where task_id = v_task.task_id;
      v_changed := v_changed || array['title'];
    end if;
    if (p_fields ? 'detail')
       and coalesce(p_fields ->> 'detail', '') is distinct from coalesce(v_task.detail, '') then
      update public.tasks set detail = coalesce(p_fields ->> 'detail', '')
       where task_id = v_task.task_id;
      v_changed := v_changed || array['detail'];
    end if;
    if (p_fields ? 'due_on')
       and nullif(p_fields ->> 'due_on', '')::date is distinct from v_task.due_on then
      update public.tasks set due_on = nullif(p_fields ->> 'due_on', '')::date
       where task_id = v_task.task_id;
      v_changed := v_changed || array['due_on'];
    end if;
    if (p_fields ? 'priority')
       and nullif(p_fields ->> 'priority', '')::int is not null
       and nullif(p_fields ->> 'priority', '')::int is distinct from v_task.priority then
      update public.tasks set priority = nullif(p_fields ->> 'priority', '')::int
       where task_id = v_task.task_id;
      v_changed := v_changed || array['priority'];
    end if;
    if (p_fields ? 'done') then
      if coalesce((p_fields ->> 'done')::boolean, false) and v_task.state <> 'done' then
        update public.tasks set state = 'done', done_at = app.now_utc()
         where task_id = v_task.task_id;
        v_changed := v_changed || array['done'];
      elsif not coalesce((p_fields ->> 'done')::boolean, false) and v_task.state = 'done' then
        update public.tasks set state = 'todo', done_at = null
         where task_id = v_task.task_id;
        v_changed := v_changed || array['reopened'];
      end if;
    end if;
  end if;

  select * into v_task from public.tasks where task_id = v_link.task_id;
  update public.task_links
     set external_revision = coalesce(v_rev, external_revision),
         external_project_id = coalesce(nullif(p_fields ->> 'external_project_id', ''),
                                        external_project_id),
         pulled_at = app.now_utc(),
         /*
           A conflict does NOT advance the watermark. The canonical value is
           still ahead of the provider, so it must still be offered for push —
           which is what resolves the conflict on the next round, in the
           direction the invariant requires.
         */
         synced_revision = case when v_conflict then synced_revision else v_task.revision end,
         sync_state = case when v_conflict then 'conflict' else 'ok' end,
         sync_error = case when v_conflict
                           then 'both sides changed this since the last sync - the copy here was kept'
                           else null end,
         updated_at = app.now_utc()
   where task_id = v_link.task_id and provider = v_provider;

  return jsonb_build_object('ok', true, 'id', v_task.task_id, 'title', v_task.title,
                            'conflict', v_conflict, 'changed', to_jsonb(v_changed),
                            'revision', v_task.revision);
end;
$$;


--
-- Name: FUNCTION task_pulled(p_provider text, p_external_id text, p_fields jsonb); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.task_pulled(p_provider text, p_external_id text, p_fields jsonb) IS 'Apply one inbound change from a provider. Canonical wins a genuine conflict and the link says so; a tombstoned task is never recreated. #259 Phase 2.';


--
-- Name: task_push_failed(uuid, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.task_push_failed(p_task_id uuid, p_provider text, p_error text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
begin
  insert into public.task_links
    (task_id, provider, external_id, sync_state, sync_error, updated_at)
  values (p_task_id, p_provider, 'pending:' || p_task_id::text, 'error',
          coalesce(nullif(btrim(p_error), ''), 'the provider refused, and said nothing'),
          app.now_utc())
  on conflict (task_id, provider) do update
     set sync_state = 'error',
         sync_error = excluded.sync_error,
         updated_at = app.now_utc();
  return jsonb_build_object('ok', true, 'recorded', p_error);
end
$$;


--
-- Name: task_pushed(uuid, text, text, integer, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.task_pushed(p_task_id uuid, p_provider text, p_external_id text, p_revision integer, p_external_project_id text DEFAULT NULL::text, p_external_revision text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
begin
  insert into public.task_links
    (task_id, provider, external_id, external_project_id, external_revision,
     synced_revision, pushed_at, sync_state, sync_error, updated_at)
  values (p_task_id, p_provider, p_external_id, p_external_project_id, p_external_revision,
          p_revision, app.now_utc(), 'ok', null, app.now_utc())
  on conflict (task_id, provider) do update
     set external_id = excluded.external_id,
         external_project_id = excluded.external_project_id,
         external_revision = excluded.external_revision,
         /*
           GREATEST, not the incoming value. A push that lands out of order
           must not walk the watermark backwards and make a newer revision
           look unpushed for ever.
         */
         synced_revision = greatest(coalesce(public.task_links.synced_revision, 0),
                                    coalesce(excluded.synced_revision, 0)),
         pushed_at = excluded.pushed_at,
         sync_state = 'ok',
         sync_error = null,
         updated_at = app.now_utc();
  return jsonb_build_object('ok', true, 'task', p_task_id, 'provider', p_provider);
end
$$;


--
-- Name: task_sync_panel(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.task_sync_panel() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select app.vikunja_settings() || jsonb_build_object(
    'trouble', app.task_sync_trouble('vikunja'),
    /*
      What it is keeping in step, so "connected" is a number rather than a
      claim. A panel that says connected over an empty mapping is the dead-dial
      shape one layer up.
    */
    'linked', (select count(*)::int from public.task_links l
                join public.tasks t on t.task_id = l.task_id
               where l.provider = 'vikunja' and not coalesce(t.is_fixture, false)),
    'last_synced', (select max(greatest(coalesce(pushed_at, 'epoch'::timestamptz),
                                        coalesce(pulled_at, 'epoch'::timestamptz)))
                      from public.task_links where provider = 'vikunja'))
$$;


--
-- Name: task_sync_trouble(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.task_sync_trouble(p_provider text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'task_id', l.task_id, 'title', t.title, 'provider', l.provider,
           'state', l.sync_state, 'why', l.sync_error,
           'last_pushed', l.pushed_at, 'last_pulled', l.pulled_at)
         order by l.updated_at desc), '[]'::jsonb)
    from public.task_links l
    join public.tasks t on t.task_id = l.task_id
   where l.sync_state in ('error', 'conflict')
     and (p_provider is null or l.provider = p_provider)
     and not coalesce(t.is_fixture, false)
$$;


--
-- Name: tasks_repeat_on_done(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.tasks_repeat_on_done() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare v_due date; v_remind timestamptz;
begin
  if new.state <> 'done' or coalesce(old.state, '') = 'done' then return new; end if;
  if new.repeat_every is null then return new; end if;

  -- `due` keeps the schedule; `done` starts the clock again now. Both from the
  -- anchor the row already has, so a task finished late does not silently
  -- reschedule itself into the past.
  v_due := case
             when new.repeat_from = 'done'
               then ((app.now_utc() + new.repeat_every) at time zone 'UTC')::date
             else new.due_on + new.repeat_every
           end;
  -- A schedule that has fallen behind catches up rather than creating a
  -- backlog of one occurrence per missed period.
  while v_due < (app.now_utc() at time zone 'UTC')::date loop
    v_due := v_due + new.repeat_every;
  end loop;

  v_remind := case
                when new.remind_at is null or new.due_on is null then null
                -- `date - date` is an INTEGER of days, and timestamptz plus
                -- integer is not an operator. The reminder keeps its distance
                -- from the due date, so it has to be days as an interval.
                else new.remind_at + ((v_due - new.due_on) * interval '1 day')
              end;

  insert into public.tasks
    (project_id, title, detail, state, priority, due_on, remind_at,
     assigned_to_human, added_by, labels, repeat_every, repeat_from, parent_task_id)
  values (new.project_id, new.title, new.detail, 'todo', new.priority, v_due, v_remind,
          new.assigned_to_human, new.added_by, new.labels,
          new.repeat_every, new.repeat_from, new.parent_task_id);

  -- The finished one stops repeating, or every completion makes another.
  update public.tasks set repeat_every = null, repeat_from = null
   where task_id = new.task_id;
  return new;
end;
$$;


--
-- Name: tasks_to_push(text, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.tasks_to_push(p_provider text, p_limit integer DEFAULT 200) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with mine as (
    select t.*, l.external_id, l.external_project_id, l.synced_revision
      from public.tasks t
      left join public.task_links l
        on l.task_id = t.task_id and l.provider = p_provider
     where t.assigned_to_human
       and not coalesce(t.is_fixture, false)
       -- Never pushed, or moved since it was.
       and (l.task_id is null or t.revision > coalesce(l.synced_revision, 0))
     order by t.updated_at
     limit greatest(coalesce(p_limit, 200), 1)
  )
  select jsonb_build_object(
    'provider', p_provider,
    'upserts', (select coalesce(jsonb_agg(jsonb_build_object(
        'id', m.task_id, 'revision', m.revision,
        'title', m.title, 'detail', m.detail,
        'state', m.state, 'done', m.state = 'done',
        'priority', m.priority, 'due_on', m.due_on, 'starts_on', m.starts_on,
        'remind_at', m.remind_at, 'labels', to_jsonb(m.labels),
        'parent', m.parent_task_id,
        'project', (select p.slug from public.projects p where p.project_id = m.project_id),
        'external_id', m.external_id,
        'external_project_id', m.external_project_id) order by m.updated_at), '[]'::jsonb)
      from mine m),
    /*
      Deletions travel in the same answer as the upserts, because a provider
      that learns about them separately will eventually apply them in the
      wrong order and resurrect a task Grant deleted.
    */
    'deletes', (select coalesce(jsonb_agg(jsonb_build_object(
        'id', d.task_id, 'title', d.title, 'links', d.links)), '[]'::jsonb)
      from public.task_tombstones d
     where d.cleared_at is null
       and d.links @> jsonb_build_array(jsonb_build_object('provider', p_provider)))
  )
$$;


--
-- Name: teach_expertise(text, text[]); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.teach_expertise(p_slug text, p_terms text[]) RETURNS text[]
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  update public.staff s
     set expertise = (
           select array_agg(distinct lower(btrim(t)) order by lower(btrim(t)))
             from unnest(s.expertise || p_terms) as t
            where btrim(t) <> ''
         ),
         updated_at = app.now_utc()
   where s.slug = p_slug
  returning s.expertise
$$;


--
-- Name: FUNCTION teach_expertise(p_slug text, p_terms text[]); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.teach_expertise(p_slug text, p_terms text[]) IS 'Add subject words to a specialist. Additive and de-duplicating, so terms Grant has added on the dashboard are never overwritten by a later seed.';


--
-- Name: teach_skill(text, text, text, text, public.lesson_scope, uuid, text, text, text[], uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.teach_skill(p_name text, p_when_to_use text, p_procedure text, p_authored_by text, p_scope public.lesson_scope DEFAULT 'global'::public.lesson_scope, p_project_id uuid DEFAULT NULL::uuid, p_staff_slug text DEFAULT NULL::text, p_job_kind text DEFAULT NULL::text, p_tools text[] DEFAULT '{}'::text[], p_from_job uuid DEFAULT NULL::uuid, p_supersedes uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  prior   public.skills%rowtype;
  made    public.skills%rowtype;
  next_v  integer := 1;
  unknown text;
begin
  if p_supersedes is not null then
    select * into prior from public.skills where skill_id = p_supersedes;
    if not found then
      return jsonb_build_object('error', 'nothing to supersede: ' || p_supersedes::text);
    end if;
    if exists (select 1 from public.skills where supersedes = p_supersedes) then
      return jsonb_build_object('error', 'that skill has already been revised');
    end if;
    next_v := prior.version + 1;
  end if;

  -- Named before anything is written, so the error is about the tool rather
  -- than about a foreign key on a table the author has never heard of.
  select t into unknown
    from unnest(coalesce(p_tools, '{}'::text[])) as t
   where not exists (select 1 from public.tool_permissions tp where tp.tool = t)
   limit 1;
  if unknown is not null then
    return jsonb_build_object(
      'error', 'no such tool: ' || unknown ||
               '. A skill may only name tools that already exist; ask for a new '
               'one rather than inventing it (ADR-0017).');
  end if;

  insert into public.skills
    (row_kind, scope, project_id, staff_slug, job_kind, name, when_to_use,
     procedure, authored_by, from_job, version, supersedes)
  values
    ('skill', p_scope, p_project_id, p_staff_slug, p_job_kind, p_name,
     p_when_to_use, p_procedure, p_authored_by, p_from_job, next_v, p_supersedes)
  returning * into made;

  insert into public.skill_tools (skill_id, tool)
  select made.skill_id, t from unnest(coalesce(p_tools, '{}'::text[])) as t
  on conflict do nothing;

  perform public.append_event(
    coalesce((select correlation_id from public.jobs where job_id = p_from_job),
             extensions.gen_random_uuid()),
    case when p_authored_by = 'grant' then 'user' else 'agent' end,
    p_authored_by, 'learning', 'office.skill_written',
    true, p_project_id, null,
    jsonb_build_object('skill_id', made.skill_id, 'name', p_name,
                       'scope', p_scope, 'version', made.version,
                       'tools', coalesce(p_tools, '{}'::text[])),
    -- The procedure is up to 4,000 characters and the ledger caps a rationale
    -- at 1,000, which is §6 refusing to become a place text is dumped. What it
    -- needs is enough to identify the change; the row itself holds the rest.
    left(format('%s — %s', p_name, p_when_to_use), 1000),
    '[]'::jsonb, null, null,
    'app.retire_skill(skill_id, by, reason)',
    p_from_job);

  return jsonb_build_object(
    'skill_id', made.skill_id,
    'version', made.version,
    'replaced', p_supersedes,
    'tools', coalesce(p_tools, '{}'::text[])
  );
end;
$$;


--
-- Name: FUNCTION teach_skill(p_name text, p_when_to_use text, p_procedure text, p_authored_by text, p_scope public.lesson_scope, p_project_id uuid, p_staff_slug text, p_job_kind text, p_tools text[], p_from_job uuid, p_supersedes uuid); Type: COMMENT; Schema: app; Owner: -
--

