--
-- Name: telegram_bot_created(text, text, uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.telegram_bot_created(p_bot_id text, p_username text, p_token_ref uuid, p_staff_slug text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare v jsonb;
begin
  insert into public.telegram_bots
    (bot_id, username, token_ref, staff_slug, expected, is_pager, enabled,
     disabled_reason, origin)
  values (p_bot_id, p_username, p_token_ref, p_staff_slug, true, false, true, null, 'created')
  on conflict (bot_id) do update
    set username        = excluded.username,
        token_ref       = excluded.token_ref,
        staff_slug      = coalesce(excluded.staff_slug, public.telegram_bots.staff_slug),
        enabled         = true,
        -- The whole point: the row said BotFather was the only way, and it
        -- was not. Clearing it is the record of that being settled.
        disabled_reason = null,
        origin          = 'created',
        updated_at      = app.now_utc()
  returning jsonb_build_object('bot_id', bot_id, 'username', username,
                               'staff_slug', staff_slug) into v;
  return v;
end;
$$;


--
-- Name: telegram_bot_for(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.telegram_bot_for(p_staff_slug text) RETURNS TABLE(bot_id text, username text, token text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select b.bot_id, b.username, app.resolve_secret(b.token_ref)
    from public.telegram_bots b
   where b.staff_slug = p_staff_slug
     and b.enabled
     and b.token_ref is not null
$$;


--
-- Name: FUNCTION telegram_bot_for(p_staff_slug text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.telegram_bot_for(p_staff_slug text) IS 'The voice a staff member speaks with, or no row when they have none. No row is a normal answer - two of seven bots do not exist - and the caller falls back to the pager rather than failing.';


--
-- Name: telegram_capacity(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.telegram_capacity() RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  select jsonb_build_object(
    'has_api_credentials', exists (
      select 1 from vault.decrypted_secrets where name = 'telegram.api_hash'),
    'has_user_session', exists (
      select 1 from vault.decrypted_secrets where name = 'telegram.user_session'),
    'owned', (select count(*)::int from public.telegram_bots where enabled),
    'spare', (select count(*)::int from public.telegram_bots
               where enabled and staff_slug is null and not is_pager),
    'limit', coalesce(
      (select (value #>> '{}')::int from public.system_config
        where key = 'telegram.bot_limit'), 20),
    'unfilled_roles', coalesce((
      select jsonb_agg(jsonb_build_object('staff_slug', b.staff_slug, 'username', b.username)
             order by b.staff_slug)
        from public.telegram_bots b
       where b.disabled_reason is not null), '[]'::jsonb)
  )
$$;


--
-- Name: telegram_chat_for(text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.telegram_chat_for(p_subject text, p_bot_id text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with who as (
    select b.staff_slug
      from public.telegram_bots b
     where b.bot_id = p_bot_id
  ),
  direct as (
    select coalesce(c.value #>> '{}', '') as slug
      from public.system_config c
     where c.key = 'telegram.direct_to_grant'
  ),
  private_chat as (
    -- Unchanged from 0041. An attributed chat beats an unattributed one; the
    -- newest beats the oldest.
    select chat_id
      from public.telegram_chats
     where chat_type = 'private'
       and deliverable
       and bot_id = p_bot_id
       and (subject = p_subject or subject is null)
     order by (subject is not null) desc, last_seen_at desc
     limit 1
  )
  select coalesce(
    case
      -- No rule set, or this bot is the one allowed through: private chat.
      -- staff_slug null is the pager bot, which is the Chief of Staff's.
      when (select slug from direct) = ''
        or (select staff_slug from who) is null
        or (select staff_slug from who) = (select slug from direct)
      then (select chat_id from private_chat)
      -- Everyone else: the office group, and the private chat only while
      -- there is no office group to send to.
      else coalesce(app.telegram_office_chat(p_bot_id), (select chat_id from private_chat))
    end,
    null
  );
$$;


--
-- Name: FUNCTION telegram_chat_for(p_subject text, p_bot_id text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.telegram_chat_for(p_subject text, p_bot_id text) IS 'Where this bot sends. The Chief of Staff reaches Grant directly; the rest go to the office group once one exists, and to the private chat until then.';


--
-- Name: telegram_office_chat(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.telegram_office_chat(p_bot_id text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  -- A group this particular bot is in. The chat id is shared across bots but
  -- the row is not: `telegram_chats` is keyed on (bot_id, chat_id) precisely
  -- because a bot that has not been added to the room cannot post to it (0097).
  select chat_id
  from public.telegram_chats
  where bot_id = p_bot_id
    and chat_type in ('group', 'supergroup')
    and deliverable
  order by last_seen_at desc
  limit 1;
$$;


--
-- Name: FUNCTION telegram_office_chat(p_bot_id text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.telegram_office_chat(p_bot_id text) IS 'The office group this bot can post to, or null. Null is the ordinary state until Grant creates the group and adds the bots.';


