--
-- Name: test_destination_is_not_real(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.test_destination_is_not_real() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_real int;
begin
  select count(*)::int into v_real
    from public.deliveries d
    left join public.jobs j on j.job_id = d.job_id
   where d.channel = new.channel
     and d.target_ref = new.target_ref
     and d.sent_at is not null
     and (d.job_id is null or not app.harness_job(d.job_id));
  if v_real > 0 then
    raise exception
      'refusing: % % has received % real delivery(s) - it is a production destination',
      new.channel, new.target_ref, v_real;
  end if;
  return new;
end;
$$;


--
-- Name: tool_allowed(text, boolean); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.tool_allowed(p_tool text, p_approved boolean DEFAULT false) RETURNS boolean
    LANGUAGE plpgsql STABLE
    AS $$
declare
  v record;
begin
  select * into v from public.tool_permissions where tool = p_tool;

  -- An unknown tool is refused. §10's "never allow free-form model output to
  -- directly trigger destructive tool calls" only holds if an invented tool
  -- name fails closed rather than falling through.
  if v is null then
    return false;
  end if;
  if not v.enabled then
    return false;
  end if;
  -- Level 3 needs explicit approval every time; approval is not a mode the
  -- system can put itself into.
  if v.level = 3 then
    return p_approved;
  end if;
  return true;
end;
$$;


--
-- Name: FUNCTION tool_allowed(p_tool text, p_approved boolean); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.tool_allowed(p_tool text, p_approved boolean) IS 'An UNKNOWN tool is refused. §10 forbids free-form model output triggering destructive calls, which only holds if an invented tool name fails closed.';


--
-- Name: touch_contacts(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.touch_contacts() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin new.updated_at := app.now_utc(); return new; end $$;


--
-- Name: touch_task(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.touch_task() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  new.updated_at := now();
  -- Keep done_at honest without making every caller remember it.
  if new.state = 'done' and old.state <> 'done' then new.done_at := now(); end if;
  if new.state <> 'done' then new.done_at := null; end if;
  /*
    0513. The version a provider compares against.

    Bumped here rather than by each writer, for the reason every other trigger
    on this table exists: there are five doors onto `public.tasks` and a
    version maintained by four of them is a version that lies.
  */
  new.revision := coalesce(old.revision, 0) + 1;
  return new;
end $$;


--
-- Name: touch_updated_at(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.touch_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  new.updated_at := now();
  return new;
end
$$;


--
-- Name: trigger_health(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.trigger_health() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select coalesce(jsonb_agg(v order by name), '[]'::jsonb)
    from (
      select t.name,
             jsonb_build_object(
               'name', t.name, 'source', t.source, 'event_type', t.event_type,
               'enabled', t.enabled, 'job_kind', t.job_kind,
               'project', (select name from public.projects p where p.project_id = t.project_id),
               'fired', (select count(*) from public.trigger_firings f
                          where f.trigger_id = t.trigger_id and f.decision = 'fired'),
               'declined', (select count(*) from public.trigger_firings f
                             where f.trigger_id = t.trigger_id and f.decision <> 'fired'),
               'last_fired', (select max(at) from public.trigger_firings f
                               where f.trigger_id = t.trigger_id and f.decision = 'fired'),
               'last_declined', (select jsonb_build_object('at', f.at, 'why', f.why)
                                   from public.trigger_firings f
                                  where f.trigger_id = t.trigger_id and f.decision <> 'fired'
                                  order by f.at desc limit 1),
               'seen_this_hour', (select count(*) from public.trigger_firings f
                                   where f.trigger_id = t.trigger_id
                                     and f.at > app.now_utc() - interval '1 hour')) as v
        from public.event_triggers t
    ) q;
$$;


