--
-- Name: unarchive_document(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.unarchive_document(p_document uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare v_title text; v_was text;
begin
  select title, state into v_title, v_was
    from public.documents where document_id = p_document;
  if v_title is null then
    return jsonb_build_object('ok', false, 'error', 'no such document');
  end if;
  update public.documents
     set state = 'approved', missing_since = null
   where document_id = p_document;
  return jsonb_build_object('ok', true, 'title', v_title, 'was', v_was);
end;
$$;


--
-- Name: unarchive_project(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.unarchive_project(p_slug text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare v_project uuid; v_name text; v_off jsonb; v_attached int;
begin
  select project_id, name into v_project, v_name
    from public.projects where slug = p_slug and status = 'archived';
  if v_project is null then
    return jsonb_build_object('ok', false, 'error', format('no archived project called %s', p_slug));
  end if;

  /*
    ADR-0014, asked BEFORE the write rather than discovered at commit.

    The constraint trigger is DEFERRED, so without this the update succeeds,
    the function returns a cheerful `ok: true`, and the transaction then blows
    up somewhere the caller cannot attribute. A refusal that names the remedy
    is the whole difference between a rule and a fault.
  */
  select count(*) into v_attached
    from public.project_attachments a
   where a.project_id = v_project and a.enabled;
  if v_attached = 0 then
    return jsonb_build_object(
      'ok', false,
      'error', format(
        '%s has nothing attached, and an active project has to read from '
        'somewhere real (ADR-0014). Reconnect a source first, then bring it back.',
        v_name),
      'needs', 'an attachment');
  end if;

  update public.projects set status = 'active' where project_id = v_project;

  select coalesce(jsonb_agg(r.slug order by r.slug), '[]'::jsonb) into v_off
    from public.responsibilities r where r.project_id = v_project and not r.enabled;

  return jsonb_build_object(
    'ok', true, 'project', p_slug, 'name', v_name, 'still_off', v_off);
end;
$$;


--
-- Name: undelivered(uuid, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.undelivered(p_project_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select coalesce(jsonb_agg(x.v order by x.at desc), '[]'::jsonb)
    from (
      select d.updated_at as at,
             jsonb_build_object(
               'delivery_id', d.delivery_id,
               'channel',     d.channel,
               'purpose',     d.purpose,
               'target',      d.target_ref,
               'attempt',     d.attempt,
               'error_code',  d.error_code,
               'job',         d.job_id,
               'project',     j.project_id,
               'at',          d.updated_at,
               -- A code nobody can act on is a code nobody reads.
               'says', case
                 when d.error_code like 'chat_not_found%'
                   then 'That chat no longer exists, or the bot was removed from it.'
                 when d.error_code like 'indeterminate%'
                   then 'The provider did not say whether it arrived.'
                 when d.error_code like '%rate%'
                   then 'The provider is rate-limiting us.'
                 when d.error_code like '%timeout%' or d.error_code like '%ECONN%'
                   then 'The provider could not be reached.'
                 else 'The provider refused it.'
               end
             ) as v
        from public.deliveries d
        join public.jobs j on j.job_id = d.job_id
       where d.state = 'failed'
         and not app.harness_job(j.job_id)
         and (p_project_id is null or j.project_id = p_project_id)
       order by d.updated_at desc
       limit greatest(1, least(coalesce(p_limit, 50), 200))
    ) x
$$;


--
-- Name: FUNCTION undelivered(p_project_id uuid, p_limit integer); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.undelivered(p_project_id uuid, p_limit integer) IS 'Issue #202. What could not be delivered, with the attempt count, the error code and a sentence a person can act on.';


--
-- Name: understood(uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.understood(p_job_id uuid, p_sentence text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_said text := btrim(coalesce(p_sentence, ''));
  v_was  text;
begin
  if length(v_said) < 8 then
    return jsonb_build_object('error', 'a restatement has to say something');
  end if;
  -- Truncated rather than refused: losing the restatement because a model was
  -- verbose would lose the artefact this Issue is about, and the first 400
  -- characters of a long one still shows a misreading.
  v_said := left(v_said, 400);

  select understood_as into v_was from public.jobs where job_id = p_job_id;
  if not found then
    return jsonb_build_object('error', 'no such job');
  end if;
  if v_was is not null then
    return jsonb_build_object('ok', false, 'already', v_was);
  end if;

  update public.jobs set understood_as = v_said where job_id = p_job_id;
  return jsonb_build_object('ok', true, 'understood_as', v_said);
end;
$$;


--
-- Name: undo_none(text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.undo_none(p_kind text, p_description text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_id uuid;
begin
  if coalesce(current_setting('app.undoing', true), '') = '1' then
    return null;
  end if;
  insert into public.undoable_actions
    (correlation_id, kind, description, reversal, status, undo_deadline)
  values (gen_random_uuid(), p_kind, p_description, '{}'::jsonb, 'not_undoable', null)
  returning action_id into v_id;
  return v_id;
end;
$$;


--
-- Name: undo_offer(text, text, jsonb, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.undo_offer(p_kind text, p_description text, p_reversal jsonb, p_minutes integer DEFAULT 2) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_id uuid;
begin
  -- An undo of an undo is not a feature.
  if coalesce(current_setting('app.undoing', true), '') = '1' then
    return null;
  end if;
  -- A reversal with nothing in it is not a reversal; the table says so too,
  -- and reaching that constraint would turn a missing inverse into a failed
  -- write of the thing the person actually asked for.
  if p_reversal is null or p_reversal = '{}'::jsonb then
    return null;
  end if;

  insert into public.undoable_actions
    (correlation_id, kind, description, reversal, status, undo_deadline)
  values (gen_random_uuid(), p_kind, p_description, p_reversal, 'available',
          app.now_utc() + make_interval(mins => p_minutes))
  returning action_id into v_id;
  return v_id;
end;
$$;


--
-- Name: FUNCTION undo_offer(p_kind text, p_description text, p_reversal jsonb, p_minutes integer); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.undo_offer(p_kind text, p_description text, p_reversal jsonb, p_minutes integer) IS 'Record an exact inverse at the moment the previous value is still known. Returns null while an undo is being performed, so undoing is not itself undoable.';


--
-- Name: undo_tasks_from_job(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.undo_tasks_from_job(p_job uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_removed int;
  v_kept    int;
begin
  if p_job is null then
    return jsonb_build_object('error', 'there is no job to undo');
  end if;

  select count(*) into v_kept
    from public.tasks t
   where t.job_id = p_job
     and (t.state <> 'todo' or t.updated_at > t.created_at + interval '1 second');

  with gone as (
    delete from public.tasks t
     where t.job_id = p_job
       and t.state = 'todo'
       -- `tasks_touch` sets updated_at on every UPDATE, so this is how a row
       -- Grant has edited says so. A second of slack because the insert and
       -- the trigger are not the same instant.
       and t.updated_at <= t.created_at + interval '1 second'
    returning 1
  )
  select count(*) into v_removed from gone;

  return jsonb_build_object('removed', v_removed, 'kept', v_kept,
    'note', case when v_kept = 0 then 'all of them'
                 else format('%s left alone - you had already changed %s of them', v_kept, v_kept)
            end);
end;
$$;


--
-- Name: FUNCTION undo_tasks_from_job(p_job uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.undo_tasks_from_job(p_job uuid) IS 'Take back the tasks one job created (#130, 0398). Keyed on tasks.job_id rather than on titles, which normalise and collide. Only rows still todo and never edited: anything Grant has touched since is his work and stays, and the answer counts what it left alone rather than implying otherwise.';


--
-- Name: unlearn(uuid, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.unlearn(p_lesson_id uuid, p_by text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  target public.lessons%rowtype;
  note   text;
begin
  select * into target from public.lessons where lesson_id = p_lesson_id;
  if not found then
    return jsonb_build_object('error', 'no such lesson');
  end if;
  if exists (select 1 from public.lessons where supersedes = p_lesson_id) then
    return jsonb_build_object('error', 'that lesson is already superseded');
  end if;

  -- The retraction row carries the reason in `body`, and `body` has a minimum
  -- length, so "withdrawn" with no reason is not a thing that can be recorded.
  note := 'Withdrawn: ' || btrim(coalesce(p_reason, ''));
  if length(note) < 20 then
    return jsonb_build_object('error', 'say why it is being withdrawn');
  end if;

  insert into public.lessons
    (row_kind, scope, project_id, staff_slug, job_kind, body,
     learned_by, confidence, supersedes)
  values
    ('retraction', target.scope, target.project_id, target.staff_slug,
     target.job_kind, left(note, 280), p_by, 1.00, p_lesson_id);

  return jsonb_build_object('retracted', p_lesson_id);
end;
$$;


--
-- Name: FUNCTION unlearn(p_lesson_id uuid, p_by text, p_reason text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.unlearn(p_lesson_id uuid, p_by text, p_reason text) IS 'Withdraw a lesson by writing a retraction that supersedes it. Nothing is deleted; a reason is required.';


