--
-- Name: unrouted_live_jobs(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.unrouted_live_jobs() RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select count(*)::int
  from public.jobs j
  where j.state not in ('complete', 'cancelled', 'failed')
    and not exists (
      select 1 from public.routing_decisions r where r.job_id = j.job_id
    );
$$;


--
-- Name: FUNCTION unrouted_live_jobs(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.unrouted_live_jobs() IS 'Live jobs with no routing decision, and therefore no subject terms - the duplicate scan''s blind spot, reported so that a `none_found` result can be read with the coverage it actually had.';


--
-- Name: unused_capabilities(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.unused_capabilities() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'connector', c.connector, 'verb', c.verb, 'returns', c.returns,
           'reach', c.reach, 'cost', c.cost_note
         ) order by c.connector, c.verb), '[]'::jsonb)
    from public.connector_capabilities c
    join public.knowledge_connectors k on k.connector = c.connector
   where btrim(c.used_by) = ''
     and c.reach in ('api', 'unofficial')
     and k.enabled
$$;


--
-- Name: usage_is_harness(text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.usage_is_harness(p_model text, p_provider text) RETURNS boolean
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(p_model, '') in ('fixture/free-model', 'gate5-probe', 'probe')
      or coalesce(p_model, '') like 'fixture/%'
      or coalesce(p_model, '') like 'gate%-probe'
      or coalesce(p_provider, '') in ('fixture', 'probe')
$$;


--
-- Name: FUNCTION usage_is_harness(p_model text, p_provider text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.usage_is_harness(p_model text, p_provider text) IS 'A model call made by the verification suites rather than by the office. Named in ONE place: a name-based rule that grows quietly is how a previous one missed four patterns and reported 264 harness failures to Grant as the office collapsing.';


--
-- Name: usage_overview(integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.usage_overview(p_days integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  days      integer := greatest(coalesce(p_days, 30), 1);
  head      jsonb;
  services  jsonb;
  top       jsonb;
  spark     jsonb;
  harness   integer;
begin
  select app.free_tier_headroom() into head;

  -- Counted and reported rather than hidden. "We made 1,140 calls of which 57
  -- were our own tests" is honest; silently showing 1,083 invites the question
  -- of where the others went the first time he compares it to something.
  select count(*)::int into harness
    from public.inference_usage u
   where u.occurred_at >= app.now_utc() - make_interval(days => days)
     and app.usage_is_harness(u.model_id, u.provider);

  services := jsonb_build_array(
    (select jsonb_build_object(
      'key', 'openrouter',
      'name', 'Model calls',
      'detail', 'OpenRouter, free tier',
      'unit', 'usd',
      'used', round(coalesce(sum(u.cost_usd), 0)::numeric, 6),
      'limit', null,
      'of_limit', null,
      'window', 'last ' || days::text || ' days',
      'secondary', jsonb_build_object(
        'calls', count(*),
        'tokens', coalesce(sum(u.prompt_tokens + u.completion_tokens), 0),
        'failed', count(*) filter (where u.outcome <> 'ok'),
        'harness_excluded', harness
      ),
      'provenance', case
        when count(*) filter (where u.provider_reported_cost is not null) = 0 then 'measured'
        else 'reported' end,
      'note', case
        when coalesce(sum(u.cost_usd), 0) = 0
          then 'Every call so far has been on a free model.'
        else null end,
      'day', round(coalesce(sum(u.cost_usd) filter
              (where u.occurred_at >= app.now_utc() - interval '1 day'), 0)::numeric, 6),
      'week', round(coalesce(sum(u.cost_usd) filter
              (where u.occurred_at >= app.now_utc() - interval '7 days'), 0)::numeric, 6),
      'month', round(coalesce(sum(u.cost_usd) filter
              (where u.occurred_at >= app.now_utc() - interval '30 days'), 0)::numeric, 6)
    ) from public.inference_usage u
      left join public.jobs j on j.job_id = u.job_id
      where u.occurred_at >= app.now_utc() - make_interval(days => days)
        and coalesce(j.is_fixture, false) = false
        and not app.usage_is_harness(u.model_id, u.provider)),

    (select jsonb_build_object(
      'key', 'notebooklm',
      'name', 'Notebook generations',
      'detail', 'Audio, slides, video, mind maps',
      'unit', 'units',
      'used', coalesce(sum(s.units) filter
              (where s.occurred_at >= app.now_utc() - interval '5 hours'), 0),
      'limit', (select (value #>> '{}')::int from public.system_config
                 where key = 'notebook.window_units'),
      'of_limit', null,
      'window', 'five hours',
      'secondary', jsonb_build_object(
        'week_used', coalesce(sum(s.units) filter
                     (where s.occurred_at >= app.now_utc() - interval '7 days'), 0),
        'week_limit', (select (value #>> '{}')::int from public.system_config
                        where key = 'notebook.week_units'),
        'operations', count(*),
        'failed', count(*) filter (where not s.succeeded)
      ),
      'provenance', 'estimated',
      'note', 'Our own count. Google publishes no usage figure for this.',
      'day', coalesce(sum(s.units) filter
             (where s.occurred_at >= app.now_utc() - interval '1 day'), 0),
      'week', coalesce(sum(s.units) filter
              (where s.occurred_at >= app.now_utc() - interval '7 days'), 0),
      'month', coalesce(sum(s.units) filter
               (where s.occurred_at >= app.now_utc() - interval '30 days'), 0)
    ) from public.notebook_spend s
      left join public.jobs j on j.job_id = s.job_id
     where coalesce(j.is_fixture, false) = false),

    (select jsonb_build_object(
      'key', 'tts',
      'name', 'Speech',
      'detail', 'Google Chirp 3',
      'unit', 'characters',
      'used', coalesce(sum(t.characters) filter
              (where date_trunc('month', t.billing_month)
                     = date_trunc('month', app.now_utc())), 0),
      'limit', 1000000,
      'of_limit', null,
      'window', 'this month',
      'secondary', jsonb_build_object('failed', count(*) filter (where t.failed)),
      'provenance', 'measured',
      'note', 'Counted by us — Google exposes no live counter for Chirp 3.',
      'day', coalesce(sum(t.characters) filter
             (where t.created_at >= app.now_utc() - interval '1 day'), 0),
      'week', coalesce(sum(t.characters) filter
              (where t.created_at >= app.now_utc() - interval '7 days'), 0),
      'month', coalesce(sum(t.characters) filter
               (where t.created_at >= app.now_utc() - interval '30 days'), 0)
    ) from public.tts_usage t),

    jsonb_build_object(
      'key', 'supabase_db', 'name', 'Database', 'detail', 'Supabase, free tier',
      'unit', 'bytes',
      'used', (head -> 'database' ->> 'bytes')::bigint,
      'limit', (head -> 'database' ->> 'limit_bytes')::bigint,
      'of_limit', (head -> 'database' ->> 'percent')::numeric,
      'window', 'now', 'provenance', 'measured', 'note', null,
      'secondary', jsonb_build_object('largest', head -> 'largest')
    ),
    jsonb_build_object(
      'key', 'supabase_storage', 'name', 'File storage', 'detail', 'Supabase, free tier',
      'unit', 'bytes',
      'used', (head -> 'storage' ->> 'bytes')::bigint,
      'limit', (head -> 'storage' ->> 'limit_bytes')::bigint,
      'of_limit', (head -> 'storage' ->> 'percent')::numeric,
      'window', 'now', 'provenance', 'measured', 'note', null,
      'secondary', jsonb_build_object('objects', (head -> 'storage' ->> 'objects')::int)
    ),

    (select jsonb_build_object(
      'key', 'mcp', 'name', 'Tool calls', 'detail', 'MCP clients',
      'unit', 'calls',
      'used', count(*), 'limit', null, 'of_limit', null, 'window', 'this month',
      'provenance', 'measured', 'note', null,
      'secondary', jsonb_build_object('failed', count(*) filter (where c.outcome <> 'ok')),
      'day', count(*) filter (where c.called_at >= app.now_utc() - interval '1 day'),
      'week', count(*) filter (where c.called_at >= app.now_utc() - interval '7 days'),
      'month', count(*) filter (where c.called_at >= app.now_utc() - interval '30 days')
    ) from public.mcp_calls c)
  );

  select coalesce(jsonb_agg(x order by (x ->> 'calls')::int desc), '[]'::jsonb)
    into top
    from (
      select jsonb_build_object(
               'name', u.model_id,
               'provider', u.provider,
               'calls', count(*)::int,
               'tokens', coalesce(sum(u.prompt_tokens + u.completion_tokens), 0),
               'cost', round(coalesce(sum(u.cost_usd), 0)::numeric, 6),
               'failed', count(*) filter (where u.outcome <> 'ok')
             ) as x
        from public.inference_usage u
        left join public.jobs j on j.job_id = u.job_id
       where u.occurred_at >= app.now_utc() - make_interval(days => days)
         and coalesce(j.is_fixture, false) = false
         and not app.usage_is_harness(u.model_id, u.provider)
       group by u.model_id, u.provider
       order by count(*) desc
       limit 8
    ) t;

  select coalesce(jsonb_agg(jsonb_build_object('day', d.day, 'calls', d.calls, 'cost', d.cost)
                            order by d.day), '[]'::jsonb)
    into spark
    from (
      select (u.occurred_at at time zone app.grant_timezone())::date as day,
             count(*)::int as calls,
             round(coalesce(sum(u.cost_usd), 0)::numeric, 6) as cost
        from public.inference_usage u
        left join public.jobs j on j.job_id = u.job_id
       where u.occurred_at >= app.now_utc() - make_interval(days => days)
         and coalesce(j.is_fixture, false) = false
         and not app.usage_is_harness(u.model_id, u.provider)
       group by 1
    ) d;

  return jsonb_build_object(
    'generated_at', app.now_utc(),
    'window_days', days,
    'target', 'about £0 / month',
    'harness_excluded', harness,
    'services', services,
    'top_models', top,
    'by_day', spark
  );
end;
$$;


--
-- Name: FUNCTION usage_overview(p_days integer); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.usage_overview(p_days integer) IS 'Every service, with its denominator and its provenance (#61). One projection so the studio and the build page cannot give two answers to "what did we spend".';


--
-- Name: validate_vault_refs(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.validate_vault_refs() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'vault', 'public'
    AS $_$
declare
  r app.vault_secret_ref;
  col text;
begin
  foreach col in array array[
    'bot_token_ref', 'signing_secret_ref', 'client_secret_ref',
    'config_token_ref', 'config_refresh_ref'
  ]
  loop
    execute format('select ($1).%I', col) into r using new;
    if r is not null and not exists (select 1 from vault.secrets s where s.id = r::uuid) then
      raise exception
        '%.% references vault secret % which does not exist',
        tg_table_name, col, r
        using errcode = '23503',
              hint = 'Create the secret with vault.create_secret() first, then '
                     'store the id it returns.';
    end if;
  end loop;
  return new;
end
$_$;


--
-- Name: vault_inventory(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.vault_inventory() RETURNS TABLE(service text, name text, description text, bytes integer, created_at timestamp with time zone, age_days integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    split_part(s.name, '.', 1) as service,
    s.name,
    s.description,
    length(s.decrypted_secret)::integer as bytes,
    s.created_at,
    floor(extract(epoch from (app.now_utc() - s.created_at)) / 86400)::integer as age_days
  from vault.decrypted_secrets s
  order by split_part(s.name, '.', 1), s.name
$$;


--
-- Name: FUNCTION vault_inventory(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.vault_inventory() IS 'Every secret the vault holds: name, what it is for, how big and how old. Never the value, and never a prefix of one. Exists so "do we have a credential for X?" is a lookup instead of somebody remembering (0159).';


--
-- Name: vault_secret(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.vault_secret(p_name text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
begin
  if p_name not in (
    'google.client_secret',
    'google.refresh_token',
    'github.dispatch_token',
    -- Where a refresh token waits between "Grant pressed Disconnect" and
    -- "Google confirmed the grant is dead" (#109). Read by exactly one
    -- handler, whose only purpose is to destroy it.
    'google.revoking_refresh_token'
  ) then
    raise exception 'no' using errcode = '42501';
  end if;
  return (select decrypted_secret from vault.decrypted_secrets where name = p_name);
end;
$$;


--
-- Name: vikunja_settings(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.vikunja_settings() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'base_url', (select value #>> '{}' from public.system_config where key = 'vikunja.base_url'),
    'project_id', (select (value #>> '{}')::int from public.system_config
                    where key = 'vikunja.project_id'),
    'configured', exists (select 1 from public.system_config where key = 'vikunja.base_url')
              and exists (select 1 from vault.secrets where name = 'vikunja.api_token'))
$$;


--
-- Name: voice_answer(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.voice_answer(p_command_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  c record;
  g text;
  who text;
  said text;
  n integer;
  rows_text text;
  v_cal jsonb;
  v_age text;
begin
  select * into c from public.inbound_commands where command_id = p_command_id;
  if not found then
    return jsonb_build_object('error', 'no such command');
  end if;

  said := coalesce(c.transcript, c.instruction, '');
  g := app.spoken_gist(said);
  if g = '' then
    return null;
  end if;

  if app.spoken_is_a_request(said) then
    return null;
  end if;

  -- --------------------------------------------------------------------
  -- "what have I got on today" / "am I free this afternoon"
  -- --------------------------------------------------------------------
  if g ~ '\m(calendar|diary|schedule|meetings?|agenda|got on|free|busy today|this week)\M' then
    v_cal := app.calendar_ahead(case when g ~ '\m(week|this week)\M' then 168 else 24 end);
    if (v_cal ->> 'enabled')::boolean is not true then
      return jsonb_build_object(
        'speak', 'The calendar is not connected yet. Settings, then Google, and there are '
                 'four steps.',
        'kind', 'state');
    end if;
    if (v_cal ->> 'as_of') is null then
      return jsonb_build_object(
        'speak', 'The calendar is connected but nothing has been read from it yet.',
        'kind', 'state');
    end if;
    -- The age, in the sentence. See the note above.
    v_age := case
      when (v_cal ->> 'as_of')::timestamptz > app.now_utc() - interval '90 minutes'
        then ''
      else format(' This is as of %s.',
                  to_char((v_cal ->> 'as_of')::timestamptz, 'FMDay FMHH12:MIam'))
    end;
    n := jsonb_array_length(v_cal -> 'events');
    if n = 0 then
      return jsonb_build_object(
        'speak', format('Nothing in the diary%s.%s',
                        case when g ~ '\mweek\M' then ' this week' else ' today' end, v_age),
        'kind', 'state');
    end if;
    select string_agg(
             format('%s%s',
                    coalesce(e ->> 'summary', 'an untitled entry'),
                    case when (e ->> 'all_day')::boolean then ' (all day)'
                         else to_char((e ->> 'starts_at')::timestamptz, ' at FMHH12:MIam') end),
             '; ' order by (e ->> 'starts_at')::timestamptz)
      into rows_text
      from jsonb_array_elements(v_cal -> 'events') e;
    return jsonb_build_object(
      'speak', format('%s %s: %s.%s', n,
                      case when n = 1 then 'thing' else 'things' end, rows_text, v_age),
      'kind', 'state');
  end if;

  if g ~ '\m(what|who|how)\M' and g ~ '\m(said|say|find|found|going on|about|doing|been up to|conclude|concluded|reported|report)\M' then
    who := app.spoken_about_whom(said);
    if who is not null then
      select left(o.body, 900) into rows_text
        from public.outputs o
        join public.jobs j on j.job_id = o.job_id
       where j.state = 'complete'
         and app.staff_behind_job(o.job_id) = who
       order by o.created_at desc
       limit 1;

      select s.name into said from public.staff s where s.slug = who;
      if rows_text is null then
        return jsonb_build_object(
          'speak', format('%s has not finished anything yet, so there is nothing to report.', said),
          'kind', 'state'
        );
      end if;
      return jsonb_build_object(
        'speak', format('%s, most recently: %s', said, rows_text),
        'kind', 'state'
      );
    end if;
  end if;

  if g ~ '\m(waiting|blocked|blocking|need from me|needs me|decide|decisions)\M' then
    select count(*)::integer into n from public.blockers where state = 'open';
    if n = 0 then
      return jsonb_build_object('speak', 'Nothing is waiting on you.', 'kind', 'state');
    end if;
    select string_agg(requested_action, '; ' order by created_at) into rows_text
      from (
        select requested_action, created_at from public.blockers
         where state = 'open' order by created_at limit 3
      ) b;
    return jsonb_build_object(
      'speak', format(
        '%s %s waiting on you. %s%s',
        n, case when n = 1 then 'thing is' else 'things are' end, rows_text,
        case when n > 3 then format(' And %s more.', n - 3) else '' end),
      'kind', 'state'
    );
  end if;

  if g ~ '\m(everyone|anyone|right now|in flight|in hand|working on|going on)\M'
     and g !~ '\m(said|find|found|conclude)\M' then
    select count(*)::integer into n from public.jobs
     where state in ('queued', 'running', 'waiting_external', 'output_created',
                     'quality_review', 'committing', 'committed', 'notifying', 'retrying');
    if n = 0 then
      return jsonb_build_object(
        'speak', 'Nothing is in hand at the moment. The queue is empty.', 'kind', 'state');
    end if;
    select string_agg(format('%s, %s', kind, state), '; ' order by created_at) into rows_text
      from (
        select kind, state::text as state, created_at from public.jobs
         where state in ('queued', 'running', 'waiting_external', 'output_created',
                         'quality_review', 'committing', 'committed', 'notifying', 'retrying')
         order by created_at limit 4
      ) j;
    return jsonb_build_object(
      'speak', format('%s %s in hand. %s', n,
                      case when n = 1 then 'thing is' else 'things are' end, rows_text),
      'kind', 'state'
    );
  end if;

  if g ~ '\m(projects?)\M' and g ~ '\m(what|which|how many|list|got|have)\M' then
    select count(*)::integer into n from public.projects where status = 'active';
    select string_agg(name, ', ' order by updated_at desc) into rows_text
      from public.projects where status = 'active';
    return jsonb_build_object(
      'speak', case
        when n = 0 then 'There are no active projects.'
        else format('%s active %s: %s.', n,
                    case when n = 1 then 'project' else 'projects' end, rows_text)
      end,
      'kind', 'state'
    );
  end if;

  if g ~ '\m(spent|spend|cost|costing|budget|allowance)\M' then
    select count(*)::integer into n from public.inference_usage
     where occurred_at > app.now_utc() - interval '24 hours';
    return jsonb_build_object(
      'speak', format(
        '%s model %s in the last day, costing %s dollars. On the notebook we have used %s of %s '
        'in the current window — that is our own count, not Google''s, because they publish '
        'no usage figure.',
        n, case when n = 1 then 'call' else 'calls' end,
        trim(to_char(coalesce((select sum(cost_usd) from public.inference_usage
                                where occurred_at > app.now_utc() - interval '24 hours'), 0),
                     'FM999990.0000')),
        coalesce((app.notebook_allowance() ->> 'window_spent'), '0'),
        coalesce((app.notebook_allowance() ->> 'window_ceiling'), 'unknown')),
      'kind', 'state'
    );
  end if;

  return null;
end;
$$;


--
-- Name: FUNCTION voice_answer(p_command_id uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.voice_answer(p_command_id uuid) IS 'A spoken answer assembled from real rows, or null meaning "this is work". Lives in the canonical layer because §5 forbids a channel adapter from deciding anything, and answering is a decision.';


--
-- Name: voice_lookup(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.voice_lookup(p_about text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_project uuid;
  v_staff   text;
  v_said    text := coalesce(trim(p_about), '');
begin
  select s.slug into v_staff
    from public.staff s
   where s.active
     and (v_said ~* ('\m' || s.name || '\M') or v_said ~* ('\m' || s.slug || '\M'))
   order by length(s.name) desc
   limit 1;

  if v_staff is not null then
    return jsonb_build_object(
      'about', 'person',
      'who', (select jsonb_build_object('name', s.name, 'title', s.title,
                       'style', s.communication_style)
                from public.staff s where s.slug = v_staff),
      'recent', (
        select coalesce(jsonb_agg(jsonb_build_object(
                 'project', pr.name,
                 'headline', left(o.body, 400),
                 'when', o.created_at) order by o.created_at desc), '[]'::jsonb)
          from (select o2.* from public.outputs o2
                  join public.staff s2 on s2.staff_id = o2.staff_id
                 where s2.slug = v_staff
                 order by o2.created_at desc limit 5) o
          left join public.jobs j on j.job_id = o.job_id
          left join public.projects pr on pr.project_id = j.project_id
      ),
      'duties', (
        select coalesce(jsonb_agg(jsonb_build_object(
                 'what', r.description, 'every_minutes', r.period_minutes,
                 'on', r.enabled) order by r.slug), '[]'::jsonb)
          from public.responsibilities r
          join public.staff s on s.staff_id = r.staff_id
         where s.slug = v_staff
      )
    );
  end if;

  select r.project_id into v_project
    from app.resolve_project_by_name(v_said) r
   where r.confidence >= 0.55
   order by r.confidence desc
   limit 1;

  if v_project is not null then
    return jsonb_build_object(
      'about', 'project',
      'project', (
        select jsonb_build_object(
          'name', p.name, 'purpose', coalesce(p.purpose, p.description),
          'status', p.status,
          'connected_to', (select coalesce(jsonb_agg(jsonb_build_object(
                             'connector', a.connector, 'what', a.display_name,
                             'holds', a.artifact_kind) order by a.connector), '[]'::jsonb)
                             from public.project_attachments a
                            where a.project_id = p.project_id and a.enabled))
          from public.projects p where p.project_id = v_project
      ),
      'material', (
        select coalesce(jsonb_agg(jsonb_build_object(
                 'title', d.title, 'size', d.content_chars)
               order by d.content_chars desc), '[]'::jsonb)
          from (select * from public.documents
                 where project_id = v_project
                   and mirrors_document_id is null
                 order by content_chars desc limit 12) d
      ),
      'recent', (
        select coalesce(jsonb_agg(jsonb_build_object(
                 'who', coalesce(s.name, 'the office'),
                 'headline', left(o.body, 400),
                 'when', o.created_at) order by o.created_at desc), '[]'::jsonb)
          from (select o2.* from public.outputs o2
                  join public.jobs j2 on j2.job_id = o2.job_id
                 where j2.project_id = v_project
                 order by o2.created_at desc limit 5) o
          left join public.staff s on s.staff_id = o.staff_id
      ),
      'in_flight', (
        select coalesce(jsonb_agg(jsonb_build_object(
                 'kind', j.kind, 'status', j.state, 'since', j.created_at)
               order by j.created_at desc), '[]'::jsonb)
          from public.jobs j
         where j.project_id = v_project
           and j.state not in ('complete', 'failed', 'cancelled')
      )
    );
  end if;

  return jsonb_build_object('about', 'everything', 'state', app.voice_state());
end;
$$;


--
-- Name: FUNCTION voice_lookup(p_about text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.voice_lookup(p_about text) IS 'One hop of real state for a voice call: a named colleague, a named project resolved through app.resolve_project_by_name, or the state of play. Read-only — writes still go through enqueue_inbound (0167).';


--
-- Name: voice_refusal(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.voice_refusal(p_bot_id text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select case
    when coalesce(
      (select value #>> '{}' from public.system_config where key = 'voice.transcription'),
      'none'
    ) <> 'none'
      then jsonb_build_object('refuse', false)
    else jsonb_build_object(
      'refuse', true,
      'token', (select app.resolve_secret(t.token_ref)
                  from public.telegram_bots t
                 where t.bot_id = p_bot_id and t.enabled and t.token_ref is not null)
    )
  end
$$;


--
-- Name: voice_state(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.voice_state() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select jsonb_build_object(
    'as_of', app.now_utc(),
    'projects', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'name', p.name,
               'purpose', left(coalesce(p.purpose, p.description, ''), 200),
               -- 0169: originals. Claire told Grant a project had 33 documents
               -- when it had 12 things, because the office had imported its own
               -- output back in.
               'documents', (select count(*) from public.documents d
                              where d.project_id = p.project_id
                                and d.mirrors_document_id is null),
               'connected_to', (select coalesce(string_agg(distinct a.connector, ', '), 'nothing')
                                  from public.project_attachments a
                                 where a.project_id = p.project_id and a.enabled),
               'last_output', (select max(o.created_at)
                                 from public.outputs o
                                 join public.jobs j on j.job_id = o.job_id
                                where j.project_id = p.project_id))
             order by p.name), '[]'::jsonb)
        from public.projects p
       where p.status = 'active' and not p.is_fixture
    ),
    'team', (
      select coalesce(jsonb_agg(jsonb_build_object('name', s.name, 'title', s.title)
             order by s.name), '[]'::jsonb)
        from public.staff s where s.active
    ),
    'today', app.office_health(24),
    'waiting_on_grant', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'what', left(n.requested_action, 160),
               'why', left(coalesce(n.why_needed, ''), 160),
               'project', pr.name,
               'work_goes_on', n.work_can_continue,
               'since', n.created_at) order by n.created_at), '[]'::jsonb)
        from public.needs_me n
        left join public.projects pr on pr.project_id = n.project_id
    ),
    'latest', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'who', coalesce(s.name, 'the office'),
               'project', pr.name,
               'headline', left(o.body, 220),
               'when', o.created_at) order by o.created_at desc), '[]'::jsonb)
        from (select ob.* from public.outputs ob
                join public.jobs jb on jb.job_id = ob.job_id
               where not jb.is_fixture
               order by ob.created_at desc limit 6) o
        left join public.staff s on s.staff_id = o.staff_id
        left join public.jobs j on j.job_id = o.job_id
        left join public.projects pr on pr.project_id = j.project_id
    )
  )
$$;


