$$;


--
-- Name: who_knows_about(text, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.who_knows_about(p_text text, p_limit integer DEFAULT 3) RETURNS TABLE(slug text, name text, matched text[], score real)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with words as (
    select distinct w
      from unnest(regexp_split_to_array(lower(coalesce(p_text, '')), '[^a-z]+')) as w
     where length(w) >= 4
  ),
  terms as (
    select s.slug, s.name, lower(btrim(t)) as term
      from public.staff s, unnest(s.expertise) as t
     where s.active
  ),
  hits as (
    select t.slug, t.name, t.term, w.w,
           greatest(
             case when t.term like '%' || w.w || '%' or w.w like '%' || t.term || '%'
                  then 1.0 else 0 end,
             /*
               A shared four-character prefix: write/writing, source/sources,
               forecast/forecasting. Scored a shade below an exact containment
               so a real match always outranks a stem match.
             */
             case when length(t.term) >= 5 and length(w.w) >= 5
                       and left(t.term, 4) = left(w.w, 4)
                  then 0.9 else 0 end,
             extensions.similarity(t.term, w.w)
           ) as s
      from terms t
      join words w
        on t.term like '%' || w.w || '%'
        or w.w like '%' || t.term || '%'
        or (length(t.term) >= 5 and length(w.w) >= 5 and left(t.term, 4) = left(w.w, 4))
        or extensions.similarity(t.term, w.w) > 0.62
  )
  select h.slug,
         h.name,
         array_agg(distinct h.term order by h.term) as matched,
         sum(least(h.s, 1.0))::real as score
    from hits h
   group by h.slug, h.name
   order by sum(least(h.s, 1.0)) desc, h.slug
   limit greatest(coalesce(p_limit, 3), 1)
$$;


--
-- Name: FUNCTION who_knows_about(p_text text, p_limit integer); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.who_knows_about(p_text text, p_limit integer) IS 'Ranked specialists for a subject, from staff.expertise — data Grant edits on the dashboard rather than a regex in TypeScript (#65). Says WHICH terms matched, because a routing decision nobody can question is one nobody can correct.';


--
-- Name: withdraw_tool_request(uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.withdraw_tool_request(p_request_id uuid, p_by text DEFAULT 'grant'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  update public.tool_requests
     set state = 'withdrawn', settled_at = app.now_utc(), decided_by = p_by
   where request_id = p_request_id and state = 'open';
  if not found then
    return jsonb_build_object('error', 'nothing open to withdraw');
  end if;
  return jsonb_build_object('withdrawn', p_request_id);
end;
$$;


