CREATE FUNCTION app.worker_paused() RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  select coalesce(
    (select (value #>> '{}')::timestamptz > app.now_utc()
       from public.system_config
      where key = 'worker.paused_until'
        and coalesce(value #>> '{}', '') <> ''),
    false
  )
$$;


--
-- Name: write_briefing(text, date, text, jsonb, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.write_briefing(p_kind text, p_for_date date, p_body text, p_inputs jsonb, p_scope_ref text DEFAULT 'grant'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  as_kind public.briefing_kind;
  made    public.briefings%rowtype;
begin
  begin
    as_kind := p_kind::public.briefing_kind;
  exception when invalid_text_representation then
    return jsonb_build_object(
      'error', format('%L is not a briefing kind; expected one of: %s',
                      p_kind,
                      (select string_agg(e.enumlabel, ', ' order by e.enumsortorder)
                         from pg_catalog.pg_enum e
                         join pg_catalog.pg_type t on t.oid = e.enumtypid
                        where t.typname = 'briefing_kind')));
  end;

  insert into public.briefings (kind, for_date, scope_ref, body, inputs)
  values (as_kind, p_for_date, p_scope_ref, p_body, coalesce(p_inputs, '{}'::jsonb))
  on conflict (kind, scope_ref, for_date) do nothing
  returning * into made;

  if made.briefing_id is null then
    return jsonb_build_object(
      'already_written', true,
      'for_date', p_for_date,
      'briefing_id', (select b.briefing_id from public.briefings b
                       where b.kind = as_kind and b.scope_ref = p_scope_ref
                         and b.for_date = p_for_date)
    );
  end if;

  return jsonb_build_object('briefing_id', made.briefing_id, 'already_written', false);
end;
$$;


--
-- Name: FUNCTION write_briefing(p_kind text, p_for_date date, p_body text, p_inputs jsonb, p_scope_ref text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.write_briefing(p_kind text, p_for_date date, p_body text, p_inputs jsonb, p_scope_ref text) IS 'Store a briefing, at most one per kind per scope per day. Takes text and casts, because every caller is a string; an unrecognised kind is told what the valid ones are. Relies on the unique index rather than checking first: a check-then-insert has a race and an index does not.';


