--

CREATE FUNCTION public.append_event(p_correlation_id uuid, p_actor_kind text, p_actor text, p_trigger text, p_action_type text, p_reversible boolean, p_project_id uuid DEFAULT NULL::uuid, p_before_state jsonb DEFAULT NULL::jsonb, p_after_state jsonb DEFAULT NULL::jsonb, p_rationale_summary text DEFAULT NULL::text, p_source_refs jsonb DEFAULT '[]'::jsonb, p_provider_used text DEFAULT NULL::text, p_tool_used text DEFAULT NULL::text, p_reversal_method text DEFAULT NULL::text, p_related_job_id uuid DEFAULT NULL::uuid, p_related_task_id uuid DEFAULT NULL::uuid, p_compensates_event_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE sql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  insert into public.events (
    correlation_id, actor_kind, actor, trigger, action_type, reversible,
    project_id, before_state, after_state, rationale_summary, source_refs,
    provider_used, tool_used, reversal_method, related_job_id, related_task_id,
    compensates_event_id
  ) values (
    p_correlation_id, p_actor_kind, p_actor, p_trigger, p_action_type, p_reversible,
    p_project_id, p_before_state, p_after_state, p_rationale_summary, p_source_refs,
    p_provider_used, p_tool_used, p_reversal_method, p_related_job_id, p_related_task_id,
    p_compensates_event_id
  )
  returning event_id
$$;


--
-- Name: FUNCTION append_event(p_correlation_id uuid, p_actor_kind text, p_actor text, p_trigger text, p_action_type text, p_reversible boolean, p_project_id uuid, p_before_state jsonb, p_after_state jsonb, p_rationale_summary text, p_source_refs jsonb, p_provider_used text, p_tool_used text, p_reversal_method text, p_related_job_id uuid, p_related_task_id uuid, p_compensates_event_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.append_event(p_correlation_id uuid, p_actor_kind text, p_actor text, p_trigger text, p_action_type text, p_reversible boolean, p_project_id uuid, p_before_state jsonb, p_after_state jsonb, p_rationale_summary text, p_source_refs jsonb, p_provider_used text, p_tool_used text, p_reversal_method text, p_related_job_id uuid, p_related_task_id uuid, p_compensates_event_id uuid) IS 'The only intended way to write the ledger. An explicit parameter list with no free-form passthrough, so there is nowhere for chain-of-thought to go (§6). SECURITY INVOKER, so it is not a way around RLS.';


