--
-- Name: job_transitions_allowed; Type: TABLE; Schema: app; Owner: -
--

CREATE TABLE app.job_transitions_allowed (
    from_state public.job_state NOT NULL,
    to_state public.job_state NOT NULL,
    CONSTRAINT no_self_transition CHECK ((from_state <> to_state))
);


--
-- Name: schema_migrations; Type: TABLE; Schema: app; Owner: -
--

CREATE TABLE app.schema_migrations (
    name text NOT NULL,
    checksum text NOT NULL,
    applied_at timestamp with time zone DEFAULT app.now_utc() NOT NULL,
    applied_by text DEFAULT CURRENT_USER NOT NULL,
    duration_ms integer,
    CONSTRAINT schema_migrations_checksum_sha256 CHECK ((checksum ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT schema_migrations_name_format CHECK ((name ~ '^[0-9]{4}_[a-z0-9]+(_[a-z0-9]+)*\.sql$'::text))
);


--
-- Name: TABLE schema_migrations; Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON TABLE app.schema_migrations IS 'Every migration this database has applied, with the SHA-256 of the file as applied. A mismatch against the file on disk means history was edited, which CI rejects.';


--
-- Name: appearance_settings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.appearance_settings (
    owner text NOT NULL,
    settings jsonb DEFAULT '{}'::jsonb NOT NULL,
    updated_at timestamp with time zone DEFAULT app.now_utc() NOT NULL,
    CONSTRAINT appearance_is_an_object CHECK ((jsonb_typeof(settings) = 'object'::text)),
    CONSTRAINT appearance_is_bounded CHECK ((length((settings)::text) <= 98304))
);


--
-- Name: TABLE appearance_settings; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.appearance_settings IS 'How the studio looks, per person (#124, ADR-0021). One jsonb rather than a column each: the page already treats it as one object and a column per value would need a migration every time a palette is added. localStorage is the cache in front of this, never the record.';


--
-- Name: artifacts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.artifacts (
    artifact_id uuid DEFAULT gen_random_uuid() NOT NULL,
    project_id uuid NOT NULL,
    notebook_ref text NOT NULL,
    external_ref text,
    kind text NOT NULL,
    title text,
    url text,
    state text DEFAULT 'generating'::text NOT NULL,
    detail text,
    requested_by_job uuid,
    preexisting jsonb DEFAULT '[]'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT app.now_utc() NOT NULL,
    updated_at timestamp with time zone DEFAULT app.now_utc() NOT NULL,
    ready_at timestamp with time zone,
    CONSTRAINT artifacts_ready_has_a_link CHECK (((state <> 'ready'::text) OR ((url IS NOT NULL) AND (ready_at IS NOT NULL)))),
    CONSTRAINT artifacts_state_known CHECK ((state = ANY (ARRAY['generating'::text, 'ready'::text, 'failed'::text, 'abandoned'::text])))
);

ALTER TABLE ONLY public.artifacts FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE artifacts; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.artifacts IS 'What NotebookLM produced for a project, and the link to open it. Grant: "see if you can pull them into our store project and display the results as a link within both Slack and Telegram." Separate from `documents` because an audio overview has no text to cite and because the sync owns the document keyspace for connector ''notebooklm''.';


--
-- Name: asset_actions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.asset_actions (
    action text NOT NULL,
    label text NOT NULL,
    says text NOT NULL,
    needs_two boolean DEFAULT false NOT NULL,
    "position" integer DEFAULT 0 NOT NULL
);


--
-- Name: TABLE asset_actions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.asset_actions IS '#27. The named things an agent can be asked to do to an asset — Review, Summarise, Research, Critique, Extract tasks, Compare. Data rather than a CASE so an eighth is a row and not a coding session. "Custom instruction" is deliberately absent: it opens the composer instead, and has no fixed sentence. 0313.';


--
-- Name: autonomy_policy; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.autonomy_policy (
    autonomy public.autonomy_level NOT NULL,
    action_level smallint NOT NULL,
    verdict public.policy_verdict NOT NULL,
    note text NOT NULL,
    set_by text DEFAULT 'the default matrix'::text NOT NULL,
    set_at timestamp with time zone DEFAULT app.now_utc() NOT NULL,
    CONSTRAINT autonomy_policy_level_known CHECK (((action_level >= 0) AND (action_level <= 3))),
    CONSTRAINT autonomy_policy_level_three_always_asks CHECK (((action_level < 3) OR (verdict <> 'proceed'::public.policy_verdict)))
);


--
-- Name: TABLE autonomy_policy; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.autonomy_policy IS 'What the office may do at each autonomy level, per action class (#15). The action class is tool_permissions.level. Edit a cell to change behaviour; the CHECK is what stops a level-3 action ever becoming automatic.';


--
-- Name: autonomy_settings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.autonomy_settings (
    setting_id uuid DEFAULT gen_random_uuid() NOT NULL,
    project_id uuid,
    level public.autonomy_level NOT NULL,
    set_by text NOT NULL,
    reason text NOT NULL,
    set_at timestamp with time zone DEFAULT app.now_utc() NOT NULL,
    CONSTRAINT autonomy_settings_actor_present CHECK ((length(TRIM(BOTH FROM set_by)) > 0)),
    CONSTRAINT autonomy_settings_reason_present CHECK ((length(TRIM(BOTH FROM reason)) >= 5))
);

ALTER TABLE ONLY public.autonomy_settings FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE autonomy_settings; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.autonomy_settings IS 'Append-only. The current level is the latest row for a scope; the history is what makes "what was this allowed to do at the time" answerable.';


--
-- Name: blockers; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.blockers (
    blocker_id uuid DEFAULT gen_random_uuid() NOT NULL,
    project_id uuid,
    job_id uuid,
    requested_action text NOT NULL,
    why_needed text NOT NULL,
    real_deadline timestamp with time zone,
    consequences_of_delay text NOT NULL,
    approval_options text[] NOT NULL,
    originating_agent text NOT NULL,
    work_can_continue boolean NOT NULL,
    state public.blocker_state DEFAULT 'open'::public.blocker_state NOT NULL,
    resolved_at timestamp with time zone,
    resolution text,
    created_at timestamp with time zone DEFAULT app.now_utc() NOT NULL,
    updated_at timestamp with time zone DEFAULT app.now_utc() NOT NULL,
    standing_tool text,
    standing_option text,
    on_answer jsonb,
    CONSTRAINT blockers_consequences_substantive CHECK (((length(consequences_of_delay) >= 3) AND (length(consequences_of_delay) <= 2000))),
    CONSTRAINT blockers_deadline_after_creation CHECK (((real_deadline IS NULL) OR (real_deadline > created_at))),
    CONSTRAINT blockers_has_an_option CHECK ((array_length(approval_options, 1) >= 1)),
    CONSTRAINT blockers_on_answer_is_complete CHECK (((on_answer IS NULL) OR ((on_answer ? 'option'::text) AND (on_answer ? 'kind'::text) AND (jsonb_typeof((on_answer -> 'payloads'::text)) = 'array'::text)))),
    CONSTRAINT blockers_requested_action_substantive CHECK (((length(requested_action) >= 3) AND (length(requested_action) <= 2000))),
    CONSTRAINT blockers_resolved_iff_settled CHECK (((state <> 'open'::public.blocker_state) = (resolved_at IS NOT NULL))),
    CONSTRAINT blockers_standing_needs_both CHECK (((standing_tool IS NULL) = (standing_option IS NULL))),
    CONSTRAINT blockers_why_needed_substantive CHECK (((length(why_needed) >= 3) AND (length(why_needed) <= 2000)))
);

ALTER TABLE ONLY public.blockers FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE blockers; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.blockers IS '§12 "Needs Me". Every field the spec names is a column, and the ones that are not genuinely optional are NOT NULL — a blocker without its consequences-of-delay is a random agent message wearing a table row.';


--
-- Name: COLUMN blockers.standing_tool; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.blockers.standing_tool IS 'The capability answering standing_option would authorize from now on (#15). Null on a question that grants nothing, which is most of them.';


--
-- Name: COLUMN blockers.on_answer; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.blockers.on_answer IS 'What answering with a particular option PERFORMS (#257): {option, kind, payloads[]}. Written by the handler that raised the blocker, never derived from the option text. Null on a question that performs nothing, which is most of them.';


--
-- Name: branch_groups; Type: TABLE; Schema: public; Owner: -
