);


--
-- Name: TABLE branch_groups; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.branch_groups IS 'One question split into concurrent specialist branches (#262). A branch is an ordinary job; this says which jobs belong to one question.';


