COMMENT ON TABLE public.breadth_dimensions IS 'The coverage dimensions of #235. Grant may add rows; nothing in code enumerates them.';


--
-- Name: briefings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.briefings (
    briefing_id uuid DEFAULT gen_random_uuid() NOT NULL,
    kind public.briefing_kind NOT NULL,
