    suppressed_reason text,
    CONSTRAINT briefings_body_substantive CHECK ((length(TRIM(BOTH FROM body)) >= 40)),
    CONSTRAINT briefings_delivery_is_explained CHECK ((((delivered_at IS NOT NULL) AND (array_length(delivered_to, 1) >= 1)) OR (delivered_at IS NULL))),
    CONSTRAINT briefings_scope_present CHECK ((length(TRIM(BOTH FROM scope_ref)) > 0))
);

ALTER TABLE ONLY public.briefings FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE briefings; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.briefings IS '§12 morning/evening briefings. `(kind, scope_ref, for_date)` is unique so a duty re-attempted after a crash collides instead of sending a second one.';


--
-- Name: COLUMN briefings.for_date; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.briefings.for_date IS 'The day this briefing is FOR, in local reckoning. Stored rather than derived from generated_at: a briefing produced at 23:40 UTC may be tomorrow''s.';


--
-- Name: COLUMN briefings.delivered_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.briefings.delivered_at IS 'Null means not sent - legitimately so when preferences muted it. Separate from generation so a muted morning does not look like a crashed one.';


