    bot_token_ref app.vault_secret_ref,
    signing_secret_ref app.vault_secret_ref,
    client_secret_ref app.vault_secret_ref,
    config_token_ref app.vault_secret_ref,
    config_refresh_ref app.vault_secret_ref,
    config_token_expires_at timestamp with time zone,
    config_token_rotated_at timestamp with time zone,
    rotation_failures integer DEFAULT 0 NOT NULL,
    last_rotation_error text,
    enabled boolean DEFAULT true NOT NULL,
    disabled_reason text,
    installed_at timestamp with time zone,
    revoked_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT app.now_utc() NOT NULL,
    updated_at timestamp with time zone DEFAULT app.now_utc() NOT NULL,
    CONSTRAINT slack_app_id_format CHECK ((slack_app_id ~ '^A[A-Z0-9]{8,}$'::text)),
    CONSTRAINT slack_app_name_present CHECK ((length(TRIM(BOTH FROM app_name)) > 0)),
    CONSTRAINT slack_disabled_has_reason CHECK ((enabled OR (disabled_reason IS NOT NULL))),
    CONSTRAINT slack_revoked_is_disabled CHECK (((revoked_at IS NULL) OR (NOT enabled))),
    CONSTRAINT slack_rotation_error_is_brief CHECK (((last_rotation_error IS NULL) OR (length(last_rotation_error) <= 500))),
    CONSTRAINT slack_rotation_failures_non_negative CHECK ((rotation_failures >= 0)),
