ALTER TABLE ONLY public.slack_app_credentials FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE slack_app_credentials; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.slack_app_credentials IS 'One row per Slack app (§15). Holds secret REFERENCES only — every credential column is a uuid into Supabase Vault, so a token cannot be stored here at all. Carries the config token pair''s rotation state, which is why a static environment variable cannot serve this purpose.';


--
-- Name: COLUMN slack_app_credentials.config_token_expires_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.slack_app_credentials.config_token_expires_at IS 'Slack config tokens expire roughly every 12 hours. Everything Slack depends on a credential that turns over twice a day, so rotation is tested against a real expiry window in Phase 2 before anything is built on it.';


--
-- Name: credential_health; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.credential_health AS
 WITH refs AS (
         SELECT c.slack_app_id,
            r.column_name,
            r.ref
           FROM (public.slack_app_credentials c
             CROSS JOIN LATERAL ( VALUES ('bot_token_ref'::text,c.bot_token_ref), ('signing_secret_ref'::text,c.signing_secret_ref), ('client_secret_ref'::text,c.client_secret_ref), ('config_token_ref'::text,c.config_token_ref), ('config_refresh_ref'::text,c.config_refresh_ref)) r(column_name, ref))
        )
 SELECT slack_app_id,
    column_name,
    (ref)::text AS secret_ref,
        CASE
            WHEN (ref IS NULL) THEN 'not_configured'::text
            WHEN (EXISTS ( SELECT 1
               FROM vault.secrets s
              WHERE (s.id = (refs.ref)::uuid))) THEN 'ok'::text
            ELSE 'DANGLING'::text
        END AS status
   FROM refs;


--
-- Name: VIEW credential_health; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.credential_health IS 'Every credential reference and whether it still resolves. A reference is a hint that a credential exists (§8), and hints get reconciled — 0007''s write-time trigger cannot see a secret deleted out from under a row.';


--
-- Name: credential_health_problems; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.credential_health_problems AS
 SELECT slack_app_id,
    column_name,
    secret_ref,
    status
   FROM public.credential_health
  WHERE (status = 'DANGLING'::text);


--
-- Name: VIEW credential_health_problems; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.credential_health_problems IS 'Empty is healthy. Non-empty means a credential reference no longer resolves, which fails only when the credential is needed — i.e. when something is already going wrong.';


--
-- Name: dashboard_layouts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.dashboard_layouts (
    project_id uuid NOT NULL,
    owner text DEFAULT 'grant'::text NOT NULL,
    panels jsonb NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT dashboard_layouts_panels_is_array CHECK (((jsonb_typeof(panels) = 'array'::text) AND (jsonb_array_length(panels) > 0)))
);


--
-- Name: decisions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.decisions (
    decision_id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    question text NOT NULL,
    chose text NOT NULL,
    ruled_out text[] NOT NULL,
    because text NOT NULL,
    decided_by text NOT NULL,
    decided_at timestamp with time zone DEFAULT app.now_utc() NOT NULL,
    project_id uuid,
    from_job uuid,
    supersedes uuid,
    is_fixture boolean GENERATED ALWAYS AS (((decided_by ~~ 'verify:%'::text) OR (decided_by ~~ 'fixture-%'::text))) STORED NOT NULL,
    search tsvector GENERATED ALWAYS AS (((setweight(to_tsvector('english'::regconfig, COALESCE(question, ''::text)), 'A'::"char") || setweight(to_tsvector('english'::regconfig, COALESCE(chose, ''::text)), 'B'::"char")) || setweight(to_tsvector('english'::regconfig, COALESCE(because, ''::text)), 'C'::"char"))) STORED,
    CONSTRAINT decisions_because_said CHECK ((btrim(because) <> ''::text)),
    CONSTRAINT decisions_chose_said CHECK ((btrim(chose) <> ''::text)),
    CONSTRAINT decisions_not_its_own_ancestor CHECK ((supersedes IS DISTINCT FROM decision_id)),
    CONSTRAINT decisions_question_said CHECK ((btrim(question) <> ''::text))
);


--
-- Name: TABLE decisions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.decisions IS 'What the office CONCLUDED, and what that ruled out (#129). Distinct from documents (material it was given), from lessons (rules about how to behave) and from routing_decisions (which agent answers — a different noun wearing the same word). Scoped to the office: project_id records where a decision came up and is never a filter. Append-only; superseding writes a new row.';


--
-- Name: decisions_live; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.decisions_live AS
 SELECT decision_id,
    question,
    chose,
    ruled_out,
    because,
    decided_by,
    decided_at,
    project_id,
    from_job,
    supersedes,
    is_fixture,
    search
   FROM public.decisions d
  WHERE (NOT (EXISTS ( SELECT 1
           FROM public.decisions n
          WHERE (n.supersedes = d.decision_id))));


--
-- Name: VIEW decisions_live; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.decisions_live IS 'Decisions nothing later has replaced. Derived, because a superseded flag would need an UPDATE and this table refuses them.';


--
-- Name: deliveries; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.deliveries (
    delivery_id uuid DEFAULT gen_random_uuid() NOT NULL,
    channel text NOT NULL,
    dedupe_key text NOT NULL,
    account_ref text NOT NULL,
    target_ref text NOT NULL,
    thread_ref text,
    staff_id uuid,
    correlation_id uuid,
    job_id uuid,
    purpose text NOT NULL,
    state public.slack_delivery_state DEFAULT 'claimed'::public.slack_delivery_state NOT NULL,
    attempt integer DEFAULT 1 NOT NULL,
    lease_expires_at timestamp with time zone NOT NULL,
    message_ref text,
    link text,
    error_code text,
    suppressed_reason text,
    created_at timestamp with time zone DEFAULT app.now_utc() NOT NULL,
    updated_at timestamp with time zone DEFAULT app.now_utc() NOT NULL,
    sent_at timestamp with time zone,
    CONSTRAINT deliveries_attempt_positive CHECK ((attempt >= 1)),
    CONSTRAINT deliveries_channel_known CHECK ((channel = ANY (ARRAY['slack'::text, 'telegram'::text, 'voice'::text, 'teamhq'::text]))),
    CONSTRAINT deliveries_failed_has_error CHECK (((state <> 'failed'::public.slack_delivery_state) OR (error_code IS NOT NULL))),
    CONSTRAINT deliveries_purpose_known CHECK ((purpose = ANY (ARRAY['result'::text, 'progress'::text, 'blocker'::text, 'ack'::text, 'briefing'::text, 'notice'::text]))),
    CONSTRAINT deliveries_ref_only_when_posted CHECK (((message_ref IS NULL) OR (state = ANY (ARRAY['sent'::public.slack_delivery_state, 'suppressed'::public.slack_delivery_state])))),
    CONSTRAINT deliveries_sent_at_iff_sent CHECK (((state = 'sent'::public.slack_delivery_state) = (sent_at IS NOT NULL))),
    CONSTRAINT deliveries_sent_has_ref CHECK (((state <> 'sent'::public.slack_delivery_state) OR (message_ref IS NOT NULL))),
    CONSTRAINT deliveries_suppressed_iff_reason CHECK (((state = 'suppressed'::public.slack_delivery_state) = (suppressed_reason IS NOT NULL))),
    CONSTRAINT deliveries_target_shaped CHECK (
CASE channel
    WHEN 'slack'::text THEN (target_ref ~ '^[CDG][A-Z0-9]{6,}$'::text)
    WHEN 'telegram'::text THEN (target_ref ~ '^-?[0-9]+$'::text)
    ELSE (length(target_ref) > 0)
END)
);

ALTER TABLE ONLY public.deliveries FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE deliveries; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.deliveries IS 'One row per outbound message on any channel, claimed before the send and completed after it. Generalised from slack_deliveries in 0039: the invariant is a property of delivery, not of Slack.';


--
-- Name: delivery_health; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.delivery_health AS
 SELECT channel,
    (state)::text AS state,
    (count(*))::integer AS deliveries,
    (sum(
        CASE
            WHEN (attempt > 1) THEN 1
            ELSE 0
        END))::integer AS needed_more_than_one_attempt,
    max(attempt) AS worst_attempt,
    (count(*) FILTER (WHERE ((state = 'claimed'::public.slack_delivery_state) AND (lease_expires_at < app.now_utc()))))::integer AS leases_expired
   FROM public.deliveries
  GROUP BY channel, state;


--
-- Name: VIEW delivery_health; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.delivery_health IS 'Counts, not a claim about health. `leases_expired` above zero means claims are outliving their claimers - deliveries nobody is currently carrying.';


--
-- Name: document_collections; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.document_collections (
    document_id uuid NOT NULL,
    collection_id uuid NOT NULL,
    added_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: documents; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.documents (
    document_id uuid DEFAULT gen_random_uuid() NOT NULL,
    project_id uuid,
    external_parent_ref text,
    external_ref text,
    title text,
    doc_type text,
    content text,
    content_fingerprint text,
    content_chars integer,
    fetched_at timestamp with time zone,
    remote_updated_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT app.now_utc() NOT NULL,
    updated_at timestamp with time zone DEFAULT app.now_utc() NOT NULL,
    connector text,
    search tsvector GENERATED ALWAYS AS ((setweight(to_tsvector('english'::regconfig, COALESCE(title, ''::text)), 'A'::"char") || setweight(to_tsvector('english'::regconfig, COALESCE(content, ''::text)), 'B'::"char"))) STORED,
    added_by text,
    mirrors_document_id uuid,
    origin text DEFAULT 'yours'::text NOT NULL,
    state text DEFAULT 'approved'::text NOT NULL,
    produced_by text,
    produced_by_job uuid,
    tags text[] DEFAULT '{}'::text[] NOT NULL,
    storage_path text,
    mime_type text,
    byte_size bigint,
    duration_s integer,
    pinned boolean DEFAULT false NOT NULL,
    superseded_by uuid,
    source_title text,
    missing_since timestamp with time zone,
    CONSTRAINT connector_matches_origin CHECK ((((origin = 'source'::text) AND (connector IS NOT NULL) AND (length(btrim(connector)) > 0)) OR ((origin = 'yours'::text) AND ((connector IS NULL) OR (btrim(connector) = ''::text))) OR (origin = 'made'::text))),
    CONSTRAINT documents_content_and_fingerprint_together CHECK (((content IS NULL) = (content_fingerprint IS NULL))),
    CONSTRAINT documents_external_identity_is_whole CHECK (((external_parent_ref IS NULL) OR (external_ref IS NOT NULL))),
    CONSTRAINT documents_fetched_iff_content CHECK (((content IS NULL) = (fetched_at IS NULL))),
    CONSTRAINT documents_file_is_complete CHECK ((((storage_path IS NULL) AND (mime_type IS NULL) AND (byte_size IS NULL)) OR ((storage_path IS NOT NULL) AND (mime_type IS NOT NULL) AND (byte_size > 0)))),
    CONSTRAINT documents_fingerprint_sha256 CHECK (((content_fingerprint IS NULL) OR (content_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT documents_origin_check CHECK ((origin = ANY (ARRAY['yours'::text, 'source'::text, 'made'::text]))),
    CONSTRAINT documents_state_check CHECK ((state = ANY (ARRAY['draft'::text, 'review'::text, 'approved'::text, 'archived'::text]))),
    CONSTRAINT only_made_things_await_review CHECK (((state <> 'review'::text) OR (origin = 'made'::text)))
);

ALTER TABLE ONLY public.documents FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE documents; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.documents IS 'Every document the system holds, whatever fed it in (ADR-0013). Postgres is the store; a connector is a route, and losing a route loses the route and not the corpus - which is exactly what 2026-09-04 demonstrated.';


--
-- Name: COLUMN documents.external_parent_ref; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.documents.external_parent_ref IS 'The container the document came from - a notebook, a Notion database - or null for an upload, which came from nowhere but here. Null together with external_ref, never half-set: see documents_external_identity_is_whole.';


--
-- Name: COLUMN documents.external_ref; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.documents.external_ref IS 'The id this document has in the system it came from, or null when it came from nowhere but here (an upload). Never a key this system relies on.';


--
-- Name: COLUMN documents.search; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.documents.search IS 'ADR-0013 point 4: retrieval is ours. Generated, so it cannot drift from the content the way a trigger-maintained column silently can.';


--
-- Name: COLUMN documents.added_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.documents.added_by IS 'Which MCP client added this, when one did. Null for everything else. The connector says HOW it arrived; this says WHO asked.';


--
-- Name: COLUMN documents.mirrors_document_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.documents.mirrors_document_id IS 'This row is a copy of another document that WE wrote into a connector — the Notion page office.notion_import created from a NotebookLM source, say. It is not new material and must not be counted, retrieved or shown as such. Null for everything that arrived from outside (0169).';


--
-- Name: COLUMN documents.produced_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.documents.produced_by IS 'Who made this, when origin is ''made''. NULL means we do not know, which is what every reader''s coalesce is written against — 0284. Never '''': a sentinel reads as a producer in a group-by and defeats the coalesce, which is 0177''s argument about connector = ''none'' in a second column.';


--
-- Name: COLUMN documents.storage_path; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.documents.storage_path IS 'Where the bytes are in the `files` bucket. NULL for a text-only document. The bucket is private: a document out of a dashboard project is Grant''s, which means Telegram must be sent the bytes rather than a link.';


--
-- Name: COLUMN documents.mime_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.documents.mime_type IS 'What the file is. Decides how it is sent — audio/* goes as playable audio rather than as an attachment.';


--
-- Name: COLUMN documents.duration_s; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.documents.duration_s IS 'Seconds, for audio and video. Telegram shows it on the player, and "a 24 minute overview" is the fact that decides whether he presses play.';


--
-- Name: COLUMN documents.pinned; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.documents.pinned IS 'Grant said this one is the important one (#152). A flag on the row, not a separate table - the issue asks for that explicitly and it is right: a pin is a property of the document, not a relationship.';


--
-- Name: COLUMN documents.superseded_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.documents.superseded_by IS 'The document that replaced this one (#152). NOT mirrors_document_id, which means "this is a copy we wrote out to a connector" (0169) and is filtered on for that meaning - a column that means two things cannot be filtered on either.';


--
-- Name: COLUMN documents.source_title; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.documents.source_title IS 'What the CONNECTOR last called this document. Null for anything the office made or Grant uploaded. Compared on re-read so an upstream rename can be applied without undoing a rename Grant made himself.';


--
-- Name: COLUMN documents.missing_since; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.documents.missing_since IS 'When this document was first absent from its source listing (#257, ADR-0040). Cleared when it reappears. Two consecutive absences archive it; one never does, because a partial listing during a provider incident is indistinguishable from a deletion at the moment it happens.';


--
-- Name: CONSTRAINT connector_matches_origin ON documents; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT connector_matches_origin ON public.documents IS '#20. `origin` is provenance (who made it), `connector` is location (where it lives). A source must name where it came from; something the office made may name where it was written to. 0177 fused the two, which is how six pages the office authored were counted as Grant''s source material.';


--
-- Name: drive_watch; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.drive_watch (
    attachment_id uuid NOT NULL,
    folder_id text NOT NULL,
    page_token text,
    primed boolean DEFAULT false NOT NULL,
    last_checked_at timestamp with time zone,
    last_change_at timestamp with time zone,
    failures integer DEFAULT 0 NOT NULL,
    last_error text,
    created_at timestamp with time zone DEFAULT app.now_utc() NOT NULL,
    updated_at timestamp with time zone DEFAULT app.now_utc() NOT NULL,
    last_reconciled_at timestamp with time zone,
    last_reconcile_note text,
    CONSTRAINT drive_watch_folder_id_check CHECK ((length(btrim(folder_id)) > 0))
);


--
-- Name: TABLE drive_watch; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.drive_watch IS 'Where each attached Drive folder''s change feed has got to. Separate from project_attachments because a re-attach must start the watch afresh rather than resume a stale cursor.';


--
-- Name: COLUMN drive_watch.primed; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.drive_watch.primed IS 'The first pass takes a start token and reports nothing — a folder attached today may hold hundreds of files from last year, and asking about all of them is not a welcome.';


--
-- Name: COLUMN drive_watch.last_reconciled_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.drive_watch.last_reconciled_at IS 'When the folder was last LISTED to find deletions the changes feed cannot report. Daily, not every pass.';


--
-- Name: COLUMN drive_watch.last_reconcile_note; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.drive_watch.last_reconcile_note IS 'What that listing concluded, including a refusal from the blast-radius guard, so a quiet failure is visible.';


--
-- Name: eval_cases; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.eval_cases (
    case_id uuid DEFAULT gen_random_uuid() NOT NULL,
    slug text NOT NULL,
    ask text NOT NULL,
