    expect text NOT NULL,
    issue integer,
    why text NOT NULL,
    active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT app.now_utc() NOT NULL,
    context text,
    dimensions text[] DEFAULT '{}'::text[] NOT NULL,
    CONSTRAINT eval_cases_expect_check CHECK ((expect = ANY (ARRAY['good'::text, 'poor'::text])))
);


--
-- Name: COLUMN eval_cases.context; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.eval_cases.context IS 'Facts about this office a fair grader would need, never the verdict. The judge sees this; it never sees `expect` or `why`.';


--
-- Name: COLUMN eval_cases.dimensions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.eval_cases.dimensions IS 'Which #235 dimensions this case covers. Every element must exist in breadth_dimensions.';


--
-- Name: eval_runs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.eval_runs (
    run_id uuid DEFAULT gen_random_uuid() NOT NULL,
