    origin_channel text NOT NULL,
    given_by text DEFAULT 'grant'::text NOT NULL,
    created_at timestamp with time zone DEFAULT app.now_utc() NOT NULL,
    CONSTRAINT feedback_channel_known CHECK ((origin_channel = ANY (ARRAY['slack'::text, 'telegram'::text, 'voice'::text, 'teamhq'::text, 'email'::text]))),
    CONSTRAINT feedback_correction_says_what CHECK (((signal <> 'correction'::public.feedback_signal) OR (length(TRIM(BOTH FROM COALESCE(body, ''::text))) >= 10)))
);

ALTER TABLE ONLY public.feedback FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE feedback; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.feedback IS 'What Grant thought of something. `origin_channel` matters: a reaction is a weak signal and a typed sentence is not, and treating them alike is how a stray emoji becomes a policy.';


